# 族前缀：只覆盖**同义的一族**事件，不覆盖整个 socket.* 命名空间 ——
# `socket.__new__`（也就是 socket.socket() 建对象）必须放行，
# onnxruntime / opencv / setuptools 在无害场景下会建 socket，
# 一刀切拦掉会把产品打坏。宁可漏拦，也不要误伤。
_OFFLINE_DENIED_EVENT_PREFIXES = (
    "socket.send",  # socket.send / socket.sendto / socket.sendmsg
    "os.exec",   # os.exec / os.execve / os.execvpe / os.execl ...
    "os.spawn",  # os.spawn / os.spawnv / os.spawnve ...
)

# 被拦行为的说法（用户直接看得到，所以**不许混进英文或域名** ——
# GUI 的 localizedBackendDetail() 一旦在消息里看到拉丁字母就改用通用话术，
# 真正的离线原因就看不见了）。
_OFFLINE_EVENT_LABELS: tuple[tuple[str, str, str], ...] = (
    # (事件名或族前缀, 被拦行为的说法, 消息里的禁止句)
    ("socket.connect", "建立网络连接", "禁止建立网络连接"),
    ("http.client.connect", "建立网络连接", "禁止建立网络连接"),
    ("socket.getaddrinfo", "解析外部域名", "禁止解析外部域名"),
    ("socket.gethostbyname", "解析外部域名", "禁止解析外部域名"),
    ("socket.gethostbyaddr", "解析外部域名", "禁止解析外部域名"),
    ("socket.sendto", "发送网络数据包", "禁止发送网络数据包"),
    ("socket.sendmsg", "发送网络数据包", "禁止发送网络数据包"),
    ("subprocess.Popen", "启动外部程序", "禁止启动外部程序"),
    ("os.posix_spawn", "启动外部程序", "禁止启动外部程序"),
    ("os.spawn", "启动外部程序", "禁止启动外部程序"),
    ("os.system", "调用系统命令", "禁止调用系统命令"),
    ("os.exec", "替换当前进程", "禁止替换当前进程"),
    ("webbrowser.open", "打开浏览器访问网址", "禁止打开浏览器访问网址"),
    ("urllib.Request", "发起网址请求", "禁止发起网址请求"),
)


def _offline_event_label(event: str) -> tuple[str, str]:
    """被拦行为的说法 + 消息里的禁止句。"""
    for matcher, label, prohibition in _OFFLINE_EVENT_LABELS:
        if event.startswith(matcher):
            return label, prohibition
    return "访问网络", "禁止访问网络"


def _split_command_tokens(text: str) -> list[str]:
    """按引号切命令行（Windows 的 audit 事件给的是整条命令行字符串）。"""
    tokens: list[str] = []
    current: list[str] = []
    in_quotes = False
    for character in text:
        if character == '"':
            in_quotes = not in_quotes
            continue
        if character.isspace() and not in_quotes:
            if current:
                tokens.append("".join(current))
                current = []
            continue
        current.append(character)
    if current:
        tokens.append("".join(current))
    return tokens


def _command_tokens(arguments: tuple[Any, ...]) -> list[str]:
    """把 audit 事件的参数还原成 argv（POSIX 给的是 list，Windows 给的是字符串）。"""
    tokens: list[str] = []
    for value in arguments:
        if isinstance(value, str):
            tokens.extend(_split_command_tokens(value))
        elif isinstance(value, (list, tuple)):
            tokens.extend(item for item in value if isinstance(item, str))
    return tokens


def _path_candidates(path: str) -> tuple[str, ...]:
    """路径的等价写法（绝对化 + 解析符号链接 + Windows 大小写归一）。"""
    if not path:
        return ()
    absolute = os.path.abspath(path)
    resolved = os.path.realpath(absolute)
    return tuple(
        dict.fromkeys(os.path.normcase(item) for item in (absolute, resolved))
    )


_BACKEND_SELF_CANDIDATES = _path_candidates(__file__)
_EXECUTABLE_CANDIDATES = _path_candidates(sys.executable)


def _allows_backend_self_spawn(arguments: tuple[Any, ...]) -> bool:
    """允许后端**再拉起自己**（交付自检就是这么干的）。

    只放行"用当前解释器、且把本模块自身当作脚本参数"这一种情况：
    子进程 import 同一个模块，会装上同一套离线钩子，所以这不是绕过；
    `curl`、PowerShell 之类仍然一律拒绝。
    """
    tokens = _command_tokens(arguments)
    if len(tokens) < 2:
        return False
    interpreter = os.path.normcase(os.path.abspath(tokens[0]))
    if interpreter not in _EXECUTABLE_CANDIDATES:
        return False
    backend_tokens = set(_BACKEND_SELF_CANDIDATES)
    for token in tokens[1:]:
        if os.path.normcase(os.path.abspath(token)) in backend_tokens:
            return True
    return False


def _offline_event_prohibition(
    event: str, arguments: tuple[Any, ...]
) -> tuple[str, str] | None:
    """这个 audit event 要不要拦？返回 (被拦行为的说法, 禁止句)；None = 放行。"""
    if event == "socket.connect":
        # **有意无条件拒绝，连本机回环也拒。** 见文件顶部 _OFFLINE_ALLOWED_HOSTS
        # 上方 2026-10-28（审计 A20）那段说明：socket.connect 是把字节真正送出去
        # 的那一步，回环也可能是本机代理/转发器；后端自身（stdin/stdout JSONL）
        # 不使用任何本机 TCP。既有回归测试
        # backend/tests/test_backend.py::test_backend_runtime_blocks_socket_connections
        # 锁的就是"连 127.0.0.1 也要抛 PermissionError"。
        return _offline_event_label(event)
    if event in ("socket.getaddrinfo", "socket.gethostbyname", "socket.gethostbyaddr"):
        host = arguments[0] if arguments else None
        if _is_local_host(host):
            return None
        return _offline_event_label(event)
    if event == "socket.sendto":
        address = arguments[1] if len(arguments) > 1 else None
        host = address[0] if isinstance(address, tuple) and address else None
        if _is_local_host(host):
            return None
        return _offline_event_label(event)
    if event == "socket.sendmsg":
        # socket.sendmsg 的 audit 事件里没有目标地址，没法判断是不是本机，
        # 所以一律拒绝（产品自身不用它）。
        return _offline_event_label(event)
    if event == "subprocess.Popen":
        if _allows_backend_self_spawn(arguments):
            return None
        return _offline_event_label(event)
    if event in _OFFLINE_ALWAYS_DENIED_EVENTS:
        return _offline_event_label(event)
    if any(
        event.startswith(prefix) for prefix in _OFFLINE_DENIED_EVENT_PREFIXES
    ):
        return _offline_event_label(event)
    return None


def _offline_violation_detail(event: str, arguments: tuple[Any, ...]) -> str:
    """被拦动作的技术细节（只进运行轨迹，不进用户可见消息）。"""
    parts: list[str] = []
    for argument in arguments:
        if argument is None or isinstance(argument, (str, int, float, bool)):
            parts.append(repr(argument))
        else:
            parts.append(type(argument).__name__)
    return "%s(%s)" % (event, ", ".join(parts))


def _deny_network_access(event: str, arguments: tuple[Any, ...]) -> None:
    """Enforce the product's offline contract before third-party imports run.

    钩子里**只判定和抛异常**：不做 I/O、不打印 —— 后端一个请求一行 JSON，
    往 stdout 写东西会破坏协议。
    """
    prohibition = _offline_event_prohibition(event, arguments)
    if prohibition is None:
        return
    label, prohibition_text = prohibition
    raise _OfflinePolicyViolation(
        "离线识别禁止联网：已拦截「%s」。本工具%s，只在本机离线识别，不访问网络；"
        "如识别失败，请检查随包模型文件是否完整。" % (label, prohibition_text),
        technical_detail=_offline_violation_detail(event, arguments),
    )


def _is_offline_policy_violation(error: BaseException) -> bool:
    """异常是不是"离线策略拦截"（跨模块重导入也认）。"""
    return bool(getattr(error, "_ocrtable_offline_policy_violation", False))


def _record_offline_policy_violation(error: BaseException) -> None:
    """把被拦截的联网动作记进运行轨迹（用户看得见的提示在异常消息里）。"""
    _write_runtime_trace(
        "offline_policy_violation",
        force_flush=True,
        detail=getattr(error, "technical_detail", "") or str(error),
    )


sys.addaudithook(_deny_network_access)


class _SystemMemoryStatus(ctypes.Structure):
    _fields_ = [
        ("length", ctypes.c_ulong),
        ("memory_load", ctypes.c_ulong),
        ("total_physical", ctypes.c_ulonglong),
        ("available_physical", ctypes.c_ulonglong),
        ("total_page_file", ctypes.c_ulonglong),
        ("available_page_file", ctypes.c_ulonglong),
        ("total_virtual", ctypes.c_ulonglong),
        ("available_virtual", ctypes.c_ulonglong),
        ("available_extended_virtual", ctypes.c_ulonglong),
    ]


def _available_memory_bytes() -> tuple[int, int] | None:
    if os.name != "nt":
        return None
    status = _SystemMemoryStatus()
    status.length = ctypes.sizeof(_SystemMemoryStatus)
    try:
        succeeded = ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status))
    except (AttributeError, OSError):
        return None
    if not succeeded:
        return None
    return int(status.available_physical), int(status.available_page_file)


def _require_recognition_memory_headroom() -> str:
    """按可用内存选择识别档位（双阈值迟滞带）。

    **降档立刻、升档更黏**：

    - 可用内存低于阈值 -> **立即**进低档。单测锁定了「临界低内存必须立刻进
      串行模式且不得拒绝识别」，所以降档不能有任何延迟。
    - 已经在低档时，要升回正常档需要可用内存**超过阈值 + 512 MB**。这条
      迟滞带消除了阈值附近来回横跳。

    2026-10-22 实测（1200 例语料前 57 例）：档位在 low_memory / normal 之间
    **翻转 15 次**（26% 的相邻用例变了档）。每次翻转都会触发
    _configure_recognition_memory_mode() -> release_for_table_structure() ->
    下一次请求把全部 OpenVINO 模型重建一遍（实测 0.1~1.5 秒/次）；低档本身
    又慢 48%、逐格准确率低 28%（low 档中位 39.4 秒 / 0.688，normal 档中位
    26.7 秒 / 0.759）。反复横跳是纯浪费，还让耗时数据完全无法横向比较。
    """
    available = _available_memory_bytes()
    if available is None:
        _configure_recognition_memory_mode(False)
        _remember_request_memory_mode()
        return "normal"
    available_physical, available_page_file = available
    threshold = _low_memory_threshold_bytes()
    release_threshold = threshold + _LOW_MEMORY_RELEASE_MARGIN_BYTES
    if _ACTIVE_RECOGNITION_MEMORY_MODE == "low_memory":
        # 已在低档：要用更高的阈值才升回正常档（迟滞带）。
        low_memory = not (
            available_physical >= release_threshold
            and available_page_file >= release_threshold
        )
    else:
        low_memory = bool(
            available_physical < threshold
            or available_page_file < threshold
        )
    _configure_recognition_memory_mode(low_memory)
    _remember_request_memory_mode()
    return "low_memory" if low_memory else "normal"


def _remember_request_memory_mode() -> None:
    """记下本次请求选定的内存档位（请求中途档位再变也不改这里）。"""
    global _REQUEST_MEMORY_MODE
    _REQUEST_MEMORY_MODE = _ACTIVE_RECOGNITION_MEMORY_MODE


def _flush_runtime_trace(force: bool = False) -> None:
    global _runtime_trace_buffer, _runtime_trace_last_flush
    if _runtime_trace_file is None or not _runtime_trace_buffer:
        return
    now = time.monotonic()
    if (
        not force
        and len(_runtime_trace_buffer) < 64
        and now - _runtime_trace_last_flush < 0.5
    ):
        return
    try:
        _runtime_trace_file.write("".join(_runtime_trace_buffer))
        _runtime_trace_file.flush()
        _runtime_trace_buffer = []
        _runtime_trace_last_flush = now
    except OSError:
        # Performance tracing must never make recognition fail.
        _runtime_trace_buffer = []


def _write_runtime_trace(
    event: str, *, force_flush: bool = False, **values: Any
) -> None:
    if not _runtime_trace_active:
        return
    payload = {
        "event": event,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()),
        "epoch_seconds": round(time.time(), 3),
        "elapsed_seconds": round(
            max(0.0, time.monotonic() - _runtime_trace_started), 3
        ),
    }
    payload.update(values)
    try:
        encoded = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
            default=_runtime_trace_json_default,
        )
    except (TypeError, ValueError, OverflowError):
        # 运行轨迹只用于诊断，任何异常值都不能中断正式识别结果。
        return
    _runtime_trace_buffer.append(encoded + "\n")
    _flush_runtime_trace(force_flush)


def _runtime_trace_json_default(value: Any) -> Any:
    if np is not None and isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Path):
        return str(value)
    return str(value)


def _begin_runtime_trace(image_path: Any) -> None:
    global _runtime_trace_active, _runtime_trace_started
    global _runtime_trace_model_totals, _runtime_trace_file
    global _runtime_trace_buffer, _runtime_trace_last_flush
    global _low_memory_threshold_override_error
    _runtime_trace_started = time.monotonic()
    _runtime_trace_model_totals = {}
    _runtime_trace_buffer = []
    _runtime_trace_last_flush = _runtime_trace_started
    if _ocr_engine is not None:
        _ocr_engine.reset_execution_profile()
    if _runtime_trace_file is not None:
        try:
            _runtime_trace_file.close()
        except OSError:
            pass
        _runtime_trace_file = None
    try:
        _RUNTIME_TRACE_PATH.parent.mkdir(parents=True, exist_ok=True)
        _runtime_trace_file = _RUNTIME_TRACE_PATH.open(
            "w", encoding="utf-8", buffering=65536
        )
    except OSError:
        _runtime_trace_file = None
    _runtime_trace_active = True
    _write_runtime_trace(
        "request_start",
        force_flush=True,
        image_name=Path(str(image_path)).name,
        process_id=os.getpid(),
    )
    # 补写请求开始前才发现的「现场标定环境变量非法」。
    if _low_memory_threshold_override_error is not None:
        _write_runtime_trace(
            "low_memory_threshold_override_invalid",
            force_flush=True,
            env_var="OCRTABLE_LOW_MEMORY_THRESHOLD_MB",
            detail=_low_memory_threshold_override_error,
            fallback="auto_threshold",
        )
        _low_memory_threshold_override_error = None


def _finish_runtime_trace() -> None:
    global _runtime_trace_active, _runtime_trace_file, _runtime_trace_buffer
    _write_runtime_trace(
        "request_end", force_flush=True, profile=_runtime_trace_summary()
    )
    _runtime_trace_active = False
    if _runtime_trace_file is not None:
        try:
            _runtime_trace_file.close()
        except OSError:
            pass
        _runtime_trace_file = None
    _runtime_trace_buffer = []


def _runtime_trace_summary() -> dict[str, Any]:
    summary = {
        "trace_path": str(_RUNTIME_TRACE_PATH),
        "elapsed_seconds": round(
            max(0.0, time.monotonic() - _runtime_trace_started), 3
        ),
        "models": {
            name: {
                "calls": int(values.get("calls", 0)),
                "images": int(values.get("images", 0)),
                "seconds": round(float(values.get("seconds", 0.0)), 3),
            }
            for name, values in _runtime_trace_model_totals.items()
        },
        "evidence_cache": {
            "hits": _recognition_evidence_hits,
            "misses": _recognition_evidence_misses,
            "entries": len(_recognition_evidence_cache),
        },
        "ordered_batch_evidence_cache": {
            "hits": _ordered_batch_evidence_hits,
            "misses": _ordered_batch_evidence_misses,
            "entries": len(_ordered_batch_evidence_cache),
        },
        "page_evidence_cache": {
            "hits": _page_evidence_hits,
            "misses": _page_evidence_misses,
            "entries": len(_page_evidence_cache),
        },
        # **本次请求实际使用的**内存档位与推理线程数。
        # 验收脚本原来读的是模块级的当前值（请求结束时的状态），请求中途
        # 档位一变就会把"低档跑出来的结果"标成正常档 —— 2026-10-22 实测
        # FC-00006 因此被追了半个多小时：同一份代码两次跑出 0.9268 与
        # 0.939，差别其实只是"请求开始时是不是低内存档"。
        "memory_mode": _REQUEST_MEMORY_MODE,
        "inference_threads": _RECOGNITION_INFERENCE_THREADS,
    }
    if _ocr_engine is not None:
        summary["recognition_scheduler"] = _ocr_engine.execution_profile()
    return summary


def _recognition_batch_size(args: tuple[Any, ...], kwargs: dict[str, Any]) -> int:
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if images is None:
        return 1
    if hasattr(images, "shape") and hasattr(images, "dtype"):
        return 1
    try:
        return len(images)
    except TypeError:
        return 1


def _recognition_batch_geometry(
    args: tuple[Any, ...], kwargs: dict[str, Any]
) -> dict[str, int | float]:
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if images is None:
        return {}
    image_list = [images] if hasattr(images, "shape") else list(images)
    shapes = [image.shape[:2] for image in image_list if hasattr(image, "shape")]
    if not shapes:
        return {}
    return {
        "max_width": max(int(width) for _, width in shapes),
        "max_height": max(int(height) for height, _ in shapes),
        "max_aspect": round(
            max(float(width) / max(1.0, float(height)) for height, width in shapes),
            3,
        ),
        "total_pixels": sum(int(height) * int(width) for height, width in shapes),
    }


def _normalize_recognition_output(output: Any) -> Any:
    """保证 OCR 返回的 boxes / txts / scores 永远不是 None。

    检测不到任何文字时，RapidOCR 会把这三个字段置为 None，而后端里有三百多处
    直接按序列使用它们，于是整张表以 `TypeError: 'NoneType' object is not
    iterable` 失败——实测 1200 例语料里 4 例。在唯一的模型调用出口统一补齐，
    比在三百个使用点逐个判空可靠得多。
    """
    if output is None:
        return output
    try:
        # boxes 必须保持二维 (N,4) 语义：调用方会做 np.asarray(box)[:, 0]，
        # 也会在缩放分支里乘以宽高比，形状不对会直接抛异常。
        if getattr(output, "boxes", None) is None:
            output.boxes = np.zeros((0, 4), dtype=np.float32)
        if getattr(output, "txts", None) is None:
            output.txts = []
        if getattr(output, "scores", None) is None:
            output.scores = []
    except (AttributeError, TypeError, ValueError):
        return output
    return output


class _FineGrainedBudgetExceeded(RuntimeError):
    """细粒度复核超出预算。宁可明确失败，也不把「没算完」的结果当成结果给客户。"""


class _InvalidRequestError(ValueError):
    """请求参数校验失败（**只**由 validate_request 抛出）。

    2026-10-30（lead 复查 P1）：之前 `_classify_error` 把管线内任何
    ValueError/TypeError/KeyError 都兜底判成 `INVALID_REQUEST` + `retryable=False`，
    于是识别/导出流程里的真实内部缺陷（`float(None)`、numpy 形状不符、openpyxl
    异常……）都会显示成"请求无效"，客户端既不重试也看不到内部错误码。
    有了这个专用类型，只有参数校验失败归 INVALID_REQUEST。
    """


_FINE_GRAINED_RECOGNITION_MODELS = ("medium", "v6-medium-alternate", "v6-small")
# 逐格复核没有上限时，一张误导性背景网格就能让单例跑满 5 分钟（实测最慢
# 822 秒）：错切出的网格越碎，要复核的格子越多，形成正反馈。超预算后立刻
# 中止并让界面提示客户裁剪区域，绝不返回一份没复核完的表格。
#
# 预算按**墙钟总时间**算，不按模型累计时间算。早先只累计细粒度模型的耗时，
# 结果一次 45 秒的预算要等 62~135 秒才触发（实测 12 例 runtime_error，
# wall 最大 135 秒）—— 模型之外还有页面检测、线框检测、透视矫正等开销，
# 一张完全不受控的表照样能跑几分钟。
#
# 150 秒这个值来自 634 例历史跑批的耗时分布：端到端中位 63 秒、P90 153 秒，
# 而逐格准确率 ≥ 0.8 的 296 例里有 89% 在 120 秒内、约 93% 在 150 秒内。
# 设 150 秒既保住了几乎所有本来能出结果的表，又把 822 秒那类失控例砍掉。
#
# 交付要求更严：**单例不得超过 1 分钟**，且大多数表应当在一分钟内出结果。
# 2026-10-13 实测 628 例：端到端中位 61.1 秒、模型调用占 88%、
# 非模型开销只有 9.2 秒。收窄口径为单路复测后：同一批 5 张表单路只要
# 11.6~19.9 秒，2 路并发中位 19.5 秒、99.2% 在 60 秒内。
#
# **墙钟计时在并发下不可靠**：多路跑批时模型调用被操作系统调度拉长，同一张
# 本该 12~20 秒跑完的表会在 21 秒就触发前瞻估算被拒（2 路实测误伤 3.2% 的
# 高准确率表）。所以批量验收要用环境变量 OCRTABLE_BUDGET_DISABLED=1 关闭
# 硬预算，拿完整的准确率数据；耗时与内存的交付口径一律用单路复测。
_MAX_REQUEST_SECONDS = 60.0
# 单条 JSONL 请求的字节上限（2026-10-30）。协议一次请求一行，正常请求（含
# spans/cells 的 export_xlsx）远小于 16 MiB；没有上限时一个不含换行的巨型输入
# 会让整段驻留内存。见 _serve_persistent。
_MAX_REQUEST_LINE_BYTES = 16 * 1024 * 1024
# 输入图片的上限（2026-10-30）：文件字节上限挡住"整文件读入"的内存峰值，像素上限
# 挡住高压缩比但尺寸巨大的解码结果。真实语料 PNG 均 < 5 MB、最大 462 格。
_MAX_IMAGE_FILE_BYTES = 64 * 1024 * 1024
_MAX_IMAGE_PIXELS = 100_000_000
# 几何候选穷举用掉的预算比例上限（见 _geometry_search_budget_exhausted）。
_GEOMETRY_SEARCH_BUDGET_FRACTION = 0.70
# 几何候选穷举是否因为预算提前收尾（见 _note_geometry_search_truncated）。
_GEOMETRY_SEARCH_TRUNCATED = False
# 本次请求**开始时**选定的内存档位（见 _require_recognition_memory_headroom）。
# 与模块级的 _ACTIVE_RECOGNITION_MEMORY_MODE 分开：后者是"此刻"的档位，
# 请求中途可能变；这里要的是"这次识别实际用的那一档"。
_REQUEST_MEMORY_MODE = "unknown"
_budget_enabled = not os.environ.get("OCRTABLE_BUDGET_DISABLED", "").strip()
_request_started_at = 0.0
# 墙钟是**每个请求**的契约，不是进程 lifetime 的。2026-10-22 加检查点时漏了
# 这个作用域：_request_started_at 只在请求入口赋值、请求结束**不复位**，于是
# 请求结束后再调几何函数（单测直调引擎、后台预热）会拿上一次请求留下的
# 起始时间算差值 —— 上一次请求跑了 73 秒，这次就报"识别已用 73 秒"，
# 把 1300 项单测里的 5 项打成 error。
# 现在显式记录"当前是否有活跃请求"，没有活跃请求就**不计时**。
_request_active = False
# 本次请求的**实际预算秒数**（默认 = 60 秒契约上限；客户端传了
# deadline_seconds 时按更小的那个收口）。几何候选穷举的收尾线按它算，
# 否则"传 5 秒快速失败"的承诺完全落空
# （findings/10-input-robustness.md F-02：实测传 5 秒仍跑 42.91 秒）。
_request_budget_seconds = _MAX_REQUEST_SECONDS
# 逐格复核的**图片总量**上限。628 例实测：正常情况下 medium 收到的图片数
# 只有真值格数的 1.01 倍，每格一次复核，不浪费；但网格切错时会形成正反馈 ——
# 碎片越碎要复核的格越多，FC-00965 只有 65 格却送了 1603 张（24.7 倍，
# 335 秒），FC-00324 462 格送了 2271 张（819 秒）。这些例的准确率本来就
# 接近 0（0.00~0.17），多送的图没换来任何准确率，只是白烧 300~800 秒。
#
# 800 张足够覆盖 700 格以内的表按「每格一次」复核（实测最大的正常例约
# 460 格），同时把失控的正反馈截断在可接受范围内。
#
# 2026-10-19 上调到 1600：原值按「每格一次」立论，但复核倍数不是常数。
# FC-00041 真值 286 格、正反馈下送了 787 张（2.75 倍），在 800 这道线上
# 被误杀 —— 放宽后 32 秒跑完、形状 26x11 全对、逐格 0.895，落在 60 秒
# 契约之内。也就是说这道闸门当时拦下的是一张 0.895 的表，而不只是失控例。
# 上限只负责「无界的正反馈」，**边界仍然是墙钟**：墙钟在每批识别前检查、
# 并按已观测的单图耗时前瞻估算本批要多久，所以放宽图片数不会让任何一张
# 跑超过 60 秒。失控例（FC-00965 65 格送 1603 张、FC-00324 462 格送
# 2271 张）准确率本来就接近 0，多送的图没换来任何准确率，只是被墙钟多
# 留在 60 秒而不是被图片数提前截断——放宽上限换来的是 2 例真实结果。
_MAX_FINE_GRAINED_IMAGES = 1600
_fine_grained_images = 0
# 这两个计数器必须**在模块级就存在**：它们被 global 声明的函数随时可能读写，
# 而 _begin_request_budget() 只在 handle_request 入口调用。任何在请求
# 之外发生的细粒度识别（单测直接调引擎、后台预热）都会因为
# "_fine_grained_seconds is not defined" 抛 NameError，把一次正常的识别
# 变成崩溃。之前只初始化了 _fine_grained_images，漏了 _fine_grained_seconds。
_fine_grained_seconds = 0.0
# 外层逐格成本（裁格 + 3.2 倍 LANCZOS4 放大 + CLAHE + 低内存档 Small/Medium
# 模型重建）**不进**细粒度计数器，前瞻估算只用内层 OpenVINO infer 耗时，
# 于是估算值系统性偏低，注定超时的批次被放行。2026-10-22 实测 FC-00026：
# 外层 "v6-small-complete-ruled-lines n=32" 1.924 秒，而内层 "v6-small n=32"
# 只有 0.794 秒 —— 59% 的逐格成本没进估算，FC-00016 因此冲到 102.7 秒
# （超 60 秒契约 71%）。这里单独记外层口径，供前瞻估算取两者较大值。
_outer_recognition_seconds = 0.0
_outer_recognition_images = 0


def _begin_request_budget() -> None:
    global _request_started_at, _fine_grained_seconds, _fine_grained_images
    global _request_budget_seconds
    global _outer_recognition_seconds, _outer_recognition_images
    global _table_structure_engine_failure
    global _request_active
    global _GEOMETRY_SEARCH_TRUNCATED
    global _REQUEST_MEMORY_MODE
    _request_started_at = time.perf_counter()
    _request_active = True
    _request_budget_seconds = _MAX_REQUEST_SECONDS
    _GEOMETRY_SEARCH_TRUNCATED = False
    _REQUEST_MEMORY_MODE = "unknown"
    _fine_grained_seconds = 0.0
    _fine_grained_images = 0
    _outer_recognition_seconds = 0.0
    _outer_recognition_images = 0
    _table_structure_engine_failure = None
    # 把墙钟探针交给 pipeline：网格重提取、屏幕网格检测、透视矫正、图像
    # 预处理这些重活全在 table_pipeline 里，ocr_backend 逐个调用点插检查点
    # 既漏又难维护（2026-10-22 就漏了「快速纠偏结束 → 边缘恢复开始」之间
    # 那 23 秒），由 pipeline 在每个重活入口回调一次探针，新调用点自动受管。
    if pipeline is not None:
        pipeline.set_budget_probe(_check_request_wall_clock)


def _end_request_budget() -> None:
    """请求结束：墙钟计时随之失效。

    之前只有 _begin_request_budget()、没有对称的收尾，于是请求结束后
    _request_started_at 仍指向那次请求的开始时刻。任何在请求之外发生的
    调用（单测直调引擎、后台预热、几何候选筛选）都会拿这个陈旧起点算
    差值，把"上次请求花了 73 秒"误判成"本次已用 73 秒"。
    """
    global _request_started_at, _request_active
    global _request_budget_seconds
    _request_active = False
    _request_started_at = 0.0
    _request_budget_seconds = _MAX_REQUEST_SECONDS
    if pipeline is not None:
        pipeline.set_budget_probe(None)


def _record_outer_recognition_cost(seconds: float, images: int) -> None:
    """记录外层逐格开销（裁格 / 放大 / 增强 / 模型重建）。"""
    global _outer_recognition_seconds, _outer_recognition_images
    if seconds <= 0.0:
        return
    _outer_recognition_seconds += float(seconds)
    _outer_recognition_images += int(images)


def _caller_name(depth: int) -> str:
    try:
        return sys._getframe(depth).f_code.co_name
    except (ValueError, AttributeError):
        return "unknown"


def _record_recognition_call(
    model_name: str,
    batch_size: int,
    duration: float,
    status: str,
) -> None:
    global _fine_grained_seconds, _fine_grained_images
    if model_name in _FINE_GRAINED_RECOGNITION_MODELS:
        _fine_grained_seconds += duration
        _fine_grained_images += batch_size
    totals = _runtime_trace_model_totals.setdefault(
        model_name, {"calls": 0, "images": 0, "seconds": 0.0}
    )
    totals["calls"] = int(totals["calls"]) + 1
    totals["images"] = int(totals["images"]) + batch_size
    totals["seconds"] = float(totals["seconds"]) + duration
    _write_runtime_trace(
        "model_end",
        model=model_name,
        images=batch_size,
        duration_seconds=round(duration, 3),
        status=status,
    )


def _timed_recognition_call(
    model_name: str,
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    batch_size = _recognition_batch_size(args, kwargs)
    fine_grained = model_name in _FINE_GRAINED_RECOGNITION_MODELS
    if _budget_enabled:
        _enforce_request_budget(model_name, batch_size, fine_grained)
    # A model call can block for minutes on a dense table. Publish the start
    # event immediately so the external monitor shows the real active stage.
    _write_runtime_trace(
        "model_start",
        force_flush=True,
        model=model_name,
        images=batch_size,
        caller=_caller_name(3),
        **_recognition_batch_geometry(args, kwargs),
    )
    started = time.perf_counter()
    status = "ok"
    try:
        return _normalize_recognition_output(recognizer(*args, **kwargs))
    except Exception:
        status = "error"
        raise
    finally:
        duration = max(0.0, time.perf_counter() - started)
        _record_recognition_call(model_name, batch_size, duration, status)


def _effective_request_limit_seconds() -> float:
    """本次请求真正生效的墙钟上限 = min(60 秒契约, 请求自带 deadline 预算)。

    2026-10-23（findings 103 / FINAL-REPORT §六·E P1-1）：客户传
    ``options.deadline_seconds = 5`` 实测仍跑满 ~58 秒。原因是
    ``_request_budget_seconds`` 只被几何穷举收尾线用到（见
    ``_geometry_search_budget_exhausted``），而**所有真正会中止请求的检查点**
    （``_enforce_request_budget`` 的模型入口判定、``_check_request_wall_clock``
    的几何/解码/结构阶段判定）一律硬比较 ``_MAX_REQUEST_SECONDS``（60 秒），
    请求级 deadline 完全没参与中止判定 —— 于是"传 5 秒快速失败"的承诺落空，
    那个 5 秒只体现在响应字段 ``deadline_seconds`` 上。

    这里只**收紧、不放宽**：
    - ``deadline_seconds <= 0``（GUI 正式集成固定传 0）→ 预算解析成
      ``_HARD_RECOGNITION_CEILING_SECONDS``（120 秒，语义仍是"不额外收紧"）
      → ``min(60, 120) = 60``，与改动前逐秒一致；
    - 非法值已由 ``_recognize`` 收口到 ``min(原预算, 60)``（见 F-07），
      所以这里同样只会得到 <= 60 的值；
    - 只有客户显式传了更小的 ``deadline_seconds`` 时才会小于 60，即
      "客户要求的时限更短"这一种情况，正好是该生效的情况。
    """
    contract = _MAX_REQUEST_SECONDS
    try:
        budget = float(_request_budget_seconds)
    except (TypeError, ValueError):
        return contract
    if not math.isfinite(budget) or budget <= 0.0:
        return contract
    return min(contract, budget)


def _enforce_request_budget(
    model_name: str,
    batch_size: int,
    fine_grained: bool,
) -> None:
    """Raise _FineGrainedBudgetExceeded before a call that cannot finish in time."""
    global _fine_grained_seconds, _fine_grained_images
    # 墙钟预算对所有模型生效：真正让单例失控的是"这张表要算多久"，
    # 而不是"哪几个模型在算"。
    # 判定线取 min(60 秒契约, 请求级 deadline 预算)，见
    # _effective_request_limit_seconds()。
    limit = _effective_request_limit_seconds()
    spent = (time.perf_counter() - _request_started_at) if _request_started_at else 0.0
    if spent >= limit:
        _write_runtime_trace(
            "model_budget_exceeded",
            force_flush=True,
            model=model_name,
            caller=_caller_name(3),
            reason="wall_clock",
            spent_seconds=round(spent, 3),
            limit_seconds=round(limit, 3),
            request_budget_seconds=round(float(_request_budget_seconds), 3),
            fine_grained_images=_fine_grained_images,
        )
        raise _FineGrainedBudgetExceeded(
            "逐格复核已用 %.0f 秒仍未完成，判定表格结构过于复杂或存在干扰网格" % spent
        )
    if fine_grained:
        # 预算要**预留余量**：检查通过之后的那一次批量调用本身还要跑几秒到
        # 几十秒，直接用「已经花了多少」当阈值，实测 wall 会冲到 62~124 秒。
        # 用已观测的单图耗时估算这一批要多久。初值要贴近真实：细粒度调用里
        # 大头是 v6-small（实测约 0.07 秒/张），medium 才 0.22 秒/张，
        # 一律按 0.15 秒估会把 300 张的一批高估成 45 秒、进而提前拒掉
        # 本来 20 秒就能跑完的表。
        per_image = (
            _fine_grained_seconds / _fine_grained_images
            if _fine_grained_images
            else 0.08
        )
        # 外层口径：裁格 / 3.2 倍放大 / CLAHE / 低内存档模型重建都算在逐格成本里。
        # 取两者较大值只会让前瞻估算更保守（更早截断），不会放宽任何上限。
        if _outer_recognition_images:
            per_image = max(
                per_image,
                _outer_recognition_seconds / _outer_recognition_images,
            )
        estimate = batch_size * max(0.02, per_image)
        if spent + estimate >= limit:
            _write_runtime_trace(
                "model_budget_exceeded",
                force_flush=True,
                model=model_name,
                caller=_caller_name(3),
                reason="wall_clock_with_lookahead",
                spent_seconds=round(spent, 3),
                estimate_seconds=round(estimate, 3),
                limit_seconds=round(limit, 3),
                request_budget_seconds=round(float(_request_budget_seconds), 3),
                fine_grained_images=_fine_grained_images,
            )
            raise _FineGrainedBudgetExceeded(
                "逐格复核预计需 %.0f 秒（已用 %.0f 秒，本批 %d 张约 %.0f 秒），"
                "判定表格结构过于复杂或存在干扰网格" % (spent + estimate, spent,
                                                  batch_size, estimate)
            )
    if fine_grained and _fine_grained_images + batch_size > _MAX_FINE_GRAINED_IMAGES:
        _write_runtime_trace(
            "model_budget_exceeded",
            force_flush=True,
            model=model_name,
            caller=_caller_name(3),
            reason="image_volume",
            spent_seconds=round(spent, 3),
            fine_grained_images=_fine_grained_images,
            batch_size=batch_size,
        )
        raise _FineGrainedBudgetExceeded(
            "逐格复核累计送识别的图片已达 %d 张，判定网格切分异常、同一批单元格被"
            "反复复核" % _fine_grained_images
        )


def _geometry_search_budget_exhausted() -> bool:
    """几何候选穷举是否该收尾。

    60 秒契约里，识别（模型推理）通常要占 20~30 秒，留给几何搜索的不多。
    而候选展开是**穷举**：为了多恢复一行，最多要试 7 组 x 2 = 14 次全分辨率
    透视矫正 + 网格重提取，单次约 2 秒（FC-00016 实测这一段 29 秒）。
    预算用掉大半还继续穷举，结果只有一个 —— 撞墙钟，整次识别失败，
    错误码 RECOGNITION_BUDGET_EXCEEDED，客户拿到的是一句"识别失败"。

    与其失败，不如用**已经找到的**候选收尾：把"超时"换成"少一行"。
    触发线定在 70%（42 秒）：正常完成的用例几何阶段远低于这个数，
    受影响的只有本来就跑不完的用例 —— 它们现在的结果是错误，不是结果。

    只在活跃请求内生效（单测直调引擎时没有请求，不该被这条线拦下）。
    """
    if not _budget_enabled or not _request_active:
        return False
    started = _request_started_at
    if not started:
        return False
    spent = time.perf_counter() - started
    # 2026-10-23：这条收尾线原来硬编码 60×0.70=42 秒，与请求自带的
    # deadline_seconds 无关（findings/10 F-02：传 5 秒实测仍跑 42.91 秒，
    # 传 30 秒跑 41.30 秒，两个都贴着 42 秒这条线）。现在按本次请求的
    # 实际预算收口：min(60 秒契约, 本次预算)×0.70。
    # **只收得更紧，绝不更松** —— 默认预算 120 秒 → min(60,120)=60 → 42 秒，
    # 与改动前逐秒一致。判定线口径与中止检查点统一到
    # _effective_request_limit_seconds()，避免两处各算一套。
    limit = _effective_request_limit_seconds()
    return spent >= limit * _GEOMETRY_SEARCH_BUDGET_FRACTION


def _note_geometry_search_truncated() -> None:
    """记下"几何候选穷举因预算提前收尾"。

    收尾之后如果整条流水线仍然没能确认表格结构，报错必须说"预算用完了"，
    不能说"没检测到表格" —— 后者会把用户引到"照片不清晰"这种错误方向上。
    2026-10-22 实测 FC-00020：收尾前报的是"逐格复核预计需 62 秒"，
    收尾后却报"未检测到可识别的表格"，后者是误导。
    """
    global _GEOMETRY_SEARCH_TRUNCATED
    _GEOMETRY_SEARCH_TRUNCATED = True


def _check_request_wall_clock(stage: str) -> None:
    """墙钟检查点下沉到几何阶段。

    2026-10-22 实测（31 例）：3 例超 60 秒 —— FC-00016 102.7 秒、FC-00031
    93.5 秒、FC-00029 72.9 秒，超契约最多 71%。根因是墙钟**只在模型调用入口**
    检查，解码 / 纠偏 / 边缘恢复 / 后处理阶段一个检查点都没有：FC-00016 的
    前置几何就花了 24.0 秒（解码 5.11 + 矫正 8.98 + 边缘恢复 5.41），这 24 秒
    全在计时之外。

    这里只**收紧**、不放宽：超时仍然抛 _FineGrainedBudgetExceeded，错误码与
    原来完全一致（RECOGNITION_BUDGET_EXCEEDED），只是把发现时刻从"识别跑完"
    提前到"几何阶段就超了"。

    判定线取 min(60 秒契约, 请求级 deadline 预算)。2026-10-23 之前这里硬比较
    60 秒，客户传 ``deadline_seconds = 5`` 的请求在这个检查点上照样放行到 60 秒
    （findings 103 / FINAL-REPORT §六·E P1-1）。``deadline_seconds <= 0`` 时
    预算解析成 120 秒，min 后仍是 60 秒，60 秒墙钟契约一秒不变。
    """
    if not _budget_enabled or not _request_active:
        return
    limit = _effective_request_limit_seconds()
    spent = (time.perf_counter() - _request_started_at) if _request_started_at else 0.0
    if spent < limit:
        return
    _write_runtime_trace(
        "model_budget_exceeded",
        force_flush=True,
        model=stage,
        caller=_caller_name(2),
        reason="wall_clock_stage",
        spent_seconds=round(spent, 3),
        limit_seconds=round(limit, 3),
        request_budget_seconds=round(float(_request_budget_seconds), 3),
        fine_grained_images=_fine_grained_images,
    )
    raise _FineGrainedBudgetExceeded(
        "识别已用 %.0f 秒仍未完成（阶段：%s），判定表格结构过于复杂或存在干扰网格"
        % (spent, stage)
    )


def _begin_recognition_evidence() -> None:
    global _recognition_evidence_active, _recognition_evidence_cache
    global _ordered_batch_evidence_cache
    global _ordered_batch_evidence_hits, _ordered_batch_evidence_misses
    global _page_evidence_cache, _page_evidence_hits, _page_evidence_misses
    global _recognition_evidence_hits, _recognition_evidence_misses
    _recognition_evidence_active = True
    _recognition_evidence_cache = {}
    _ordered_batch_evidence_cache = {}
    _page_evidence_cache = {}
    _recognition_evidence_hits = 0
    _recognition_evidence_misses = 0
    _ordered_batch_evidence_hits = 0
    _ordered_batch_evidence_misses = 0
    _page_evidence_hits = 0
    _page_evidence_misses = 0


def _finish_recognition_evidence() -> None:
    global _recognition_evidence_active, _recognition_evidence_cache
    global _ordered_batch_evidence_cache
    global _page_evidence_cache
    _recognition_evidence_active = False
    # Only text and scores are cached, but release them between requests so a
    # long-running tablet session has a fixed per-image memory lifetime.
    _recognition_evidence_cache = {}
    _ordered_batch_evidence_cache = {}
    _page_evidence_cache = {}


def _image_evidence_key(model_name: str, image: Any) -> tuple[Any, ...] | None:
    if image is None or not hasattr(image, "shape") or not hasattr(image, "dtype"):
        return None
    try:
        contiguous = np.ascontiguousarray(image)
        digest = hashlib.blake2b(
            memoryview(contiguous), digest_size=16
        ).digest()
        return (
            model_name,
            tuple(int(value) for value in contiguous.shape),
            str(contiguous.dtype),
            digest,
        )
    except (TypeError, ValueError, BufferError):
        return None


def _page_output_from_evidence(
    evidence: tuple[Any, Any, Any], evidence_key: tuple[Any, ...]
) -> SimpleNamespace:
    boxes, texts, scores = evidence
    return SimpleNamespace(
        boxes=copy.deepcopy(boxes),
        txts=copy.deepcopy(texts),
        scores=copy.deepcopy(scores),
        imgs=None,
        _evidence_key=evidence_key,
    )


def _cached_page_recognition_call(
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    global _page_evidence_hits, _page_evidence_misses
    if not _recognition_evidence_active or len(args) != 1 or kwargs:
        return _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    image = args[0]
    key = _image_evidence_key("page-mobile", image)
    if key is None:
        return _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    cached = _page_evidence_cache.get(key)
    if cached is not None:
        _page_evidence_hits += 1
        return _page_output_from_evidence(cached, key)

    _page_evidence_misses += 1
    output = _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    _release_recognition_images(output)
    setattr(output, "_evidence_key", key)
    if all(hasattr(output, name) for name in ("boxes", "txts", "scores")):
        _page_evidence_cache[key] = (
            copy.deepcopy(output.boxes),
            copy.deepcopy(output.txts),
            copy.deepcopy(output.scores),
        )
    return output


def _cached_text_recognition_call(
    model_name: str,
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    global _recognition_evidence_hits, _recognition_evidence_misses
    global _ordered_batch_evidence_hits, _ordered_batch_evidence_misses
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if (
        not _recognition_evidence_active
        or images is None
        or bool(getattr(recognition_input, "return_word_box", False))
        or len(args) > 1
        or bool(kwargs)
    ):
        return _timed_recognition_call(model_name, recognizer, args, kwargs)
    if hasattr(images, "shape") and hasattr(images, "dtype"):
        image_list = [images]
    else:
        try:
            image_list = list(images)
        except TypeError:
            return _timed_recognition_call(model_name, recognizer, args, kwargs)
    if not image_list:
        return _timed_recognition_call(model_name, recognizer, args, kwargs)

    keys = [_image_evidence_key(model_name, image) for image in image_list]
    if any(key is None for key in keys):
        return _timed_recognition_call(model_name, recognizer, args, kwargs)

    # Mobile and Medium normalize each image against the widest neighbour in
    # their internal batch. Reuse is safe only when the entire ordered batch is
    # byte-for-byte identical; never remove cached members or rebuild the batch.
    if int(getattr(recognizer, "rec_batch_num", 0) or 0) != 1:
        batch_key = ("ordered_batch", model_name, tuple(keys))
        cached_batch = _ordered_batch_evidence_cache.get(batch_key)
        if cached_batch is not None:
            _ordered_batch_evidence_hits += 1
            texts, scores = cached_batch
            return SimpleNamespace(
                txts=list(texts), scores=list(scores), imgs=None
            )
        _ordered_batch_evidence_misses += 1
        output = _timed_recognition_call(model_name, recognizer, args, kwargs)
        _release_recognition_images(output)
        output_texts = [str(text) for text in output.txts]
        output_scores = [float(score) for score in output.scores]
        if (
            len(output_texts) == len(image_list)
            and len(output_scores) == len(image_list)
        ):
            _ordered_batch_evidence_cache[batch_key] = (
                output_texts,
                output_scores,
            )
        return output

    texts = [""] * len(image_list)
    scores = [0.0] * len(image_list)
    missing_positions: list[int] = []
    positions_by_missing_key: dict[tuple[Any, ...], list[int]] = {}
    for position, key in enumerate(keys):
        cached = _recognition_evidence_cache.get(key)
        if cached is None:
            matching_positions = positions_by_missing_key.setdefault(key, [])
            matching_positions.append(position)
            if len(matching_positions) == 1:
                missing_positions.append(position)
                _recognition_evidence_misses += 1
            else:
                # Identical cells can occur repeatedly in one table. They are
                # the same model evidence, so infer the pixels once and fan the
                # exact result back out to every matching position.
                _recognition_evidence_hits += 1
        else:
            texts[position], scores[position] = cached
            _recognition_evidence_hits += 1

    if missing_positions:
        missing_images = [image_list[position] for position in missing_positions]
        try:
            missing_input = type(recognition_input)(img=missing_images)
        except (TypeError, ValueError):
            return _timed_recognition_call(model_name, recognizer, args, kwargs)
        if args:
            missing_args = (missing_input, *args[1:])
            missing_kwargs = kwargs
        else:
            missing_args = ()
            missing_kwargs = dict(kwargs)
            missing_kwargs["input"] = missing_input
        output = _timed_recognition_call(
            model_name, recognizer, missing_args, missing_kwargs
        )
        output_texts = [str(text) for text in output.txts]
        output_scores = [float(score) for score in output.scores]
        _release_recognition_images(output)
        if (
            len(output_texts) != len(missing_positions)
            or len(output_scores) != len(missing_positions)
        ):
            # Preserve the recognizer's original full-batch contract if a
            # backend ever returns an unexpected result length.
            return _timed_recognition_call(
                model_name, recognizer, args, kwargs
            )
        for source_position, text, score in zip(
            missing_positions, output_texts, output_scores
        ):
            key = keys[source_position]
            _recognition_evidence_cache[key] = (text, score)
            for position in positions_by_missing_key[key]:
                texts[position] = text
                scores[position] = score

    return SimpleNamespace(txts=texts, scores=scores, imgs=None)


_HARD_RECOGNITION_CEILING_SECONDS = 120.0


class _RecognitionBudget:
    """Monotonic per-image budget.

    ``deadline_seconds <= 0`` 过去表示"完全不设限"，最高质量模式下修复轮次
    可以无限串联，实测出现过单张图 300 秒无响应，与交付标准（单张 ≤25s）和
    README 的说法直接冲突。现在即使调用方不传时限，也保留与显式时限相同的
    硬上限：预算耗尽后停止追加证据并走安全回退，而不是把界面挂死。
    """

    def __init__(
        self,
        seconds: float,
        clock: Any = None,
        hard_ceiling: float = _HARD_RECOGNITION_CEILING_SECONDS,
    ):
        requested_seconds = float(seconds)
        self.unlimited = requested_seconds <= 0.0
        self.seconds = (
            float(hard_ceiling)
            if self.unlimited
            else max(1.0, min(float(hard_ceiling), requested_seconds))
        )
        self._clock = clock or time.monotonic
        self._started = self._clock()
        self._deadline = self._started + self.seconds
        self.limited = False

    def elapsed(self) -> float:
        return max(0.0, self._clock() - self._started)

    def remaining(self) -> float:
        return max(0.0, self._deadline - self._clock())

    def allow(self, minimum_remaining: float = 0.0) -> bool:
        allowed = self.remaining() >= max(0.0, float(minimum_remaining))
        if not allowed:
            self.limited = True
        return allowed

    def reached(self) -> bool:
        return self.remaining() <= 0.0

