_MEDIUM_RECOGNITION_BATCH_SIZE = 16
_SERVER_RECOGNITION_BATCH_SIZE = 8
# 只在 Python 调用边界聚合请求，模型内部批大小仍由上面的常量控制。
# 这样可减少逐单元格调用开销，同时保持图片顺序、模型配置和识别证据不变。
_RECOGNITION_CALL_GROUP_SIZE = 32
_RECOGNITION_LOGICAL_PROCESSORS = max(1, os.cpu_count() or 1)
_RECOGNITION_INFERENCE_THREADS = min(6, _RECOGNITION_LOGICAL_PROCESSORS)
_ACTIVE_RECOGNITION_MEMORY_MODE = "normal"


def _configure_recognition_memory_mode(low_memory: bool) -> None:
    """低内存只降低并发和批大小，不减少任何识别或复核步骤。"""
    global _MEDIUM_RECOGNITION_BATCH_SIZE
    global _SERVER_RECOGNITION_BATCH_SIZE
    global _RECOGNITION_CALL_GROUP_SIZE
    global _RECOGNITION_INFERENCE_THREADS
    global _ACTIVE_RECOGNITION_MEMORY_MODE
    next_mode = "low_memory" if low_memory else "normal"
    if _ACTIVE_RECOGNITION_MEMORY_MODE != next_mode:
        release = getattr(_ocr_engine, "release_for_table_structure", None)
        if callable(release):
            release()
    if low_memory:
        _MEDIUM_RECOGNITION_BATCH_SIZE = 4
        _SERVER_RECOGNITION_BATCH_SIZE = 4
        _RECOGNITION_CALL_GROUP_SIZE = 8
        _RECOGNITION_INFERENCE_THREADS = min(4, _RECOGNITION_LOGICAL_PROCESSORS)
        _ACTIVE_RECOGNITION_MEMORY_MODE = "low_memory"
    else:
        _MEDIUM_RECOGNITION_BATCH_SIZE = 16
        _SERVER_RECOGNITION_BATCH_SIZE = 8
        _RECOGNITION_CALL_GROUP_SIZE = 32
        _RECOGNITION_INFERENCE_THREADS = min(6, _RECOGNITION_LOGICAL_PROCESSORS)
        _ACTIVE_RECOGNITION_MEMORY_MODE = "normal"


def _adaptive_wide_detector_limit(image: Any, configured_limit: int) -> int:
    """约束检测器的额外放大，避免小图被扩成数百万像素的输入。"""
    if not hasattr(image, "shape") or len(image.shape) < 2:
        return int(configured_limit)
    height, width = image.shape[:2]
    aspect = max(height, width) / float(max(1, min(height, width)))
    upscaled_limit = int(math.floor(math.sqrt(2_500_000.0 / aspect)))
    if aspect >= 2.4:
        upscaled_limit = min(upscaled_limit, int(math.floor(2880.0 / aspect)))
    return min(int(configured_limit), max(320, upscaled_limit))


def model_directory() -> Path:
    configured = os.environ.get("OCR_TABLE_MODEL_DIR")
    if configured:
        return Path(configured).expanduser().resolve()
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent / "models"

    roots = (Path(__file__).resolve().parent, Path(sys.executable).resolve().parent, Path.cwd().resolve())
    for root in roots:
        for directory in (root, *root.parents):
            candidate = directory / "runtime" / "models"
            if candidate.is_dir():
                return candidate
    return Path(__file__).resolve().parents[1] / "runtime" / "models"


def build_ocr_parameters(models: Path) -> dict[str, Any]:
    from rapidocr import EngineType, LangDet, LangRec, ModelType, OCRVersion

    return {
        "Global.model_root_dir": str(models),
        "Global.max_side_len": 2400,
        "EngineConfig.openvino.inference_num_threads": _RECOGNITION_INFERENCE_THREADS,
        "EngineConfig.openvino.performance_hint": "LATENCY",
        "EngineConfig.openvino.num_streams": 1,
        "EngineConfig.openvino.enable_hyper_threading": False,
        "Det.engine_type": EngineType.OPENVINO,
        "Det.lang_type": LangDet.CH,
        "Det.model_type": ModelType.MEDIUM,
        "Det.ocr_version": OCRVersion.PPOCRV6,
        "Det.limit_side_len": 1280,
        "Det.model_path": str(models / "PP-OCRv6_det_medium.xml"),
        "Cls.engine_type": EngineType.OPENVINO,
        "Cls.cls_batch_num": 8,
        "Rec.engine_type": EngineType.OPENVINO,
        "Rec.lang_type": LangRec.CH,
        "Rec.model_type": ModelType.MEDIUM,
        "Rec.ocr_version": OCRVersion.PPOCRV6,
        "Rec.rec_batch_num": _MEDIUM_RECOGNITION_BATCH_SIZE,
        "Rec.model_path": str(models / "PP-OCRv6_rec_medium.xml"),
        "Cls.model_path": str(models / "ch_ppocr_mobile_v2.0_cls_mobile.xml"),
    }


def build_fast_ocr_parameters(models: Path) -> dict[str, Any]:
    """整页主读使用 V6 Small；最终风险格仍交给 V6 Medium。"""
    from rapidocr import LangRec, ModelType, OCRVersion

    parameters = build_ocr_parameters(models)
    parameters.update(
        {
            "Rec.lang_type": LangRec.CH,
            "Rec.model_type": ModelType.SMALL,
            "Rec.ocr_version": OCRVersion.PPOCRV6,
            "Rec.model_path": str(models / "PP-OCRv6_rec_small.xml"),
        }
    )
    return parameters


def build_server_ocr_parameters(models: Path) -> dict[str, Any]:
    """兼容旧配置入口；生产运行仍只加载 PP-OCRv6 Medium。"""
    parameters = build_ocr_parameters(models)
    parameters["Rec.rec_batch_num"] = _SERVER_RECOGNITION_BATCH_SIZE
    return parameters


def _parallel_text_recognizer(recognizer: Any, request_count: int) -> Any:
    try:
        from recognition_scheduler import build_parallel_text_recognizer
    except ImportError:
        from .recognition_scheduler import build_parallel_text_recognizer
    return build_parallel_text_recognizer(
        recognizer,
        request_count=request_count,
    )


class _ConsistentPageTextClassifier:
    """用整页长文本的强方向证据约束短文本的弱方向翻转。"""

    def __init__(self, classifier: Any):
        self._classifier = classifier

    def __getattr__(self, name: str) -> Any:
        return getattr(self._classifier, name)

    @property
    def cls_thresh(self) -> float:
        return self._classifier.cls_thresh

    @cls_thresh.setter
    def cls_thresh(self, value: float) -> None:
        self._classifier.cls_thresh = value

    def __call__(self, images: Any) -> Any:
        originals = [images] if isinstance(images, np.ndarray) else images
        output = self._classifier(images)
        predictions = output.cls_res or []
        votes = Counter(
            str(angle) for crop, (angle, score) in zip(originals, predictions)
            if str(angle) in {"0", "180"} and float(score) >= 0.98
            and crop.shape[1] / max(1.0, float(crop.shape[0])) >= 2.5
        )
        if sum(votes.values()) < 8 or len(votes) != 1:
            return output
        dominant, count = votes.most_common(1)[0]
        corrected = []
        for index, (crop, (angle, score)) in enumerate(zip(originals, predictions)):
            if (str(angle) not in {"0", "180"} or float(score) >= 0.98
                    or crop.shape[1] / max(1.0, float(crop.shape[0])) > 2.0):
                continue
            applied = "180" if str(angle) == "180" and float(score) > self.cls_thresh else "0"
            if applied != dominant:
                output.img_list[index] = (
                    cv2.rotate(crop, cv2.ROTATE_180) if dominant == "180" else crop.copy()
                )
                corrected.append(index)
        if corrected:
            _write_runtime_trace("page_orientation_consensus", angle=dominant,
                                 anchors=count, corrected_indices=corrected)
        return output


class _BoundedPageTextDetector:
    def __init__(self, detector: Any):
        self._detector = detector

    def __getattr__(self, name: str) -> Any:
        return getattr(self._detector, name)

    @property
    def limit_side_len(self) -> int:
        return self._detector.limit_side_len

    @limit_side_len.setter
    def limit_side_len(self, value: int) -> None:
        self._detector.limit_side_len = value

    def __call__(self, image: np.ndarray) -> Any:
        height, width = image.shape[:2]
        if height * width <= 2_500_000 or not _has_photographic_background(image):
            return self._detector(image)
        scale = math.sqrt(2_500_000.0 / (height * width))
        resized = cv2.resize(image, (int(width * scale), int(height * scale)),
                             interpolation=cv2.INTER_AREA)
        output = self._detector(resized)
        if output.boxes is not None:
            boxes = np.asarray(output.boxes, dtype=np.float32)
            boxes *= np.asarray([width / resized.shape[1],
                                 height / resized.shape[0]], dtype=np.float32)
            output.boxes = boxes
            output.img = image
        return output


def _install_page_detector_budget(engine: Any) -> None:
    detector = getattr(engine, "text_det", None)
    if (callable(detector) and isinstance(getattr(detector, "limit_side_len", None), (int, float))
            and not isinstance(detector, _BoundedPageTextDetector)):
        engine.text_det = _BoundedPageTextDetector(detector)


def _install_page_orientation_consensus(engine: Any) -> None:
    classifier = getattr(engine, "text_cls", None)
    if (callable(classifier) and isinstance(getattr(classifier, "cls_thresh", None), (int, float))
            and not isinstance(classifier, _ConsistentPageTextClassifier)):
        engine.text_cls = _ConsistentPageTextClassifier(classifier)


class _HybridOcrEngine:
    """V6 Small 整页主读，V6 Medium 只复核已选择的风险格。"""

    def __init__(
        self,
        page_engine: Any,
        verification_recognizer: Any = None,
        page_layout_factory: Any = None,
        verification_factory: Any = None,
        page_recognition_factory: Any = None,
    ):
        self._page_engine = page_engine
        _install_page_detector_budget(self._page_engine)
        _install_page_orientation_consensus(self._page_engine)
        self._verification_recognizer = verification_recognizer
        self._page_layout_factory = page_layout_factory
        self._verification_factory = verification_factory
        self._page_recognition_factory = page_recognition_factory
        self._page_recognition_profile: dict[str, Any] | None = None
        self._verification_profile: dict[str, Any] | None = None

    def release_page_layout_models(self) -> bool:
        """逐格复核期间释放不再使用的整页检测与方向分类模型。"""
        if self._page_layout_factory is None:
            return False
        if (
            getattr(self._page_engine, "text_det", None) is None
            and getattr(self._page_engine, "text_cls", None) is None
        ):
            return False
        text_det = getattr(self._page_engine, "text_det", None)
        text_cls = getattr(self._page_engine, "text_cls", None)
        self._page_engine.text_det = None
        self._page_engine.text_cls = None
        _dispose_openvino_component(text_det)
        _dispose_openvino_component(text_cls)
        gc.collect()
        return True

    def _ensure_page_layout_models(self) -> None:
        if (
            getattr(self._page_engine, "text_det", None) is not None
            and getattr(self._page_engine, "text_cls", None) is not None
        ):
            return
        if self._page_layout_factory is None:
            raise RuntimeError("整页检测模型已释放且无法恢复。")
        text_det, text_cls = self._page_layout_factory()
        self._page_engine.text_det = text_det
        self._page_engine.text_cls = text_cls
        _install_page_detector_budget(self._page_engine)
        _install_page_orientation_consensus(self._page_engine)

    @staticmethod
    def _scheduler_profile(recognizer: Any) -> dict[str, Any]:
        if recognizer is None:
            return {
                "scheduler": "lazy-not-loaded",
                "requests": 0,
                "recognition_batch_size": _MEDIUM_RECOGNITION_BATCH_SIZE,
            }
        scheduler_profile = getattr(recognizer, "execution_profile", None)
        if callable(scheduler_profile):
            return scheduler_profile()
        return {
            "scheduler": "rapidocr-synchronous",
            "requests": 1,
            "recognition_batch_size": int(
                getattr(recognizer, "rec_batch_num", _MEDIUM_RECOGNITION_BATCH_SIZE)
            ),
        }

    def _release_page_recognizer(self) -> bool:
        recognizer = getattr(self._page_engine, "text_rec", None)
        if self._page_recognition_factory is None or recognizer is None:
            return False
        self._page_recognition_profile = self._scheduler_profile(recognizer)
        self._page_engine.text_rec = None
        _dispose_openvino_component(recognizer)
        gc.collect()
        return True

    def _ensure_page_recognizer(self) -> Any:
        recognizer = getattr(self._page_engine, "text_rec", None)
        if recognizer is not None:
            return recognizer
        if self._page_recognition_factory is None:
            raise RuntimeError("整页识别模型已释放且无法恢复。")
        if (
            _ACTIVE_RECOGNITION_MEMORY_MODE == "low_memory"
            and self._verification_factory is not None
            and self._verification_recognizer is not None
        ):
            self._verification_profile = self._scheduler_profile(
                self._verification_recognizer
            )
            _dispose_openvino_component(self._verification_recognizer)
            self._verification_recognizer = None
            gc.collect()
        _write_runtime_trace(
            "model_construct",
            family="v6-small",
            caller=_caller_name(2),
            parent=_caller_name(3),
        )
        with contextlib.redirect_stdout(sys.stderr):
            self._page_engine.text_rec = self._page_recognition_factory()
        gc.collect()
        return self._page_engine.text_rec

    def _ensure_verification_recognizer(self) -> Any:
        if self._verification_recognizer is not None:
            return self._verification_recognizer
        if self._verification_factory is None:
            raise RuntimeError("风险格复核模型尚未加载且无法恢复。")
        # 整页检测与方向模型先释放；内存充足时保留 Small，避免风险格交替复核反复编译模型。
        # 低内存模式仍串行切换 Small 与 Medium。
        self.release_page_layout_models()
        if _ACTIVE_RECOGNITION_MEMORY_MODE == "low_memory":
            self._release_page_recognizer()
        _write_runtime_trace(
            "model_construct",
            family="v6-medium",
            caller=_caller_name(2),
            parent=_caller_name(3),
        )
        with contextlib.redirect_stdout(sys.stderr):
            self._verification_recognizer = self._verification_factory()
        gc.collect()
        return self._verification_recognizer

    def prepare_verification_recognizer(self) -> None:
        """在分配风险格增强视图前加载 Medium，降低瞬时内存重叠。"""
        self._ensure_verification_recognizer()

    def release_for_table_structure(self) -> bool:
        """结构模型加载前释放已完成页面取证的全部OCR模型。"""
        changed = False
        if self._verification_recognizer is not None:
            self._verification_profile = self._scheduler_profile(
                self._verification_recognizer
            )
            _dispose_openvino_component(self._verification_recognizer)
            self._verification_recognizer = None
            changed = True
        changed = self._release_page_recognizer() or changed
        changed = self.release_page_layout_models() or changed
        if changed:
            gc.collect()
        return changed

    def prepare_for_request(self) -> None:
        """Persistent mode starts each request with page models, not both families."""
        if self._verification_factory is not None and self._verification_recognizer is not None:
            self._verification_profile = self._scheduler_profile(
                self._verification_recognizer
            )
            _dispose_openvino_component(self._verification_recognizer)
            self._verification_recognizer = None
            gc.collect()
        self._ensure_page_recognizer()
        self._ensure_page_layout_models()

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        # Restore Small only after Medium has been released; then restore the
        # page layout stages.  The reverse order briefly holds both families.
        if self._verification_recognizer is not None:
            self._verification_profile = self._scheduler_profile(
                self._verification_recognizer
            )
            _dispose_openvino_component(self._verification_recognizer)
            self._verification_recognizer = None
            gc.collect()
        self._ensure_page_recognizer()
        self._ensure_page_layout_models()
        page_image = args[0] if args else kwargs.get("input")
        detector = getattr(self._page_engine, "text_det", None)
        configured_limit = getattr(detector, "limit_side_len", None)
        adaptive_limit = (
            _adaptive_wide_detector_limit(page_image, int(configured_limit))
            if configured_limit is not None
            else None
        )
        if adaptive_limit is not None:
            detector.limit_side_len = adaptive_limit
        try:
            output = _cached_page_recognition_call(self._page_engine, args, kwargs)
        finally:
            if configured_limit is not None:
                detector.limit_side_len = configured_limit
        _release_recognition_images(output)
        return output

    def fast_text_rec(self, *args: Any, **kwargs: Any) -> Any:
        """调用整页主读使用的 V6 Small 识别器。"""
        recognizer = self._ensure_page_recognizer()
        return _cached_text_recognition_call(
            "v6-small", recognizer, args, kwargs
        )

    def text_rec(self, *args: Any, **kwargs: Any) -> Any:
        recognizer = self._ensure_verification_recognizer()
        return _cached_text_recognition_call(
            "medium", recognizer, args, kwargs
        )

    def server_text_rec(self, *args: Any, **kwargs: Any) -> Any:
        """兼容旧仲裁入口：使用 V6 Medium 的增强视图，不加载 V5。"""
        recognizer = self._ensure_verification_recognizer()
        if not args or not hasattr(args[0], "img"):
            return _cached_text_recognition_call(
                "v6-medium-alternate", recognizer, args, kwargs
            )
        from rapidocr.ch_ppocr_rec.typings import TextRecInput

        alternate_images = []
        for image in args[0].img:
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
            enhanced = cv2.createCLAHE(clipLimit=1.8, tileGridSize=(4, 4)).apply(gray)
            alternate_images.append(cv2.cvtColor(enhanced, cv2.COLOR_GRAY2BGR))
        alternate_input = TextRecInput(img=alternate_images)
        return _cached_text_recognition_call(
            "v6-medium-alternate",
            recognizer,
            (alternate_input, *args[1:]),
            kwargs,
        )

    def execution_profile(self) -> dict[str, Any]:
        page_recognizer = getattr(self._page_engine, "text_rec", None)
        return {
            "v6-small-page": (
                self._scheduler_profile(page_recognizer)
                if page_recognizer is not None
                else self._page_recognition_profile
                or self._scheduler_profile(None)
            ),
            "v6-medium-cell": (
                self._scheduler_profile(self._verification_recognizer)
                if self._verification_recognizer is not None
                else self._verification_profile
                or self._scheduler_profile(None)
            ),
        }

    def reset_execution_profile(self) -> None:
        self._page_recognition_profile = None
        self._verification_profile = None
        for recognizer in (
            getattr(self._page_engine, "text_rec", None),
            self._verification_recognizer,
        ):
            if recognizer is None:
                continue
            reset_profile = getattr(recognizer, "reset_execution_profile", None)
            if callable(reset_profile):
                reset_profile()

    def __getattr__(self, name: str) -> Any:
        return getattr(self._page_engine, name)


def _release_recognition_images(output: Any) -> None:
    """文本和分数取得后立即释放 RapidOCR 保留的输入图像。"""
    if output is not None and hasattr(output, "imgs"):
        output.imgs = None


def _dispose_openvino_component(component: Any) -> bool:
    """在已确认不再调用组件后立即解除OpenVINO原生推理请求。"""
    release_native = getattr(component, "release_native_resources", None)
    if callable(release_native):
        return bool(release_native())
    inference_session = getattr(component, "session", None)
    if inference_session is None:
        return False
    changed = False
    if getattr(inference_session, "session", None) is not None:
        inference_session.session = None
        changed = True
    if getattr(inference_session, "model", None) is not None:
        inference_session.model = None
        changed = True
    return changed


def _release_openvino_source_model(component: Any) -> bool:
    """编译完成后释放只用于读取模型元数据的OpenVINO源图。"""
    inference_session = getattr(component, "session", None)
    if inference_session is None or getattr(inference_session, "model", None) is None:
        return False
    inference_session.model = None
    return True


def _build_medium_text_recognizer(models: Path) -> Any:
    _check_request_wall_clock("model_construct")
    """只加载用于单元格复核的 Medium 识别阶段。"""
    from rapidocr import RapidOCR
    from rapidocr.ch_ppocr_rec.main import TextRecognizer

    loader = object.__new__(RapidOCR)
    parameters = build_ocr_parameters(models)
    request_count = 2 if _ACTIVE_RECOGNITION_MEMORY_MODE == "normal" else 1
    config = loader._load_config(None, parameters)
    config.Rec.engine_cfg = config.EngineConfig[config.Rec.engine_type.value]
    config.Rec.font_path = config.Global.font_path
    config.Rec.model_root_dir = config.Global.model_root_dir
    recognizer = TextRecognizer(config.Rec)
    _release_openvino_source_model(recognizer)
    gc.collect()
    return _parallel_text_recognizer(recognizer, request_count)


