def validate_model_files(models: Path) -> None:
    for name, expected_hash in MODEL_HASHES.items():
        path = models / name
        if not path.is_file():
            raise FileNotFoundError(f"识别模型文件缺失：{name}")
        digest = hashlib.sha256()
        with path.open("rb") as model_file:
            for chunk in iter(lambda: model_file.read(1024 * 1024), b""):
                digest.update(chunk)
        if digest.hexdigest().lower() != expected_hash:
            raise ValueError(f"识别模型文件校验失败：{name}")


def _load_runtime() -> None:
    global cv2, np, pipeline
    if cv2 is None or np is None or pipeline is None:
        import cv2 as cv2_module
        import numpy as numpy_module
        import table_pipeline as pipeline_module

        # 图像处理和模型推理各有线程池；避免OpenCV默认占满全部逻辑核。
        cv2_module.setNumThreads(min(2, os.cpu_count() or 1))
        cv2 = cv2_module
        np = numpy_module
        pipeline = pipeline_module


def _engines(load_table: bool = False):
    global _ocr_engine, _table_engine
    models = model_directory()
    if _ocr_engine is None:
        from rapidocr import RapidOCR

        validate_model_files(models)
        with contextlib.redirect_stdout(sys.stderr):
            page_engine = RapidOCR(params=build_fast_ocr_parameters(models))
            _release_openvino_source_model(page_engine.text_det)
            _release_openvino_source_model(page_engine.text_cls)
            _release_openvino_source_model(page_engine.text_rec)
            gc.collect()
            _ocr_engine = _HybridOcrEngine(
                page_engine,
                page_layout_factory=lambda: _build_page_layout_models(models),
                verification_factory=lambda: _build_medium_text_recognizer(models),
                page_recognition_factory=lambda: _build_small_text_recognizer(models),
            )
    if load_table and _table_engine is None:
        from rapid_table import ModelType, RapidTable, RapidTableInput

        release_for_table = getattr(_ocr_engine, "release_for_table_structure", None)
        if callable(release_for_table):
            release_for_table()

        table_model = models / "slanet-plus.onnx"
        table_input = RapidTableInput(
            model_type=ModelType.SLANETPLUS,
            model_dir_or_path=table_model,
            use_ocr=False,
        )
        with contextlib.redirect_stdout(sys.stderr):
            _table_engine = RapidTable(table_input)
            _table_engine.cfg.use_ocr = True
    return _ocr_engine, _table_engine


def _read_image(path: Path) -> np.ndarray:
    # 2026-10-30（lead 复查 P1）：原来是 `np.fromfile` 整文件读入再 `imdecode`，
    # **没有任何大小/像素上限** —— 一张 200 MP 的图会先在解码这一步吃掉 1~2 GB
    # （解码后才轮到 _resize_for_processing 缩放），内存闸只看剩余物理内存、
    # 不看这张图本身要多少，弱机直接原生 OOM。这里前置两道闸：
    #   1) 文件字节数上限（正常交付语料 PNG 均 < 5 MB，留 64 MiB 余量）；
    #   2) 解码后像素上限（挡住"高压缩比但尺寸巨大"的文件）。
    # 两者都走既有 IMAGE_READ_FAILED 口径，不新增错误码。
    try:
        file_bytes = path.stat().st_size
    except OSError as error:
        raise ValueError(f"cannot read image: {error}") from error
    if file_bytes > _MAX_IMAGE_FILE_BYTES:
        raise ValueError(
            "cannot read image: 图片文件过大（%.0f MiB，上限 %d MiB），请压缩或裁剪后重试。"
            % (file_bytes / (1024 * 1024), _MAX_IMAGE_FILE_BYTES // (1024 * 1024))
        )
    try:
        data = np.fromfile(str(path), dtype=np.uint8)
    except OSError as error:
        raise ValueError(f"cannot read image: {error}") from error
    try:
        image = cv2.imdecode(data, cv2.IMREAD_COLOR)
    except Exception as error:
        # 2026-10-23：OpenCV 自己对空文件/损坏文件是**抛** cv2.error，
        # 不是返回 None。原来没有 try/except，cv2.error 直接穿透到顶层，
        # 被归成 INTERNAL_ERROR + retryable=true —— 用户看到的是 OpenCV 原文，
        # GUI 还会自动重跑一整轮识别（30~60 秒 / 2 GB）。
        # 这里统一成"图片读不了"，走既有的 IMAGE_READ_FAILED 分支。
        if cv2 is None or not isinstance(error, cv2.error):
            raise
        raise ValueError("cannot read image: %s" % (error,)) from error
    finally:
        del data
    if image is None:
        raise ValueError("unsupported or damaged image")
    pixels = int(image.shape[0]) * int(image.shape[1])
    if pixels > _MAX_IMAGE_PIXELS:
        raise ValueError(
            "cannot read image: 图片尺寸过大（%d×%d），请缩小到 %d 万像素以内再识别。"
            % (image.shape[1], image.shape[0], _MAX_IMAGE_PIXELS // 10000)
        )
    return image


# 一条细缝形状的图不可能是表格，却会把检测网络的 ConvTranspose 上采样撑到
# 一次 6 GB 分配并直接失败。真实 Excel 截图与手机拍摄的宽高比都不超过 4.5，
# 这里留了很大余量。刻意不限制最小边：小尺寸截图本身是安全的，
# 拦它只会误伤缩略图和用户的正常输入。
_MAX_FRAME_ASPECT = 12.0


def _reject_unreadable_source_frame(image: np.ndarray) -> None:
    """只对用户交进来的那张原图生效，中间矫正图不受此限制。"""
    height, width = image.shape[:2]
    short_side = min(int(height), int(width))
    if short_side <= 0:
        raise ValueError("图片尺寸无效，请重新选择图片。")
    if max(int(height), int(width)) / float(short_side) > _MAX_FRAME_ASPECT:
        raise ValueError(
            f"图片过于狭长（{width}×{height}），无法作为表格识别，请重新取景。"
        )


def _resize_for_processing(image: np.ndarray, max_pixels: int = 2400 * 2400) -> tuple[np.ndarray, float]:
    """按总像素控制工作内存，避免长表或宽表的短边被压到无法读字。"""
    height, width = image.shape[:2]
    if height * width <= max_pixels:
        return image, 1.0
    scale = math.sqrt(max_pixels / float(height * width))
    resized = cv2.resize(
        image,
        (max(1, int(width * scale)), max(1, int(height * scale))),
        interpolation=cv2.INTER_AREA,
    )
    return resized, scale


def _write_image(path: Path, image: np.ndarray) -> None:
    suffix = path.suffix.lower() or ".png"
    success, encoded = cv2.imencode(suffix, image)
    if not success:
        raise ValueError("cannot encode rectified image")
    path.parent.mkdir(parents=True, exist_ok=True)
    encoded.tofile(str(path))


def _crop_has_truncated_edge(rectified: np.ndarray) -> bool:
    """Detect ink flush against a crop edge without a supported table border line."""
    if rectified.size == 0:
        return False
    height, width = rectified.shape[:2]
    if height < 80 or width < 120:
        return False
    gray = cv2.cvtColor(rectified, cv2.COLOR_BGR2GRAY) if rectified.ndim == 3 else rectified
    binary = cv2.adaptiveThreshold(
        gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY_INV, 31, 11
    )
    band = max(3, int(round(min(height, width) * 0.004)))
    horizontal_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (max(12, width // 20), 1))
    vertical_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (1, max(12, height // 20)))
    horizontal = cv2.morphologyEx(binary, cv2.MORPH_OPEN, horizontal_kernel)
    vertical = cv2.morphologyEx(binary, cv2.MORPH_OPEN, vertical_kernel)
    edges = (
        (binary[:band, :], horizontal[:band, :], 1),
        (binary[height - band :, :], horizontal[height - band :, :], 1),
        (binary[:, :band], vertical[:, :band], 0),
        (binary[:, width - band :], vertical[:, width - band :], 0),
    )
    for ink_band, line_band, line_axis in edges:
        ink = float(np.count_nonzero(ink_band)) / max(1.0, ink_band.size)
        if ink < 0.004:
            continue
        covered = np.count_nonzero(np.any(line_band > 0, axis=line_axis))
        span = max(1.0, ink_band.shape[1] if line_axis == 1 else ink_band.shape[0])
        if covered / span < 0.35:
            return True
    return False


def _crop_cuts_through_source_content(source: np.ndarray, metadata: dict[str, Any]) -> bool:
    """Flag a primary-report crop whose outer boundary slices through source ink."""
    bounds = metadata.get("crop_bounds")
    if not isinstance(bounds, (list, tuple)) or len(bounds) != 4:
        return False
    left, top, right, bottom = (max(0, int(value)) for value in bounds)
    height, width = source.shape[:2]
    if right <= left or bottom <= top:
        return False
    gray = cv2.cvtColor(source, cv2.COLOR_BGR2GRAY) if source.ndim == 3 else source
    band = max(3, int(round(min(height, width) * 0.006)))
    margin = 2
    strips = (
        gray[top:bottom, max(0, left - band) : max(0, left - margin)],
        gray[top:bottom, min(width, right + margin) : min(width, right + band)],
        gray[max(0, top - band) : max(0, top - margin), left:right],
        gray[min(height, bottom + margin) : min(height, bottom + band), left:right],
    )
    source_rows = metadata.get("source_rows")
    aligned_rows = None
    if isinstance(source_rows, list) and len(source_rows) >= 4:
        row_marks = sorted({max(0, int(value)) for value in source_rows})
        aligned_rows = [
            value for value in row_marks
            if top <= value < bottom
        ]
    for strip in strips:
        if not strip.size:
            continue
        ink_ratio = float(np.count_nonzero(strip < 200)) / float(strip.size)
        if ink_ratio < 0.005:
            continue
        if aligned_rows is not None and strip.shape[0] > strip.shape[1]:
            # A vertical strip next to the crop edge is suspicious only when
            # its ink lines up with the table row bands; window chrome and
            # chart clutter stay tolerated by the primary-report crop feature.
            matches = 0
            for value in aligned_rows:
                relative = value - top
                row_band = strip[max(0, relative - 2) : relative + 3, :]
                if row_band.size and np.count_nonzero(row_band < 200) > 0:
                    matches += 1
            if matches >= max(3, int(len(aligned_rows) * 0.30)):
                return True
            continue
        if ink_ratio >= 0.02:
            return True
    return False


def _parallel_outer_top_rule_above_detected_crop(
    source: np.ndarray,
    corners: list[list[float]] | np.ndarray,
) -> bool:
    """Detect a full-width header rule just above a body-only perspective crop."""
    if source.size == 0:
        return False
    points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    top_y = int(round(float(np.mean(points[:2, 1]))))
    bottom_y = int(round(float(np.mean(points[2:, 1]))))
    left = max(0, int(round(float(min(points[0, 0], points[3, 0])))))
    right = min(source.shape[1], int(round(float(max(points[1, 0], points[2, 0])))))
    table_height = max(1, bottom_y - top_y)
    band_top = max(0, top_y - max(16, int(round(table_height * 0.18))))
    band_bottom = max(band_top, top_y - 4)
    if right - left < 120 or band_bottom - band_top < 8:
        return False
    gray = cv2.cvtColor(source, cv2.COLOR_BGR2GRAY) if source.ndim == 3 else source
    band = gray[band_top:band_bottom, left:right]
    binary = cv2.threshold(band, 190, 255, cv2.THRESH_BINARY_INV)[1]
    horizontal = cv2.morphologyEx(
        binary,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (max(40, (right - left) // 3), 1)),
    )
    support = np.count_nonzero(horizontal, axis=1) / float(max(1, right - left))
    return bool(support.size and float(support.max()) >= 0.65)


def _truncated_crop_has_complete_dense_row_boundaries(image: np.ndarray) -> bool:
    """Keep a clipped-edge sheet only when two ruler bands prove every row."""
    if image.size == 0:
        return False
    height, width = image.shape[:2]
    if height < 240 or width < 480:
        return False
    horizontal, _, _ = pipeline._grid_maps(image)

    def centers(left_ratio: float, right_ratio: float) -> list[int]:
        left = max(0, int(round(width * left_ratio)))
        right = min(width, int(round(width * right_ratio)))
        if right - left < 24:
            return []
        projection = np.count_nonzero(horizontal[:, left:right], axis=1)
        indices = np.flatnonzero(
            projection >= max(3, int(round((right - left) * 0.20)))
        )
        groups = np.split(indices, np.where(np.diff(indices) > 1)[0] + 1)
        return [int(round(float(group.mean()))) for group in groups if group.size]

    def complete_track(values: list[int]) -> tuple[float, float] | None:
        if not 13 <= len(values) <= 129:
            return None
        if values[0] > height * 0.04 or values[-1] < height * 0.965:
            return None
        gaps = np.diff(values).astype(float)
        typical = float(np.median(gaps)) if gaps.size else 0.0
        regularity = float(
            np.mean(np.abs(gaps - typical) <= max(4.0, typical * 0.30))
        )
        if typical < 8.0 or regularity < 0.85:
            return None
        return typical, regularity

    first = centers(0.03, 0.095)
    second = centers(0.10, 0.20)
    first_metrics = complete_track(first)
    second_metrics = complete_track(second)
    if first_metrics is None or second_metrics is None:
        return False
    if (
        abs(len(first) - len(second)) > 2
        or abs(first_metrics[0] - second_metrics[0])
        > max(2.0, min(first_metrics[0], second_metrics[0]) * 0.15)
    ):
        return False
    tolerance = max(4.0, min(first_metrics[0], second_metrics[0]) * 0.30)
    first_match = sum(
        any(abs(value - other) <= tolerance for other in second) for value in first
    ) / float(len(first))
    second_match = sum(
        any(abs(value - other) <= tolerance for other in first) for value in second
    ) / float(len(second))
    return bool(first_match >= 0.92 and second_match >= 0.92)


def _third_grid_row_has_complete_internal_boundaries(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Confirm that a simple title/header has a fully separated third grid row."""
    if image.size == 0 or len(columns) < 6 or len(rows) < 4:
        return False
    top, bottom = int(rows[2]), int(rows[3])
    if bottom - top < 12:
        return False
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    supported = 0
    for position in columns[1:-1]:
        band = gray[
            top + 3 : bottom - 3,
            max(0, int(position) - 4) : min(gray.shape[1], int(position) + 5),
        ].astype(np.float32)
        if band.shape[0] < 6 or band.shape[1] < 3:
            continue
        row_edge = np.max(np.abs(np.diff(band, axis=1)), axis=1)
        edge_sample = np.concatenate((row_edge[:3], row_edge[-3:]))
        supported += float(np.mean(edge_sample > 8.0)) >= 0.65
    return supported >= len(columns) - 3


def _rectified_crop_is_usable(
    source: np.ndarray,
    rectified: np.ndarray,
    metadata: dict[str, Any],
) -> bool:
    if not metadata.get("detected"):
        return True
    if source.size == 0 or rectified.size == 0:
        return False
    crop_is_truncated = _crop_has_truncated_edge(rectified)
    if _crop_cuts_through_source_content(source, metadata):
        # 四边完整性预检失败：裁剪边界切开文字或表格内容，保留完整画面。
        return False
    if crop_is_truncated and not _truncated_crop_has_complete_dense_row_boundaries(
        rectified
    ):
        return False
    source_height, source_width = source.shape[:2]
    result_height, result_width = rectified.shape[:2]
    corners = metadata.get("corners")
    if isinstance(corners, list) and len(corners) == 4:
        points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
        if not np.isfinite(points).all() or not cv2.isContourConvex(points.astype(np.int32)):
            return False
        edge_lengths = [
            float(np.linalg.norm(points[(index + 1) % 4] - points[index]))
            for index in range(4)
        ]
        # A false paper/table contour can collapse one side to a few pixels.
        # Perspective correction then stretches an almost triangular strip and
        # destroys text that the page detector read clearly in the source.  A
        # real photographed rectangle may be trapezoidal, but neither pair of
        # opposite sides should differ by an order of magnitude.
        for first, second in ((edge_lengths[0], edge_lengths[2]), (edge_lengths[1], edge_lengths[3])):
            if min(first, second) / max(1.0, max(first, second)) < 0.15:
                return False
    if metadata.get("paper_expanded"):
        # A complete paper sheet may intentionally occupy only a small part of
        # a far-shot photo. The document detector already rejects hollow frames
        # and incomplete two-edge crops, so retaining this crop enlarges the
        # actual table instead of silently reverting to the distant full frame.
        if not _rectification_touches_image_edge(
            metadata,
            source_width,
            source_height,
        ):
            return True
        corners = metadata.get("corners")
        if isinstance(corners, list) and len(corners) == 4:
            points = np.asarray(corners, dtype=float).reshape(4, 2)
            margin = max(8.0, min(source_width, source_height) * 0.01)
            return bool(
                points[:, 0].min() >= -margin
                and points[:, 0].max() <= source_width - 1 + margin
                and points[:, 1].min() >= -margin
                and points[:, 1].max() <= source_height - 1 + margin
            )
        return False
    height_ratio = result_height / max(1.0, float(source_height))
    width_ratio = result_width / max(1.0, float(source_width))
    area_ratio = (result_height * result_width) / max(1.0, float(source_height * source_width))
    # A false document contour often selects only a header band or a narrow
    # page edge.  OCR on that crop can look successful while silently losing
    # most rows.  Prefer the complete frame when either dimension is too small;
    # completeness is more important than the modest speed-up from cropping.
    return bool(height_ratio >= 0.38 and width_ratio >= 0.38 and area_ratio >= 0.15)


def _inner_rectification_discards_complete_sheet_extent(
    paper_rectification: dict[str, Any],
    inner_rectification: dict[str, Any],
) -> bool:
    """Reject an inner crop that removes a large part of a confirmed paper quad."""
    paper_corners = paper_rectification.get("corners")
    inner_corners = inner_rectification.get("corners")
    if not (
        paper_rectification.get("paper_expanded")
        and isinstance(paper_corners, list)
        and isinstance(inner_corners, list)
        and len(paper_corners) == 4
        and len(inner_corners) == 4
    ):
        return False
    try:
        paper = np.asarray(paper_corners, dtype=np.float32).reshape(4, 2)
        inner = np.asarray(inner_corners, dtype=np.float32).reshape(4, 2)
    except (TypeError, ValueError):
        return False
    paper_area = abs(float(cv2.contourArea(paper)))
    inner_area = abs(float(cv2.contourArea(inner)))
    if paper_area <= 0.0 or inner_area <= 0.0:
        return False
    paper_height = max(
        1.0,
        float(np.linalg.norm(paper[3] - paper[0])),
        float(np.linalg.norm(paper[2] - paper[1])),
    )
    top_cut_limit = max(12.0, paper_height * 0.025)
    if (
        float(inner[0, 1] - paper[0, 1]) > top_cut_limit
        and float(inner[1, 1] - paper[1, 1]) > top_cut_limit
    ):
        return True
    bottom_cut_limit = max(12.0, paper_height * 0.025)
    if (
        float(paper[2, 1] - inner[2, 1]) > bottom_cut_limit
        and float(paper[3, 1] - inner[3, 1]) > bottom_cut_limit
    ):
        return True
    return inner_area < paper_area * 0.82


def _screen_grid_is_credible(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    if len(columns) < 3 or len(rows) < 4:
        return False
    horizontal, vertical, _ = pipeline._grid_maps(image)
    height, width = horizontal.shape[:2]
    supported_rows = 0
    for row in rows:
        top = max(0, row - 2)
        bottom = min(height, row + 3)
        band = horizontal[top:bottom, :]
        if band.size and np.count_nonzero(band) / band.size >= 0.025:
            supported_rows += 1
    if supported_rows < max(3, int(np.ceil(len(rows) * 0.12))):
        return False
    if len(columns) <= 3:
        return True
    if pipeline.spreadsheet_ruler_confirms_columns(image, columns, rows):
        return True
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    spreadsheet_geometry = pipeline._recover_spreadsheet_ruler_grid(
        gray,
        columns,
        rows,
        require_change=False,
    )
    ruler_recovery_conflicted = False
    ruler_recovery_allows_physical_fallback = False
    if spreadsheet_geometry is not None:
        ruler_columns, ruler_rows = spreadsheet_geometry
        tolerance = max(8, int(round(width * 0.006)))
        ruler_recovery_matches = bool(
            len(ruler_columns) == len(columns)
            and len(ruler_rows) == len(rows)
            and all(
                abs(left - right) <= tolerance
                for left, right in zip(ruler_columns, columns)
            )
        )
        if ruler_recovery_matches:
            return True
        ruler_recovery_conflicted = True
        ruler_recovery_allows_physical_fallback = bool(
            len(ruler_columns) < len(columns)
            and len(ruler_rows) == len(rows)
            and all(
                abs(recovered - detected) <= tolerance
                for recovered, detected in zip(ruler_rows, rows)
            )
        )
    # 仅有横线不能认证电子表格：重复的文字竖画可能被误判成大量假列。
    # 真正的内部列边界必须在多个普通数据行带中可见（合并标题行可以缺少这些边界）。
    supported_columns = 0
    fully_supported_columns = 0
    for column in columns[1:-1]:
        band_supports = []
        for top, bottom in zip(rows, rows[1:]):
            inset = max(2, int(round((bottom - top) * 0.18)))
            band_top = max(0, min(height, top + inset))
            band_bottom = max(band_top + 1, min(height, bottom - inset))
            left = max(0, column - 3)
            right = min(width, column + 4)
            band = vertical[band_top:band_bottom, left:right]
            if band.size:
                band_supports.append(
                    float(np.mean(np.any(band > 0, axis=1)))
                )
        strong_bands = sum(support >= 0.45 for support in band_supports)
        if strong_bands >= max(2, int(np.ceil(len(band_supports) * 0.20))):
            supported_columns += 1
        if strong_bands >= int(np.ceil(len(band_supports) * 0.80)):
            fully_supported_columns += 1
    if ruler_recovery_conflicted:
        internal_supports = _vertical_rule_supports(image, columns, rows)[1:-1]
        return bool(
            ruler_recovery_allows_physical_fallback
            and supported_rows >= int(np.ceil(len(rows) * 0.80))
            and fully_supported_columns == len(columns) - 2
            and internal_supports
            and all(support >= 0.75 for support in internal_supports)
        )
    return supported_columns >= max(1, int(np.ceil((len(columns) - 2) * 0.75)))


def _spreadsheet_ruler_label_matches(value: str, expected: str) -> bool:
    raw = value.strip()
    upper = raw.upper()
    if expected == "B":
        return upper == "B" or raw == "8"
    if expected == "I":
        return raw in {"I", "i", "1", "l", "|", "一"}
    if expected == "O":
        return upper == "O" or raw == "0"
    if expected == "Q":
        return upper == "Q" or raw == "a"
    return upper == expected


def _recover_missing_spreadsheet_row_boundary_from_page_rulers(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    boxes: Any,
    texts: Any,
    scores: Any = None,
) -> list[int] | None:
    """Recover one faint physical row rule only when spreadsheet rulers prove it."""
    if (
        image.size == 0
        or boxes is None
        or texts is None
        or len(columns) < 10
        or len(rows) < 10
        or columns[0] < 0
        or columns[-1] > image.shape[1]
        or rows[0] < 0
        or rows[-1] > image.shape[0]
    ):
        return None

    score_values = list(scores) if scores is not None else []
    entries: list[dict[str, Any]] = []
    for index, (box, text) in enumerate(zip(boxes, texts)):
        value = str(text).strip()
        if not value:
            continue
        points = np.asarray(box, dtype=float).reshape(-1, 2)
        if points.size == 0 or not np.isfinite(points).all():
            continue
        left = float(points[:, 0].min())
        right = float(points[:, 0].max())
        top = float(points[:, 1].min())
        bottom = float(points[:, 1].max())
        entries.append(
            {
                "text": value,
                "center_x": (left + right) * 0.5,
                "center_y": (top + bottom) * 0.5,
                "score": (
                    float(score_values[index])
                    if index < len(score_values)
                    else 1.0
                ),
            }
        )
    if not entries:
        return None

    ruler_entries = [
        entry
        for entry in entries
        if len(entry["text"]) == 1
        and columns[1] <= entry["center_x"] <= columns[-1]
        and rows[0] <= entry["center_y"] <= rows[1] + 2
    ]
    ruler_entries.sort(key=lambda entry: entry["center_x"])
    expected_ruler_count = len(columns) - 2
    if not 8 <= expected_ruler_count <= 26 or len(ruler_entries) != expected_ruler_count:
        return None
    for index, entry in enumerate(ruler_entries):
        if (
            not _spreadsheet_ruler_label_matches(
                entry["text"], chr(ord("A") + index)
            )
            or not columns[index + 1]
            <= entry["center_x"]
            <= columns[index + 2]
        ):
            return None
    if float(np.mean([entry["score"] for entry in ruler_entries])) < 0.75:
        return None

    row_ruler_entries = [
        entry
        for entry in entries
        if re.fullmatch(r"[1-9]\d{0,2}", entry["text"])
        and entry["score"] >= 0.90
        and columns[0] <= entry["center_x"] <= columns[1]
        and entry["center_y"] >= rows[1]
    ]
    row_ruler_entries.sort(key=lambda entry: entry["center_y"])
    if len(row_ruler_entries) < 8:
        return None
    initial_rulers = row_ruler_entries[:8]
    if [int(entry["text"]) for entry in initial_rulers] != list(range(1, 9)):
        return None

    interval_indexes: list[int] = []
    for entry in initial_rulers:
        matches = [
            index
            for index, (top, bottom) in enumerate(zip(rows, rows[1:]))
            if top <= entry["center_y"] < bottom
        ]
        if len(matches) != 1:
            return None
        interval_indexes.append(matches[0])
    shared_pairs = [
        index
        for index in range(len(initial_rulers) - 1)
        if interval_indexes[index] == interval_indexes[index + 1]
    ]
    if len(shared_pairs) != 1:
        return None

    shared_index = shared_pairs[0]
    first_center = float(initial_rulers[shared_index]["center_y"])
    second_center = float(initial_rulers[shared_index + 1]["center_y"])
    center_gaps = np.diff(
        [float(entry["center_y"]) for entry in initial_rulers]
    ).astype(float)
    reference_gaps = np.delete(center_gaps, shared_index)
    typical_gap = float(np.median(reference_gaps)) if reference_gaps.size else 0.0
    shared_gap = second_center - first_center
    if typical_gap < 12.0 or not 0.75 * typical_gap <= shared_gap <= 1.25 * typical_gap:
        return None

    interval_index = interval_indexes[shared_index]
    interval_top = int(rows[interval_index])
    interval_bottom = int(rows[interval_index + 1])
    physical_gaps = np.diff(rows).astype(float)
    ordinary_gaps = np.delete(physical_gaps, interval_index)
    typical_physical_gap = (
        float(np.median(ordinary_gaps)) if ordinary_gaps.size else 0.0
    )
    if (
        typical_physical_gap < 12.0
        or not 1.70 * typical_physical_gap
        <= interval_bottom - interval_top
        <= 2.40 * typical_physical_gap
    ):
        return None

    predicted = int(round((first_center + second_center) * 0.5))
    search_top = max(interval_top + 5, predicted - 5)
    search_bottom = min(interval_bottom - 5, predicted + 5)
    if search_top > search_bottom:
        return None
    gray = (
        cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        if image.ndim == 3
        else image
    )
    left = max(0, int(columns[1]))
    right = min(gray.shape[1], int(columns[-1]))
    if right - left < 80:
        return None
    sobel_y = np.abs(cv2.Sobel(gray, cv2.CV_32F, 0, 1, ksize=3))[:, left:right]
    candidates = [
        (float(np.mean(sobel_y[y] >= 18.0)), y)
        for y in range(search_top, search_bottom + 1)
    ]
    line_coverage, recovered_boundary = max(candidates)
    if line_coverage < 0.25:
        return None
    split_gaps = (
        recovered_boundary - interval_top,
        interval_bottom - recovered_boundary,
    )
    if any(
        gap < 0.70 * typical_physical_gap
        or gap > 1.35 * typical_physical_gap
        for gap in split_gaps
    ):
        return None

    recovered_rows = list(map(int, rows))
    recovered_rows.insert(interval_index + 1, int(recovered_boundary))
    return recovered_rows


def _recover_dense_spreadsheet_grid_from_page_rulers(
    image: np.ndarray,
    candidate_columns: list[int],
    candidate_rows: list[int],
    boxes: Any,
    texts: Any,
    scores: Any = None,
) -> tuple[list[int], list[int]] | None:
    """Recover an over-split screenshot grid from OCR rulers and headers.

    Dense tiny text can create many false vertical-rule candidates.  Recovery
    is allowed only when the page detector independently reads a consecutive
    A..Z ruler and the following header row supplies matching column centres;
    every accepted boundary must still come from the CV grid candidate.
    """
    if (
        image.size == 0
        or boxes is None
        or texts is None
        or len(candidate_columns) < 6
        or len(candidate_rows) < 16
    ):
        return None
    height, width = image.shape[:2]
    if (
        candidate_rows[0] < 4
        or candidate_rows[0] > height * 0.10
        or candidate_rows[-1] < height * 0.90
        or len(candidate_rows) - 1 > 120
    ):
        return None

    score_values = list(scores) if scores is not None else []
    entries: list[dict[str, Any]] = []
    for index, (box, text) in enumerate(zip(boxes, texts)):
        value = str(text).strip()
        if not value:
            continue
        points = np.asarray(box, dtype=float).reshape(-1, 2)
        if points.size == 0 or not np.isfinite(points).all():
            continue
        left = float(points[:, 0].min())
        right = float(points[:, 0].max())
        top = float(points[:, 1].min())
        bottom = float(points[:, 1].max())
        entries.append(
            {
                "text": value,
                "left": left,
                "right": right,
                "top": top,
                "bottom": bottom,
                "center_x": (left + right) * 0.5,
                "center_y": (top + bottom) * 0.5,
                "score": (
                    float(score_values[index])
                    if index < len(score_values)
                    else 1.0
                ),
            }
        )
    if not entries:
        return None

    first_row_top = int(candidate_rows[0])
    first_row_bottom = int(candidate_rows[1])
    row_gap = max(1, first_row_bottom - first_row_top)
    ruler_entries = [
        entry
        for entry in entries
        if len(entry["text"]) == 1
        and candidate_columns[0] <= entry["center_x"] <= candidate_columns[-1]
        and entry["center_y"] < first_row_top
        and entry["bottom"] <= first_row_top + max(3.0, row_gap * 0.18)
    ]
    ruler_entries.sort(key=lambda entry: entry["center_x"])
    if not 8 <= len(ruler_entries) <= 26:
        return None

    for index, entry in enumerate(ruler_entries):
        if not _spreadsheet_ruler_label_matches(
            entry["text"], chr(ord("A") + index)
        ):
            return None
    if float(np.mean([entry["score"] for entry in ruler_entries])) < 0.75:
        return None

    centers = [float(entry["center_x"]) for entry in ruler_entries]
    center_gaps = np.diff(centers).astype(float)
    typical_center_gap = float(np.median(center_gaps)) if center_gaps.size else 0.0
    if (
        typical_center_gap < 12.0
        or float(center_gaps.min(initial=typical_center_gap)) < 8.0
        or float(center_gaps.max(initial=typical_center_gap)) > typical_center_gap * 2.5
        or centers[-1] - centers[0] < width * 0.80
    ):
        return None

    header_entries = [
        entry
        for entry in entries
        if first_row_top - 2 <= entry["center_y"] <= first_row_bottom + 4
        and entry["center_x"] >= candidate_columns[0]
        and entry["center_x"] <= candidate_columns[-1]
    ]
    unused_headers = set(range(len(header_entries)))
    header_support = 0
    for index, center in enumerate(centers):
        local_gaps = []
        if index:
            local_gaps.append(center - centers[index - 1])
        if index + 1 < len(centers):
            local_gaps.append(centers[index + 1] - center)
        tolerance = max(8.0, min(local_gaps or [typical_center_gap]) * 0.30)
        matches = [
            (abs(float(header_entries[item]["center_x"]) - center), item)
            for item in unused_headers
            if abs(float(header_entries[item]["center_x"]) - center) <= tolerance
        ]
        if matches:
            _, selected = min(matches)
            unused_headers.remove(selected)
            header_support += 1
    if header_support < int(math.ceil(len(centers) * 0.80)):
        return None

    minimum_gap = max(12, int(round(width * 0.008)))
    boundary_tolerance = max(8.0, width * 0.008)
    recovered_columns: list[int] | None = None
    left_candidates = [
        int(column)
        for column in candidate_columns
        if 0 <= int(column) < centers[0]
    ]
    for initial_left in reversed(left_candidates):
        recovered = [initial_left]
        valid = True
        for index, center in enumerate(centers):
            predicted_right = 2.0 * center - recovered[-1]
            next_center = centers[index + 1] if index + 1 < len(centers) else width + 1.0
            right_candidates = [
                int(column)
                for column in candidate_columns
                if center < int(column) < next_center
            ]
            if not right_candidates:
                valid = False
                break
            selected = min(
                right_candidates,
                key=lambda column: abs(float(column) - predicted_right),
            )
            if (
                abs(float(selected) - predicted_right) > boundary_tolerance
                or selected - recovered[-1] < minimum_gap
            ):
                valid = False
                break
            recovered.append(selected)
        if not valid or len(recovered) != len(centers) + 1:
            continue
        gaps = np.diff(recovered).astype(float)
        typical_gap = float(np.median(gaps)) if gaps.size else 0.0
        if (
            recovered[0] > width * 0.08
            or recovered[-1] < width * 0.95
            or recovered[-1] - recovered[0] < width * 0.88
            or typical_gap < minimum_gap
            or float(gaps.max(initial=typical_gap)) > typical_gap * 2.5
            or len(candidate_columns) < len(recovered) + 2
        ):
            continue
        recovered_columns = recovered
        break

    if recovered_columns is None or not _grid_geometry_is_bounded(
        recovered_columns,
        candidate_rows,
        maximum_cells=1280,
    ):
        return None
    return recovered_columns, list(candidate_rows)


def _page_ocr_confirms_spreadsheet_ruler_above_grid(
    columns: list[int],
    rows: list[int],
    page_text_evidence: list[tuple[str, float, float, float]],
) -> bool:
    column_count = len(columns) - 1
    if not 8 <= column_count <= 26 or len(rows) < 3:
        return False
    row_gap = max(1.0, float(rows[1] - rows[0]))
    candidates = [
        (str(text).strip(), float(center_x), float(score))
        for text, center_x, center_y, score in page_text_evidence
        if len(str(text).strip()) == 1
        and float(score) >= 0.60
        and float(rows[0]) - row_gap <= float(center_y) < float(rows[0])
    ]
    matched_scores: list[float] = []
    for index, (left, right) in enumerate(zip(columns, columns[1:])):
        center = (float(left) + float(right)) * 0.5
        tolerance = max(6.0, (float(right) - float(left)) * 0.30)
        matches = [
            (abs(candidate_x - center), score)
            for text, candidate_x, score in candidates
            if abs(candidate_x - center) <= tolerance
            and _spreadsheet_ruler_label_matches(
                text,
                chr(ord("A") + index),
            )
        ]
        if matches:
            matched_scores.append(min(matches)[1])
    required = max(8, column_count - 1)
    return bool(
        len(matched_scores) >= required
        and float(np.mean(matched_scores)) >= 0.85
    )


def _excluded_supported_rows_are_only_spreadsheet_ruler(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    page_text_evidence: list[tuple[str, float, float, float]],
) -> bool:
    if not _page_ocr_confirms_spreadsheet_ruler_above_grid(
        columns,
        rows,
        page_text_evidence,
    ):
        return False
    horizontal, _, _ = pipeline._grid_maps(image)
    height, width = horizontal.shape[:2]
    left = max(0, min(width - 1, int(columns[0])))
    right = max(left + 1, min(width, int(columns[-1]) + 1))
    table_width = right - left
    projection = np.count_nonzero(horizontal[:, left:right], axis=1)
    centers = pipeline._line_centers(projection, table_width)
    gaps = np.diff(rows).astype(float)
    ordinary = gaps[gaps <= np.percentile(gaps, 75)] if gaps.size else gaps
    typical = float(np.median(ordinary)) if ordinary.size else 0.0
    if typical < 6.0:
        return False
    tolerance = max(4.0, typical * 0.18)
    adjacent_outside = []
    for center in centers:
        if center < rows[0] - tolerance:
            distance = float(rows[0] - center)
        elif center > rows[-1] + tolerance:
            distance = float(center - rows[-1])
        else:
            continue
        if typical * 0.55 <= distance <= typical * 1.50:
            adjacent_outside.append(int(center))
    return bool(adjacent_outside and all(center < rows[0] for center in adjacent_outside))


def _vertical_rule_supports(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> list[float]:
    """Measure physical vertical-rule support inside the detected table band."""
    if image.size == 0 or not columns or len(rows) < 2:
        return [0.0 for _ in columns]
    _, vertical, _ = pipeline._grid_maps(image)
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    edge_x = np.abs(cv2.Sobel(gray, cv2.CV_32F, 1, 0, ksize=3))
    height, width = vertical.shape[:2]
    top = max(0, min(height - 1, int(rows[0])))
    bottom = max(top + 1, min(height, int(rows[-1]) + 1))
    span = max(1, bottom - top)
    supports: list[float] = []
    for column in columns:
        left = max(0, int(column) - 3)
        right = min(width, int(column) + 4)
        band = vertical[top:bottom, left:right]
        if not band.size:
            supports.append(0.0)
            continue
        supported_scanlines = np.any(band > 0, axis=1)
        supports.append(float(np.count_nonzero(supported_scanlines)) / span)
    return supports


def _photographic_ruled_grid_is_credible(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Require continuous physical column evidence before trusting a photo grid."""
    if not _screen_grid_is_credible(image, columns, rows):
        return False
    internal_supports = _vertical_rule_supports(image, columns, rows)[1:-1]
    if not internal_supports:
        return False
    typical_support = float(np.median(internal_supports))
    # A real ruled boundary can be interrupted by a merged title row or a
    # shadow, but it must remain visible through a meaningful part of the table.
    # Relative support rejects one text-stroke/crease outlier in an otherwise
    # strong grid; the absolute floor rejects a set of uniformly weak guesses.
    minimum_support = max(0.08, min(0.22, typical_support * 0.35))
    gaps = np.diff(columns).astype(float)
    ordinary_gaps = gaps[1:] if gaps.size > 2 else gaps
    typical_gap = (
        float(np.median(ordinary_gaps)) if ordinary_gaps.size else 0.0
    )
    faint_leading_ruler_gutter = bool(
        len(internal_supports) >= 4
        and typical_gap >= 24.0
        and columns[0] <= max(3, int(round(image.shape[1] * 0.01)))
        and gaps[0] <= typical_gap * 0.50
        and internal_supports[0] >= 0.06
        and all(support >= minimum_support for support in internal_supports[1:])
    )
    return bool(
        typical_support >= 0.18
        and (
            all(support >= minimum_support for support in internal_supports)
            or faint_leading_ruler_gutter
        )
    )


def _collapse_one_unruled_spurious_column_boundary(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> list[int] | None:
    """Remove one line-free split whose adjacent gaps form one ordinary column."""
    if (
        image.size == 0
        or not 3 <= len(columns) - 1 <= 32
        or len(rows) - 1 < 8
        or columns[-1] - columns[0] < image.shape[1] * 0.85
        or rows[-1] - rows[0] < image.shape[0] * 0.80
    ):
        return None
    supports = _vertical_rule_supports(image, columns, rows)
    if len(supports) != len(columns):
        return None
    weak = [
        index
        for index in range(1, len(columns) - 1)
        if supports[index] < 0.08
    ]
    if len(weak) != 1:
        return None
    weak_index = weak[0]
    if any(
        support < 0.75
        for index, support in enumerate(supports[1:-1], start=1)
        if index != weak_index
    ):
        return None
    gaps = np.diff(columns).astype(float)
    reference_gaps = [
        float(gap)
        for index, gap in enumerate(gaps)
        if index not in {weak_index - 1, weak_index}
    ]
    typical_gap = float(np.median(reference_gaps)) if reference_gaps else 0.0
    left_gap = float(gaps[weak_index - 1])
    right_gap = float(gaps[weak_index])
    combined_gap = left_gap + right_gap
    if typical_gap < 24.0:
        return None
    small_gap = min(left_gap, right_gap)
    large_gap = max(left_gap, right_gap)
    if left_gap < typical_gap * 0.80 and right_gap < typical_gap * 0.80:
        if not typical_gap * 0.72 <= combined_gap <= typical_gap * 1.35:
            return None
    else:
        # A repeated form can produce one text-stroke split next to a wide
        # real cell.  The weak boundary is still removable when the other
        # half matches the adjacent ordinary gap and the short half is a
        # clear outlier.
        neighboring = [
            float(gap) for index, gap in enumerate(gaps)
            if index not in {weak_index - 1, weak_index}
            and float(gap) >= typical_gap * 0.80
        ]
        reference = float(np.median(neighboring)) if neighboring else typical_gap
        if not (
            small_gap <= max(18.0, reference * 0.18)
            and reference * 0.78 <= large_gap <= reference * 1.22
        ):
            return None
    return [
        int(value)
        for index, value in enumerate(columns)
        if index != weak_index
    ]


def _select_primary_report_column_range(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> tuple[int, int] | None:
    """Select only proven outer spreadsheet clutter, never split an inner wide column."""
    if image.size == 0 or len(columns) < 6 or len(rows) < 5:
        return None
    gaps = np.diff(columns).astype(float)
    positive_gaps = gaps[gaps >= 6.0]
    if positive_gaps.size < 4:
        return None
    typical_gap = float(np.median(positive_gaps))
    if typical_gap < 12.0:
        return None
    supports = _vertical_rule_supports(image, columns, rows)
    start = 0
    end = len(columns) - 1

    # Excel row-number/ruler gutters are a tiny outer cell bounded by two
    # well-supported rules.  Removing that one cell is safe only when the next
    # several cells establish the ordinary scale.  A genuinely narrow first
    # data column remains untouched when it is not an extreme outlier.
    if (
        gaps[0] <= max(18.0, typical_gap * 0.28)
        and supports[0] >= 0.50
        and supports[1] >= 0.50
        and len(gaps) >= 4
        and float(np.median(gaps[1:4])) >= typical_gap * 0.72
    ):
        start = 1

    # A photographed Excel sheet can place a chart pane after one very wide
    # separator and then expose a tiny pair of application/chart axes. Those
    # axes are long, high-contrast lines, so support weakness cannot distinguish
    # them from the main report.  The dominant report is the complete block
    # before the wide separator; require the entire suffix to be only one or
    # two tiny cells so a legitimate wide notes column is never removed.
    for gap_index in range(start + 3, len(gaps) - 1):
        suffix_gaps = gaps[gap_index + 1 :]
        if (
            gaps[gap_index] >= typical_gap * 2.45
            and 1 <= len(suffix_gaps) <= 2
            and bool(
                np.all(suffix_gaps <= max(18.0, typical_gap * 0.28))
            )
        ):
            end = gap_index
            break

    # Remove at most two weak trailing frame/chart axes.  Width alone is never
    # sufficient: a wide notes column is retained when its outer physical rule
    # is supported.  This targets the common full-Excel-photo case where the
    # report is followed by a chart pane or application frame.
    removed_trailing = 0
    while end - start >= 4 and removed_trailing < 2:
        preceding_gap = float(columns[end] - columns[end - 1])
        weak_boundary = supports[end] < 0.42
        weak_pair_after_tiny_cell = bool(
            preceding_gap <= max(18.0, typical_gap * 0.28)
            and supports[end - 1] < 0.46
        )
        detached_outer_axis = bool(
            preceding_gap >= typical_gap * 2.45
            and supports[end - 1] >= 0.55
        )
        if not weak_boundary or not (weak_pair_after_tiny_cell or detached_outer_axis):
            break
        end -= 1
        removed_trailing += 1

    if start == 0 and end == len(columns) - 1:
        return None
    selected_span = int(columns[end]) - int(columns[start])
    table_span = max(1, int(columns[-1]) - int(columns[0]))
    if end - start < 3 or selected_span < image.shape[1] * 0.40:
        return None
    if selected_span < table_span * 0.55:
        return None
    return start, end


def _primary_report_crop_from_ruled_grid(
    image: np.ndarray,
    ruled_grid: tuple[list[int], list[int], np.ndarray] | None,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray], dict[str, Any]] | None:
    """Crop a dominant report while preserving exact physical cell boundaries."""
    if image.size == 0 or ruled_grid is None:
        return None
    columns, rows, cleaned = ruled_grid
    selected = _select_primary_report_column_range(image, columns, rows)
    if selected is None:
        return None
    start, end = selected
    selected_columns = [int(value) for value in columns[start : end + 1]]
    selected_rows = [int(value) for value in rows]
    if len(selected_columns) < 4 or len(selected_rows) < 4:
        return None

    column_gaps = np.diff(selected_columns)
    row_gaps = np.diff(selected_rows)
    typical_column = float(np.median(column_gaps)) if column_gaps.size else 20.0
    typical_row = float(np.median(row_gaps)) if row_gaps.size else 20.0
    horizontal_padding = int(round(max(4.0, min(32.0, typical_column * 0.10))))
    top_padding = int(round(max(12.0, min(image.shape[0] * 0.20, typical_row * 2.35))))
    bottom_padding = int(round(max(4.0, min(24.0, typical_row * 0.45))))
    left = max(0, selected_columns[0] - horizontal_padding)
    right = min(image.shape[1], selected_columns[-1] + horizontal_padding + 1)
    top = max(0, selected_rows[0] - top_padding)
    bottom = min(image.shape[0], selected_rows[-1] + bottom_padding + 1)
    if right - left < 120 or bottom - top < 100:
        return None

    cropped = image[top:bottom, left:right].copy()
    cropped_cleaned = cleaned[top:bottom, left:right].copy()
    shifted_columns = [value - left for value in selected_columns]
    shifted_rows = [value - top for value in selected_rows]
    metadata = {
        "detected": True,
        "corners": [
            [left, top],
            [right - 1, top],
            [right - 1, bottom - 1],
            [left, bottom - 1],
        ],
        "mode": "primary_report",
        "primary_report": True,
        "source_column_count": len(columns) - 1,
        "selected_column_count": len(shifted_columns) - 1,
        "crop_bounds": [left, top, right, bottom],
        "source_rows": selected_rows,
    }
    return cropped, (shifted_columns, shifted_rows, cropped_cleaned), metadata


def _ruled_grid_spans_source_frame(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Keep a complete axis-aligned source grid out of auto perspective warping."""
    if image.size == 0 or len(columns) < 3 or len(rows) < 4:
        return False
    height, width = image.shape[:2]
    horizontal_span = (columns[-1] - columns[0]) / max(1.0, float(width))
    vertical_span = (rows[-1] - rows[0]) / max(1.0, float(height))
    return bool(horizontal_span >= 0.85 and vertical_span >= 0.85)


def _ruled_grid_has_asymmetric_side_gap(
    image: np.ndarray,
    columns: list[int],
    rows: list[int] | None = None,
) -> bool:
    """Flag a likely missed edge column without assuming the table schema."""
    if image.size == 0 or len(columns) < 3:
        return False
    width = image.shape[1]
    left_gap = max(0, int(columns[0]))
    right_gap = max(0, width - 1 - int(columns[-1]))
    grid_span = max(0, int(columns[-1]) - int(columns[0]))
    suspected = bool(
        grid_span >= width * 0.35
        and max(left_gap, right_gap) >= width * 0.18
        and abs(left_gap - right_gap) >= width * 0.10
    )
    if not suspected or rows is None or right_gap <= left_gap:
        return suspected
    horizontal, _, _ = pipeline._grid_maps(image)
    tolerance = max(6, int(round(width * 0.02)))
    confirmed_endpoints = 0
    for row in rows:
        line = np.any(
            horizontal[max(0, row - 3) : min(horizontal.shape[0], row + 4)] > 0,
            axis=0,
        )
        if (
            np.any(line[max(0, columns[-1] - tolerance) : columns[-1] + tolerance + 1])
            and np.mean(line[columns[-1] + tolerance + 1 :]) < 0.05
        ):
            confirmed_endpoints += 1
    return confirmed_endpoints < math.ceil(len(rows) * 0.70)


def _expanded_document_rectification(
    source: np.ndarray,
    rectification: dict[str, Any],
    expansion_ratio: float = 0.15,
) -> tuple[np.ndarray, dict[str, Any]] | None:
    corners = rectification.get("corners")
    if source.size == 0 or not isinstance(corners, list) or len(corners) != 4:
        return None
    points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    if not np.isfinite(points).all() or not cv2.isContourConvex(points.astype(np.int32)):
        return None
    ratio = min(0.20, max(0.08, float(expansion_ratio)))
    center = points.mean(axis=0)
    expanded = center + (points - center) * (1.0 + ratio)
    height, width = source.shape[:2]
    if (
        np.any(expanded[:, 0] < 1)
        or np.any(expanded[:, 1] < 1)
        or np.any(expanded[:, 0] > width - 2)
        or np.any(expanded[:, 1] > height - 2)
    ):
        return None
    original_area = abs(float(cv2.contourArea(points)))
    expanded_area = abs(float(cv2.contourArea(expanded)))
    if original_area <= 0.0 or expanded_area > original_area * 1.50:
        return None

    top_left, top_right, bottom_right, bottom_left = expanded
    target_width = int(round(max(
        np.linalg.norm(top_right - top_left),
        np.linalg.norm(bottom_right - bottom_left),
    )))
    target_height = int(round(max(
        np.linalg.norm(bottom_left - top_left),
        np.linalg.norm(bottom_right - top_right),
    )))
    if target_width < 40 or target_height < 40:
        return None
    destination = np.array(
        [
            [0, 0],
            [target_width - 1, 0],
            [target_width - 1, target_height - 1],
            [0, target_height - 1],
        ],
        dtype=np.float32,
    )
    transform = cv2.getPerspectiveTransform(expanded, destination)
    warped = cv2.warpPerspective(
        source,
        transform,
        (target_width, target_height),
        flags=cv2.INTER_CUBIC,
        borderValue=(255, 255, 255),
    )
    rotated, _, angle = pipeline._deskew(warped)
    metadata = {
        "detected": True,
        "corners": [
            [round(float(point[0]), 2), round(float(point[1]), 2)]
            for point in expanded
        ],
        "base_corners": corners,
        "deskew_angle": round(float(angle), 3),
        "paper_expanded": True,
        "expanded_from_asymmetric_gap": True,
        "mode": "auto",
    }
    return pipeline._enhance_for_ocr(rotated), metadata


def _recover_clipped_left_photo_column(
    source: np.ndarray,
    rectified: np.ndarray,
    rectification: dict[str, Any],
    ruled_grid: tuple[list[int], list[int], np.ndarray],
    maximum_cells: int,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray], dict[str, Any]] | None:
    columns, rows, _ = ruled_grid
    if (
        len(rows) < 12
        or len(columns) < 5
        or columns[0] > 2
        or columns[1] < 70
    ):
        return None
    gray = cv2.cvtColor(rectified, cv2.COLOR_BGR2GRAY)
    outer_band = gray[
        rows[0]:rows[-1],
        max(0, columns[0] - 2):columns[0] + 6,
    ]
    visible_outer_rule = bool(
        outer_band.size
        and float(np.mean(np.any(outer_band < 135, axis=1))) >= 0.85
    )
    edge_left = columns[0] + 8 if visible_outer_rule else 3
    edge_hits = inner_hits = 0
    for top, bottom in zip(rows[1:-1], rows[2:]):
        inset = max(2, int((bottom - top) * 0.20))
        edge = gray[top + inset:bottom - inset, edge_left:edge_left + 17]
        inner = gray[top + inset:bottom - inset, edge_left + 17:edge_left + 42]
        edge_hits += bool(edge.size and float(np.mean(edge < 135)) >= 0.05)
        inner_hits += bool(inner.size and float(np.mean(inner < 135)) >= 0.05)
    count = len(rows) - 2
    if edge_hits < count * 0.60 or inner_hits > count * 0.20:
        return None
    expanded = _expanded_document_rectification(source, rectification, 0.08)
    if expanded is None:
        return None
    candidate_image, metadata = expanded
    candidate_grid = pipeline.extract_ruled_grid(candidate_image, prefer_adaptive=True)
    if (
        candidate_grid is None
        or len(candidate_grid[0]) != len(columns)
        or len(candidate_grid[1]) != len(rows)
        or candidate_grid[0][0] < candidate_image.shape[1] * 0.02
        or not _grid_geometry_is_bounded(
            candidate_grid[0], candidate_grid[1], maximum_cells=maximum_cells
        )
        or not _photographic_ruled_grid_is_credible(
            candidate_image, candidate_grid[0], candidate_grid[1]
        )
    ):
        return None
    metadata["clipped_left_column_recovered"] = True
    metadata["edge_completeness_checked"] = rectification.get(
        "edge_completeness_checked", False
    )
    return candidate_image, candidate_grid, metadata


def _expanded_grid_is_strictly_more_complete(
    base_image: np.ndarray,
    base_grid: tuple[list[int], list[int], np.ndarray],
    candidate_image: np.ndarray,
    candidate_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int = 720,
) -> bool:
    if candidate_grid is None:
        return False
    base_columns, base_rows, _ = base_grid
    columns, rows, _ = candidate_grid
    base_column_count = len(base_columns) - 1
    base_row_count = len(base_rows) - 1
    column_count = len(columns) - 1
    row_count = len(rows) - 1
    if (
        not _ruled_grid_has_asymmetric_side_gap(base_image, base_columns)
        or column_count <= base_column_count
        or row_count < base_row_count
        or row_count > base_row_count + 3
        or not _grid_geometry_is_bounded(
            columns,
            rows,
            maximum_cells=maximum_cells,
        )
        or not _photographic_ruled_grid_is_credible(
            candidate_image,
            columns,
            rows,
        )
        or _ruled_grid_has_asymmetric_side_gap(candidate_image, columns)
    ):
        return False
    height, width = candidate_image.shape[:2]
    if (
        (columns[-1] - columns[0]) < width * 0.80
        or (rows[-1] - rows[0]) < height * 0.65
    ):
        return False
    gaps = np.diff(columns).astype(float)
    median_gap = float(np.median(gaps)) if gaps.size else 0.0
    if (
        median_gap <= 0.0
        or float(gaps.min()) < median_gap * 0.45
        or float(gaps.max()) > median_gap * 2.40
    ):
        return False
    _, vertical, _ = pipeline._grid_maps(candidate_image)
    supports = []
    for column in (columns[0], columns[-1]):
        band = vertical[:, max(0, column - 2) : min(width, column + 3)]
        supports.append(np.count_nonzero(band) / max(1.0, float(band.size)))
    return bool(min(supports) >= 0.12)


def _vertical_document_rectification(
    source: np.ndarray,
    corners: list[list[float]] | np.ndarray,
    expansion_ratio: float,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
    """Expand only the top and bottom document edges and return its source transform."""
    if source.size == 0:
        return None
    points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    if not np.isfinite(points).all() or not cv2.isContourConvex(points.astype(np.int32)):
        return None
    ratio = float(expansion_ratio)
    if ratio < 0.0 or ratio > 0.10:
        return None
    top_left, top_right, bottom_right, bottom_left = points
    expanded = np.array(
        [
            top_left - ratio * (bottom_left - top_left),
            top_right - ratio * (bottom_right - top_right),
            bottom_right + ratio * (bottom_right - top_right),
            bottom_left + ratio * (bottom_left - top_left),
        ],
        dtype=np.float32,
    )
    height, width = source.shape[:2]
    expanded[:, 0] = np.clip(expanded[:, 0], 0, width - 1)
    expanded[:, 1] = np.clip(expanded[:, 1], 0, height - 1)
    if abs(float(cv2.contourArea(expanded))) < 1600.0:
        return None
    top_left, top_right, bottom_right, bottom_left = expanded
    target_width = int(round(max(
        np.linalg.norm(top_right - top_left),
        np.linalg.norm(bottom_right - bottom_left),
    )))
    target_height = int(round(max(
        np.linalg.norm(bottom_left - top_left),
        np.linalg.norm(bottom_right - top_right),
    )))
    if target_width < 40 or target_height < 40:
        return None
    destination = np.array(
        [
            [0, 0],
            [target_width - 1, 0],
            [target_width - 1, target_height - 1],
            [0, target_height - 1],
        ],
        dtype=np.float32,
    )
    transform = cv2.getPerspectiveTransform(expanded, destination)
    warped = cv2.warpPerspective(
        source,
        transform,
        (target_width, target_height),
        flags=cv2.INTER_CUBIC,
        borderValue=(255, 255, 255),
    )
    return pipeline._enhance_for_ocr(warped), transform, expanded


def _top_document_rectification(
    source: np.ndarray,
    corners: list[list[float]] | np.ndarray,
    expansion_ratio: float,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
    """Only expand the detected top edge while preserving side and bottom geometry."""
    if source.size == 0 or not 0.0 <= float(expansion_ratio) <= 0.14:
        return None
    points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    if not np.isfinite(points).all() or not cv2.isContourConvex(points.astype(np.int32)):
        return None
    top_left, top_right, bottom_right, bottom_left = points
    ratio = float(expansion_ratio)
    expanded = np.asarray(
        [
            top_left - ratio * (bottom_left - top_left),
            top_right - ratio * (bottom_right - top_right),
            bottom_right,
            bottom_left,
        ],
        dtype=np.float32,
    )
    height, width = source.shape[:2]
    expanded[:, 0] = np.clip(expanded[:, 0], 0, width - 1)
    expanded[:, 1] = np.clip(expanded[:, 1], 0, height - 1)
    target_width = int(round(max(
        np.linalg.norm(expanded[1] - expanded[0]),
        np.linalg.norm(expanded[2] - expanded[3]),
    )))
    target_height = int(round(max(
        np.linalg.norm(expanded[3] - expanded[0]),
        np.linalg.norm(expanded[2] - expanded[1]),
    )))
    if target_width < 40 or target_height < 40:
        return None
    destination = np.asarray(
        [[0, 0], [target_width - 1, 0], [target_width - 1, target_height - 1], [0, target_height - 1]],
        dtype=np.float32,
    )
    transform = cv2.getPerspectiveTransform(expanded, destination)
    warped = cv2.warpPerspective(
        source,
        transform,
        (target_width, target_height),
        flags=cv2.INTER_CUBIC,
        borderValue=(255, 255, 255),
    )
    return pipeline._enhance_for_ocr(warped), transform, expanded


def _bottom_document_rectification(
    source: np.ndarray,
    corners: list[list[float]] | np.ndarray,
    expansion_ratio: float,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
    """Only expand the detected bottom edge while preserving top and side geometry."""
    if source.size == 0 or not 0.0 <= float(expansion_ratio) <= 0.08:
        return None
    points = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    if not np.isfinite(points).all() or not cv2.isContourConvex(points.astype(np.int32)):
        return None
    top_left, top_right, bottom_right, bottom_left = points
    ratio = float(expansion_ratio)
    expanded = np.asarray(
        [
            top_left,
            top_right,
            bottom_right + ratio * (bottom_right - top_right),
            bottom_left + ratio * (bottom_left - top_left),
        ],
        dtype=np.float32,
    )
    height, width = source.shape[:2]
    expanded[:, 0] = np.clip(expanded[:, 0], 0, width - 1)
    expanded[:, 1] = np.clip(expanded[:, 1], 0, height - 1)
    target_width = int(round(max(
        np.linalg.norm(expanded[1] - expanded[0]),
        np.linalg.norm(expanded[2] - expanded[3]),
    )))
    target_height = int(round(max(
        np.linalg.norm(expanded[3] - expanded[0]),
        np.linalg.norm(expanded[2] - expanded[1]),
    )))
    if target_width < 40 or target_height < 40:
        return None
    destination = np.asarray(
        [[0, 0], [target_width - 1, 0], [target_width - 1, target_height - 1], [0, target_height - 1]],
        dtype=np.float32,
    )
    transform = cv2.getPerspectiveTransform(expanded, destination)
    warped = cv2.warpPerspective(
        source,
        transform,
        (target_width, target_height),
        flags=cv2.INTER_CUBIC,
        borderValue=(255, 255, 255),
    )
    return pipeline._enhance_for_ocr(warped), transform, expanded


def _grid_has_text_supported_trailing_rows(
    image: np.ndarray,
    grid: tuple[list[int], list[int], np.ndarray],
    base_row_count: int,
) -> bool:
    """Accept added bottom rows only when each contains text and continuing rules."""
    columns, rows, _ = grid
    growth = len(rows) - 1 - int(base_row_count)
    if not 1 <= growth <= 2 or len(columns) < 3:
        return False
    horizontal, vertical, _ = pipeline._grid_maps(image)
    first_added = len(rows) - 1 - growth
    for index in range(first_added, len(rows) - 1):
        top, bottom = int(rows[index]), int(rows[index + 1])
        if (
            not pipeline._leading_interval_has_text_components(
                image,
                top,
                bottom,
                horizontal,
                vertical,
            )
            or pipeline._edge_rule_continuation(
                vertical,
                [int(value) for value in columns[1:-1]],
                top + 2,
                bottom - 2,
                horizontal=False,
            )
            < 0.70
        ):
            return False
    return True


def _recover_opposite_edge_after_top_only_expansion(
    source: np.ndarray,
    rectified: np.ndarray,
    rectification: dict[str, Any],
    ruled_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray], dict[str, Any]] | None:
    """Finish a missed outer edge after a proven first expansion."""
    corners = rectification.get("corners")
    if (
        source.size == 0
        or ruled_grid is None
        or not (
            rectification.get("top_only_expansion") is True
            or (
                rectification.get("vertical_expansion_ratio") is not None
                and int(rectification.get("edge_rows_recovered", 0)) >= 1
            )
        )
        or not isinstance(corners, list)
        or len(corners) != 4
    ):
        return None
    baseline = _ruled_grid_edge_evidence(rectified, ruled_grid)
    if baseline is None:
        return None
    base_rows = len(ruled_grid[1]) - 1
    base_columns = len(ruled_grid[0]) - 1
    original_corners = np.asarray(corners, dtype=np.float32).reshape(4, 2)

    if not rectification.get("top_only_expansion"):
        clear_probes = 0
        for probe_ratio in (0.05, 0.06):
            _check_request_wall_clock("geometry_candidates")
            probe = _bottom_document_rectification(source, original_corners, probe_ratio)
            if probe is None:
                break
            probe_image, probe_transform, _ = probe
            projected = cv2.perspectiveTransform(
                original_corners.reshape(1, 4, 2), probe_transform
            )[0]
            bottom = int(round(float(np.mean(projected[2:, 1]))))
            row_gap = float(np.median(np.diff(ruled_grid[1]))) * (
                probe_image.shape[0] / max(1.0, float(rectified.shape[0]))
            )
            near = max(5, int(row_gap * 0.20))
            far = max(near + 8, int(row_gap * 1.50))
            horizontal, _, _ = pipeline._grid_maps(probe_image)
            left = int(probe_image.shape[1] * 0.08)
            right = int(probe_image.shape[1] * 0.92)
            support = np.count_nonzero(horizontal[:, left:right], axis=1) / max(1, right - left)
            band = support[min(len(support), bottom + near):min(len(support), bottom + far)]
            if band.size and float(band.max()) < 0.06:
                clear_probes += 1
        if clear_probes == 2:
            return None

    def stable_candidate(
        side: str,
    ) -> tuple[float, np.ndarray, tuple[list[int], list[int], np.ndarray], np.ndarray] | None:
        expander = (
            _top_document_rectification
            if side == "top"
            else _bottom_document_rectification
        )
        ratio_pairs = (
            (0.05, 0.06),
            (0.04, 0.05),
            (0.06, 0.07),
            (0.03, 0.035),
            (0.025, 0.03),
            (0.02, 0.025),
            (0.015, 0.02),
        )
        failed_ratios: set[float] = set()
        for ratio_pair in ratio_pairs:
            # 预算已经用掉大半就不再穷举：继续试下去只会撞 60 秒墙钟，
            # 整次识别失败。收尾用已经找到的候选，结果是"少一行"而不是"报错"。
            if _geometry_search_budget_exhausted():
                _note_geometry_search_truncated()
                break
            candidates = []
            for ratio in ratio_pair:
                # 2026-10-22 实测 FC-00016：这个循环最多 7 组 × 2 = 14 次
                # 「透视矫正 + 全分辨率重提取网格」，单次约 2 秒，合计近 30 秒
                # —— 全部发生在上一处检查点之后，墙钟看不到它，只能等它跑完
                # 再判定超时（78.9 秒）。这里逐候选检查，超时立刻停。
                _check_request_wall_clock("opposite_edge_candidate")
                if ratio in failed_ratios:
                    continue
                failed_ratios.add(ratio)
                expanded = expander(source, original_corners, ratio)
                if expanded is None:
                    continue
                candidate_image, transform, candidate_corners = expanded
                candidate_grid = pipeline.extract_ruled_grid(
                    candidate_image,
                    prefer_adaptive=True,
                )
                evidence = _ruled_grid_edge_evidence(
                    candidate_image,
                    candidate_grid,
                )
                if candidate_grid is None or evidence is None:
                    continue
                preserves, _ = _expanded_grid_preserves_base_and_adds_strong_rows(
                    baseline,
                    evidence,
                    original_corners,
                    transform,
                )
                row_count = len(candidate_grid[1]) - 1
                column_count = len(candidate_grid[0]) - 1
                if not (
                    preserves
                    and column_count == base_columns
                    and 1 <= row_count - base_rows <= 2
                    and _grid_geometry_is_bounded(
                        candidate_grid[0],
                        candidate_grid[1],
                        maximum_cells=maximum_cells,
                    )
                    and _photographic_ruled_grid_is_credible(
                        candidate_image,
                        candidate_grid[0],
                        candidate_grid[1],
                    )
                ):
                    continue
                if side == "top":
                    if (
                        row_count != base_rows + 1
                        or not pipeline._leading_interval_has_text_components(
                            candidate_image,
                            candidate_grid[1][0],
                            candidate_grid[1][1],
                            *pipeline._grid_maps(candidate_image)[:2],
                        )
                    ):
                        continue
                elif not _grid_has_text_supported_trailing_rows(
                    candidate_image,
                    candidate_grid,
                    base_rows,
                ):
                    continue
                candidates.append(
                    (ratio, candidate_image, candidate_grid, candidate_corners)
                )
                failed_ratios.remove(ratio)
            if (
                len(candidates) == 2
                and (
                    len(candidates[0][2][1]),
                    len(candidates[0][2][0]),
                )
                == (
                    len(candidates[1][2][1]),
                    len(candidates[1][2][0]),
                )
            ):
                return candidates[0]
        return None

    selected = (
        stable_candidate("top") or stable_candidate("bottom")
        if rectification.get("top_only_expansion") is True
        else stable_candidate("bottom")
    )
    if selected is None:
        return None
    ratio, candidate_image, candidate_grid, candidate_corners = selected
    metadata = dict(rectification)
    metadata.update(
        {
            "corners": [
                [round(float(point[0]), 2), round(float(point[1]), 2)]
                for point in candidate_corners
            ],
            "edge_completeness_checked": True,
            "edge_rows_recovered": len(candidate_grid[1]) - 1
            - (len(ruled_grid[1]) - 1)
            + int(rectification.get("edge_rows_recovered", 0)),
            "opposite_edge_expansion": True,
            "opposite_edge_expansion_ratio": ratio,
        }
    )
    return candidate_image, candidate_grid, metadata


def _ruled_grid_edge_evidence(
    image: np.ndarray,
    grid: tuple[list[int], list[int], np.ndarray] | None,
) -> dict[str, Any] | None:
    if image.size == 0 or grid is None:
        return None
    columns, rows, _ = grid
    if len(columns) < 3 or len(rows) < 4:
        return None
    horizontal, vertical = pipeline._physical_rule_maps(image)
    left = max(0, int(columns[0]))
    right = min(image.shape[1] - 1, int(columns[-1]))
    line_support: list[float] = []
    intersection_support: list[float] = []
    for row in rows:
        top = max(0, int(row) - 2)
        bottom = min(image.shape[0], int(row) + 3)
        band = horizontal[top:bottom, left : right + 1]
        line_support.append(
            float(np.mean(np.any(band > 0, axis=0))) if band.size else 0.0
        )
        intersections = 0
        for column in columns:
            column_left = max(0, int(column) - 3)
            column_right = min(image.shape[1], int(column) + 4)
            horizontal_patch = horizontal[top:bottom, column_left:column_right]
            vertical_patch = vertical[top:bottom, column_left:column_right]
            if np.any(horizontal_patch > 0) and np.any(vertical_patch > 0):
                intersections += 1
        intersection_support.append(intersections / float(max(1, len(columns))))
    return {
        "columns": [int(value) for value in columns],
        "rows": [int(value) for value in rows],
        "height": int(image.shape[0]),
        "line_support": line_support,
        "intersection_support": intersection_support,
    }


def _ruled_grid_has_closed_outer_frame(
    image: np.ndarray,
    grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> bool:
    """仅在外边框闭合且四周留有可检查的余量时停止扩边。"""
    if not _complete_ruled_photo_grid(image, grid, maximum_cells):
        return False
    evidence = _ruled_grid_edge_evidence(image, grid)
    if evidence is None or grid is None:
        return False
    columns, rows, _ = grid
    line_support = [float(value) for value in evidence["line_support"]]
    intersections = [float(value) for value in evidence["intersection_support"]]
    if (
        min(line_support[0], line_support[-1]) < 0.72
        or min(intersections[0], intersections[-1]) < 0.70
    ):
        return False

    _, vertical, _ = pipeline._grid_maps(image)
    typical = float(np.median(np.diff(rows)))
    probe_depth = max(8, int(round(typical * 0.55)))
    if rows[0] < probe_depth + 3 or image.shape[0] - rows[-1] < probe_depth + 3:
        return False
    if min(_vertical_rule_supports(image, columns, rows)[::len(columns) - 1]) < 0.70:
        return False

    def continuation(top: int, bottom: int) -> float:
        if bottom <= top:
            return 0.0
        supported = []
        for column in (columns[0], columns[-1]):
            left = max(0, int(column) - 3)
            right = min(vertical.shape[1], int(column) + 4)
            band = vertical[top:bottom, left:right]
            supported.append(
                float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            )
        return max(supported, default=0.0)

    top_end = max(0, int(rows[0]) - 3)
    bottom_start = min(vertical.shape[0], int(rows[-1]) + 3)
    above = continuation(max(0, top_end - probe_depth), top_end)
    below = continuation(
        bottom_start, min(vertical.shape[0], bottom_start + probe_depth)
    )
    return bool(above < 0.20 and below < 0.20)


def _grid_has_two_leading_merged_header_rows(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Confirm two text-bearing sparse header bands before a divided detail row."""
    if len(columns) < 4 or len(rows) < 5:
        return False
    _, vertical, _ = pipeline._grid_maps(image)

    def internal_support(row: int) -> list[float]:
        top, bottom = int(rows[row]), int(rows[row + 1])
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        values = []
        for boundary in columns[1:-1]:
            band = vertical[
                band_top:band_bottom,
                max(0, int(boundary) - 3) : min(vertical.shape[1], int(boundary) + 4),
            ]
            values.append(
                float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            )
        return values

    first = internal_support(0)
    second = internal_support(1)
    detail = internal_support(2)
    return bool(
        first
        and second
        and detail
        and float(np.mean(first)) < 0.25
        and float(np.mean(second)) < 0.35
        and sum(value >= 0.35 for value in detail)
        >= max(2, int(math.ceil(len(detail) * 0.65)))
        and pipeline._leading_interval_has_text_components(
            image,
            int(rows[0]),
            int(rows[1]),
            None,
            vertical,
        )
        and pipeline._leading_interval_has_text_components(
            image,
            int(rows[1]),
            int(rows[2]),
            None,
            vertical,
        )
    )


def _blank_form_physical_grid_is_safe(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    *,
    photographic_background: bool,
) -> bool:
    """Accept a sparse form only when a complete physical frame proves its blanks."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        photographic_background
        or not 8 <= row_count <= 80
        or not 2 <= column_count <= 12
        or len(columns) != column_count + 1
        or len(rows) != row_count + 1
        or any(len(row) != column_count for row in grid)
        or row_count * column_count > 320
    ):
        return False
    height, width = image.shape[:2]
    if (
        columns[0] > width * 0.10
        or columns[-1] < width * 0.90
        or rows[0] > height * 0.10
        or rows[-1] < height * 0.90
    ):
        return False
    evidence = _ruled_grid_edge_evidence(image, (columns, rows, np.empty((0, 0))))
    if evidence is None:
        return False
    line_support = [float(value) for value in evidence["line_support"]]
    intersections = [float(value) for value in evidence["intersection_support"]]
    if (
        not line_support
        or min(line_support) < 0.90
        or float(np.median(intersections)) < 0.65
    ):
        return False
    populations = [sum(bool(str(value).strip()) for value in row) for row in grid]
    title_rows = [row for row in range(min(2, row_count)) if populations[row] == 1]
    if len(title_rows) != 1:
        return False
    title_row = title_rows[0]
    header_row = title_row + 1
    if header_row >= row_count or populations[header_row] < column_count - 1:
        return False
    blank_runs: list[tuple[int, int]] = []
    start = None
    for row, population in enumerate(populations[header_row + 1 :], start=header_row + 1):
        if population == 0 and start is None:
            start = row
        elif population != 0 and start is not None:
            blank_runs.append((start, row))
            start = None
    if start is not None:
        blank_runs.append((start, row_count))
    qualifying = [run for run in blank_runs if run[1] - run[0] >= 3]
    if len(qualifying) != 1:
        return False
    blank_start, blank_end = qualifying[0]
    labelled_tail_rows = sum(populations[row] > 0 for row in range(blank_end, row_count))
    return bool(blank_start == header_row + 1 and labelled_tail_rows >= 2)


def _trim_window_chrome_bands(
    image: np.ndarray,
    ruled_grid: tuple[list[int], list[int], np.ndarray],
) -> tuple[list[int], list[int], np.ndarray]:
    """把电子表格窗口的外壳行带（功能区/公式栏/行列标尺/状态栏）从物理网格剔掉。

    Excel/WPS 截图里工作表的竖向网格线只从表体区域开始：功能区标签、公式栏的
    名称框、行列标尺都落在竖线覆盖范围之外。旧实现只能"先认出列标尺行，再连带
    删掉它上面的行"——一旦用户关掉了标尺（show_rulers=False，这条路极常见），
    功能区就直接混进交付的表格：实测 10x4 的库存台账被读成 12x6，多出
    "文件/开始/插入/页面布局/公式/数据/审阅/视图"和名称框 "B2:D"。

    判据纯几何：某个行带内几乎没有列边界竖线穿过，就说明它落在表体之外。为避免
    误伤真实表头，这里要求整张网格过半的行带都确实被竖线贯穿，且网格贴近画面
    上下边缘（这是"窗口截图"而非"裁好的表"的特征），并且至少保留 2 行。
    """
    columns, rows, mask = ruled_grid
    row_count = len(rows) - 1
    if row_count < 4 or len(columns) < 3 or image is None or image.size == 0:
        return ruled_grid
    height, width = image.shape[:2]
    if height < 120 or width < 300:
        return ruled_grid
    _, vertical, _ = pipeline._grid_maps(image)
    if vertical is None or vertical.size == 0:
        return ruled_grid

    def band_support(index: int) -> float:
        top = max(0, int(rows[index]) + 2)
        bottom = min(vertical.shape[0], int(rows[index + 1]) - 2)
        if bottom - top < 4:
            return 1.0
        values = []
        for boundary in columns[1:-1]:
            left = max(0, int(boundary) - 3)
            right = min(vertical.shape[1], int(boundary) + 4)
            piece = vertical[top:bottom, left:right]
            values.append(
                float(np.mean(np.any(piece > 0, axis=1))) if piece.size else 0.0
            )
        return float(np.mean(values)) if values else 1.0

    supports = [band_support(index) for index in range(row_count)]
    ruled_bands = sum(value >= 0.60 for value in supports)
    if ruled_bands < max(3, int(math.ceil(row_count * 0.50))):
        return ruled_grid
    first = 0
    if rows[0] <= height * 0.30:
        while first + 2 < row_count and supports[first] < 0.25:
            first += 1
    last = row_count
    if rows[-1] >= height * 0.70:
        while last - first > 2 and supports[last - 1] < 0.25:
            last -= 1
    if first == 0 and last == row_count:
        return ruled_grid
    _write_runtime_trace(
        "route",
        name="window_chrome_bands_trimmed",
        leading=first,
        trailing=row_count - last,
        rows=last - first,
    )
    return columns, rows[first:last + 1], mask


def _raw_blank_form_grid_candidate(
    image: np.ndarray,
    current_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> tuple[list[int], list[int], np.ndarray] | None:
    """Recover a clear blank form from raw full-length physical rules."""
    if image.size == 0 or min(image.shape[:2]) < 160:
        return None
    horizontal, vertical, _ = pipeline._grid_maps(image)
    columns = pipeline._line_centers(
        np.count_nonzero(vertical, axis=0), image.shape[0]
    )
    rows = pipeline._line_centers(
        np.count_nonzero(horizontal, axis=1), image.shape[1]
    )
    row_count = len(rows) - 1
    column_count = len(columns) - 1
    if (
        not 3 <= row_count <= 80
        or not 2 <= column_count <= 12
        or row_count * column_count > maximum_cells
        or columns[0] > image.shape[1] * 0.10
        or columns[-1] < image.shape[1] * 0.90
        or rows[0] > image.shape[0] * 0.10
        or rows[-1] < image.shape[0] * 0.90
    ):
        return None
    if current_grid is not None and (
        len(current_grid[0]) == len(columns)
        and len(current_grid[1]) == len(rows)
    ):
        return None
    row_gaps = np.diff(rows).astype(float)
    typical_gap = float(np.median(row_gaps[2:])) if row_gaps.size > 2 else 0.0
    if (
        typical_gap < 12.0
        or row_gaps[0] < typical_gap * 1.25
        or row_gaps[1] < typical_gap * 1.25
    ):
        return None

    internal_count = max(0, column_count - 1)
    if internal_count < 1:
        return None

    def interval_divider_count(row: int) -> int:
        top, bottom = int(rows[row]), int(rows[row + 1])
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        count = 0
        for boundary in columns[1:-1]:
            band = vertical[
                band_top:band_bottom,
                max(0, int(boundary) - 3) : min(vertical.shape[1], int(boundary) + 4),
            ]
            support = float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            count += support >= 0.80
        return count

    divider_counts = [interval_divider_count(row) for row in range(row_count)]
    if (
        divider_counts[0] > max(1, int(math.floor(internal_count * 0.34)))
        or divider_counts[1] < max(1, int(math.ceil(internal_count * 0.80)))
    ):
        return None
    full_body_floor = max(1, int(math.ceil(internal_count * 0.80)))
    body_end = 2
    while body_end < row_count and divider_counts[body_end] >= full_body_floor:
        body_end += 1
    if body_end - 2 < 3 or row_count - body_end < 2:
        return None
    tail_ceiling = max(1, int(math.floor(internal_count * 0.34)))
    if any(count > tail_ceiling for count in divider_counts[body_end:]):
        return None

    mask = cv2.bitwise_or(horizontal, vertical)
    mask = cv2.dilate(mask, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)))
    cleaned = image.copy()
    cleaned[mask > 0] = 255
    return (
        [int(value) for value in columns],
        [int(value) for value in rows],
        cleaned,
    )


def _trim_blank_form_outer_closure_rows(
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> tuple[list[int], list[list[str]], list[list[float]] | None] | None:
    """Remove only empty closure intervals outside a recognisable blank form."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count < 8
        or column_count < 2
        or len(rows) != row_count + 1
        or any(len(row) != column_count for row in grid)
    ):
        return None
    populations = [sum(bool(str(value).strip()) for value in row) for row in grid]
    start = 0
    while start < min(3, row_count) and populations[start] == 0:
        start += 1
    end = row_count
    while end > max(start, row_count - 3) and populations[end - 1] == 0:
        end -= 1
    if start == 0 and end == row_count:
        return None
    trimmed_populations = populations[start:end]
    if len(trimmed_populations) < 8 or trimmed_populations[0] != 1:
        return None
    if len(trimmed_populations) < 2 or trimmed_populations[1] < column_count - 1:
        return None
    blank_runs: list[tuple[int, int]] = []
    blank_start = None
    for row, population in enumerate(trimmed_populations[2:], start=2):
        if population == 0 and blank_start is None:
            blank_start = row
        elif population != 0 and blank_start is not None:
            blank_runs.append((blank_start, row))
            blank_start = None
    if blank_start is not None:
        blank_runs.append((blank_start, len(trimmed_populations)))
    qualifying = [run for run in blank_runs if run[1] - run[0] >= 3]
    if len(qualifying) != 1 or qualifying[0][0] != 2:
        return None
    labelled_tail_rows = sum(
        population > 0 for population in trimmed_populations[qualifying[0][1] :]
    )
    if labelled_tail_rows < 2:
        return None
    trimmed_confidence = (
        None
        if confidence_grid is None
        else [list(row) for row in confidence_grid[start:end]]
    )
    return (
        list(rows[start : end + 1]),
        [list(row) for row in grid[start:end]],
        trimmed_confidence,
    )


def _collapse_blank_form_split_header_row(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> tuple[list[int], list[list[str]], list[list[float]] | None] | None:
    """Remove one weak false divider that splits a tall blank-form header."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count < 9
        or not 2 <= column_count <= 12
        or len(columns) != column_count + 1
        or len(rows) != row_count + 1
        or any(len(row) != column_count for row in grid)
    ):
        return None
    populations = [sum(bool(str(value).strip()) for value in row) for row in grid]
    if populations[0] != 1 or min(populations[1], populations[2]) > 1:
        return None
    merged_header: list[str] = []
    merged_scores: list[float] = []
    for column in range(column_count):
        upper = str(grid[1][column]).strip()
        lower = str(grid[2][column]).strip()
        if upper and lower:
            upper_key = _comparable_text(upper)
            lower_key = _comparable_text(lower)
            if upper_key not in lower_key and lower_key not in upper_key:
                return None
            selected = upper if len(upper_key) >= len(lower_key) else lower
        else:
            selected = upper or lower
        merged_header.append(selected)
        if confidence_grid is not None:
            scores = [
                float(confidence_grid[row][column])
                for row in (1, 2)
                if str(grid[row][column]).strip()
            ]
            merged_scores.append(min(scores) if scores else 0.0)
    if sum(bool(value) for value in merged_header) < column_count - 1:
        return None
    blank_end = 3
    while blank_end < row_count and populations[blank_end] == 0:
        blank_end += 1
    if blank_end - 3 < 3:
        return None
    if sum(populations[row] > 0 for row in range(blank_end, row_count)) < 2:
        return None

    horizontal = pipeline._grid_maps(image)[0]
    support_values = []
    for boundary in (rows[1], rows[2], rows[3]):
        band = horizontal[
            max(0, int(boundary) - 2) : min(horizontal.shape[0], int(boundary) + 3),
            max(0, int(columns[0])) : min(horizontal.shape[1], int(columns[-1]) + 1),
        ]
        support_values.append(
            float(np.mean(np.any(band > 0, axis=0))) if band.size else 0.0
        )
    if not (
        support_values[0] >= 0.80
        and support_values[1] < 0.50
        and support_values[2] >= 0.80
    ):
        return None

    collapsed_grid = [list(grid[0]), merged_header, *[list(row) for row in grid[3:]]]
    collapsed_confidence = None
    if confidence_grid is not None:
        collapsed_confidence = [
            list(confidence_grid[0]),
            merged_scores,
            *[list(row) for row in confidence_grid[3:]],
        ]
    return (
        [int(value) for value in [*rows[:2], *rows[3:]]],
        collapsed_grid,
        collapsed_confidence,
    )


def _recover_blank_form_physical_spans(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    *,
    force_title_span: bool = False,
) -> list[dict[str, Any]]:
    """Recover title and repeated blank-entry merges from physical dividers."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count < 2
        or column_count < 2
        or len(columns) != column_count + 1
        or len(rows) != row_count + 1
    ):
        return []
    _, vertical, _ = pipeline._grid_maps(image)

    def supported_boundaries(row: int) -> list[int]:
        top, bottom = int(rows[row]), int(rows[row + 1])
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        supported = [0]
        for index, boundary in enumerate(columns[1:-1], start=1):
            band = vertical[
                band_top:band_bottom,
                max(0, int(boundary) - 3) : min(vertical.shape[1], int(boundary) + 4),
            ]
            support = float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            if support >= 0.90:
                supported.append(index)
        supported.append(column_count)
        return supported

    spans: list[dict[str, Any]] = []
    title_cells = [column for column, value in enumerate(grid[0]) if str(value).strip()]
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    title_top, title_bottom = int(rows[0]), int(rows[1])
    title_inset = max(2, int(round((title_bottom - title_top) * 0.16)))
    title_band_top = min(title_bottom, title_top + title_inset)
    title_band_bottom = max(title_band_top + 1, title_bottom - title_inset)
    title_has_internal_divider = False
    for boundary in columns[1:-1]:
        band = gray[
            title_band_top:title_band_bottom,
            max(0, int(boundary) - 2) : min(gray.shape[1], int(boundary) + 3),
        ]
        if band.size and float(np.max(np.mean(band < 180, axis=0))) >= 0.95:
            title_has_internal_divider = True
            break
    if title_cells and (force_title_span or not title_has_internal_divider):
        title_text = "".join(str(grid[0][column]).strip() for column in title_cells)
        title_scores = (
            [float(confidence_grid[0][column]) for column in title_cells]
            if confidence_grid is not None
            else []
        )
        grid[0] = [""] * column_count
        grid[0][0] = title_text
        if confidence_grid is not None:
            confidence_grid[0] = [0.0] * column_count
            confidence_grid[0][0] = min(title_scores) if title_scores else 0.77
        spans.append(
            {
                "row": 0,
                "column": 0,
                "row_span": 1,
                "column_span": column_count,
                "role": "title",
            }
        )

    patterns = [supported_boundaries(row) for row in range(row_count)]
    for row in range(1, row_count):
        boundaries = patterns[row]
        if len(boundaries) >= column_count + 1:
            continue
        row_has_text = any(str(value).strip() for value in grid[row])
        repeated_blank_pattern = bool(
            not row_has_text
            and row >= 3
            and patterns[row - 1] == boundaries
            and patterns[row - 2] == boundaries
        )
        if not row_has_text and not repeated_blank_pattern:
            continue
        for start, end in zip(boundaries, boundaries[1:]):
            if end - start <= 1:
                continue
            hidden_text = any(str(grid[row][column]).strip() for column in range(start + 1, end))
            if hidden_text:
                continue
            spans.append(
                {
                    "row": row,
                    "column": start,
                    "row_span": 1,
                    "column_span": end - start,
                    "role": "merged",
                }
            )
    return spans


def _recover_blank_form_title_multiview(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
    ocr_engine: Any,
) -> list[float]:
    """Re-read a blank-form title only when three model families agree."""
    if (
        not grid
        or confidence_grid is None
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or not any(
            span.get("role") == "title"
            and int(span.get("row", -1)) == 0
            and int(span.get("column", -1)) == 0
            and int(span.get("column_span", 1)) == len(grid[0])
            for span in spans
        )
    ):
        return []
    recognizers = [
        getattr(ocr_engine, "fast_text_rec", None),
        getattr(ocr_engine, "text_rec", None),
        getattr(ocr_engine, "server_text_rec", None),
    ]
    if not all(callable(recognizer) for recognizer in recognizers):
        return []
    crop = image[
        max(0, int(rows[0]) + 2) : min(image.shape[0], int(rows[1]) - 2),
        max(0, int(columns[0]) + 2) : min(image.shape[1], int(columns[-1]) - 2),
    ]
    tight = _tight_text_crop(crop) if crop.size else crop
    if tight.size == 0:
        return []
    views = [
        tight,
        cv2.resize(tight, None, fx=2.0, fy=2.0, interpolation=cv2.INTER_LANCZOS4),
        cv2.resize(tight, None, fx=3.2, fy=3.2, interpolation=cv2.INTER_LANCZOS4),
    ]
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    family_results: list[tuple[str, float]] = []
    all_scores: list[float] = []
    for recognizer in recognizers:
        output = recognizer(TextRecInput(img=views))
        _release_recognition_images(output)
        texts = [str(value).strip() for value in output.txts]
        scores = [float(value) for value in output.scores]
        all_scores.extend(scores)
        if len(texts) != 3 or len(scores) != 3:
            return all_scores
        groups: dict[str, list[tuple[str, float]]] = {}
        for text, score in zip(texts, scores):
            key = _comparable_text(text)
            if len(key) >= 3 and score >= 0.90:
                groups.setdefault(key, []).append((text, score))
        supported = [values for values in groups.values() if len(values) >= 2]
        if len(supported) != 1:
            return all_scores
        values = supported[0]
        family_results.append((values[0][0], min(score for _, score in values)))
    keys = {_comparable_text(text) for text, _ in family_results}
    if len(keys) != 1:
        confidence_grid[0][0] = min(float(confidence_grid[0][0]), 0.77)
        return all_scores
    grid[0][0] = family_results[0][0]
    confidence_grid[0][0] = min(score for _, score in family_results)
    return all_scores


def _clear_blank_form_span_subordinates(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
) -> set[tuple[int, int]]:
    """Clear model fills from physically merged subordinate cells."""
    cleared: set[tuple[int, int]] = set()
    for span in spans:
        anchor_row = int(span.get("row", -1))
        anchor_column = int(span.get("column", -1))
        row_span = max(1, int(span.get("row_span", 1)))
        column_span = max(1, int(span.get("column_span", 1)))
        for row in range(anchor_row, anchor_row + row_span):
            for column in range(anchor_column, anchor_column + column_span):
                if (row, column) == (anchor_row, anchor_column):
                    continue
                if not (
                    0 <= row < len(grid)
                    and 0 <= row < len(confidence_grid)
                    and 0 <= column < len(grid[row])
                    and 0 <= column < len(confidence_grid[row])
                ):
                    continue
                if str(grid[row][column]).strip() or float(confidence_grid[row][column]) != 0.0:
                    cleared.add((row, column))
                grid[row][column] = ""
                confidence_grid[row][column] = 0.0
    return cleared


def _matched_boundary_ratio(
    reference: list[float],
    candidate: list[float],
    tolerance: float,
) -> float:
    if not reference:
        return 0.0
    return sum(
        any(abs(value - other) <= tolerance for other in candidate)
        for value in reference
    ) / float(len(reference))


def _expanded_grid_preserves_base_and_adds_strong_rows(
    baseline: dict[str, Any],
    candidate: dict[str, Any],
    original_corners: np.ndarray,
    transform: np.ndarray,
) -> tuple[bool, bool]:
    projected = cv2.perspectiveTransform(
        original_corners.reshape(1, 4, 2).astype(np.float32),
        transform,
    )[0]
    old_top = float((projected[0, 1] + projected[1, 1]) / 2.0)
    old_bottom = float((projected[2, 1] + projected[3, 1]) / 2.0)
    old_span = max(1.0, old_bottom - old_top)
    mapped_rows = [
        (float(row) - old_top) / old_span * max(1, int(baseline["height"]) - 1)
        for row in candidate["rows"]
        if old_top - 3 <= row <= old_bottom + 3
    ]
    base_gaps = np.diff(baseline["rows"])
    row_tolerance = (
        max(3.0, float(np.median(base_gaps)) * 0.25)
        if base_gaps.size
        else 3.0
    )
    base_row_values = [float(value) for value in baseline["rows"]]
    matched_base_rows = [
        any(abs(value - other) <= row_tolerance for other in mapped_rows)
        for value in base_row_values
    ]
    unmatched_row_indices = [
        index for index, matched in enumerate(matched_base_rows) if not matched
    ]
    rows_preserved = bool(
        sum(matched_base_rows) / float(max(1, len(matched_base_rows))) >= 0.95
        and len(unmatched_row_indices) <= 2
        and all(
            index
            in {
                0,
                1,
                len(matched_base_rows) - 2,
                len(matched_base_rows) - 1,
            }
            for index in unmatched_row_indices
        )
    )

    base_columns = baseline["columns"]
    candidate_columns = candidate["columns"]
    if len(candidate_columns) < len(base_columns):
        return False, False
    base_span = max(1.0, float(base_columns[-1] - base_columns[0]))
    candidate_span = max(1.0, float(candidate_columns[-1] - candidate_columns[0]))
    base_normalized = [(value - base_columns[0]) / base_span for value in base_columns]
    candidate_normalized = [
        (value - candidate_columns[0]) / candidate_span for value in candidate_columns
    ]
    normalized_gaps = np.diff(base_normalized)
    column_tolerance = (
        max(0.005, float(np.median(normalized_gaps)) * 0.25)
        if normalized_gaps.size
        else 0.005
    )
    columns_preserved = _matched_boundary_ratio(
        base_normalized,
        candidate_normalized,
        column_tolerance,
    ) >= 1.0

    outside_tolerance = max(3.0, row_tolerance)
    added_indices = [
        index
        for index, row in enumerate(candidate["rows"])
        if row < old_top - outside_tolerance or row > old_bottom + outside_tolerance
    ]
    all_added_strong = bool(added_indices) and all(
        candidate["line_support"][index] >= 0.50
        or candidate["intersection_support"][index] >= 0.70
        for index in added_indices
    )
    base_shape_preserved = bool(rows_preserved and columns_preserved)
    return base_shape_preserved, all_added_strong


def _stronger_morphology_grid_for_edge_recovery(
    image: np.ndarray,
    ruled_grid: tuple[list[int], list[int], np.ndarray],
    *,
    maximum_cells: int,
) -> tuple[list[int], list[int], np.ndarray]:
    """Prefer independently supported raw rules when a screen candidate dropped lines."""
    current_columns, current_rows, _ = ruled_grid
    if _photographic_ruled_grid_is_credible(image, current_columns, current_rows):
        return ruled_grid
    horizontal, vertical, _ = pipeline._grid_maps(image)
    raw_columns = pipeline._line_centers(
        np.count_nonzero(vertical, axis=0), image.shape[0]
    )
    raw_rows = pipeline._line_centers(
        np.count_nonzero(horizontal, axis=1), image.shape[1]
    )
    column_growth = len(raw_columns) - len(current_columns)
    row_growth = len(raw_rows) - len(current_rows)
    if not (
        1 <= column_growth <= max(4, int(math.ceil(len(current_columns) * 0.50)))
        and 0 <= row_growth <= 6
        and _grid_geometry_is_bounded(
            raw_columns, raw_rows, maximum_cells=maximum_cells
        )
        and _photographic_ruled_grid_is_credible(image, raw_columns, raw_rows)
    ):
        return ruled_grid
    mask = cv2.bitwise_or(horizontal, vertical)
    mask = cv2.dilate(mask, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)))
    cleaned = image.copy()
    cleaned[mask > 0] = 255
    return raw_columns, raw_rows, cleaned


def _restore_visible_top_interval_boundary(
    image: np.ndarray,
    ruled_grid: tuple[list[int], list[int], np.ndarray] | None,
) -> tuple[list[int], list[int], np.ndarray] | None:
    """Restore a clipped top border when the visible interval contains a heading."""
    if ruled_grid is None or image.size == 0:
        return ruled_grid
    columns, rows, cleaned = ruled_grid
    if len(columns) < 3 or len(rows) < 5 or int(rows[0]) <= 3:
        return ruled_grid
    gaps = np.diff(rows).astype(float)
    typical_gap = float(np.median(gaps)) if gaps.size else 0.0
    first_boundary = int(rows[0])
    if (
        typical_gap < 8.0
        or first_boundary < typical_gap * 0.55
        or first_boundary > typical_gap * 2.20
    ):
        return ruled_grid
    horizontal, vertical, _ = pipeline._grid_maps(image)
    left = max(0, int(columns[0]))
    right = min(image.shape[1], int(columns[-1]) + 1)
    line_band = horizontal[
        max(0, first_boundary - 3) : min(image.shape[0], first_boundary + 4),
        left:right,
    ]
    line_coverage = (
        float(np.mean(np.any(line_band > 0, axis=0)))
        if line_band.size
        else 0.0
    )
    if (
        line_coverage < 0.65
        or not pipeline._leading_interval_has_text_components(
            image,
            0,
            first_boundary,
            horizontal,
            vertical,
        )
    ):
        return ruled_grid
    return list(columns), [0, *[int(value) for value in rows]], cleaned


def _recover_shadowed_regular_photo_rows(
    image: np.ndarray,
    ruled_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> tuple[list[int], list[int], np.ndarray] | None:
    """Recover a low-contrast upper row sequence from a stable lower ruled rhythm."""
    if ruled_grid is None or image.size == 0:
        return ruled_grid
    columns, rows, cleaned = ruled_grid
    height, width = image.shape[:2]
    if (
        not 4 <= len(columns) - 1 <= 12
        or not 8 <= len(rows) - 1 <= 80
        or int(rows[0]) < height * 0.25
        or int(columns[-1]) - int(columns[0]) < width * 0.80
    ):
        return ruled_grid
    observed_gaps = np.diff(rows).astype(float)
    typical_observed = float(np.median(observed_gaps)) if observed_gaps.size else 0.0
    if (
        typical_observed < 12.0
        or float(np.mean(np.abs(observed_gaps - typical_observed) <= typical_observed * 0.22))
        < 0.75
    ):
        return ruled_grid
    horizontal, vertical, _ = pipeline._grid_maps(image)
    left, right = int(columns[0]), int(columns[-1])
    table_width = max(1, right - left)
    projection = np.count_nonzero(horizontal[:, left:right], axis=1)
    extended = pipeline._extend_regular_boundaries_with_evidence(
        list(rows),
        projection,
        table_width,
        0,
        height - 1,
    )
    if len(extended) < len(rows) + 4:
        return ruled_grid
    extended_gaps = np.diff(extended).astype(float)
    ordinary = extended_gaps[
        extended_gaps <= np.percentile(extended_gaps, 75)
    ]
    typical = float(np.median(ordinary)) if ordinary.size else 0.0
    if typical < 12.0:
        return ruled_grid
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    edge_profile = np.mean(
        np.abs(cv2.Sobel(gray, cv2.CV_32F, 0, 1, ksize=3))[:, left:right],
        axis=1,
    )
    target = int(round(float(extended[0]) - typical))
    radius = max(5, int(round(typical * 0.45)))
    search_start = max(3, target - radius)
    search_stop = min(int(extended[0]) - 4, target + radius)
    if search_stop <= search_start:
        return ruled_grid
    preceding = search_start + int(
        np.argmax(edge_profile[search_start:search_stop])
    )
    reference_edges = [
        float(edge_profile[int(row)])
        for row in extended[1:-1]
        if 0 <= int(row) < len(edge_profile)
    ]
    if (
        not reference_edges
        or float(edge_profile[preceding])
        < max(45.0, float(np.median(reference_edges)) * 0.45)
    ):
        return ruled_grid
    if preceding <= typical * 0.65:
        top_border = preceding
        recovered_rows = sorted(
            {top_border, *[int(value) for value in extended]}
        )
    else:
        top_limit = max(3, int(round(preceding - typical * 0.65)))
        if top_limit <= 3:
            return ruled_grid
        top_border = int(np.argmax(projection[:top_limit]))
        if float(projection[top_border]) / table_width < 0.25:
            return ruled_grid
        recovered_rows = sorted(
            {top_border, preceding, *[int(value) for value in extended]}
        )
    leading_header_supported = _grid_has_two_leading_merged_header_rows(
        image,
        columns,
        recovered_rows,
    )
    if not leading_header_supported and len(recovered_rows) >= 4:
        first_text = pipeline._leading_interval_has_text_components(
            image,
            recovered_rows[0],
            recovered_rows[1],
            None,
            vertical,
        )
        second_text = pipeline._leading_interval_has_text_components(
            image,
            recovered_rows[1],
            recovered_rows[2],
            None,
            vertical,
        )
        detail_top, detail_bottom = recovered_rows[2], recovered_rows[3]
        detail_inset = max(2, int(round((detail_bottom - detail_top) * 0.16)))
        edge_x = np.abs(cv2.Sobel(gray, cv2.CV_32F, 1, 0, ksize=3))
        supported_boundaries = 0
        for boundary in columns[1:-1]:
            band = edge_x[
                detail_top + detail_inset : detail_bottom - detail_inset,
                max(0, int(boundary) - 8) : min(width, int(boundary) + 9),
            ]
            if not band.size:
                continue
            column_means = np.mean(band, axis=0)
            strongest = int(np.argmax(column_means))
            strength = float(column_means[strongest])
            coverage = float(np.mean(band[:, strongest] >= 15.0))
            if strength >= 12.0 and coverage >= 0.70:
                supported_boundaries += 1
        leading_header_supported = bool(
            first_text
            and second_text
            and supported_boundaries
            >= max(2, int(math.ceil((len(columns) - 2) * 0.30)))
        )
    if (
        (len(recovered_rows) - 1) * (len(columns) - 1) > maximum_cells
        or not leading_header_supported
        or not _photographic_ruled_grid_is_credible(
            image,
            columns,
            recovered_rows,
        )
    ):
        return ruled_grid
    return list(columns), recovered_rows, cleaned


def _recover_missing_photo_grid_from_shadowed_expansions(
    source: np.ndarray,
    rectification: dict[str, Any],
    *,
    maximum_cells: int,
) -> tuple[
    np.ndarray,
    tuple[list[int], list[int], np.ndarray],
    dict[str, Any],
] | None:
    """Recover a full low-contrast grid only when two nearby expansions agree."""
    corners = rectification.get("corners")
    if (
        source.size == 0
        or rectification.get("detected") is not True
        or rectification.get("mode") != "auto"
        or not isinstance(corners, list)
        or len(corners) != 4
    ):
        return None
    original_corners = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    candidates = []
    for ratio in (0.062, 0.065):
        _check_request_wall_clock("geometry_candidates")
        expanded = _vertical_document_rectification(
            source,
            original_corners,
            ratio,
        )
        if expanded is None:
            continue
        candidate_image, _, expanded_corners = expanded
        candidate_grid = pipeline.extract_ruled_grid(
            candidate_image,
            prefer_adaptive=True,
        )
        candidate_grid = _restore_visible_top_interval_boundary(
            candidate_image,
            candidate_grid,
        )
        candidate_grid = _recover_shadowed_regular_photo_rows(
            candidate_image,
            candidate_grid,
            maximum_cells=maximum_cells,
        )
        if (
            candidate_grid is None
            or not _grid_geometry_is_bounded(
                candidate_grid[0],
                candidate_grid[1],
                maximum_cells=maximum_cells,
            )
        ):
            continue
        candidates.append(
            (ratio, candidate_image, candidate_grid, expanded_corners)
        )
    if len(candidates) != 2:
        return None
    first, second = candidates
    first_shape = (len(first[2][1]) - 1, len(first[2][0]) - 1)
    second_shape = (len(second[2][1]) - 1, len(second[2][0]) - 1)
    if first_shape != second_shape:
        return None

    def normalized(values: list[int], extent: int) -> np.ndarray:
        return np.asarray(values, dtype=float) / max(1.0, float(extent - 1))

    first_columns = normalized(first[2][0], first[1].shape[1])
    second_columns = normalized(second[2][0], second[1].shape[1])
    first_rows = normalized(first[2][1], first[1].shape[0])
    second_rows = normalized(second[2][1], second[1].shape[0])
    interior_column_delta = float(
        np.max(np.abs(first_columns[1:-1] - second_columns[1:-1]))
    )
    outer_column_delta = max(
        abs(float(first_columns[0]) - float(second_columns[0])),
        abs(float(first_columns[-1]) - float(second_columns[-1])),
    )
    if (
        interior_column_delta > 0.015
        or outer_column_delta > 0.05
        or float(np.max(np.abs(first_rows - second_rows))) > 0.035
    ):
        return None
    ratio, candidate_image, candidate_grid, expanded_corners = first
    metadata = dict(rectification)
    metadata.update(
        {
            "corners": [
                [round(float(point[0]), 2), round(float(point[1]), 2)]
                for point in expanded_corners
            ],
            "base_corners": corners,
            "edge_completeness_checked": True,
            "vertical_expansion_ratio": ratio,
            "shadowed_regular_rows_recovered": True,
        }
    )
    return candidate_image, candidate_grid, metadata


def _more_complete_perspective_grid_than_partial_screen(
    image: np.ndarray,
    screen_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray], dict[str, Any]] | None:
    """Reject a locally straight grid when perspective reveals the full table."""
    if screen_grid is None or image is None or image.size == 0:
        return None
    screen_columns, screen_rows, _ = screen_grid
    screen_row_count = len(screen_rows) - 1
    screen_column_count = len(screen_columns) - 1
    height = image.shape[0]
    if (
        not 2 <= screen_row_count <= 10
        or not 2 <= screen_column_count <= 12
        or len(screen_rows) < 2
        or (screen_rows[-1] - screen_rows[0]) >= height * 0.55
        or screen_rows[0] < height * 0.10
        or screen_rows[-1] > height * 0.90
    ):
        return None

    candidate_image, metadata = pipeline.prepare_image(image, "auto")
    if metadata.get("detected") is not True:
        return None
    candidate_grid = pipeline.extract_ruled_grid(
        candidate_image,
        prefer_adaptive=True,
    )
    if candidate_grid is None:
        return None
    candidate_columns, candidate_rows, _ = candidate_grid
    candidate_row_count = len(candidate_rows) - 1
    candidate_column_count = len(candidate_columns) - 1
    candidate_height = candidate_image.shape[0]
    if (
        candidate_row_count < max(5, screen_row_count + 2)
        or not screen_column_count - 1
        <= candidate_column_count
        <= screen_column_count + 2
        or candidate_rows[0] > candidate_height * 0.12
        or candidate_rows[-1] < candidate_height * 0.88
        or candidate_columns[0] > candidate_image.shape[1] * 0.12
        or candidate_columns[-1] < candidate_image.shape[1] * 0.88
        or not _grid_geometry_is_bounded(
            candidate_columns,
            candidate_rows,
            maximum_cells=maximum_cells,
        )
        or not _photographic_ruled_grid_is_credible(
            candidate_image,
            candidate_columns,
            candidate_rows,
        )
    ):
        return None
    return candidate_image, candidate_grid, metadata


def _restore_expanded_perspective_crop_edges(
    image: np.ndarray,
    grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    expected_columns: int,
    base_rows: int,
) -> tuple[list[int], list[int], np.ndarray] | None:
    """Restore symmetric crop-edge columns and one trailing row from regular rules."""
    if grid is None or image is None or image.size == 0:
        return grid
    columns, rows, cleaned = grid
    height, width = image.shape[:2]
    if (
        expected_columns < 4
        or len(columns) - 1 != expected_columns - 2
        or len(rows) - 1 < max(8, base_rows + 1)
        or len(columns) < 4
        or len(rows) < 8
    ):
        return grid

    column_gaps = np.diff(columns).astype(float)
    typical_column = float(np.median(column_gaps)) if column_gaps.size else 0.0
    column_tolerance = max(5.0, typical_column * 0.15)
    leading_margin = float(columns[0])
    trailing_margin = float((width - 1) - columns[-1])
    if (
        typical_column < 12.0
        or float(np.max(np.abs(column_gaps - typical_column))) > column_tolerance
        or not typical_column * 0.35 <= leading_margin <= typical_column * 1.15
        or not typical_column * 0.35 <= trailing_margin <= typical_column * 1.15
    ):
        return grid

    restored_columns = [0, *[int(value) for value in columns], width - 1]
    restored_rows = [int(value) for value in rows]
    row_gaps = np.diff(restored_rows).astype(float)
    typical_row = float(np.median(row_gaps)) if row_gaps.size else 0.0
    trailing_row_margin = float((height - 1) - restored_rows[-1])
    regular_rows = bool(
        typical_row >= 8.0
        and float(np.mean(np.abs(row_gaps - typical_row) <= max(4.0, typical_row * 0.16)))
        >= 0.85
    )
    if (
        regular_rows
        and typical_row * 0.65 <= trailing_row_margin <= typical_row * 1.20
        and restored_rows[0] <= height * 0.08
        and restored_rows[-1] >= height * 0.90
    ):
        restored_rows.append(height - 1)
    return restored_columns, restored_rows, cleaned


def _recover_photo_grid_edges_at_half_scale(
    source: np.ndarray,
    rectified: np.ndarray,
    rectification: dict[str, Any],
    ruled_grid: tuple[list[int], list[int], np.ndarray],
    *,
    maximum_cells: int,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray], dict[str, Any]] | None:
    """半分辨率探测表格外沿，再用原图验证完整物理线框。"""
    corners = rectification.get("corners")
    if (
        rectification.get("full_frame_perspective_grid") is not True
        or not isinstance(corners, list) or len(corners) != 4
        or min(source.shape[:2]) < 1800
        or min(rectified.shape[:2]) < 1000
        or len(ruled_grid[1]) < 16
        or len(ruled_grid[0]) > 11
    ):
        return None
    source_height = source.shape[0]
    top_margin = (float(corners[0][1]) + float(corners[1][1])) * 0.5
    bottom_margin = source_height - (
        float(corners[2][1]) + float(corners[3][1])
    ) * 0.5
    if top_margin - bottom_margin < source_height * 0.025:
        return None

    small_source = cv2.resize(source, None, fx=0.5, fy=0.5, interpolation=cv2.INTER_AREA)
    small_rectified = cv2.resize(
        rectified, None, fx=0.5, fy=0.5, interpolation=cv2.INTER_AREA
    )
    small_metadata = dict(rectification)
    small_metadata["corners"] = [
        [float(x) * 0.5, float(y) * 0.5] for x, y in corners
    ]
    small_grid = pipeline.extract_ruled_grid(small_rectified, prefer_adaptive=True)
    if small_grid is None or (
        len(small_grid[0]), len(small_grid[1])
    ) != (len(ruled_grid[0]), len(ruled_grid[1])):
        return None
    reduced, grid, metadata, inconclusive = _recover_vertically_truncated_photo_grid(
        small_source, small_rectified, small_metadata, small_grid,
        maximum_cells=maximum_cells,
    )
    if inconclusive or grid is None:
        return None
    opposite = _recover_opposite_edge_after_top_only_expansion(
        small_source, reduced, metadata, grid, maximum_cells=maximum_cells
    )
    if opposite is not None:
        reduced, grid, metadata = opposite
    if len(grid[1]) <= len(ruled_grid[1]) or not metadata.get("edge_completeness_checked"):
        return None

    full_metadata = dict(metadata)
    for key in ("corners", "base_corners"):
        if isinstance(full_metadata.get(key), list):
            full_metadata[key] = [
                [round(float(x) * 2.0, 2), round(float(y) * 2.0, 2)]
                for x, y in full_metadata[key]
            ]
    warped = _vertical_document_rectification(source, full_metadata["corners"], 0.0)
    if warped is None:
        return None
    full_rectified = warped[0]
    full_grid = pipeline.extract_ruled_grid(full_rectified, prefer_adaptive=True)
    if (
        full_grid is None
        or (len(full_grid[0]), len(full_grid[1])) != (len(grid[0]), len(grid[1]))
        or not _grid_geometry_is_bounded(
            full_grid[0], full_grid[1], maximum_cells=maximum_cells
        )
        or not _photographic_ruled_grid_is_credible(
            full_rectified, full_grid[0], full_grid[1]
        )
        or not _complete_ruled_photo_grid(full_rectified, full_grid, maximum_cells)
        or _crop_cuts_through_source_content(source, full_metadata)
    ):
        return None
    full_metadata["edge_rows_recovered"] = len(full_grid[1]) - len(ruled_grid[1])
    full_metadata["edge_columns_recovered"] = len(full_grid[0]) - len(ruled_grid[0])
    return full_rectified, full_grid, full_metadata


def _recover_vertically_truncated_photo_grid(
    source: np.ndarray,
    rectified: np.ndarray,
    rectification: dict[str, Any],
    ruled_grid: tuple[list[int], list[int], np.ndarray] | None,
    *,
    maximum_cells: int,
) -> tuple[np.ndarray, tuple[list[int], list[int], np.ndarray] | None, dict[str, Any], bool]:
    """Recover clipped outer rows only when two adjacent expansions agree."""
    metadata = dict(rectification)
    restored_base_grid = (
        ruled_grid
        if metadata.get("paper_grid_refined")
        else _restore_visible_top_interval_boundary(rectified, ruled_grid)
    )
    if (
        ruled_grid is not None
        and restored_base_grid is not None
        and len(restored_base_grid[1]) == len(ruled_grid[1]) + 1
    ):
        ruled_grid = restored_base_grid
        metadata["top_interval_boundary_restored"] = True
    corners = metadata.get("corners")
    top_only_eligible = False
    balanced_margin_eligible = False
    source_height = float(source.shape[0]) if source.size else 0.0
    top_margin = math.inf
    bottom_margin = math.inf
    if isinstance(corners, list) and len(corners) == 4 and source.size:
        top_margin = (float(corners[0][1]) + float(corners[1][1])) * 0.5
        bottom_margin = source_height - (
            float(corners[2][1]) + float(corners[3][1])
        ) * 0.5
        top_only_eligible = bool(
            top_margin >= source_height * 0.08
            and top_margin - bottom_margin >= source_height * 0.025
        )
        balanced_margin_eligible = bool(
            top_margin >= source_height * 0.08
            and bottom_margin >= source_height * 0.06
        )
    eligible = bool(
        ruled_grid is not None
        and metadata.get("detected") is True
        and metadata.get("mode") == "auto"
        and isinstance(corners, list)
        and len(corners) == 4
        and (
            _crop_has_truncated_edge(rectified)
            or top_only_eligible
            or balanced_margin_eligible
        )
    )
    if not eligible:
        metadata["edge_completeness_checked"] = not _crop_has_truncated_edge(rectified)
        return rectified, ruled_grid, metadata, False
    if (
        _bottom_source_edge_is_unrecoverable(metadata, int(source_height))
    ):
        # The source frame itself ends at the detected lower paper edge, so no
        # geometric expansion can recover pixels below it. Keep the bounded
        # grid, report the unresolved edge, and avoid several futile warps.
        metadata["edge_completeness_checked"] = False
        metadata["unrecoverable_source_edge"] = True
        return rectified, ruled_grid, metadata, True
    if (
        _complete_ruled_photo_grid(rectified, ruled_grid, maximum_cells)
        and not _crop_cuts_through_source_content(source, metadata)
    ):
        if _ruled_grid_has_closed_outer_frame(
            rectified, ruled_grid, maximum_cells=maximum_cells
        ) and not (
            top_only_eligible
            and _parallel_outer_top_rule_above_detected_crop(source, corners)
        ):
            metadata["edge_completeness_checked"] = True
            metadata["closed_outer_frame_retained"] = True
            return rectified, ruled_grid, metadata, False
        original_corners = np.asarray(corners, dtype=np.float32).reshape(4, 2)
        probe = _vertical_document_rectification(source, original_corners, 0.10)
        if probe is not None:
            probe_image, probe_transform, _ = probe
            projected = cv2.perspectiveTransform(
                original_corners.reshape(1, 4, 2), probe_transform
            )[0]
            top = int(round(float(np.mean(projected[:2, 1]))))
            bottom = int(round(float(np.mean(projected[2:, 1]))))
            row_gap = float(np.median(np.diff(ruled_grid[1]))) * (
                probe_image.shape[0] / max(1.0, float(rectified.shape[0]))
            )
            near = max(10, int(round(row_gap * 0.20)))
            far = max(near + 8, int(round(row_gap * 1.25)))
            horizontal, _, _ = pipeline._grid_maps(probe_image)
            left = int(probe_image.shape[1] * 0.08)
            right = int(probe_image.shape[1] * 0.92)
            support = np.count_nonzero(horizontal[:, left:right], axis=1) / max(1, right - left)
            top_band = support[max(0, top - far):max(0, top - near)]
            bottom_band = support[min(len(support), bottom + near):min(len(support), bottom + far)]
            strong_outer_bottom_rule = bool(
                top_band.size and bottom_band.size
                and float(top_band.max()) < 0.08
                and float(bottom_band.max()) >= 0.30
            )
            if (
                top_band.size and bottom_band.size
                and float(top_band.max()) < 0.08
                and float(bottom_band.max()) < 0.08
            ):
                metadata["edge_completeness_checked"] = True
                metadata["outer_rule_probe_clear"] = True
                return rectified, ruled_grid, metadata, False
        else:
            strong_outer_bottom_rule = False
    else:
        strong_outer_bottom_rule = False
    if (
        _crop_has_truncated_edge(rectified)
        and not top_only_eligible
        and not balanced_margin_eligible
        and _truncated_crop_has_complete_dense_row_boundaries(rectified)
        and _ruled_grid_spans_source_frame(
            rectified,
            ruled_grid[0],
            ruled_grid[1],
        )
        and _photographic_ruled_grid_is_credible(
            rectified,
            ruled_grid[0],
            ruled_grid[1],
        )
        and (
            (len(ruled_grid[0]) - 1) * (len(ruled_grid[1]) - 1) <= 320
            or _third_grid_row_has_complete_internal_boundaries(
                rectified,
                ruled_grid[0],
                ruled_grid[1],
            )
        )
        and not _crop_cuts_through_source_content(source, metadata)
    ):
        metadata["edge_completeness_checked"] = True
        metadata["complete_simple_header_frame_retained"] = True
        return rectified, ruled_grid, metadata, False
    original_base_rows = len(ruled_grid[1]) - 1
    original_base_columns = len(ruled_grid[0]) - 1
    ruled_grid = _stronger_morphology_grid_for_edge_recovery(
        rectified,
        ruled_grid,
        maximum_cells=maximum_cells,
    )
    merged_columns = pipeline._merge_nearby_centers(
        ruled_grid[0],
        maximum_gap=5,
    )
    if (
        len(merged_columns) == len(ruled_grid[0]) - 1
        and _grid_geometry_is_bounded(
            merged_columns,
            ruled_grid[1],
            maximum_cells=maximum_cells,
        )
        and _photographic_ruled_grid_is_credible(
            rectified,
            merged_columns,
            ruled_grid[1],
        )
    ):
        ruled_grid = (merged_columns, ruled_grid[1], ruled_grid[2])
        metadata["merged_duplicate_vertical_rule"] = True
    original_corners = np.asarray(corners, dtype=np.float32).reshape(4, 2)
    baseline = _ruled_grid_edge_evidence(rectified, ruled_grid)
    if baseline is None:
        metadata["edge_completeness_checked"] = False
        return rectified, ruled_grid, metadata, False
    candidate_type = tuple[
        float,
        np.ndarray,
        tuple[list[int], list[int], np.ndarray],
        np.ndarray,
        np.ndarray,
    ]
    base_rows = len(baseline["rows"]) - 1
    base_columns = len(baseline["columns"]) - 1
    morphology_columns_recovered = base_columns > original_base_columns
    saw_supported_external_rows = False

    def qualified_candidate(
        ratio: float,
        *,
        allow_stable_clipped_edge: bool = False,
    ) -> candidate_type | None:
        nonlocal saw_supported_external_rows
        # 每个候选都要做一次透视矫正 + 线框抽取 + 边缘证据，整轮搜索最多 10 个
        # 候选。2026-10-22 实测 FC-00016 的几何阶段独占了 60 秒预算（整例
        # 80 秒），就是因为这段中间一个检查点都没有。在这里逐候选检查，
        # 超时就地中止，不再整轮跑完。
        _check_request_wall_clock("edge_recovery_candidate")
        expanded = _vertical_document_rectification(source, original_corners, ratio)
        if expanded is None:
            return None
        candidate_image, transform, expanded_corners = expanded
        candidate_grid = pipeline.extract_ruled_grid(candidate_image, prefer_adaptive=True)
        candidate_grid = _restore_expanded_perspective_crop_edges(
            candidate_image,
            candidate_grid,
            expected_columns=base_columns,
            base_rows=base_rows,
        )
        evidence = _ruled_grid_edge_evidence(candidate_image, candidate_grid)
        if evidence is None or candidate_grid is None:
            return None
        candidate_rows = len(evidence["rows"]) - 1
        candidate_columns = len(evidence["columns"]) - 1
        preserves, strong_additions = _expanded_grid_preserves_base_and_adds_strong_rows(
            baseline,
            evidence,
            original_corners,
            transform,
        )
        recovered_rows = candidate_rows - base_rows
        column_growth = candidate_columns - base_columns
        stable_clipped_edge = bool(
            allow_stable_clipped_edge
            and base_columns >= 16
            and base_rows >= 24
            and preserves
            and not strong_additions
            and recovered_rows == 2
            and column_growth == 0
            and _crop_has_truncated_edge(candidate_image)
        )
        stable_balanced_margin_rows = bool(
            balanced_margin_eligible
            and base_columns < 16
            and bool(metadata.get("full_frame_perspective_grid", False))
            and preserves
            and not strong_additions
            and recovered_rows in (1, 2, 3)
            and column_growth == 0
        )
        stable_balanced_header_replacement = bool(
            balanced_margin_eligible
            and base_columns < 16
            and bool(metadata.get("full_frame_perspective_grid", False))
            and preserves
            and not strong_additions
            and recovered_rows == 0
            and column_growth == 0
            and _grid_has_two_leading_merged_header_rows(
                candidate_image,
                evidence["columns"],
                evidence["rows"],
            )
        )
        supported_additions = bool(
            strong_additions
            or (morphology_columns_recovered and recovered_rows >= 2)
            or stable_clipped_edge
            or stable_balanced_margin_rows
            or stable_balanced_header_replacement
        )
        columns_safely_completed = bool(
            0 <= column_growth <= max(4, int(math.ceil(base_columns * 0.50)))
        )
        outer_rows_have_text = bool(
            recovered_rows >= 1
            and _grid_has_text_supported_outer_rows(
                candidate_image, candidate_grid, recovered_rows
            )
        )
        saw_supported_external_rows = bool(
            saw_supported_external_rows
            or (
                strong_additions
                and recovered_rows >= 1
                and outer_rows_have_text
            )
        )
        if (
            preserves
            and supported_additions
            and outer_rows_have_text
            and columns_safely_completed
            and 1 <= recovered_rows <= 6
            and _grid_geometry_is_bounded(
                evidence["columns"], evidence["rows"], maximum_cells=maximum_cells
            )
            and _photographic_ruled_grid_is_credible(
                candidate_image, evidence["columns"], evidence["rows"]
            )
        ):
            return (
                ratio,
                candidate_image,
                candidate_grid,
                transform,
                expanded_corners,
            )
        return None

    defer_top_only_for_balanced_bottom = bool(
        top_only_eligible
        and base_rows >= 18
        and bottom_margin >= source_height * 0.08
        and bool(metadata.get("full_frame_perspective_grid", False))
    )
    if top_only_eligible:
        complete_header_candidates: dict[float, candidate_type] = {}
        top_candidate_cache: dict[float, candidate_type | None] = {}

        def evaluated_top_candidate(
            ratio: float,
            expected_growth: int,
        ) -> candidate_type | None:
            if ratio in top_candidate_cache:
                cached = top_candidate_cache[ratio]
                if cached is None:
                    return None
                return (
                    cached
                    if len(cached[2][1]) - 1 == base_rows + expected_growth
                    else None
                )
            expanded = _top_document_rectification(source, original_corners, ratio)
            if expanded is None:
                top_candidate_cache[ratio] = None
                return None
            candidate_image, transform, expanded_corners = expanded
            candidate_grid = pipeline.extract_ruled_grid(
                candidate_image,
                prefer_adaptive=True,
            )
            candidate_grid = _restore_expanded_perspective_crop_edges(
                candidate_image,
                candidate_grid,
                expected_columns=base_columns,
                base_rows=base_rows,
            )
            candidate_grid = _restore_visible_top_interval_boundary(
                candidate_image,
                candidate_grid,
            )
            evidence = _ruled_grid_edge_evidence(candidate_image, candidate_grid)
            if evidence is None or candidate_grid is None:
                return None
            preserves, strong_additions = (
                _expanded_grid_preserves_base_and_adds_strong_rows(
                    baseline,
                    evidence,
                    original_corners,
                    transform,
                )
            )
            candidate_rows = len(evidence["rows"]) - 1
            candidate_columns = len(evidence["columns"]) - 1
            bounded = _grid_geometry_is_bounded(
                evidence["columns"],
                evidence["rows"],
                maximum_cells=maximum_cells,
            )
            credible = _photographic_ruled_grid_is_credible(
                candidate_image,
                evidence["columns"],
                evidence["rows"],
            )
            _write_runtime_trace(
                "route",
                force_flush=True,
                name=(
                    "top_only_expansion_candidate"
                    if expected_growth == 1
                    else "top_only_two_row_candidate"
                ),
                ratio=ratio,
                rows=candidate_rows,
                columns=candidate_columns,
                preserves=preserves,
                strong_additions=strong_additions,
                bounded=bounded,
                credible=credible,
            )
            candidate = (
                ratio,
                candidate_image,
                candidate_grid,
                transform,
                expanded_corners,
            )
            candidate_row_gaps = np.diff(evidence["rows"]).astype(float)
            typical_candidate_gap = (
                float(np.median(candidate_row_gaps[1:]))
                if candidate_row_gaps.size > 1
                else 0.0
            )
            leading_gap_ratio = (
                float(candidate_row_gaps[0]) / typical_candidate_gap
                if typical_candidate_gap > 0.0 and candidate_row_gaps.size
                else 0.0
            )
            if (
                preserves
                and candidate_columns == base_columns
                and bounded
                and credible
                and 0 <= candidate_rows - base_rows <= 3
                and 0.75 <= leading_gap_ratio <= 2.10
                and _grid_has_two_leading_merged_header_rows(
                    candidate_image,
                    evidence["columns"],
                    evidence["rows"],
                )
            ):
                complete_header_candidates[ratio] = candidate
            if not (
                preserves
                and candidate_columns == base_columns
                and bounded
                and credible
                and 1 <= candidate_rows - base_rows <= 2
                and _grid_has_text_supported_outer_rows(
                    candidate_image,
                    candidate_grid,
                    expected_growth,
                    leading_only=True,
                )
            ):
                top_candidate_cache[ratio] = None
                return None
            top_candidate_cache[ratio] = candidate
            return candidate if candidate_rows == base_rows + expected_growth else None

        shallow_candidates = [
            candidate
            for ratio in (0.03, 0.04, 0.05)
            if (candidate := evaluated_top_candidate(ratio, 1)) is not None
        ]
        if len(shallow_candidates) == 3 and not defer_top_only_for_balanced_bottom:
            candidate_shapes = {
                (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
                for candidate in shallow_candidates
            }
            if len(candidate_shapes) == 1:
                ratio, candidate_image, candidate_grid, _, expanded_corners = (
                    shallow_candidates[0]
                )
                metadata.update(
                    {
                        "corners": [
                            [round(float(point[0]), 2), round(float(point[1]), 2)]
                            for point in expanded_corners
                        ],
                        "base_corners": corners,
                        "edge_completeness_checked": True,
                        "edge_rows_recovered": 1,
                        "edge_columns_recovered": 0,
                        "vertical_expansion_ratio": ratio,
                        "top_only_expansion": True,
                    }
                )
                return candidate_image, candidate_grid, metadata, False
        for ratio_pair in ((0.10, 0.12), (0.075, 0.08)):
            single_row_candidates = [
                candidate
                for ratio in ratio_pair
                if (candidate := evaluated_top_candidate(ratio, 1)) is not None
            ]
            if len(single_row_candidates) == 2:
                candidate_shapes = {
                    (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
                    for candidate in single_row_candidates
                }
                if len(candidate_shapes) == 1:
                    ratio, candidate_image, candidate_grid, _, expanded_corners = (
                        single_row_candidates[0]
                    )
                    metadata.update({
                        "corners": [
                            [round(float(point[0]), 2), round(float(point[1]), 2)]
                            for point in expanded_corners
                        ],
                        "base_corners": corners,
                        "edge_completeness_checked": True,
                        "edge_rows_recovered": 1,
                        "edge_columns_recovered": 0,
                        "vertical_expansion_ratio": ratio,
                        "top_only_expansion": True,
                        "stable_single_row_top_expansion": True,
                    })
                    if not defer_top_only_for_balanced_bottom:
                        return candidate_image, candidate_grid, metadata, False
            two_row_candidates = [
                candidate
                for ratio in ratio_pair
                if (candidate := evaluated_top_candidate(ratio, 2)) is not None
            ]
            complete_pair = [
                complete_header_candidates[ratio]
                for ratio in ratio_pair
                if ratio in complete_header_candidates
            ]
            if len(complete_pair) == 2:
                complete_shapes = [
                    (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
                    for candidate in complete_pair
                ]
                if (
                    complete_shapes[0][1] == complete_shapes[1][1]
                    and abs(complete_shapes[0][0] - complete_shapes[1][0]) <= 1
                ):
                    selected = min(
                        complete_pair,
                        key=lambda candidate: (
                            len(candidate[2][1]),
                            candidate[0],
                        ),
                    )
                    ratio, candidate_image, candidate_grid, _, expanded_corners = selected
                    recovered_rows = len(candidate_grid[1]) - 1 - base_rows
                    metadata.update(
                        {
                            "corners": [
                                [round(float(point[0]), 2), round(float(point[1]), 2)]
                                for point in expanded_corners
                            ],
                            "base_corners": corners,
                            "edge_completeness_checked": True,
                            "edge_rows_recovered": recovered_rows,
                            "edge_columns_recovered": 0,
                            "vertical_expansion_ratio": ratio,
                            "top_only_expansion": True,
                            "stable_header_top_expansion": True,
                        }
                    )
                    if not defer_top_only_for_balanced_bottom:
                        return candidate_image, candidate_grid, metadata, False
            if len(two_row_candidates) != 2:
                continue
            candidate_shapes = {
                (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
                for candidate in two_row_candidates
            }
            if len(candidate_shapes) != 1:
                continue
            ratio, candidate_image, candidate_grid, _, expanded_corners = (
                two_row_candidates[0]
            )
            metadata.update(
                {
                    "corners": [
                        [round(float(point[0]), 2), round(float(point[1]), 2)]
                        for point in expanded_corners
                    ],
                    "base_corners": corners,
                    "edge_completeness_checked": True,
                    "edge_rows_recovered": 2,
                    "edge_columns_recovered": 0,
                    "vertical_expansion_ratio": ratio,
                    "top_only_expansion": True,
                    "stable_two_row_top_expansion": True,
                }
            )
            if not defer_top_only_for_balanced_bottom:
                return candidate_image, candidate_grid, metadata, False
        complete_shape_groups: dict[tuple[int, int], list[candidate_type]] = {}
        for candidate in complete_header_candidates.values():
            shape = (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
            complete_shape_groups.setdefault(shape, []).append(candidate)
        stable_complete_groups = [
            candidates
            for candidates in complete_shape_groups.values()
            if len(candidates) >= 2
        ]
        if stable_complete_groups:
            selected_group = max(
                stable_complete_groups,
                key=lambda candidates: (
                    len(candidates[0][2][1]),
                    len(candidates),
                    -min(candidate[0] for candidate in candidates),
                ),
            )
            def title_height_error(candidate: candidate_type) -> tuple[float, float]:
                candidate_rows = np.diff(candidate[2][1]).astype(float)
                typical = (
                    float(np.median(candidate_rows[1:]))
                    if candidate_rows.size > 1
                    else 0.0
                )
                leading_ratio = (
                    float(candidate_rows[0]) / typical
                    if typical > 0.0 and candidate_rows.size
                    else 0.0
                )
                return abs(leading_ratio - 1.45), candidate[0]

            ratio, candidate_image, candidate_grid, _, expanded_corners = min(
                selected_group,
                key=title_height_error,
            )
            recovered_rows = len(candidate_grid[1]) - 1 - base_rows
            metadata.update(
                {
                    "corners": [
                        [round(float(point[0]), 2), round(float(point[1]), 2)]
                        for point in expanded_corners
                    ],
                    "base_corners": corners,
                    "edge_completeness_checked": True,
                    "edge_rows_recovered": recovered_rows,
                    "edge_columns_recovered": 0,
                    "vertical_expansion_ratio": ratio,
                    "top_only_expansion": True,
                    "stable_header_top_expansion": True,
                    "top_only_header_replacement": recovered_rows == 0,
                }
            )
            if not defer_top_only_for_balanced_bottom:
                return candidate_image, candidate_grid, metadata, False
        if len(shallow_candidates) == 3:
            candidate_shapes = {
                (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
                for candidate in shallow_candidates
            }
            if len(candidate_shapes) == 1:
                ratio, candidate_image, candidate_grid, _, expanded_corners = (
                    shallow_candidates[0]
                )
                metadata.update(
                    {
                        "corners": [
                            [round(float(point[0]), 2), round(float(point[1]), 2)]
                            for point in expanded_corners
                        ],
                        "base_corners": corners,
                        "edge_completeness_checked": True,
                        "edge_rows_recovered": 1,
                        "edge_columns_recovered": 0,
                        "vertical_expansion_ratio": ratio,
                        "top_only_expansion": True,
                    }
                )
                if not defer_top_only_for_balanced_bottom:
                    return candidate_image, candidate_grid, metadata, False

    ratio_groups = (
        ((0.075, 0.08), (0.06, 0.065), (0.034, 0.035),
         (0.095, 0.10), (0.04, 0.045))
        if strong_outer_bottom_rule and base_columns < 16
        else
        ((0.08, 0.085), (0.06, 0.065), (0.034, 0.035), (0.04, 0.045))
        if morphology_columns_recovered
        else ((0.06, 0.065), (0.034, 0.035), (0.04, 0.045))
        if base_columns >= 16
        else (
            (0.034, 0.035),
            (0.06, 0.065),
            (0.075, 0.08),
            (0.095, 0.10),
            (0.04, 0.045),
        )
    )
    stable_candidates: list[candidate_type] = []
    qualified_regular_candidates: list[candidate_type] = []
    selected_candidate: candidate_type | None = None
    saw_qualified_regular_candidate = False
    selected_from_stable_clipped_edge = False
    selected_from_shape_consensus = False
    for group_index, ratio_group in enumerate(ratio_groups):
        # 预算用掉大半就不再穷举下一组（见 _geometry_search_budget_exhausted）：
        # 已经找到的候选会走下面的形状共识路径收尾。
        if _geometry_search_budget_exhausted():
            _note_geometry_search_truncated()
            break
        group_candidates = [
            candidate
            for ratio in ratio_group
            if (candidate := qualified_candidate(ratio)) is not None
        ]
        saw_qualified_regular_candidate = bool(
            saw_qualified_regular_candidate or group_candidates
        )
        qualified_regular_candidates.extend(group_candidates)
        group_stable: list[candidate_type] = []
        for first, second in zip(group_candidates, group_candidates[1:]):
            first_shape = (len(first[2][1]) - 1, len(first[2][0]) - 1)
            second_shape = (len(second[2][1]) - 1, len(second[2][0]) - 1)
            if abs(second[0] - first[0]) <= 0.006 and first_shape == second_shape:
                group_stable.append(first)
        stable_candidates.extend(group_stable)
        if not group_stable:
            continue
        best_in_group = max(
            group_stable,
            key=lambda candidate: (len(candidate[2][1]), -candidate[0]),
        )
        recovered_in_group = len(best_in_group[2][1]) - 1 - base_rows
        if base_columns >= 16 or recovered_in_group == 1 or group_index > 0:
            selected_candidate = max(
                stable_candidates,
                key=lambda candidate: (len(candidate[2][1]), -candidate[0]),
            )
            break

    if selected_candidate is None and qualified_regular_candidates:
        candidates_by_shape: dict[tuple[int, int], list[candidate_type]] = {}
        for candidate in qualified_regular_candidates:
            shape = (len(candidate[2][1]) - 1, len(candidate[2][0]) - 1)
            candidates_by_shape.setdefault(shape, []).append(candidate)
        stable_shape_groups = [
            candidates
            for candidates in candidates_by_shape.values()
            if len(candidates) >= 3
            and max(candidate[0] for candidate in candidates)
            - min(candidate[0] for candidate in candidates)
            >= 0.02
        ]
        if stable_shape_groups:
            selected_group = max(
                stable_shape_groups,
                key=lambda candidates: (
                    len(candidates[0][2][1]),
                    len(candidates[0][2][0]),
                    len(candidates),
                ),
            )
            selected_candidate = min(
                selected_group,
                key=lambda candidate: candidate[0],
            )
            selected_from_shape_consensus = True

    if selected_candidate is None and not saw_qualified_regular_candidate:
        clipped_edge_candidates = [
            candidate
            for ratio in (0.02, 0.025)
            if (
                candidate := qualified_candidate(
                    ratio,
                    allow_stable_clipped_edge=True,
                )
            )
            is not None
        ]
        for first, second in zip(
            clipped_edge_candidates,
            clipped_edge_candidates[1:],
        ):
            first_shape = (len(first[2][1]) - 1, len(first[2][0]) - 1)
            second_shape = (len(second[2][1]) - 1, len(second[2][0]) - 1)
            if abs(second[0] - first[0]) <= 0.006 and first_shape == second_shape:
                selected_candidate = first
                selected_from_stable_clipped_edge = True
                break

    if selected_candidate is None and stable_candidates:
        selected_candidate = max(
            stable_candidates,
            key=lambda candidate: (len(candidate[2][1]), -candidate[0]),
        )
    if selected_candidate is not None:
        ratio, candidate_image, candidate_grid, _, expanded_corners = selected_candidate
        bottom_expansion_ratio: float | None = None
        if bool(metadata.get("full_frame_perspective_grid", False)):
            candidate_baseline = _ruled_grid_edge_evidence(
                candidate_image,
                candidate_grid,
            )
        else:
            candidate_baseline = None
        if candidate_baseline is not None:
            candidate_rows = len(candidate_grid[1]) - 1
            candidate_columns = len(candidate_grid[0]) - 1
            for ratio_pair in ((0.02, 0.025), (0.025, 0.03), (0.03, 0.035)):
                _check_request_wall_clock("geometry_candidates")
                bottom_candidates = []
                for bottom_ratio in ratio_pair:
                    _check_request_wall_clock("geometry_candidates")
                    expanded_bottom = _bottom_document_rectification(
                        source,
                        expanded_corners,
                        bottom_ratio,
                    )
                    if expanded_bottom is None:
                        continue
                    bottom_image, bottom_transform, bottom_corners = expanded_bottom
                    bottom_grid = pipeline.extract_ruled_grid(
                        bottom_image,
                        prefer_adaptive=True,
                    )
                    bottom_evidence = _ruled_grid_edge_evidence(
                        bottom_image,
                        bottom_grid,
                    )
                    if bottom_grid is None or bottom_evidence is None:
                        continue
                    preserves, strong_additions = (
                        _expanded_grid_preserves_base_and_adds_strong_rows(
                            candidate_baseline,
                            bottom_evidence,
                            expanded_corners,
                            bottom_transform,
                        )
                    )
                    bottom_rows = len(bottom_grid[1]) - 1
                    bottom_columns = len(bottom_grid[0]) - 1
                    if (
                        preserves
                        and (
                            strong_additions
                            or _grid_has_text_supported_trailing_rows(
                                bottom_image,
                                bottom_grid,
                                candidate_rows,
                            )
                        )
                        and bottom_columns == candidate_columns
                        and 1 <= bottom_rows - candidate_rows <= 2
                        and _grid_geometry_is_bounded(
                            bottom_grid[0],
                            bottom_grid[1],
                            maximum_cells=maximum_cells,
                        )
                        and _photographic_ruled_grid_is_credible(
                            bottom_image,
                            bottom_grid[0],
                            bottom_grid[1],
                        )
                    ):
                        bottom_candidates.append(
                            (
                                bottom_ratio,
                                bottom_image,
                                bottom_grid,
                                bottom_corners,
                            )
                        )
                if (
                    len(bottom_candidates) == 2
                    and (
                        len(bottom_candidates[0][2][1]),
                        len(bottom_candidates[0][2][0]),
                    )
                    == (
                        len(bottom_candidates[1][2][1]),
                        len(bottom_candidates[1][2][0]),
                    )
                ):
                    (
                        bottom_expansion_ratio,
                        candidate_image,
                        candidate_grid,
                        expanded_corners,
                    ) = bottom_candidates[0]
                    break
        candidate_shape = (len(candidate_grid[1]) - 1, len(candidate_grid[0]) - 1)
        metadata.update(
            {
                "corners": [
                    [round(float(point[0]), 2), round(float(point[1]), 2)]
                    for point in expanded_corners
                ],
                "base_corners": corners,
                "edge_completeness_checked": True,
                "edge_rows_recovered": candidate_shape[0]
                - original_base_rows,
                "edge_columns_recovered": candidate_shape[1]
                - original_base_columns,
                "vertical_expansion_ratio": ratio,
                "stable_clipped_edge_pair": selected_from_stable_clipped_edge,
                "stable_expansion_shape_consensus": selected_from_shape_consensus,
            }
        )
        if bottom_expansion_ratio is not None:
            metadata["bottom_only_expansion"] = True
            metadata["bottom_expansion_ratio"] = bottom_expansion_ratio
        return candidate_image, candidate_grid, metadata, False

    metadata["edge_completeness_checked"] = not saw_supported_external_rows
    return rectified, ruled_grid, metadata, saw_supported_external_rows


def _dense_grid_is_axis_aligned_screen_capture(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Recognize a dense spreadsheet screenshot even with dark application chrome."""
    if len(columns) < 16 or len(rows) < 20:
        return False
    height, width = image.shape[:2]
    if (
        columns[0] > width * 0.03
        or columns[-1] < width * 0.96
        # Camera-like exports often retain a narrow desk/frame margin above
        # an otherwise perfectly axis-aligned grid.  Five percent still keeps
        # the table near the source edge while avoiding an unnecessary second
        # rectification pass for that bounded inset.
        or rows[0] > height * 0.05
        or rows[-1] < height * 0.96
    ):
        return False
    row_gaps = np.diff(rows)
    typical_gap = float(np.median(row_gaps)) if row_gaps.size else 0.0
    if typical_gap < 8:
        return False
    tolerance = max(3.0, typical_gap * 0.18)
    regular_rows = float(np.mean(np.abs(row_gaps - typical_gap) <= tolerance))
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    sharpness = float(cv2.Laplacian(gray, cv2.CV_64F).var())
    return regular_rows >= 0.90 and sharpness >= 120.0


def _small_clear_screen_grid_uses_page_primary(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
) -> bool:
    """Use page OCR for a small, sharp, fully bounded screen table."""
    row_count = len(rows) - 1
    column_count = len(columns) - 1
    if (
        image.size == 0
        or not 8 <= row_count <= 45
        or not 2 <= column_count <= 12
        or row_count * column_count > 180
        or not _ruled_grid_spans_source_frame(image, columns, rows)
    ):
        return False
    row_gaps = np.diff(rows).astype(float)
    column_gaps = np.diff(columns).astype(float)
    typical_row = float(np.median(row_gaps)) if row_gaps.size else 0.0
    typical_column = float(np.median(column_gaps)) if column_gaps.size else 0.0
    if (
        typical_row < 24.0
        or min(column_gaps, default=0.0) < 60.0
        or (
            typical_column > 0.0
            and column_gaps[0] < typical_column * 0.60
            and column_gaps[-1] < typical_column * 0.60
        )
        or float(np.mean(np.abs(row_gaps - typical_row) <= max(3.0, typical_row * 0.20))) < 0.85
    ):
        return False
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    return float(cv2.Laplacian(gray, cv2.CV_64F).var()) >= 120.0


def _screen_grid_has_collapsed_rows(grid: list[list[str]]) -> bool:
    """Detect when missed horizontal rules combine two source rows into one crop."""
    populated = [str(value).strip() for row in grid for value in row if str(value).strip()]
    if len(populated) < 8:
        return False
    # Legitimate technical tables often use two lines per cell for bilingual
    # labels or a value plus an explanation.  Newlines alone do not prove that
    # a horizontal rule was missed.  Require record-level evidence such as two
    # consecutive identifiers and several columns containing paired records.
    return _grid_has_concatenated_physical_rows(grid)


def _grid_has_concatenated_physical_rows(grid: list[list[str]]) -> bool:
    """Detect page OCR that joins several physical rows inside many cells."""
    def has_record_sequence(value: str) -> bool:
        tokens = value.split()
        if len(tokens) < 2:
            return False
        if all(re.fullmatch(r"\d+", token) for token in tokens):
            numbers = [int(token) for token in tokens]
            return all(right == left + 1 for left, right in zip(numbers, numbers[1:]))
        identifiers = [
            re.fullmatch(r"(.+?[-_/]?)(\d+)", token, re.IGNORECASE)
            for token in tokens
        ]
        if not all(identifiers):
            return False
        prefixes = [match.group(1).casefold() for match in identifiers if match]
        numbers = [int(match.group(2)) for match in identifiers if match]
        return (
            len(set(prefixes)) == 1
            and all(right == left + 1 for left, right in zip(numbers, numbers[1:]))
        )

    for row in grid:
        values = [str(value).strip() for value in row if str(value).strip()]
        if len(values) < 3:
            continue
        sequence_evidence = any(has_record_sequence(value) for value in values)
        if not sequence_evidence:
            continue
        multi_record_values = sum(len(value.split()) >= 3 for value in values)
        if multi_record_values >= max(3, int(math.ceil(len(values) * 0.50))):
            return True
        paired_values = sum(len(value.split()) >= 2 for value in values)
        if (
            sequence_evidence
            and paired_values >= max(3, int(math.ceil(len(values) * 0.50)))
        ):
            return True
    return False


def _grid_has_concatenated_header_columns(grid: list[list[str]]) -> bool:
    columns = max((len(row) for row in grid), default=0)
    if columns == 0:
        return False
    known_headers = set(_COMMON_HEADER_LABELS)
    concatenated_cells = 0
    concatenated_labels = 0
    for row in grid[:3]:
        for column, value in enumerate(row):
            text = str(value).strip()
            if not text:
                continue
            tokens = [token for token in re.split(r"[\s|｜]+", text) if token]
            header_tokens = sum(token in known_headers for token in tokens)
            segmented = _segment_concatenated_header_labels(text)
            if header_tokens >= 3 or len(segmented) >= 3:
                return True
            if len(segmented) >= 2:
                adjacent_blank = any(
                    0 <= neighbour < len(row)
                    and not str(row[neighbour]).strip()
                    for neighbour in (column - 1, column + 1)
                )
                if adjacent_blank:
                    return True
                concatenated_cells += 1
                concatenated_labels += len(segmented)
    return columns > 3 and concatenated_cells >= 2 and concatenated_labels >= 4


def _visible_fused_header_cell_locations(
    image: np.ndarray,
    grid: list[list[str]],
    columns: list[int],
    rows: list[int],
) -> set[tuple[int, int]]:
    """Select only concatenated headers separated by a visible physical rule."""
    row_count = min(2, len(grid), max(0, len(rows) - 1))
    column_count = len(columns) - 1
    if image.size == 0 or row_count == 0 or column_count <= 0:
        return set()
    if any(len(row) != column_count for row in grid[:row_count]):
        return set()

    suspicious: list[tuple[int, int, int]] = []
    for row_index in range(row_count):
        for column, value in enumerate(grid[row_index]):
            if len(_segment_concatenated_header_labels(value)) < 2:
                continue
            for neighbour in (column - 1, column + 1):
                if (
                    0 <= neighbour < column_count
                    and not str(grid[row_index][neighbour]).strip()
                ):
                    suspicious.append((row_index, column, neighbour))
                    break
    if not suspicious:
        return set()

    _, vertical, _ = pipeline._grid_maps(image)
    height, width = vertical.shape[:2]
    selected: set[tuple[int, int]] = set()
    for row_index, column, neighbour in suspicious:
        top = max(0, min(height - 1, int(rows[row_index])))
        bottom = max(top + 1, min(height, int(rows[row_index + 1]) + 1))
        inset = max(1, min(4, (bottom - top) // 10))
        boundary_index = column if neighbour < column else column + 1
        position = max(0, min(width - 1, int(columns[boundary_index])))
        band_top = min(bottom - 1, top + inset)
        band_bottom = min(height, max(band_top + 1, bottom - inset))
        band = vertical[
            band_top:band_bottom,
            max(0, position - 3):min(width, position + 4),
        ]
        if not band.size:
            continue
        support = float(np.count_nonzero(np.any(band > 0, axis=1))) / max(
            1, band.shape[0]
        )
        if support >= 0.45:
            selected.add((row_index, column))
            selected.add((row_index, neighbour))
    return selected


def _suspicious_leading_ruled_cells(
    grid: list[list[str]],
    confidence: list[list[float]],
) -> set[tuple[int, int]]:
    """Select only leading cells whose OCR evidence cannot be published safely."""
    selected: set[tuple[int, int]] = set()
    for row_index in range(min(2, len(grid), len(confidence))):
        populated = sum(bool(str(value).strip()) for value in grid[row_index])
        dense_header_row = populated >= max(
            3,
            int(math.ceil(len(grid[row_index]) * 0.60)),
        )
        for column_index, value in enumerate(grid[row_index]):
            if column_index >= len(confidence[row_index]):
                continue
            text = "".join(unicodedata.normalize("NFKC", str(value)).split())
            score = float(confidence[row_index][column_index])
            if not text and dense_header_row:
                selected.add((row_index, column_index))
                continue
            if text and score < 0.80:
                selected.add((row_index, column_index))
                continue
            matching_prefixes = [
                label for label in _COMMON_HEADER_LABELS
                if text.startswith(label) and len(text) > len(label)
            ]
            if not matching_prefixes:
                continue
            longest = max(matching_prefixes, key=len)
            suffix = text[len(longest):]
            if re.search(r"[0-9%°℃Ω]", suffix):
                selected.add((row_index, column_index))
    return selected


def _header_semantic_labels(value: Any) -> list[str]:
    """Find non-overlapping header labels even when OCR keeps units between them."""
    compact = "".join(unicodedata.normalize("NFKC", str(value)).split())
    if not compact:
        return []
    labels: list[str] = []
    offset = 0
    while offset < len(compact):
        matched = next(
            (label for label in _COMMON_HEADER_LABELS if compact.startswith(label, offset)),
            "",
        )
        if matched:
            labels.append(matched)
            offset += len(matched)
        else:
            offset += 1
    return labels


def _grid_has_fused_physical_columns(grid: list[list[str]]) -> bool:
    """Reject several source columns that were placed in one output column."""
    if len(grid) < 2:
        return False
    column_count = max((len(row) for row in grid), default=0)
    if column_count == 1:
        values = [str(row[0]).strip() for row in grid if row and str(row[0]).strip()]
        fused_records = sum(
            len(value) >= 12
            and bool(re.search(r"[A-Za-z\u3400-\u9fff]", value))
            and len(re.findall(r"[-+]?\d+(?:[.,]\d+)?", value)) >= 2
            for value in values
        )
        return fused_records >= max(2, int(math.ceil(len(values) * 0.50)))
    if column_count < 2:
        return False
    header_candidates = []
    for row_index, row in enumerate(grid[:3]):
        label_sets = [_header_semantic_labels(value) for value in row]
        header_candidates.append(
            (sum(bool(labels) for labels in label_sets), sum(len(labels) for labels in label_sets), -row_index, row_index, label_sets)
        )
    _, _, _, header_row, label_sets = max(header_candidates)
    body_rows = grid[header_row + 1 :]
    known_states = {
        "正常", "复核", "待机", "等待", "异常", "完成", "已完成", "进行中",
        "启用", "暂停", "告警", "合格", "不合格", "在用", "待检", "维修中",
    }
    measurement_labels = {"频率", "功率", "温度", "电压", "电流", "数量", "数值1", "数值2", "数值3"}
    explanation_labels = {"备注", "说明"}
    for column_index, labels in enumerate(label_sets):
        if len(labels) >= 3:
            return True
        if len(labels) < 2:
            continue
        values = [
            str(row[column_index]).strip()
            for row in body_rows
            if column_index < len(row) and str(row[column_index]).strip()
        ]
        identifier_and_name = bool(
            any(label in {"编号", "序号", "资产编号", "设备编号"} for label in labels)
            and any(label in {"名称", "设备名称"} for label in labels)
        )
        if identifier_and_name:
            fused_identifier_rows = sum(
                bool(re.search(r"(?<![A-Za-z0-9])[A-Za-z][A-Za-z0-9._/-]*\d+", value))
                and bool(re.search(r"[\u3400-\u9fff]{2,}", value))
                for value in values
            )
            if fused_identifier_rows >= max(2, int(math.ceil(len(values) * 0.50))):
                return True
        if set(labels).issubset(measurement_labels):
            numeric_pairs = sum(
                len(re.findall(r"(?<![A-Za-z])[-+]?\d+(?:[.,]\d+)?", value)) >= 2
                for value in values
            )
            if numeric_pairs >= 2:
                return True
        status_and_explanation = bool(
            any(label in {"状态", "当前状态"} for label in labels)
            and any(label in explanation_labels for label in labels)
        )
        if status_and_explanation:
            fused_status_rows = sum(
                len(value.split()) >= 2 and value.split()[0] in known_states
                for value in values
            )
            if fused_status_rows >= 2:
                return True
        progress_and_owner = bool(
            any(label in {"进度", "完成率"} for label in labels)
            and "负责人" in labels
        )
        if progress_and_owner:
            fused_progress_rows = sum(
                bool(
                    re.fullmatch(r"\d+(?:\.\d+)?%", value.split()[0])
                    and re.fullmatch(r"[\u3400-\u9fff]{1,6}", value.split()[1])
                )
                for value in values
                if len(value.split()) >= 2
            )
            if fused_progress_rows >= 2:
                return True
    return False


def _grid_has_misaligned_identifier_rows(grid: list[list[str]]) -> bool:
    """Detect a spatial row split between consecutive identifier records."""
    if len(grid) < 6:
        return False
    column_count = max((len(row) for row in grid), default=0)
    if column_count < 3:
        return False
    header_row = next(
        (
            row_index
            for row_index, row in enumerate(grid[:3])
            if any("编号" in str(value) or "序号" in str(value) for value in row)
        ),
        -1,
    )
    if header_row < 0:
        return False
    identifier_column = next(
        column_index
        for column_index, value in enumerate(grid[header_row])
        if "编号" in str(value) or "序号" in str(value)
    )
    parsed: dict[int, tuple[str, int]] = {}
    for row_index in range(header_row + 1, len(grid)):
        if identifier_column >= len(grid[row_index]):
            continue
        value = str(grid[row_index][identifier_column]).strip()
        match = re.fullmatch(r"([A-Za-z][A-Za-z0-9._/-]*?[-_/]?)(\d+)", value)
        if match:
            parsed[row_index] = (match.group(1).upper(), int(match.group(2)))
    if len(parsed) < 4:
        return False
    for row_index in range(header_row + 2, len(grid) - 1):
        identifier = (
            str(grid[row_index][identifier_column]).strip()
            if identifier_column < len(grid[row_index])
            else ""
        )
        if identifier:
            continue
        populated = sum(bool(str(value).strip()) for value in grid[row_index])
        if populated < 2:
            continue
        previous = parsed.get(row_index - 1)
        following = parsed.get(row_index + 1)
        if (
            previous is not None
            and following is not None
            and previous[0] == following[0]
            and following[1] == previous[1] + 1
        ):
            return True
    return False


def _grid_has_misaligned_anchor_rows(grid: list[list[str]]) -> bool:
    """Detect a dense data row whose sequence anchor was shifted to a neighbour."""
    if len(grid) < 5:
        return False
    column_count = max((len(row) for row in grid), default=0)
    if column_count < 3:
        return False
    header_match: tuple[int, int, str] | None = None
    for row_index, row in enumerate(grid[:3]):
        for column_index, value in enumerate(row):
            text = str(value).strip()
            if "月份" in text:
                header_match = (row_index, column_index, "month")
                break
            if "序号" in text:
                header_match = (row_index, column_index, "integer")
                break
            if "编号" in text:
                header_match = (row_index, column_index, "identifier")
                break
        if header_match is not None:
            break
    if header_match is None:
        return False
    header_row, anchor_column, anchor_kind = header_match

    def parse_anchor(value: Any) -> tuple[str, int] | None:
        text = str(value).strip()
        if anchor_kind == "month":
            match = re.fullmatch(r"(\d{1,2})月", text)
            return ("month", int(match.group(1))) if match else None
        if anchor_kind == "integer":
            return (
                ("integer", int(text))
                if re.fullmatch(r"[0-9]+", text)
                else None
            )
        match = re.fullmatch(r"([A-Za-z][A-Za-z0-9._/-]*?[-_/]?)(\d+)", text)
        return (match.group(1).upper(), int(match.group(2))) if match else None

    parsed = {
        row_index: parse_anchor(row[anchor_column])
        for row_index, row in enumerate(grid)
        if row_index > header_row and anchor_column < len(row)
    }
    for row_index in range(header_row + 2, len(grid) - 1):
        anchor = (
            str(grid[row_index][anchor_column]).strip()
            if anchor_column < len(grid[row_index])
            else ""
        )
        if anchor:
            continue
        populated = sum(bool(str(value).strip()) for value in grid[row_index])
        if populated < max(2, int(math.ceil(column_count * 0.50))):
            continue
        previous = parsed.get(row_index - 1)
        following = parsed.get(row_index + 1)
        if (
            previous is not None
            and following is not None
            and previous[0] == following[0]
            and following[1] == previous[1] + 1
        ):
            return True
    return False


def _has_photographic_background(image: np.ndarray) -> bool:
    """Distinguish a photographed sheet from a direct spreadsheet screenshot."""
    if image is None or image.size == 0:
        return False
    height, width = image.shape[:2]
    band = max(4, int(round(min(height, width) * 0.025)))
    border = np.concatenate(
        (
            image[:band, :].reshape(-1, image.shape[2]),
            image[-band:, :].reshape(-1, image.shape[2]),
            image[:, :band].reshape(-1, image.shape[2]),
            image[:, -band:].reshape(-1, image.shape[2]),
        ),
        axis=0,
    )
    brightness = float(np.median(np.mean(border.astype(np.float32), axis=1)))
    chroma = float(np.median(np.ptp(border.astype(np.float32), axis=1)))
    return brightness < 232.0 or chroma > 10.0


def _trim_empty_outer_grid(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> tuple[list[list[str]], list[list[float]] | None]:
    """Remove empty paper-margin cells accidentally bounded by the page edge."""
    if not grid or any(len(row) != len(grid[0]) for row in grid):
        return grid, confidence_grid
    values = [list(row) for row in grid]
    confidences = (
        [list(row) for row in confidence_grid]
        if confidence_grid is not None
        else None
    )

    margin_marks = {"-", "_", "—", "–", "−", "一"}

    def is_rule_artifact(value: str) -> bool:
        normalized = "".join(unicodedata.normalize("NFKC", str(value)).split())
        return bool(normalized) and all(character in margin_marks for character in normalized)

    def band_is_empty_or_rule_artifact(band: list[str]) -> bool:
        nonempty = [str(value).strip() for value in band if str(value).strip()]
        if not nonempty:
            return True
        # A detected paper/page boundary can form an extra outer row or
        # column.  After line removal its intersections are occasionally read
        # as isolated dashes.  Treat only a sparse, dash-only outer band as a
        # margin; a populated unit/status column containing dashes is kept.
        return (
            len(nonempty) <= max(2, int(len(band) * 0.35))
            and all(is_rule_artifact(value) for value in nonempty)
        )

    def row_is_empty(index: int) -> bool:
        return band_is_empty_or_rule_artifact(values[index])

    def leading_row_is_dense_rule_artifact() -> bool:
        if len(values) < 2:
            return False
        first = [str(value).strip() for value in values[0] if str(value).strip()]
        second = [str(value).strip() for value in values[1] if str(value).strip()]
        return bool(
            len(first) >= max(3, int(len(values[0]) * 0.6))
            and all(is_rule_artifact(value) for value in first)
            and any(not is_rule_artifact(value) for value in second)
        )

    while len(values) > 1 and (row_is_empty(0) or leading_row_is_dense_rule_artifact()):
        values.pop(0)
        if confidences is not None:
            confidences.pop(0)
    while len(values) > 1 and row_is_empty(-1):
        values.pop()
        if confidences is not None:
            confidences.pop()

    def column_is_empty(index: int) -> bool:
        return band_is_empty_or_rule_artifact([str(row[index]) for row in values])

    while values and len(values[0]) > 1 and column_is_empty(0):
        for row in values:
            row.pop(0)
        if confidences is not None:
            for row in confidences:
                row.pop(0)
    while values and len(values[0]) > 1 and column_is_empty(-1):
        for row in values:
            row.pop()
        if confidences is not None:
            for row in confidences:
                row.pop()
    return values, confidences


def _repair_embedded_row_ruler_group_header(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
) -> bool:
    """Remove a fused row-ruler 1 and one proven empty paper-margin row."""
    if (
        len(grid) < 8
        or len(grid[0]) < 4
        or any(len(row) != len(grid[0]) for row in grid)
        or str(grid[0][0]).strip() != "1"
        or any(str(value).strip() for value in grid[-1])
    ):
        return False
    column_count = len(grid[0])
    known_group_headers = {
        "基础信息", "基本信息", "目标与测量", "数量与金额", "过程记录",
        "质量判定", "状态判定", "追溯信息",
    }
    group_positions = [
        column
        for column, value in enumerate(grid[0])
        if str(value).strip() in known_group_headers
    ]
    if (
        len(group_positions) < 2
        or group_positions[0] != 1
        or sum(bool(str(value).strip()) for value in grid[1]) < column_count - 1
        or sum(bool(str(value).strip()) for value in grid[-2]) < column_count - 1
    ):
        return False
    anchors = [0, *group_positions[1:]]
    boundaries = [*anchors, column_count]
    if any(
        right - left < 2
        for left, right in zip(boundaries, boundaries[1:])
    ):
        return False
    first_header = str(grid[0][group_positions[0]]).strip()
    grid[0][0] = first_header
    grid[0][group_positions[0]] = ""
    if confidence_grid is not None:
        confidence_grid[0][0] = min(
            0.77,
            float(confidence_grid[0][group_positions[0]]),
        )
        confidence_grid[0][group_positions[0]] = 0.0
    grid.pop()
    if confidence_grid is not None:
        confidence_grid.pop()
    spans.clear()
    for start, end in zip(boundaries, boundaries[1:]):
        spans.append(
            {
                "row": 0,
                "column": start,
                "row_span": 1,
                "column_span": end - start,
                "role": "group_header",
            }
        )
    spans.sort(key=lambda span: (int(span["row"]), int(span["column"])))
    return True


def _repair_fused_spreadsheet_ruler_table(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
) -> bool:
    """Strip one fused Excel ruler column and rejoin one split trailing row."""
    if (
        len(grid) < 8
        or len(grid[0]) < 5
        or any(len(row) != len(grid[0]) for row in grid)
    ):
        return False
    checked = grid[1 : min(len(grid), 9)]
    ruler_support = sum(
        str(row[0]).strip().isdigit()
        and int(str(row[0]).strip()) == index + 2
        for index, row in enumerate(checked)
    )
    if ruler_support < max(6, int(math.ceil(len(checked) * 0.75))):
        return False
    new_column_count = len(grid[0]) - 1
    detail = [str(value).strip() for value in grid[1][1:]]
    header_hints = (
        "序号", "编号", "名称", "部门", "岗位", "日期", "时间", "班次",
        "计划", "实际", "单位", "工时", "状态", "类型", "分类",
    )
    if (
        sum(bool(value) for value in detail) < new_column_count - 1
        or sum(any(hint in value for hint in header_hints) for value in detail) < 4
    ):
        return False
    known_group_headers = (
        "基础信息", "基本信息", "目标与测量", "数量与金额", "过程记录",
        "质量判定", "状态判定", "追溯信息",
    )
    anchors: dict[int, str] = {}
    for old_column, value in enumerate(grid[0]):
        text = str(value).strip()
        matches = [label for label in known_group_headers if label in text]
        if len(matches) != 1:
            continue
        new_column = 0 if old_column == 0 else old_column - 1
        if new_column in anchors:
            return False
        anchors[new_column] = matches[0]
    positions = sorted(anchors)
    if len(positions) < 2 or positions[0] != 0:
        return False
    boundaries = [*positions, new_column_count]
    if any(
        right - left < 2
        for left, right in zip(boundaries, boundaries[1:])
    ):
        return False
    trimmed_grid = [list(row[1:]) for row in grid]
    trimmed_confidence = (
        [list(row[1:]) for row in confidence_grid]
        if confidence_grid is not None
        else None
    )
    trimmed_grid[0] = ["" for _ in range(new_column_count)]
    if trimmed_confidence is not None:
        trimmed_confidence[0] = [0.0 for _ in range(new_column_count)]
    for position, label in anchors.items():
        trimmed_grid[0][position] = label
        if trimmed_confidence is not None:
            trimmed_confidence[0][position] = 0.77

    last = [str(value).strip() for value in trimmed_grid[-1]]
    previous = [str(value).strip() for value in trimmed_grid[-2]]
    first_last_content = next(
        (index for index, value in enumerate(last) if value),
        -1,
    )
    if not (
        2 <= first_last_content <= new_column_count - 3
        and not any(last[:first_last_content])
        and all(previous[:first_last_content])
        and sum(bool(value) for value in last[first_last_content:])
        >= new_column_count - first_last_content - 1
        and sum(not value for value in previous[first_last_content:])
        >= max(2, (new_column_count - first_last_content) // 2)
    ):
        return False
    trimmed_grid[-2] = [
        last[column] or previous[column]
        for column in range(new_column_count)
    ]
    if trimmed_confidence is not None:
        trimmed_confidence[-2] = [
            trimmed_confidence[-1][column]
            if last[column]
            else trimmed_confidence[-2][column]
            for column in range(new_column_count)
        ]
        trimmed_confidence.pop()
    trimmed_grid.pop()
    grid[:] = trimmed_grid
    if confidence_grid is not None and trimmed_confidence is not None:
        confidence_grid[:] = trimmed_confidence
    spans.clear()
    for start, end in zip(boundaries, boundaries[1:]):
        spans.append(
            {
                "row": 0,
                "column": start,
                "row_span": 1,
                "column_span": end - start,
                "role": "group_header",
            }
        )
    return True


def _title_spans_from_screen_grid(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None = None,
) -> list[dict[str, Any]]:
    """Preserve a top full-width title as a merged, centered title cell."""
    if len(grid) < 2 or len(grid[0]) < 3:
        return []
    title_cells = [index for index, value in enumerate(grid[0]) if str(value).strip()]
    second_row_cells = sum(bool(str(value).strip()) for value in grid[1])
    third_row_is_dense = bool(
        len(grid) >= 3
        and sum(bool(str(value).strip()) for value in grid[2]) >= len(grid[0]) - 1
    )
    if len(title_cells) != 1 or not (
        second_row_cells >= 2 or (second_row_cells >= 1 and third_row_is_dense)
    ):
        return []
    # Qt and XLSX both keep merged-cell content in the span's top-left cell.
    # OCR may place a visually centred title in any source column, so move only
    # this unambiguous, single-cell title to the merge anchor before exporting.
    source_column = title_cells[0]
    if source_column != 0:
        grid[0][0] = grid[0][source_column]
        grid[0][source_column] = ""
        if (
            confidence_grid is not None
            and confidence_grid
            and len(confidence_grid[0]) == len(grid[0])
        ):
            confidence_grid[0][0] = confidence_grid[0][source_column]
            confidence_grid[0][source_column] = 0.0
    return [{
        "row": 0,
        "column": 0,
        "row_span": 1,
        "column_span": len(grid[0]),
        "role": "title",
    }]


def _spatial_title_is_prominent(
    grid: list[list[str]],
    geometry: dict[str, Any],
) -> bool:
    """Require centred, visibly larger title text before restoring a lost span."""
    if len(grid) < 6 or len(grid[0]) < 3:
        return False
    column_count = len(grid[0])
    if (
        any(len(row) != column_count for row in grid)
        or sum(bool(str(value).strip()) for value in grid[0]) != 1
        or sum(bool(str(value).strip()) for value in grid[1]) < column_count - 1
        or sum(
            sum(bool(str(value).strip()) for value in row) >= column_count - 1
            for row in grid[2:]
        )
        < 4
    ):
        return False
    groups = geometry.get("grouped_rows")
    anchors = geometry.get("anchors")
    if (
        not isinstance(groups, list)
        or len(groups) != len(grid)
        or not isinstance(anchors, list)
        or len(anchors) != column_count
        or len(groups[0]) != 1
    ):
        return False
    title = groups[0][0]
    later_heights = [
        float(entry.get("height", 0.0))
        for row in groups[1 : min(len(groups), 8)]
        for entry in row
        if float(entry.get("height", 0.0)) > 0.0
    ]
    if not later_heights:
        return False
    title_height = float(title.get("height", 0.0))
    ordinary_height = float(np.median(later_heights))
    left_anchor = float(anchors[0])
    right_anchor = float(anchors[-1])
    table_width = max(1.0, right_anchor - left_anchor)
    table_center = (left_anchor + right_anchor) * 0.5
    return bool(
        float(title.get("score", 0.0)) >= 0.78
        and title_height >= ordinary_height * 1.18
        and abs(float(title.get("center_x", table_center)) - table_center)
        <= table_width * 0.10
    )


def _new_structure_certificate(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    source: str,
) -> dict[str, Any]:
    """在任何文字驱动的后处理之前锁定物理表格几何。"""
    source_shape = [int(image.shape[0]), int(image.shape[1])]
    boundary_payload = json.dumps(
        {
            "source": source,
            "source_shape": source_shape,
            "columns": list(map(int, columns)),
            "rows": list(map(int, rows)),
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return {
        "version": 1,
        "verified": True,
        "source": source,
        "source_shape": source_shape,
        "column_boundaries": list(map(int, columns)),
        "row_boundaries": list(map(int, rows)),
        "rows": max(0, len(rows) - 1),
        "columns": max(0, len(columns) - 1),
        "row_offset": 0,
        "column_offset": 0,
        "ui_headers_processed": False,
        "spans": [],
        "geometry_hash": hashlib.blake2b(boundary_payload, digest_size=16).hexdigest(),
    }


def _align_structure_certificate_to_grid(
    certificate: dict[str, Any], grid: list[list[str]],
) -> bool:
    """把结构证书裁到实际交付的网格范围，对不齐就返回 False。

    证书内部允许用 ``row_offset`` / ``column_offset`` 表示"物理网格比交付的
    表格大"（抬头说明行、空白尾行被删掉时）。但导出层和界面都假设 boundaries
    恰好是 行数+1 / 列数+1。两条路径一旦不同步，界面会直接判定
    "表格结构校验证书与识别结果不一致"而整张表不显示，点 Excel 也会报
    invalid XLSX structure certificate boundaries——实测 1200 例真实场景语料
    里有 35 例（约占带证书表的 4.7%）踩中，客户等于什么都没拿到。

    这里在封口前统一裁齐；裁不齐的宁可直接撤销结构认证，也不要发一个下游
    必然拒绝的证书。
    """
    if not isinstance(certificate, dict):
        return False
    rows = len(grid)
    columns = len(grid[0]) if rows else 0
    if rows <= 0 or columns <= 0 or any(len(row) != columns for row in grid):
        return False
    row_offset = int(certificate.get("row_offset", 0) or 0)
    column_offset = int(certificate.get("column_offset", 0) or 0)
    if row_offset < 0 or column_offset < 0:
        return False
    row_boundaries = [int(value) for value in certificate.get("row_boundaries", [])]
    column_boundaries = [int(value) for value in certificate.get("column_boundaries", [])]
    row_columns = certificate.get("row_column_boundaries")
    if row_offset or column_offset:
        row_boundaries = row_boundaries[row_offset:]
        column_boundaries = column_boundaries[column_offset:]
        if isinstance(row_columns, list):
            # 2026-10-30（lead 复查 P1）：逐行竖线边界同样要按 **row_offset 与
            # column_offset** 两个方向裁。旧实现只裁行方向（且这里与
            # `_drop_leading_page_caption_rows` 各裁一次 → 二次裁剪），列方向从不裁
            # ⇒ 每一行的边界列表长度恒为 columns+offset+1，`_structure_certificate_matches`
            # 的长度校验必然失败，结构认证被静默撤销；即使长度侥幸对上，逐行竖线位置
            # 也整体错位。offset 归一化只在这里做一次，`_drop_leading_page_caption_rows`
            # 不再自己裁。
            trimmed: list[Any] = []
            for boundaries in row_columns[row_offset:]:
                if isinstance(boundaries, list) and column_offset:
                    trimmed.append(list(boundaries)[column_offset:])
                else:
                    trimmed.append(boundaries)
            row_columns = trimmed
        certificate["row_column_boundaries"] = row_columns
        if isinstance(row_columns, list):
            # 裁过就必须重算 row_column_hash：否则下游哈希校验与本列表不一致，
            # 证书会被判成伪造（旧实现正是漏了这一步）。
            certificate["row_column_hash"] = hashlib.blake2b(
                json.dumps(row_columns, separators=(",", ":")).encode("utf-8"),
                digest_size=16,
            ).hexdigest()
    if len(row_boundaries) != rows + 1 or len(column_boundaries) != columns + 1:
        return False
    if any(right <= left for left, right in zip(row_boundaries, row_boundaries[1:])):
        return False
    if any(right <= left for left, right in zip(column_boundaries, column_boundaries[1:])):
        return False
    certificate["row_boundaries"] = row_boundaries
    certificate["column_boundaries"] = column_boundaries
    certificate["row_offset"] = 0
    certificate["column_offset"] = 0
    certificate["rows"] = rows
    certificate["columns"] = columns
    boundary_payload = json.dumps(
        {
            "source": str(certificate.get("source", "")),
            "source_shape": certificate.get("source_shape", []),
            "columns": column_boundaries,
            "rows": row_boundaries,
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    certificate["geometry_hash"] = hashlib.blake2b(
        boundary_payload, digest_size=16
    ).hexdigest()
    return True


def _seal_structure_certificate(certificate: dict[str, Any]) -> None:
    """对最终显示的行列和合并关系签名，供 GUI 校验发布协议。"""
    payload = json.dumps(
        {key: certificate[key] for key in (
            "row_offset", "column_offset", "rows", "columns", "spans"
        )},
        ensure_ascii=True, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")
    certificate["structure_hash"] = hashlib.blake2b(payload, digest_size=16).hexdigest()


def _align_structure_certificate_after_ui_strip(
    certificate: dict[str, Any],
    before_shape: tuple[int, int],
    after_shape: tuple[int, int],
) -> bool:
    """只允许移除已严格证明的电子表格标尺及其顶部空框。"""
    before_rows, before_columns = before_shape
    after_rows, after_columns = after_shape
    removed_rows = before_rows - after_rows
    removed_columns = before_columns - after_columns
    expected_rows = int(certificate.get("rows", -1))
    expected_columns = int(certificate.get("columns", -1))
    if (
        before_rows != expected_rows
        or before_columns != expected_columns
        or removed_rows not in (0, 1, 2)
        or removed_columns not in (0, 1)
    ):
        return False
    certificate["row_offset"] = int(certificate.get("row_offset", 0)) + removed_rows
    certificate["column_offset"] = int(certificate.get("column_offset", 0)) + removed_columns
    certificate["rows"] = after_rows
    certificate["columns"] = after_columns
    return True


def _trim_certified_empty_outer_grid(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    certificate: dict[str, Any],
    page_text_evidence: list[tuple[str, float, float, float]] | None = None,
) -> tuple[list[list[str]], list[list[float]] | None, bool]:
    """Trim empty paper-frame bands and move the physical boundary offsets."""
    source = certificate.get("source")
    if source not in {
        "photographic_ruled_grid",
        "screen_ruled_grid",
    }:
        return grid, confidence_grid, True
    before_rows, before_columns, _ = _grid_shape_and_content(grid)
    preserve_empty_outer_grid = bool(
        certificate.get("preserve_empty_outer_grid", False)
    )
    if preserve_empty_outer_grid:
        ruler_preview = grid[1:] if before_rows >= 3 else []
        stripped_preview, _ = _strip_spreadsheet_ui_headers(ruler_preview, None)
        proven_leading_frame = bool(
            ruler_preview
            and not any(str(value).strip() for value in grid[0])
            and len(stripped_preview) == len(ruler_preview) - 1
            and len(stripped_preview[0]) == before_columns
        )
        if proven_leading_frame:
            row_boundaries = [
                int(value) for value in certificate.get("row_boundaries", [])
            ]
            column_boundaries = [
                int(value) for value in certificate.get("column_boundaries", [])
            ]
            row_offset = int(certificate.get("row_offset", 0))
            column_offset = int(certificate.get("column_offset", 0))
            active_rows = row_boundaries[row_offset:]
            active_columns = column_boundaries[column_offset:]
            leading_band_has_page_title = bool(
                len(active_rows) >= 2
                and len(active_columns) >= 2
                and any(
                    float(score) >= 0.85
                    and len(_comparable_text(text)) >= 3
                    and float(active_rows[0]) <= float(center_y) <= float(active_rows[1])
                    and float(active_columns[0]) <= float(center_x) <= float(active_columns[-1])
                    for text, center_x, center_y, score in (page_text_evidence or [])
                )
            )
            if leading_band_has_page_title:
                proven_leading_frame = False
        if not proven_leading_frame:
            row_boundaries = [
                int(value) for value in certificate.get("row_boundaries", [])
            ]
            column_boundaries = [
                int(value) for value in certificate.get("column_boundaries", [])
            ]
            row_offset = int(certificate.get("row_offset", 0))
            column_offset = int(certificate.get("column_offset", 0))
            source_shape = certificate.get("source_shape", [])
            active_rows = row_boundaries[row_offset:]
            active_gaps = [
                bottom - top
                for top, bottom in zip(active_rows, active_rows[1:])
            ]
            typical_gap = (
                float(median(active_gaps[:-1]))
                if len(active_gaps) >= 2
                else 0.0
            )
            source_height = (
                int(source_shape[0])
                if isinstance(source_shape, (list, tuple)) and source_shape
                else 0
            )
            trailing_margin = (
                source_height - active_rows[-1]
                if source_height > 0 and active_rows
                else -1
            )
            short_recovered_trailing_band = bool(
                certificate.get("verified", False)
                and before_rows >= 8
                and before_columns >= 3
                and row_offset > 0
                and not certificate.get("spans")
                and len(row_boundaries) == row_offset + before_rows + 1
                and len(column_boundaries)
                == column_offset + before_columns + 1
                and len(active_gaps) == before_rows
                and typical_gap > 0.0
                and 0 < active_gaps[-1] <= typical_gap * 0.60
                and 0 <= trailing_margin <= max(
                    int(round(typical_gap * 2.25)),
                    int(round(source_height * 0.05)),
                )
                and not any(str(value).strip() for value in grid[-1])
                and sum(bool(str(value).strip()) for value in grid[-2])
                >= max(2, int(math.ceil(before_columns * 0.75)))
            )
            if not short_recovered_trailing_band:
                return grid, confidence_grid, True
            values = grid[:-1]
            confidences = (
                confidence_grid[:-1] if confidence_grid is not None else None
            )
            certificate["row_boundaries"] = row_boundaries[:-1]
            certificate["rows"] = before_rows - 1
            boundary_payload = json.dumps(
                {
                    "source": str(certificate.get("source", "")),
                    "source_shape": certificate.get("source_shape", []),
                    "columns": certificate["column_boundaries"],
                    "rows": certificate["row_boundaries"],
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
            certificate["geometry_hash"] = hashlib.blake2b(
                boundary_payload, digest_size=16
            ).hexdigest()
            return values, confidences, True
        values = grid[1:]
        confidences = confidence_grid[1:] if confidence_grid is not None else None
    elif source == "screen_ruled_grid":
        # Screen grids are already in image coordinates, so a legitimate empty
        # trailing row must remain addressable. Trim only one fully empty band
        # before a clearly populated header; this is the photographed frame
        # artefact seen above otherwise complete dense tables.
        if (
            before_rows < 2
            or any(str(value).strip() for value in grid[0])
            or sum(bool(str(value).strip()) for value in grid[1])
            < max(2, int(math.ceil(before_columns * 0.75)))
        ):
            return grid, confidence_grid, True
        values = grid[1:]
        confidences = confidence_grid[1:] if confidence_grid is not None else None
    else:
        values, confidences = _trim_empty_outer_grid(grid, confidence_grid)
    after_rows, after_columns, _ = _grid_shape_and_content(values)
    removed_rows = before_rows - after_rows
    removed_columns = before_columns - after_columns
    if not removed_rows and not removed_columns:
        return values, confidences, True
    if (
        before_rows != int(certificate.get("rows", -1))
        or before_columns != int(certificate.get("columns", -1))
        or not 0 <= removed_rows <= 2
        or not 0 <= removed_columns <= 2
    ):
        return grid, confidence_grid, False

    leading_rows = 0
    while leading_rows < before_rows and not any(
        str(value).strip() for value in grid[leading_rows]
    ):
        leading_rows += 1
    leading_columns = 0
    while leading_columns < before_columns and all(
        leading_columns >= len(row) or not str(row[leading_columns]).strip()
        for row in grid
    ):
        leading_columns += 1
    if leading_rows > removed_rows or leading_columns > removed_columns:
        return grid, confidence_grid, False
    trailing_rows = removed_rows - leading_rows
    trailing_columns = removed_columns - leading_columns
    row_boundaries = [int(value) for value in certificate.get("row_boundaries", [])]
    column_boundaries = [int(value) for value in certificate.get("column_boundaries", [])]
    if (
        len(row_boundaries) != before_rows + 1
        or len(column_boundaries) != before_columns + 1
    ):
        return grid, confidence_grid, False
    certificate["row_boundaries"] = row_boundaries[
        leading_rows : len(row_boundaries) - trailing_rows
        if trailing_rows
        else None
    ]
    certificate["column_boundaries"] = column_boundaries[
        leading_columns : len(column_boundaries) - trailing_columns
        if trailing_columns
        else None
    ]
    certificate["row_offset"] = 0
    certificate["column_offset"] = 0
    certificate["rows"] = after_rows
    certificate["columns"] = after_columns
    boundary_payload = json.dumps(
        {
            "source": str(certificate.get("source", "")),
            "source_shape": certificate.get("source_shape", []),
            "columns": certificate["column_boundaries"],
            "rows": certificate["row_boundaries"],
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    certificate["geometry_hash"] = hashlib.blake2b(
        boundary_payload, digest_size=16
    ).hexdigest()
    return values, confidences, True


def _trim_unruled_empty_trailing_margin_row(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    spans: list[dict[str, Any]],
) -> bool:
    """Trim one empty page-edge interval only when its internal rules have ended."""
    if (
        image.size == 0
        or len(grid) < 4
        or not grid[0]
        or len(confidence_grid) != len(grid)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or any(len(row) != len(grid[0]) for row in grid + confidence_grid)
        or any(str(value).strip() for value in grid[-1])
        or sum(bool(str(value).strip()) for value in grid[-2]) < len(grid[0]) - 1
        or any(int(span.get("row", -1)) >= len(grid) - 1 for span in spans)
        or image.shape[0] - int(rows[-1])
        > max(64, int(round(image.shape[0] * 0.05)))
    ):
        return False
    _, vertical, _ = pipeline._grid_maps(image)

    def internal_support(top: int, bottom: int) -> float:
        supports = []
        for boundary in columns[1:-1]:
            band = vertical[
                max(0, int(top) + 1) : min(vertical.shape[0], int(bottom)),
                max(0, int(boundary) - 2) : min(vertical.shape[1], int(boundary) + 3),
            ]
            supports.append(
                float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            )
        return float(np.median(supports)) if supports else 0.0

    previous_support = internal_support(rows[-3], rows[-2])
    trailing_support = internal_support(rows[-2], rows[-1])
    if previous_support < 0.55 or trailing_support > 0.12:
        return False
    grid.pop()
    confidence_grid.pop()
    rows.pop()
    return True


def _certified_title_span(
    image: np.ndarray,
    certificate: dict[str, Any],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> list[dict[str, Any]]:
    """只有物理标题行确实缺少内部边界时才创建标题合并格。"""
    if len(grid) < 2 or len(grid[0]) < 3:
        return []
    title_cells = [index for index, value in enumerate(grid[0]) if str(value).strip()]
    if len(title_cells) != 1:
        return []
    columns = [int(value) for value in certificate.get("column_boundaries", [])]
    rows = [int(value) for value in certificate.get("row_boundaries", [])]
    row_offset = int(certificate.get("row_offset", 0))
    column_offset = int(certificate.get("column_offset", 0))
    columns = columns[column_offset:]
    rows = rows[row_offset:]
    if len(columns) != len(grid[0]) + 1 or len(rows) < 3:
        return []
    _, vertical, _ = pipeline._grid_maps(image)
    height, width = vertical.shape[:2]

    def boundary_supports(top: int, bottom: int) -> list[float]:
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = max(0, min(height, top + inset))
        band_bottom = max(band_top + 1, min(height, bottom - inset))
        supports: list[float] = []
        for column in columns[1:-1]:
            left = max(0, min(width, column - 3))
            right = max(left + 1, min(width, column + 4))
            band = vertical[band_top:band_bottom, left:right]
            supports.append(float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0)
        return supports

    title_supports = boundary_supports(rows[0], rows[1])
    following_supports = [
        boundary_supports(rows[index], rows[index + 1])
        for index in range(1, min(len(rows) - 1, 3))
    ]
    group_cell_count = sum(bool(str(value).strip()) for value in grid[1])
    detail_cell_count = (
        sum(bool(str(value).strip()) for value in grid[2])
        if len(grid) >= 3
        else 0
    )
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= len(grid[0]) - 1
        for row in grid[3:]
    )
    following_layout_support = bool(
        2 <= group_cell_count <= max(2, len(grid[0]) // 2)
        and detail_cell_count >= len(grid[0]) - 1
        and dense_body_rows >= 4
    )
    if (
        not title_supports
        or any(value >= 0.18 for value in title_supports)
        or len(str(grid[0][title_cells[0]]).strip()) < 3
        or not (
            following_layout_support
            or any(
                len(supports) == len(title_supports)
                and all(value >= 0.35 for value in supports)
                for supports in following_supports
            )
        )
    ):
        return []
    source_column = title_cells[0]
    title_text = _normalize_certified_batch_title(grid[0][source_column])
    if source_column != 0:
        grid[0][0] = title_text
        grid[0][source_column] = ""
        if confidence_grid is not None:
            confidence_grid[0][0] = confidence_grid[0][source_column]
            confidence_grid[0][source_column] = 0.0
    else:
        grid[0][0] = title_text
    return [{
        "row": 0,
        "column": 0,
        "row_span": 1,
        "column_span": len(grid[0]),
        "role": "title",
    }]


def _strict_multilevel_title_span(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> list[dict[str, Any]]:
    """Infer a logical title merge only from a complete three-level layout."""
    if len(grid) < 7 or len(grid[0]) < 4:
        return []
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return []
    populated = [
        sum(bool(str(value).strip()) for value in row)
        for row in grid[:3]
    ]
    title_values = [str(value).strip() for value in grid[0] if str(value).strip()]
    group_values = [str(value).strip() for value in grid[1] if str(value).strip()]
    detail_values = [str(value).strip() for value in grid[2] if str(value).strip()]
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= column_count - 1
        for row in grid[3:]
    )
    textual_detail_headers = sum(
        bool(value) and not re.fullmatch(r"[+\-]?\d+(?:\.\d+)?", value)
        for value in detail_values
    )
    recognized_detail_headers = sum(
        value in _COMMON_HEADER_LABELS for value in detail_values
    )
    if not (
        len(title_values) == 1
        and len(title_values[0]) >= 3
        and populated[1] >= 2
        and populated[1] <= max(2, column_count // 2)
        and populated[2] >= column_count - 1
        and dense_body_rows >= 4
        and recognized_detail_headers >= max(3, column_count - 2)
        and all(value and not re.search(r"\d", value) for value in group_values)
    ):
        return []
    spans = _title_spans_from_screen_grid(grid, confidence_grid)
    if spans:
        grid[0][0] = _normalize_certified_batch_title(grid[0][0])
    return spans


def _strict_simple_title_span(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> list[dict[str, Any]]:
    """Infer one full-width title above a semantic detail header."""
    if len(grid) < 7 or len(grid[0]) < 4:
        return []
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return []
    title_values = [str(value).strip() for value in grid[0] if str(value).strip()]
    header_values = [str(value).strip() for value in grid[1] if str(value).strip()]
    semantic_headers = sum(
        bool(_header_semantic_labels(value))
        or value in _COMMON_HEADER_LABELS
        for value in header_values
    )
    textual_headers = sum(
        bool(value)
        and len(value) <= 18
        and not re.search(r"\d{2,}", value)
        and re.fullmatch(r"[A-Za-z\u3400-\u9fff（）() _./-]+", value) is not None
        for value in header_values
    )
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= column_count - 1
        for row in grid[2:]
    )
    if not (
        len(title_values) == 1
        and len(title_values[0]) >= 3
        and len(header_values) >= column_count - 1
        and (
            semantic_headers >= max(3, int(math.ceil(column_count * 0.50)))
            or textual_headers >= column_count - 1
        )
        and dense_body_rows >= 4
    ):
        return []
    spans = _title_spans_from_screen_grid(grid, confidence_grid)
    if spans:
        grid[0][0] = _normalize_certified_batch_title(grid[0][0])
    return spans


def _repair_redundantly_split_simple_title(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> list[dict[str, Any]]:
    """Collapse duplicate title fragments only when the following schema is dense."""
    if len(grid) < 7 or len(grid[0]) < 3:
        return []
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return []
    title_locations = [
        column for column, value in enumerate(grid[0]) if str(value).strip()
    ]
    if not 1 <= len(title_locations) <= 3:
        return []
    title_values = [str(grid[0][column]).strip() for column in title_locations]
    longest = max(title_values, key=len)
    comparable_longest = _comparable_text(longest)
    dated_longest = bool(
        re.fullmatch(
            r"[\u3400-\u9fffA-Za-z0-9][\u3400-\u9fffA-Za-z0-9 _-]{2,30}?\s*"
            r"20\d{2}年\d{1,2}月",
            longest,
        )
    )
    iso_batch_longest = bool(
        re.fullmatch(
            r"[^—一\r\n]{3,30}?\s*[—一]\s*20\d{2}-\d{2}\s*批次",
            longest,
        )
    )
    structured_title = dated_longest or iso_batch_longest
    redundant_longest = bool(
        len(title_values) >= 2
        and len(longest) >= 5
        and comparable_longest
        and all(
            (
                len(_comparable_text(value)) >= 2
                and _comparable_text(value) in comparable_longest
            )
            or (
                structured_title
                and len(_comparable_text(value)) == 1
                and _comparable_text(value)
                in {comparable_longest[:1], comparable_longest[-1:]}
            )
            for value in title_values
            if value != longest
        )
    )
    dated_values = [
        value for value in title_values if re.fullmatch(r"20\d{2}年\d{1,2}月", value)
    ]
    split_dated_title = False
    concatenated_dated_title = False
    single_complete_dated_title = bool(
        len(title_locations) == 1
        and structured_title
    )
    canonical_title = longest
    joined_title = "".join(title_values)
    joined_match = re.fullmatch(
        r"([\u3400-\u9fffA-Za-z0-9][\u3400-\u9fffA-Za-z0-9 _-]{2,30}?)\s*"
        r"(20\d{2}年\d{1,2}月)",
        joined_title,
    )
    comparable_fragments = [_comparable_text(value) for value in title_values]
    fragments_do_not_overlap = all(
        not left
        or not right
        or left not in right
        and right not in left
        for index, left in enumerate(comparable_fragments)
        for right in comparable_fragments[index + 1 :]
    )
    if (
        joined_match is not None
        and len(title_values) >= 2
        and fragments_do_not_overlap
    ):
        concatenated_dated_title = True
        canonical_title = f"{joined_match.group(1).strip()} {joined_match.group(2)}"
    joined_iso_match = re.fullmatch(
        r"(?P<label>[^—\r\n]{3,30}?)\s*—\s*"
        r"(?P<period>20\d{2}-\d{2})\s*(?P<suffix>批次)",
        joined_title,
    )
    if (
        joined_iso_match is not None
        and len(title_values) >= 2
        and fragments_do_not_overlap
    ):
        concatenated_dated_title = True
        canonical_title = (
            f"{joined_iso_match.group('label').strip()} — "
            f"{joined_iso_match.group('period')} {joined_iso_match.group('suffix')}"
        )
    if len(dated_values) == 1:
        period = dated_values[0]
        labels = [
            value
            for value in title_values
            if value != period and _comparable_text(value) not in _comparable_text(period)
        ]
        label = max(labels, key=len, default="")
        if (
            len(label) >= 3
            and all(
                _comparable_text(value) in _comparable_text(label)
                for value in labels
            )
        ):
            split_dated_title = all(
                value in {label, period}
                or _comparable_text(value) in _comparable_text(label)
                or _comparable_text(value) in _comparable_text(period)
                for value in title_values
            )
            if split_dated_title:
                canonical_title = f"{label} {period}"
    if (
        not redundant_longest
        and not split_dated_title
        and not concatenated_dated_title
        and not single_complete_dated_title
    ):
        return []
    header_values = [str(value).strip() for value in grid[1] if str(value).strip()]
    known_group_headers = {
        "基础信息", "基本信息", "目标与测量", "数量与金额", "过程记录",
        "质量判定", "状态判定", "追溯信息", "本期", "计划", "累计",
        "上限", "实际", "下限",
    }
    semantic_headers = sum(
        bool(_header_semantic_labels(value))
        or value in _COMMON_HEADER_LABELS
        or value in known_group_headers
        or bool(
            re.fullmatch(
                r"(?:no\.?|english\s+name|model|serial\s+no\.?|code|value|lower|upper)",
                value,
                flags=re.IGNORECASE,
            )
        )
        for value in header_values
    )
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= column_count - 1
        for row in grid[2:]
    )
    simple_header_supported = bool(
        len(header_values) >= column_count - 1
        and (
            semantic_headers >= 3
            or (
                (split_dated_title or concatenated_dated_title)
                and sum(
                    bool(re.fullmatch(r"[\u3400-\u9fffA-Za-z ._-]{2,12}", value))
                    for value in header_values
                )
                >= max(3, int(math.ceil((column_count - 1) * 0.75)))
            )
        )
        and dense_body_rows >= 4
    )
    nested_header_supported = bool(
        len(grid) >= 8
        and 2 <= len(header_values) <= max(3, column_count // 2 + 1)
        and semantic_headers >= 2
        and sum(bool(str(value).strip()) for value in grid[2])
        >= column_count - 1
        and sum(
            sum(bool(str(value).strip()) for value in row) >= column_count - 1
            for row in grid[3:]
        )
        >= 4
    )
    deep_nested_header_supported = bool(
        len(grid) >= 9
        and 2 <= len(header_values) <= max(3, column_count // 2 + 1)
        and semantic_headers >= 2
        and 2 <= sum(bool(str(value).strip()) for value in grid[2])
        <= max(3, int(math.ceil(column_count / 2.0)) + 1, column_count - 2)
        and sum(bool(str(value).strip()) for value in grid[3])
        >= column_count - 1
        and sum(
            sum(bool(str(value).strip()) for value in row) >= column_count - 1
            for row in grid[4:]
        )
        >= 4
    )
    very_deep_nested_header_supported = bool(
        len(grid) >= 10
        and 2 <= len(header_values) <= max(3, column_count // 2 + 1)
        and semantic_headers >= 2
        and 2 <= sum(bool(str(value).strip()) for value in grid[2])
        <= max(3, int(math.ceil(column_count / 2.0)) + 1)
        and 2 <= sum(bool(str(value).strip()) for value in grid[3])
        <= max(3, int(math.ceil(column_count / 2.0)) + 1)
        and sum(bool(str(value).strip()) for value in grid[4])
        >= column_count - 1
        and sum(
            sum(bool(str(value).strip()) for value in row) >= column_count - 1
            for row in grid[5:]
        )
        >= 4
    )
    if (
        not simple_header_supported
        and not nested_header_supported
        and not deep_nested_header_supported
        and not very_deep_nested_header_supported
    ):
        return []
    source_confidence = 0.77
    if confidence_grid is not None:
        source_confidence = min(
            float(confidence_grid[0][column]) for column in title_locations
        )
    for column in title_locations:
        grid[0][column] = ""
        if confidence_grid is not None:
            confidence_grid[0][column] = -1.0
    grid[0][0] = _normalize_certified_batch_title(canonical_title)
    if confidence_grid is not None:
        confidence_grid[0][0] = min(0.77, source_confidence)
    return [
        {
            "row": 0,
            "column": 0,
            "row_span": 1,
            "column_span": column_count,
            "role": "title",
        }
    ]


def _extend_leading_nested_group_header(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
    columns: list[int],
    rows: list[int],
    page_text_evidence: list[tuple[str, float, float, float]],
) -> bool:
    """Move a one-column-shifted parent header only with nested and center proof."""
    if (
        len(grid) < 4
        or not grid[0]
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
    ):
        return False
    column_count = len(grid[0])
    for row_index in range(min(3, len(grid) - 1)):
        group_spans = sorted(
            (
                span
                for span in spans
                if int(span.get("row", -1)) == row_index
                and span.get("role") == "group_header"
            ),
            key=lambda span: int(span.get("column", -1)),
        )
        if not group_spans:
            continue
        first_span = group_spans[0]
        start = int(first_span.get("column", -1))
        end = start + int(first_span.get("column_span", 1))
        nested_coverage = sum(
            int(span.get("column_span", 1))
            for span in spans
            if int(span.get("row", -1)) == row_index + 1
            and span.get("role") == "group_header"
        )
        if (
            start != 1
            or not 2 <= end <= column_count
            or nested_coverage < column_count
            or str(grid[row_index][0]).strip()
        ):
            continue
        text = str(grid[row_index][start]).strip()
        matches = [
            float(center_x)
            for evidence_text, center_x, center_y, score in page_text_evidence
            if _comparable_text(evidence_text) == _comparable_text(text)
            and float(score) >= 0.90
            and float(rows[row_index]) <= float(center_y) <= float(rows[row_index + 1])
        ]
        if len(matches) != 1:
            continue
        center_x = matches[0]
        expanded_left = float(columns[0])
        current_left = float(columns[start])
        right = float(columns[end])
        if not expanded_left <= center_x <= right:
            continue
        expanded_error = abs(center_x - (expanded_left + right) * 0.5) / max(
            1.0, right - expanded_left
        )
        current_error = abs(center_x - (current_left + right) * 0.5) / max(
            1.0, right - current_left
        )
        if current_error - expanded_error < 0.10:
            continue
        grid[row_index][0] = text
        grid[row_index][start] = ""
        if confidence_grid is not None:
            confidence_grid[row_index][0] = min(
                0.77,
                float(confidence_grid[row_index][start]),
            )
            confidence_grid[row_index][start] = 0.0
        first_span["column"] = 0
        first_span["column_span"] = end
        return True
    return False


def _repair_shifted_paired_nested_header(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
) -> bool:
    if len(grid) < 5 or not grid[0] or len(grid[0]) < 4:
        return False
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return False
    paired_labels = {"本期", "计划", "累计", "上限", "实际", "下限"}
    for row_index in range(1, min(4, len(grid) - 1)):
        if (
            sum(bool(str(value).strip()) for value in grid[row_index + 1])
            < column_count - 1
            or any(str(grid[row_index][column]).strip() for column in range(1, column_count, 2))
        ):
            continue
        for source_column in range(0, column_count - 2, 2):
            current = str(grid[row_index][source_column]).strip()
            matching_pairs = [
                (left, right)
                for left in paired_labels
                for right in paired_labels
                if current == left + right
            ]
            if (
                len(matching_pairs) != 1
                or str(grid[row_index][source_column + 2]).strip()
                or any(
                    column not in {source_column, source_column + 2}
                    and str(grid[row_index][column]).strip() not in paired_labels
                    for column in range(0, column_count, 2)
                )
            ):
                continue
            fused_spans = [
                span
                for span in spans
                if int(span.get("row", -1)) == row_index
                and int(span.get("column", -1)) == source_column
                and int(span.get("column_span", 0)) == 4
                and span.get("role") == "group_header"
            ]
            if len(fused_spans) != 1:
                continue
            left_label, right_label = matching_pairs[0]
            source_score = (
                float(confidence_grid[row_index][source_column])
                if confidence_grid is not None
                else 0.77
            )
            grid[row_index][source_column] = left_label
            grid[row_index][source_column + 2] = right_label
            if confidence_grid is not None:
                confidence_grid[row_index][source_column] = min(source_score, 0.77)
                confidence_grid[row_index][source_column + 2] = min(source_score, 0.77)
            spans.remove(fused_spans[0])
            spans.extend(
                [
                    {
                        "row": row_index,
                        "column": source_column,
                        "row_span": 1,
                        "column_span": 2,
                        "role": "group_header",
                    },
                    {
                        "row": row_index,
                        "column": source_column + 2,
                        "row_span": 1,
                        "column_span": 2,
                        "role": "group_header",
                    },
                ]
            )
            spans.sort(
                key=lambda span: (
                    int(span.get("row", -1)),
                    int(span.get("column", -1)),
                )
            )
            return True
    for row_index in range(1, min(4, len(grid) - 1)):
        source_columns = list(range(1, column_count, 2))
        source_values = [str(grid[row_index][column]).strip() for column in source_columns]
        if (
            str(grid[row_index][0]).strip() != str(row_index + 1)
            or len(source_columns) < 2
            or any(value not in paired_labels for value in source_values)
            or sum(bool(str(value).strip()) for value in grid[row_index])
            != len(source_columns) + 1
            or sum(bool(str(value).strip()) for value in grid[row_index + 1])
            < column_count - 1
            or any(int(span.get("row", -1)) == row_index for span in spans)
        ):
            continue
        source_scores = [
            float(confidence_grid[row_index][column])
            if confidence_grid is not None
            else 0.77
            for column in source_columns
        ]
        grid[row_index] = [""] * column_count
        if confidence_grid is not None:
            confidence_grid[row_index] = [0.0] * column_count
        for index, (value, score) in enumerate(zip(source_values, source_scores)):
            target_column = index * 2
            grid[row_index][target_column] = value
            if confidence_grid is not None:
                confidence_grid[row_index][target_column] = min(score, 0.77)
            spans.append(
                {
                    "row": row_index,
                    "column": target_column,
                    "row_span": 1,
                    "column_span": min(2, column_count - target_column),
                    "role": "group_header",
                }
            )
        spans.sort(
            key=lambda span: (
                int(span.get("row", -1)),
                int(span.get("column", -1)),
            )
        )
        return True
    return False


def _remove_unseen_summary_footer_marks(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    columns: list[int],
    rows: list[int],
) -> list[tuple[int, int]]:
    """Drop dash-only footer artifacts when the corresponding crop has no mark."""
    if (
        image.size == 0
        or not grid
        or not grid[0]
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
    ):
        return []
    footer = [str(value).strip() for value in grid[-1]]
    joined = re.sub(r"\s+", "", "".join(footer))
    marks = {"-", "_", "—", "–", "−", "一"}
    mark_columns = [
        column
        for column, value in enumerate(footer)
        if "".join(unicodedata.normalize("NFKC", value).split()) in marks
    ]
    meaningful = [value for value in footer if value and value not in marks]
    if (
        not mark_columns
        or not re.search(r"(?:合计|总计|小计|共\d+(?:条|项|行|笔))", joined)
        or not 1 <= len(meaningful) <= max(3, len(footer) // 3)
    ):
        return []
    removed = []
    top = max(0, int(round(rows[-2])))
    bottom = min(image.shape[0], int(round(rows[-1])))
    for column in mark_columns:
        left = max(0, int(round(columns[column])))
        right = min(image.shape[1], int(round(columns[column + 1])))
        pad_x = max(2, min(5, (right - left) // 14))
        pad_y = max(2, min(4, (bottom - top) // 10))
        crop = image[top + pad_y : bottom - pad_y, left + pad_x : right - pad_x]
        if _recover_horizontal_mark(crop, allow_shorter=True):
            continue
        grid[-1][column] = ""
        if confidence_grid is not None:
            confidence_grid[-1][column] = -1.0
        removed.append((len(grid) - 1, column))
    return removed


def _recover_bounded_ordinal_and_vocabulary_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
) -> list[tuple[int, int, str]]:
    """Re-read bounded ordinal confusions and blank repeated categories with Medium."""
    if (
        image.size == 0
        or not grid
        or not grid[0]
        or confidence_grid is None
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or not callable(getattr(ocr_engine, "text_rec", None))
    ):
        return []
    column_count = len(grid[0])
    header_row = -1
    ordinal_column = -1
    for row_index in range(min(3, len(grid) - 1)):
        for column_index, value in enumerate(grid[row_index]):
            if re.sub(r"\s+", "", str(value)) in {"序号", "No.", "No"}:
                header_row = row_index
                ordinal_column = column_index
                break
        if header_row >= 0:
            break

    targets: list[tuple[int, int, str, set[str]]] = []
    if header_row >= 0 and len(grid) - header_row >= 8:
        body = list(range(header_row + 1, len(grid)))
        matching = sum(
            str(grid[row][ordinal_column]).strip() == str(offset + 1)
            for offset, row in enumerate(body)
        )
        if matching >= max(6, len(body) - 2):
            for offset, row in enumerate(body):
                current = str(grid[row][ordinal_column]).strip()
                expected = str(offset + 1)
                if re.fullmatch(r"[Iil|丨]{1,3}", current) or (
                    current.isdigit() and current != expected
                ):
                    targets.append(
                        (row, ordinal_column, "ordinal", {expected})
                    )

    for candidate_header_row in range(min(5, len(grid) - 1)):
        for column, header in enumerate(grid[candidate_header_row]):
            if not any(token in str(header) for token in ("编号", "代码")):
                continue
            values = [
                (row, str(grid[row][column]).strip())
                for row in range(candidate_header_row + 1, len(grid))
            ]
            prefixes: dict[str, int] = {}
            for _, value in values:
                match = re.fullmatch(r"([A-Z]{2,4})(-.+)", value.upper())
                if match:
                    prefixes[match.group(1)] = prefixes.get(match.group(1), 0) + 1
            if not prefixes:
                continue
            prefix_lengths: dict[int, int] = {}
            for prefix, count in prefixes.items():
                prefix_lengths[len(prefix)] = prefix_lengths.get(len(prefix), 0) + count
            common_length, length_support = max(
                prefix_lengths.items(), key=lambda item: item[1]
            )
            common_prefix, support = max(prefixes.items(), key=lambda item: item[1])
            if support < 3 and length_support < 6:
                continue
            for row, value in values:
                match = re.fullmatch(r"([A-Z]{2,4})(-.+)", value.upper())
                if (
                    match
                    and match.group(1) != common_prefix
                    and _text_edit_distance(match.group(1), common_prefix) == 1
                ):
                    targets.append(
                        (
                            row,
                            column,
                            "identifier_prefix",
                            {f"{common_prefix}{match.group(2)}"},
                        )
                    )
                elif (
                    match
                    and length_support >= 6
                    and len(match.group(1)) != common_length
                    and abs(len(match.group(1)) - common_length) == 1
                ):
                    targets.append(
                        (
                            row,
                            column,
                            "identifier_length",
                            {f"{common_length}:{match.group(2)}"},
                        )
                    )

    for column in range(column_count):
        code_values = []
        length_counts: dict[int, int] = {}
        for row, row_values in enumerate(grid):
            value = str(row_values[column]).strip().upper()
            match = re.fullmatch(r"([A-Z]{2,4})(-.+)", value)
            if not match:
                continue
            code_values.append((row, match))
            length_counts[len(match.group(1))] = (
                length_counts.get(len(match.group(1)), 0) + 1
            )
        if len(code_values) < 8:
            continue
        common_length, support = max(length_counts.items(), key=lambda item: item[1])
        if support < max(6, int(math.ceil(len(code_values) * 0.80))):
            continue
        for row, match in code_values:
            if abs(len(match.group(1)) - common_length) != 1:
                continue
            target = (
                row,
                column,
                "identifier_length",
                {f"{common_length}:{match.group(2)}"},
            )
            if not any(
                existing_row == row and existing_column == column
                for existing_row, existing_column, _, _ in targets
            ):
                targets.append(target)

    last_row = len(grid) - 1
    last_is_summary = bool(
        re.search(
            r"(?:合计|总计|小计|共\d+(?:条|项|行|笔))",
            re.sub(r"\s+", "", "".join(str(value) for value in grid[last_row])),
        )
    )
    for column in range(column_count):
        if last_is_summary:
            break
        current = str(grid[last_row][column]).strip()
        counts: dict[str, tuple[str, int]] = {}
        for row in range(max(0, header_row + 1), last_row):
            value = str(grid[row][column]).strip()
            key = _motion_cell_consensus_key(value)
            if not key:
                continue
            original, count = counts.get(key, (value, 0))
            counts[key] = (original, count + 1)
        repeated = {
            key for key, (_, count) in counts.items() if count >= 3
        }
        if not current and repeated:
            targets.append((last_row, column, "vocabulary", repeated))
        elif current and repeated:
            current_key = _motion_cell_consensus_key(current)
            near = {
                key
                for key in repeated
                if key != current_key and _text_edit_distance(current_key, key) == 1
            }
            if near:
                targets.append((last_row, column, "near_vocabulary", near))
    if not targets:
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    views = []
    usable_targets = []
    for row, column, mode, allowed in targets:
        left = max(0, int(round(columns[column])))
        right = min(image.shape[1], int(round(columns[column + 1])))
        top = max(0, int(round(rows[row])))
        bottom = min(image.shape[0], int(round(rows[row + 1])))
        crop = image[top:bottom, left:right]
        tight = _tight_text_crop(crop)
        if tight.size == 0:
            continue
        view = cv2.resize(
            tight,
            None,
            fx=4.0,
            fy=4.0,
            interpolation=cv2.INTER_LANCZOS4,
        )
        if view.ndim == 2:
            view = cv2.cvtColor(view, cv2.COLOR_GRAY2BGR)
        views.append(view)
        usable_targets.append((row, column, mode, allowed))
    if not views:
        return []
    with contextlib.redirect_stdout(sys.stderr):
        recognized = ocr_engine.text_rec(TextRecInput(img=views))
    _release_recognition_images(recognized)
    if len(recognized.txts) != len(usable_targets):
        return []

    recovered = []
    for (row, column, mode, allowed), text, score in zip(
        usable_targets,
        recognized.txts,
        recognized.scores,
    ):
        value = str(text).strip()
        confidence = float(score)
        key = _motion_cell_consensus_key(value)
        if mode in {"ordinal", "identifier_prefix", "identifier_length"}:
            if mode == "identifier_length":
                identifier = re.fullmatch(r"([A-Z]{2,4})(-.+)", value.upper())
                accepted = bool(
                    identifier
                    and f"{len(identifier.group(1))}:{identifier.group(2)}" in allowed
                    and confidence >= 0.90
                )
            else:
                accepted = value.upper() in allowed and confidence >= (
                    0.90 if mode == "identifier_prefix" else 0.98
                )
            selected = value
        else:
            accepted_key = key if key in allowed else ""
            if not accepted_key and mode == "vocabulary" and confidence >= 0.84:
                near = [
                    candidate
                    for candidate in allowed
                    if _text_edit_distance(key, candidate) == 1
                ]
                if len(near) == 1:
                    accepted_key = near[0]
            accepted = bool(accepted_key) and confidence >= (
                0.85 if mode == "near_vocabulary" else 0.84 if key not in allowed else 0.75
            )
            selected = next(
                str(grid[peer][column]).strip()
                for peer in range(max(0, header_row + 1), last_row)
                if _motion_cell_consensus_key(grid[peer][column]) == accepted_key
            ) if accepted else ""
        if not accepted:
            continue
        grid[row][column] = selected
        confidence_grid[row][column] = 0.77
        recovered.append((row, column, selected))
    return recovered


def _title_span_consensus_geometry(
    spans: list[dict[str, Any]],
    row_count: int,
    column_count: int,
) -> tuple[set[tuple[int, int]], dict[tuple[int, int], int]]:
    """Lock subordinate title cells and expose the anchor's full crop width."""
    locked: set[tuple[int, int]] = set()
    widths: dict[tuple[int, int], int] = {}
    for span in spans:
        if span.get("role") != "title":
            continue
        row = int(span.get("row", -1))
        column = int(span.get("column", -1))
        width = int(span.get("column_span", 1))
        if row < 0 or row >= row_count or column < 0 or width < 1:
            continue
        usable_width = min(width, column_count - column)
        if usable_width < 1:
            continue
        widths[(row, column)] = usable_width
        locked.update(
            (row, current)
            for current in range(column + 1, column + usable_width)
        )
    return locked, widths


def _select_extended_title_candidate(
    original: str,
    primary: list[tuple[str, float]],
    alternate: list[tuple[str, float]],
) -> tuple[str, float] | None:
    """Select a full-span title only when two Medium views extend Small's prefix."""
    original_key = _comparable_text(original)
    if len(original_key) < 2:
        return None
    accepted: list[tuple[float, int, str]] = []
    for text, score in primary:
        key = _comparable_text(text)
        if score < 0.90 or len(key) < len(original_key) + 3 or not key.startswith(original_key):
            continue
        matching_scores = [
            alternate_score
            for alternate_text, alternate_score in alternate
            if alternate_score >= 0.90 and _comparable_text(alternate_text) == key
        ]
        if matching_scores:
            accepted.append(
                (
                    min(score, max(matching_scores)),
                    len(key),
                    _normalize_certified_batch_title(text),
                )
            )
    if not accepted:
        return None
    score, _, text = max(accepted, key=lambda item: (item[0], item[1], item[2]))
    return text, score


def _recover_certified_merged_title_text(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    spans: list[dict[str, Any]],
    ocr_engine: Any,
) -> list[float]:
    """Re-read a visibly truncated certified title using its full physical span."""
    if (
        not grid
        or confidence_grid is None
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or not callable(getattr(ocr_engine, "text_rec", None))
        or not callable(getattr(ocr_engine, "server_text_rec", None))
    ):
        return []
    title = next(
        (
            span
            for span in spans
            if span.get("role") == "title"
            and int(span.get("row", -1)) == 0
            and int(span.get("column", -1)) == 0
            and int(span.get("column_span", 1)) == len(grid[0])
        ),
        None,
    )
    original = str(grid[0][0]).strip()
    if title is None or not (2 <= len(_comparable_text(original)) <= 8):
        return []
    height, width = image.shape[:2]
    left = max(0, int(columns[0]) + 2)
    right = min(width, int(columns[-1]) - 2)
    top = max(0, int(rows[0]) + 2)
    bottom = min(height, int(rows[1]) - 2)
    crop = image[top:bottom, left:right]
    tight = _tight_text_crop(crop)
    if tight.size == 0:
        return []
    views = [
        tight,
        cv2.resize(tight, None, fx=2.0, fy=2.0, interpolation=cv2.INTER_LANCZOS4),
        cv2.resize(tight, None, fx=3.2, fy=3.2, interpolation=cv2.INTER_LANCZOS4),
    ]
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    primary_output = ocr_engine.text_rec(TextRecInput(img=views))
    alternate_output = ocr_engine.server_text_rec(TextRecInput(img=views))
    _release_recognition_images(primary_output)
    _release_recognition_images(alternate_output)
    primary = [
        (str(text), float(score))
        for text, score in zip(primary_output.txts, primary_output.scores)
    ]
    alternate = [
        (str(text), float(score))
        for text, score in zip(alternate_output.txts, alternate_output.scores)
    ]
    selected = _select_extended_title_candidate(original, primary, alternate)
    if selected is None:
        confidence_grid[0][0] = min(float(confidence_grid[0][0]), 0.77)
        return [score for _, score in primary + alternate]
    text, score = selected
    grid[0][0] = text
    confidence_grid[0][0] = score
    return [score for _, score in primary + alternate]


def _recover_certified_page_header_spans(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    page_text_evidence: list[tuple[str, float, float, float]],
) -> list[dict[str, Any]]:
    """Use page text and missing internal rules to rebuild title/group anchors."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count < 7
        or column_count < 4
        or len(columns) != column_count + 1
        or len(rows) != row_count + 1
        or any(len(row) != column_count for row in grid)
        or (
            confidence_grid is not None
            and (
                len(confidence_grid) != row_count
                or any(len(row) != column_count for row in confidence_grid)
            )
        )
    ):
        return []
    _, vertical, _ = pipeline._grid_maps(image)

    def supported_boundaries(row_index: int) -> list[int]:
        top = max(0, int(rows[row_index]))
        bottom = min(vertical.shape[0], int(rows[row_index + 1]))
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        result = [0]
        for index, boundary in enumerate(columns[1:-1], start=1):
            band = vertical[
                band_top:band_bottom,
                max(0, int(boundary) - 3) : min(
                    vertical.shape[1], int(boundary) + 4
                ),
            ]
            support = (
                float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            )
            if support >= 0.35:
                result.append(index)
        result.append(column_count)
        return result

    detail_row = -1
    detail_candidates: list[tuple[int, float]] = []
    for row_index in range(1, min(4, row_count)):
        detail_values = [str(value).strip() for value in grid[row_index]]
        textual_detail_headers = sum(
            bool(value) and not re.fullmatch(r"[+\-]?\d+(?:\.\d+)?", value)
            for value in detail_values
        )
        if (
            sum(bool(value) for value in detail_values) >= column_count - 1
            and textual_detail_headers >= column_count - 1
        ):
            divider_ratio = (
                len(supported_boundaries(row_index)) - 2
            ) / float(max(1, column_count - 1))
            detail_candidates.append((row_index, divider_ratio))
    if detail_candidates:
        detail_row, detail_divider_ratio = detail_candidates[0]
        if len(detail_candidates) > 1:
            following_row, following_divider_ratio = detail_candidates[1]
            if (
                detail_row == 2
                and following_row == 3
                and detail_divider_ratio <= 0.70
                and following_divider_ratio >= 0.85
                and following_divider_ratio - detail_divider_ratio >= 0.25
            ):
                detail_row = following_row
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= column_count - 1
        for row in grid[detail_row + 1 :]
    ) if detail_row >= 0 else 0
    if detail_row < 0 or dense_body_rows < 4:
        return []

    def row_entries(row_index: int) -> list[tuple[str, float, float]]:
        return sorted(
            [
                (str(text).strip(), float(center_x), float(score))
                for text, center_x, center_y, score in page_text_evidence
                if str(text).strip()
                and float(score) >= 0.90
                and float(columns[0]) <= float(center_x) <= float(columns[-1])
                and float(rows[row_index])
                <= float(center_y)
                <= float(rows[row_index + 1])
            ],
            key=lambda item: item[1],
        )

    title_boundaries = supported_boundaries(0)
    title_entries = row_entries(0)
    title_text = "".join(entry[0] for entry in title_entries)
    split_batch_title = bool(
        2 <= len(title_entries) <= 4
        and (
            re.fullmatch(
                r"[\u4e00-\u9fff]{3,12}\s*[-—一]\s*\d{4}-\d{2}\s*批次",
                title_text,
            )
            or re.fullmatch(
                r"[\u4e00-\u9fff]{3,20}\s*20\d{2}(?:年\d{1,2}月|[-/.]\d{1,2}月?)",
                title_text,
            )
        )
    )
    group_boundaries = supported_boundaries(1)
    group_entries = [
        entry for entry in row_entries(1) if not re.search(r"\d", entry[0])
    ]
    title_supported = bool(
        title_boundaries == [0, column_count]
        and
        (len(title_entries) == 1 or split_batch_title)
        and len(title_text) >= 3
    )
    if not title_supported:
        return []
    group_supported = bool(
        detail_row > 1
        and 2 <= len(group_entries) <= max(2, column_count // 2)
        and len(group_boundaries) == len(group_entries) + 1
        and all(
            float(columns[start]) <= center_x <= float(columns[end])
            for (_, center_x, _), start, end in zip(
                group_entries,
                group_boundaries,
                group_boundaries[1:],
            )
        )
    )

    rebuilt = [[str(value) for value in row] for row in grid]
    rebuilt_confidence = (
        [[float(value) for value in row] for row in confidence_grid]
        if confidence_grid is not None
        else None
    )
    rebuilt[0] = [""] * column_count
    rebuilt[0][0] = _normalize_certified_batch_title(title_text)
    if rebuilt_confidence is not None:
        rebuilt_confidence[0] = [0.0] * column_count
        rebuilt_confidence[0][0] = min(entry[2] for entry in title_entries)
    spans = [
        {
            "row": 0,
            "column": 0,
            "row_span": 1,
            "column_span": column_count,
            "role": "title",
        }
    ]
    if not group_supported:
        grid[:] = rebuilt
        if confidence_grid is not None and rebuilt_confidence is not None:
            confidence_grid[:] = rebuilt_confidence
        return spans
    rebuilt[1] = [""] * column_count
    if rebuilt_confidence is not None:
        rebuilt_confidence[1] = [0.0] * column_count
    for (text, _, score), start, end in zip(
        group_entries,
        group_boundaries,
        group_boundaries[1:],
    ):
        rebuilt[1][start] = text
        if rebuilt_confidence is not None:
            rebuilt_confidence[1][start] = score
        if end - start > 1:
            spans.append(
                {
                    "row": 1,
                    "column": start,
                    "row_span": 1,
                    "column_span": end - start,
                    "role": "group_header",
                }
            )
    grid[:] = rebuilt
    if confidence_grid is not None and rebuilt_confidence is not None:
        confidence_grid[:] = rebuilt_confidence
    return spans


def _recover_certified_physical_group_header_spans(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
    page_text_evidence: list[tuple[str, float, float, float]],
    spans: list[dict[str, Any]],
    *,
    ocr_engine: Any | None = None,
) -> list[dict[str, Any]]:
    """Anchor short merged header rows only to continuous physical dividers."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count < 7
        or column_count < 4
        or len(columns) != column_count + 1
        or len(rows) != row_count + 1
        or any(len(row) != column_count for row in grid)
    ):
        return spans
    title_rows = {
        int(span.get("row", -1))
        for span in spans
        if span.get("role") == "title"
    }
    repeated_title_before_dense_header = bool(
        0 in title_rows
        and 1 in title_rows
        and len(grid) >= 3
        and sum(bool(str(value).strip()) for value in grid[1]) == 1
        and sum(bool(str(value).strip()) for value in grid[2]) >= column_count - 1
    )
    first_group_row = (
        1
        if repeated_title_before_dense_header
        else max(title_rows) + 1
        if title_rows
        else 0
    )
    detail_row = next(
        (
            row
            for row in range(first_group_row + 1, min(4, row_count))
            if sum(bool(str(value).strip()) for value in grid[row])
            >= column_count - 1
        ),
        -1,
    )
    if detail_row < 1:
        return spans

    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    edge_x = np.abs(cv2.Sobel(gray, cv2.CV_32F, 1, 0, ksize=3))

    def supported_internal_divider_ratio(row_index: int) -> float:
        top = max(0, int(rows[row_index]))
        bottom = min(edge_x.shape[0], int(rows[row_index + 1]))
        inset = max(2, int(round((bottom - top) * 0.18)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        header_band = edge_x[band_top:band_bottom]
        if not header_band.size:
            return 0.0
        coverage = np.mean(header_band >= 80.0, axis=0)
        supported_pixels = np.flatnonzero(coverage >= 0.90).astype(int).tolist()
        line_groups: list[list[int]] = []
        for position in supported_pixels:
            if not line_groups or position > line_groups[-1][-1] + 2:
                line_groups.append([])
            line_groups[-1].append(position)
        line_centers = [int(round(float(np.median(group)))) for group in line_groups]
        typical_column_width = float(np.median(np.diff(columns)))
        maximum_alignment_error = max(6.0, typical_column_width * 0.08)
        supported = sum(
            any(abs(float(columns[index]) - center) <= maximum_alignment_error for center in line_centers)
            for index in range(1, column_count)
        )
        return supported / max(1, column_count - 1)

    following_row = detail_row + 1
    semantic_detail_headers = sum(
        bool(_header_semantic_labels(str(value).strip()))
        or str(value).strip() in _COMMON_HEADER_LABELS
        for value in grid[detail_row]
        if str(value).strip()
    )
    if (
        following_row < min(4, row_count)
        and sum(bool(str(value).strip()) for value in grid[following_row])
        >= column_count - 1
        and semantic_detail_headers < 3
    ):
        current_divider_ratio = supported_internal_divider_ratio(detail_row)
        following_divider_ratio = supported_internal_divider_ratio(following_row)
        if (
            current_divider_ratio <= 0.70
            and following_divider_ratio >= 0.85
            and following_divider_ratio - current_divider_ratio >= 0.25
        ):
            detail_row = following_row
    dense_body_rows = sum(
        sum(bool(str(value).strip()) for value in row) >= column_count - 1
        for row in grid[detail_row + 1 :]
    )
    if dense_body_rows < 4:
        return spans

    common_labels = (
        "基础信息",
        "基本信息",
        "目标与测量",
        "数量与金额",
        "过程记录",
        "质量判定",
        "状态判定",
        "追溯信息",
        "本期",
        "计划",
        "累计",
        "上限",
        "实际",
        "下限",
    )

    def canonical_fragment_text(fragments: list[tuple[str, float, float]]) -> str:
        retained: list[tuple[str, float, float]] = []
        for fragment in sorted(fragments, key=lambda item: item[1]):
            key = _comparable_text(fragment[0])
            if not key:
                continue
            if any(key in _comparable_text(value[0]) for value in retained):
                continue
            retained = [
                value
                for value in retained
                if _comparable_text(value[0]) not in key
            ]
            retained.append(fragment)
        combined = "".join(value[0].strip() for value in retained)
        combined_key = _comparable_text(combined)
        matches = [
            label
            for label in common_labels
            if _text_edit_distance(combined_key, _comparable_text(label)) <= 1
        ]
        return matches[0] if len(matches) == 1 else combined

    def reread_missing_interval(
        row_index: int,
        start: int,
        end: int,
    ) -> tuple[str, float] | None:
        medium = getattr(ocr_engine, "text_rec", None)
        alternate = getattr(ocr_engine, "server_text_rec", None)
        if not callable(medium) or not callable(alternate):
            return None
        top = max(0, int(rows[row_index]) + 2)
        bottom = min(image.shape[0], int(rows[row_index + 1]) - 2)
        left = max(0, int(columns[start]) + 3)
        right = min(image.shape[1], int(columns[end]) - 3)
        crop = image[top:bottom, left:right]
        tight = _tight_text_crop(crop) if crop.size else crop
        if tight.size == 0:
            return None
        if tight.ndim == 2:
            gray = tight
            color = cv2.cvtColor(tight, cv2.COLOR_GRAY2BGR)
        else:
            color = tight
            gray = cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY)
        clahe = cv2.createCLAHE(clipLimit=2.2, tileGridSize=(8, 4)).apply(gray)
        binary = cv2.threshold(
            clahe, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU
        )[1]
        views = [
            color,
            cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR),
            cv2.cvtColor(clahe, cv2.COLOR_GRAY2BGR),
            cv2.cvtColor(binary, cv2.COLOR_GRAY2BGR),
        ]
        from rapidocr.ch_ppocr_rec.typings import TextRecInput

        model_votes: list[tuple[str, float]] = []
        for recognizer in (medium, alternate):
            output = recognizer(TextRecInput(img=views))
            _release_recognition_images(output)
            if len(output.txts) != 4 or len(output.scores) != 4:
                return None
            votes: dict[str, list[float]] = {}
            for text, score in zip(output.txts, output.scores):
                value = str(text).strip()
                numeric_score = float(score)
                if (
                    numeric_score >= 0.88
                    and re.fullmatch(r"[A-Za-z\u3400-\u9fff][A-Za-z\u3400-\u9fff _-]{1,15}", value)
                    and not re.search(r"\d", value)
                ):
                    votes.setdefault(value, []).append(numeric_score)
            proven = [
                (text, min(scores))
                for text, scores in votes.items()
                if len(scores) >= 3
            ]
            if len(proven) != 1:
                return None
            model_votes.append(proven[0])
        if len(model_votes) != 2 or model_votes[0][0] != model_votes[1][0]:
            return None
        return model_votes[0][0], min(model_votes[0][1], model_votes[1][1], 0.77)

    rebuilt_spans = list(spans)
    for row_index in range(first_group_row, detail_row):
        existing_group_spans = [
            span
            for span in rebuilt_spans
            if int(span.get("row", -1)) == row_index
            and span.get("role") == "group_header"
        ]
        if existing_group_spans:
            covered_columns = {
                column
                for span in existing_group_spans
                for column in range(
                    int(span.get("column", -1)),
                    int(span.get("column", -1))
                    + int(span.get("column_span", 1)),
                )
            }
            uncovered_columns = [
                column
                for column in range(column_count)
                if column not in covered_columns
            ]
            isolated_populated_columns = all(
                str(grid[row_index][column]).strip()
                and (column - 1 not in uncovered_columns)
                and (column + 1 not in uncovered_columns)
                for column in uncovered_columns
            )
            if not uncovered_columns or isolated_populated_columns:
                continue
            rebuilt_spans = [
                span
                for span in rebuilt_spans
                if not (
                    int(span.get("row", -1)) == row_index
                    and span.get("role") == "group_header"
                )
            ]
        top = max(0, int(rows[row_index]))
        bottom = min(edge_x.shape[0], int(rows[row_index + 1]))
        inset = max(2, int(round((bottom - top) * 0.18)))
        band_top = min(bottom, top + inset)
        band_bottom = max(band_top + 1, bottom - inset)
        physical_boundaries = [0]
        header_band = edge_x[band_top:band_bottom]
        coverage = (
            np.mean(header_band >= 80.0, axis=0)
            if header_band.size
            else np.zeros(edge_x.shape[1], dtype=float)
        )
        supported_pixels = np.flatnonzero(coverage >= 0.90).astype(int).tolist()
        line_groups: list[list[int]] = []
        for position in supported_pixels:
            if not line_groups or position > line_groups[-1][-1] + 2:
                line_groups.append([])
            line_groups[-1].append(position)
        line_centers = [int(round(float(np.median(group)))) for group in line_groups]
        typical_column_width = float(np.median(np.diff(columns)))
        maximum_alignment_error = max(8.0, typical_column_width * 0.25)
        aligned_boundary_indices = {
            boundary_index
            for center in line_centers
            for boundary_index in [
                min(
                    range(1, column_count),
                    key=lambda index: abs(float(columns[index]) - center),
                )
            ]
            if abs(float(columns[boundary_index]) - center)
            <= maximum_alignment_error
        }
        physical_boundaries.extend(sorted(aligned_boundary_indices))
        physical_boundaries.append(column_count)
        raw_row_evidence = [
            (
                str(text).strip(),
                float(center_x),
                float(center_y),
                float(score),
            )
            for text, center_x, center_y, score in page_text_evidence
            if str(text).strip()
            and float(score) >= 0.70
            and not re.search(r"\d", str(text))
            and float(rows[row_index]) <= float(center_y) <= float(rows[row_index + 1])
            and float(columns[0]) <= float(center_x) <= float(columns[-1])
        ]
        top_ruler_limit = float(rows[row_index]) + (
            float(rows[row_index + 1]) - float(rows[row_index])
        ) * 0.30
        spreadsheet_ruler_entries = [
            entry
            for entry in raw_row_evidence
            if re.fullmatch(r"[A-Z]{1,2}", entry[0])
            and entry[2] <= top_ruler_limit
        ]

        def spreadsheet_column_number(label: str) -> int:
            number = 0
            for character in label:
                number = number * 26 + ord(character) - ord("A") + 1
            return number

        ruler_numbers = [
            spreadsheet_column_number(entry[0])
            for entry in spreadsheet_ruler_entries
        ]
        spreadsheet_ruler_detected = bool(
            len(spreadsheet_ruler_entries) >= 3
            and all(
                right == left + 1
                for left, right in zip(ruler_numbers, ruler_numbers[1:])
            )
        )
        row_evidence = [
            (text, center_x, score)
            for text, center_x, center_y, score in raw_row_evidence
            if not spreadsheet_ruler_detected
            or (text, center_x, center_y, score)
            not in spreadsheet_ruler_entries
        ]
        nested_labels = {"本期", "计划", "累计", "上限", "实际", "下限"}
        ordered_nested = [
            str(value).strip()
            for value in grid[row_index]
            if str(value).strip() in nested_labels
        ]
        paired_boundaries = list(range(0, column_count, 2)) + [column_count]
        if (
            row_index == detail_row - 1
            and len(ordered_nested) == len(paired_boundaries) - 1
            and all(
                end - start in (1, 2)
                for start, end in zip(paired_boundaries, paired_boundaries[1:])
            )
        ):
            physical_boundaries = paired_boundaries
        ordered_row_labels = [
            str(value).strip()
            for value in grid[row_index]
            if str(value).strip()
        ]
        ordered_label_keys = [_comparable_text(value) for value in ordered_row_labels]
        partition_labels = [
            value
            for index, value in enumerate(ordered_row_labels)
            if sum(
                bool(other_key)
                and other_index != index
                and other_key in ordered_label_keys[index]
                for other_index, other_key in enumerate(ordered_label_keys)
            )
            < 2
        ]
        if spreadsheet_ruler_detected:
            exact_evidence_labels = [
                text
                for text, _, _ in row_evidence
                if any(
                    _comparable_text(text) == _comparable_text(label)
                    for label in common_labels
                )
            ]
            if (
                2 <= len(exact_evidence_labels)
                <= int(math.ceil(column_count / 2.0)) + 1
            ):
                partition_labels = exact_evidence_labels
        if (
            len(physical_boundaries) - 1 != len(partition_labels)
            and 2 <= len(partition_labels) <= int(math.ceil(column_count / 2.0)) + 1
            and all(
                any(
                    _comparable_text(value) == _comparable_text(label)
                    for label in common_labels
                )
                for value in partition_labels
            )
        ):
            center_candidates: list[float] = []
            for value in partition_labels:
                matching = [
                    center_x
                    for text, center_x, _ in row_evidence
                    if _comparable_text(text) == _comparable_text(value)
                ]
                if len(matching) != 1:
                    center_candidates = []
                    break
                center_candidates.append(float(matching[0]))
            if center_candidates:
                scored_partitions: list[tuple[float, float, list[int]]] = []
                for selected in itertools.combinations(
                    range(1, column_count), len(center_candidates) - 1
                ):
                    candidate = [0, *selected, column_count]
                    widths = [
                        end - start
                        for start, end in zip(candidate, candidate[1:])
                    ]
                    if any(width < 2 for width in widths[:-1]) or widths[-1] < 1:
                        continue
                    errors: list[float] = []
                    valid = True
                    for center_x, start, end in zip(
                        center_candidates, candidate, candidate[1:]
                    ):
                        left = float(columns[start])
                        right = float(columns[end])
                        if not left <= center_x <= right:
                            valid = False
                            break
                        errors.append(
                            abs(center_x - (left + right) * 0.5)
                            / max(1.0, right - left)
                        )
                    if valid:
                        scored_partitions.append(
                            (sum(errors), max(errors, default=1.0), candidate)
                        )
                scored_partitions.sort(key=lambda item: (item[0], item[1], item[2]))
                if scored_partitions:
                    best_total, best_max, best = scored_partitions[0]
                    runner_up = (
                        scored_partitions[1][0]
                        if len(scored_partitions) > 1
                        else float("inf")
                    )
                    if best_max <= 0.18 and runner_up - best_total >= 0.03:
                        physical_boundaries = best
        removable_boundaries: set[int] = set()
        for boundary_index in range(1, len(physical_boundaries) - 1):
            previous = physical_boundaries[boundary_index - 1]
            boundary = physical_boundaries[boundary_index]
            following = physical_boundaries[boundary_index + 1]
            if boundary - previous != 1 or following - boundary != 1:
                continue
            left_text = str(grid[row_index][previous]).strip()
            right_text = str(grid[row_index][boundary]).strip()
            combined_key = _comparable_text(left_text + right_text)
            matching_labels = [
                label
                for label in common_labels
                if _text_edit_distance(
                    combined_key,
                    _comparable_text(label),
                )
                <= 1
            ]
            if len(matching_labels) != 1:
                continue
            canonical_label = matching_labels[0]
            if any(
                _comparable_text(text) == _comparable_text(canonical_label)
                and float(columns[previous])
                <= center_x
                <= float(columns[following])
                for text, center_x, _ in row_evidence
            ):
                removable_boundaries.add(boundary)
        if removable_boundaries:
            physical_boundaries = [
                boundary
                for boundary in physical_boundaries
                if boundary not in removable_boundaries
            ]
        interval_count = len(physical_boundaries) - 1
        if not 2 <= interval_count <= int(math.ceil(column_count / 2.0)) + 1:
            return spans
        unsafe_physical_intervals = [
            {
                "row": row_index,
                "column": start,
                "row_span": 1,
                "column_span": end - start,
            }
            for start, end in zip(
                physical_boundaries, physical_boundaries[1:]
            )
            if end - start > 1
            and _span_has_visible_subcell_ink(
                image,
                rows,
                columns,
                {
                    "row": row_index,
                    "column": start,
                    "row_span": 1,
                    "column_span": end - start,
                },
            )
        ]
        if unsafe_physical_intervals:
            # 从属格已有字形时，整页 OCR 的合并结果不可信；保留原网格，
            # 交给末端的逐格锚定流程用独立模型重读。
            return spans
        ordered_grid_fragments = [
            (
                str(value).strip(),
                float(confidence_grid[row_index][column])
                if confidence_grid is not None
                else 0.77,
            )
            for column, value in enumerate(grid[row_index])
            if str(value).strip()
        ]
        ordered_common_labels = bool(
            len(ordered_grid_fragments) == interval_count
            and all(
                any(
                    _comparable_text(value) == _comparable_text(label)
                    for label in common_labels
                )
                for value, _ in ordered_grid_fragments
            )
        )
        recovered: list[tuple[str, float]] = []
        for interval_index, (start, end) in enumerate(
            zip(physical_boundaries, physical_boundaries[1:])
        ):
            if ordered_common_labels:
                recovered.append(ordered_grid_fragments[interval_index])
                continue
            fragments = [
                entry
                for entry in row_evidence
                if float(columns[start]) <= entry[1] <= float(columns[end])
            ]
            if not fragments:
                reread = reread_missing_interval(row_index, start, end)
                if reread is not None:
                    recovered.append(reread)
                    continue
                fragments = [
                    (
                        str(grid[row_index][column]).strip(),
                        (float(columns[column]) + float(columns[column + 1])) * 0.5,
                        float(confidence_grid[row_index][column])
                        if confidence_grid is not None
                        else 0.77,
                    )
                    for column in range(start, end)
                    if str(grid[row_index][column]).strip()
                    and not re.search(r"\d", str(grid[row_index][column]))
                ]
            text = canonical_fragment_text(fragments)
            if not text:
                return spans
            recovered.append(
                (text, min((score for _, _, score in fragments), default=0.77))
            )

        rebuilt_spans = [
            span
            for span in rebuilt_spans
            if int(span.get("row", -1)) != row_index
        ]
        grid[row_index] = [""] * column_count
        if confidence_grid is not None:
            confidence_grid[row_index] = [0.0] * column_count
        for (start, end), (text, score) in zip(
            zip(physical_boundaries, physical_boundaries[1:]), recovered
        ):
            grid[row_index][start] = text
            if confidence_grid is not None:
                confidence_grid[row_index][start] = min(float(score), 0.77)
            if end - start > 1:
                rebuilt_spans.append(
                    {
                        "row": row_index,
                        "column": start,
                        "row_span": 1,
                        "column_span": end - start,
                        "role": "group_header",
                    }
                )
    return rebuilt_spans


def _normalize_visible_ipv4_spacing(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
) -> set[tuple[int, int]]:
    """Remove OCR-inserted spaces only from a valid IPv4-address column."""
    if not grid or not grid[0] or _grid_has_ragged_rows(grid) or len(confidence_grid) != len(grid):
        return set()
    header_row = max(
        range(min(3, len(grid))),
        key=lambda row: sum(bool(str(value).strip()) for value in grid[row]),
    )
    ip_columns = {
        column
        for column, value in enumerate(grid[header_row])
        if "IP地址" in str(value) or str(value).strip().casefold() == "ip"
    }
    restored: set[tuple[int, int]] = set()
    for row in range(header_row + 1, len(grid)):
        for column in ip_columns:
            original = str(grid[row][column]).strip()
            compact = re.sub(r"\s+", "", original)
            if compact == original or re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", compact) is None:
                continue
            octets = [int(value) for value in compact.split(".")]
            if any(value > 255 for value in octets):
                continue
            grid[row][column] = compact
            confidence_grid[row][column] = min(
                float(confidence_grid[row][column]), 0.77
            )
            restored.add((row, column))
    return restored


def _recover_unique_blank_body_page_evidence(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    page_text_evidence: list[tuple[str, float, float, float]],
    *,
    first_body_row: int = 2,
) -> list[float]:
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count != len(rows) - 1
        or column_count != len(columns) - 1
        or len(confidence_grid) != row_count
        or any(len(row) != column_count for row in grid + confidence_grid)
    ):
        return []
    candidates: dict[tuple[int, int], list[tuple[str, float]]] = {}
    for text, center_x, center_y, score in page_text_evidence:
        value = str(text).strip()
        if not value or float(score) < 0.99:
            continue
        row = next(
            (
                index
                for index, (top, bottom) in enumerate(zip(rows, rows[1:]))
                if float(top) <= float(center_y) <= float(bottom)
            ),
            -1,
        )
        column = next(
            (
                index
                for index, (left, right) in enumerate(zip(columns, columns[1:]))
                if float(left) <= float(center_x) <= float(right)
            ),
            -1,
        )
        if row < first_body_row or column < 0 or str(grid[row][column]).strip():
            continue
        left, right = float(columns[column]), float(columns[column + 1])
        top, bottom = float(rows[row]), float(rows[row + 1])
        if (
            min(float(center_x) - left, right - float(center_x))
            < max(2.0, (right - left) * 0.08)
            or min(float(center_y) - top, bottom - float(center_y))
            < max(2.0, (bottom - top) * 0.08)
        ):
            continue
        candidates.setdefault((row, column), []).append((value, float(score)))
    recovered_scores: list[float] = []
    for (row, column), values in candidates.items():
        if len(values) != 1:
            continue
        value, score = values[0]
        grid[row][column] = value
        confidence_grid[row][column] = 0.77
        recovered_scores.append(score)
    return recovered_scores


def _normalize_certified_batch_title(value: Any) -> str:
    """规范已认证批次标题中可见分隔符两侧的展示空格。"""
    text = str(value).strip()
    match = re.fullmatch(
        r"(?P<label>[^—\r\n]{3,}?)\s*[—一-]\s*"
        r"(?P<period>\d{4}-\d{2})\s*(?P<suffix>批次)",
        text,
    )
    if not match:
        dated = re.fullmatch(
            r"(?P<label>[\u3400-\u9fffA-Za-z0-9][\u3400-\u9fffA-Za-z0-9 _-]{2,30}?)\s*"
            r"(?P<period>20\d{2}年\d{1,2}月)",
            text,
        )
        if dated:
            return f"{dated.group('label')}  {dated.group('period')}"
        return text
    return (
        f"{match.group('label').rstrip()} — "
        f"{match.group('period')} {match.group('suffix')}"
    )


def _recover_visible_batch_title_dash(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
) -> bool:
    """Recover an isolated printed title dash that page OCR reads as Chinese 一."""
    if (
        not grid
        or not grid[0]
        or len(confidence_grid) != len(grid)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or any(len(row) != len(grid[0]) for row in grid + confidence_grid)
        or any(str(value).strip() for value in grid[0][1:])
    ):
        return False
    current = str(grid[0][0]).strip()
    match = re.fullmatch(
        r"(?P<label>[\u4e00-\u9fff]{3,12})\s*[-一]\s*"
        r"(?P<period>\d{4}-\d{2})\s*(?P<suffix>批次)",
        current,
    )
    if not match:
        return False
    image_height, image_width = image.shape[:2]
    left = max(0, int(columns[0]))
    right = min(image_width, int(columns[-1]))
    top = max(0, int(rows[0]))
    bottom = min(image_height, int(rows[1]))
    crop = image[top:bottom, left:right]
    if crop.size == 0 or crop.shape[0] < 12:
        return False
    gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY) if crop.ndim == 3 else crop
    threshold = max(140.0, min(200.0, float(np.percentile(gray, 98)) - 20.0))
    mask = np.uint8(gray > threshold) * 255
    count, _, stats, _ = cv2.connectedComponentsWithStats(mask, 8)
    components = [
        tuple(int(value) for value in stats[index])
        for index in range(1, count)
        if int(stats[index, cv2.CC_STAT_AREA]) >= 3
        and int(stats[index, cv2.CC_STAT_LEFT]) > 0
        and int(stats[index, cv2.CC_STAT_LEFT])
        + int(stats[index, cv2.CC_STAT_WIDTH])
        < gray.shape[1] - 1
    ]
    if not components:
        return False
    components.sort(key=lambda item: item[0])
    ink_left = min(item[0] for item in components)
    ink_right = max(item[0] + item[2] for item in components)
    candidates = []
    for index, component in enumerate(components):
        x, y, width, height, _ = component
        if (
            width < max(8, int(round(gray.shape[0] * 0.35)))
            or height > max(3, int(round(gray.shape[0] * 0.12)))
            or width < height * 4
            or index == 0
            or index + 1 >= len(components)
        ):
            continue
        previous_right = components[index - 1][0] + components[index - 1][2]
        next_left = components[index + 1][0]
        left_gap = x - previous_right
        right_gap = next_left - (x + width)
        relative_center = (x + width * 0.5 - ink_left) / max(
            1.0, float(ink_right - ink_left)
        )
        if (
            3 <= left_gap <= gray.shape[0]
            and 3 <= right_gap <= gray.shape[0]
            and 0.25 <= relative_center <= 0.60
            and gray.shape[0] * 0.35 <= y + height * 0.5 <= gray.shape[0] * 0.75
        ):
            candidates.append(component)
    if len(candidates) != 1:
        return False
    grid[0][0] = (
        f"{match.group('label')} — {match.group('period')} {match.group('suffix')}"
    )
    current_confidence = float(confidence_grid[0][0])
    confidence_grid[0][0] = (
        min(current_confidence, 0.77) if current_confidence != 0.0 else 0.77
    )
    return True


def _structure_certificate_matches(
    certificate: dict[str, Any],
    grid: list[list[str]],
    spans: list[dict[str, Any]],
) -> bool:
    rows, columns, _ = _grid_shape_and_content(grid)
    certified_spans = certificate.get("spans", [])
    if (
        not bool(certificate.get("verified", False))
        or rows != int(certificate.get("rows", -1))
        or columns != int(certificate.get("columns", -1))
        or any(len(row) != columns for row in grid)
        or spans != certified_spans
    ):
        return False
    column_boundaries = [int(value) for value in certificate.get("column_boundaries", [])]
    row_boundaries = [int(value) for value in certificate.get("row_boundaries", [])]
    row_offset = int(certificate.get("row_offset", 0))
    column_offset = int(certificate.get("column_offset", 0))
    if (
        len(row_boundaries) - 1 - row_offset != rows
        or len(column_boundaries) - 1 - column_offset != columns
    ):
        return False
    boundary_payload = json.dumps(
        {
            "source": str(certificate.get("source", "")),
            "source_shape": certificate.get("source_shape", []),
            "columns": column_boundaries,
            "rows": row_boundaries,
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    if hashlib.blake2b(boundary_payload, digest_size=16).hexdigest() != str(
        certificate.get("geometry_hash", "")
    ):
        return False
    row_columns = certificate.get("row_column_boundaries")
    if row_columns is not None:
        width = int((certificate.get("source_shape") or [0, 0])[1])
        if (
            not isinstance(row_columns, list)
            or len(row_columns) != rows
            or any(
                not isinstance(boundaries, list)
                or len(boundaries) != columns + 1
                or boundaries[0] < 0 or boundaries[-1] > width
                or any(right <= left for left, right in zip(boundaries, boundaries[1:]))
                for boundaries in row_columns
            )
            or hashlib.blake2b(
                json.dumps(row_columns, separators=(",", ":")).encode("utf-8"),
                digest_size=16,
            ).hexdigest() != certificate.get("row_column_hash")
        ):
            return False
    occupied: set[tuple[int, int]] = set()
    for span in spans:
        if not isinstance(span, dict):
            return False
        values = [
            span.get("row"),
            span.get("column"),
            span.get("row_span", 1),
            span.get("column_span", 1),
        ]
        if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
            return False
        span_row, span_column, row_span, column_span = values
        if (
            span_row < 0
            or span_column < 0
            or row_span < 1
            or column_span < 1
            or span_row + row_span > rows
            or span_column + column_span > columns
        ):
            return False
        for covered_row in range(span_row, span_row + row_span):
            for covered_column in range(span_column, span_column + column_span):
                location = (covered_row, covered_column)
                if location in occupied:
                    return False
                occupied.add(location)
                if location != (span_row, span_column) and str(
                    grid[covered_row][covered_column]
                ).strip():
                    return False
    return True


def _review_only_certificate_spans_match_physical_grid(
    certificate: dict[str, Any],
    grid: list[list[str]],
    spans: list[dict[str, Any]],
) -> bool:
    """Keep physical header spans when only the certificate safety flag was lowered."""
    if not spans:
        return False
    physical_certificate = copy.deepcopy(certificate)
    physical_certificate["verified"] = True
    return _structure_certificate_matches(physical_certificate, grid, spans)


def _spans_hide_non_anchor_text(
    grid: list[list[str]],
    spans: list[dict[str, Any]],
) -> bool:
    """Reject a merge whenever it would conceal visible subordinate content."""
    for span in spans:
        anchor_row = int(span.get("row", -1))
        anchor_column = int(span.get("column", -1))
        row_span = max(1, int(span.get("row_span", 1)))
        column_span = max(1, int(span.get("column_span", 1)))
        if (
            anchor_row < 0
            or anchor_column < 0
            or anchor_row + row_span > len(grid)
            or any(anchor_column + column_span > len(row) for row in grid)
        ):
            return True
        for row in range(anchor_row, anchor_row + row_span):
            for column in range(anchor_column, anchor_column + column_span):
                if (row, column) == (anchor_row, anchor_column):
                    continue
                if str(grid[row][column]).strip():
                    return True
    return False


def _active_structure_certificate_boundaries(
    certificate: dict[str, Any],
    grid: list[list[str]],
) -> tuple[list[int], list[int]] | None:
    """Return the physical boundaries that still correspond to the visible grid."""
    if not grid or not grid[0]:
        return None
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return None
    columns = [int(value) for value in certificate.get("column_boundaries", [])]
    rows = [int(value) for value in certificate.get("row_boundaries", [])]
    row_offset = int(certificate.get("row_offset", 0))
    column_offset = int(certificate.get("column_offset", 0))
    if row_offset < 0 or column_offset < 0:
        return None
    columns = columns[column_offset:]
    rows = rows[row_offset:]
    if (
        len(columns) != column_count + 1
        or len(rows) != len(grid) + 1
        or any(right <= left for left, right in zip(columns, columns[1:]))
        or any(bottom <= top for top, bottom in zip(rows, rows[1:]))
    ):
        return None
    return columns, rows


def _band_looks_like_window_chrome(row: list[str]) -> bool:
    """判断一行带是否只是窗口外壳（功能区、公式栏残留），而不是表格数据行。

    Excel 截图里列标尺之上还压着功能区标签行（文件/开始/插入/页面布局/公式/
    数据/审阅/视图）。旧逻辑只在第 0 行（或全空的第 1 行）上找列标尺，功能区
    在最上面时标尺行永远落在搜索范围之外，于是整条功能区被当成表格数据交付。
    外壳行必须稀疏且不含纯数字单元格，真实的数据行/标题行都不会同时满足。
    """
    values = [str(value).strip() for value in row]
    nonempty = [value for value in values if value]
    if len(nonempty) > max(2, int(math.ceil(len(values) * 0.40))):
        return False
    return not any(re.fullmatch(r"\d+(?:\.\d+)?", value) for value in nonempty)


def _band_looks_like_column_ruler(row: list[str]) -> bool:
    """一行带是否整行都是 Excel 列标尺字母（A、B、C…）。"""
    nonempty = [str(value).strip() for value in row if str(value).strip()]
    return bool(len(nonempty) >= 2) and all(
        re.fullmatch(r"[A-Z]{1,3}", value) for value in nonempty
    )


def _spreadsheet_ruler_row_index(grid: list[list[str]]) -> int:
    """Locate the sheet column-ruler band, tolerating window chrome above it."""
    if len(grid) >= 5 and not any(str(value).strip() for value in grid[0]):
        return 1
    for candidate in range(1, min(4, len(grid) - 1)):
        if (
            all(
                _band_looks_like_window_chrome(grid[index])
                for index in range(candidate)
            )
            and _band_looks_like_column_ruler(grid[candidate])
        ):
            return candidate
    return 0


def _strip_spreadsheet_ui_headers(
    grid: list[list[str]],
    confidence_grid: list[list[float]] | None,
) -> tuple[list[list[str]], list[list[float]] | None]:
    """Remove Excel/WPS row and column rulers when a screenshot includes them."""
    if len(grid) < 4 or not grid[0] or any(not row for row in grid):
        return grid, confidence_grid
    # 摄像头透视后，Excel列标尺上方可能被物理网格提取成一条全空的
    # 窄框。只有下一行仍满足严格A..Z位置证据时才会连同标尺移除。
    # 窗口功能区也可能压在标尺上方；只有外壳行全部稀疏、且下一行整行都是
    # 列标尺字母时，才把搜索窗口下移，避免误删真实标题行。
    ruler_row_index = _spreadsheet_ruler_row_index(grid)
    top = [str(value).strip() for value in grid[ruler_row_index]]
    def column_ruler_tokens(value: str) -> list[str]:
        normalized = " ".join(value.upper().split())
        ruler_confusions = {"1": "I", "一": "I", "8": "B"}
        if normalized in ruler_confusions:
            # Narrow I and rounded B are common camera-OCR confusions. They are
            # admitted only inside the full sequential/positioned A..Z proof.
            normalized = ruler_confusions[normalized]
        if not normalized or re.sub(r"[A-Z\s]+", "", normalized):
            return []
        return re.findall(r"[A-Z]{1,3}", normalized)

    def embedded_ruler_title(value: str) -> tuple[list[str], str] | None:
        match = re.fullmatch(r"([A-Z]{1,3})\s+(.+)", str(value).strip(), re.IGNORECASE)
        if match is None:
            return None
        label = match.group(1).upper()
        remainder = match.group(2).strip()
        if not re.search(r"[\u4e00-\u9fff]", remainder) or not re.search(
            r"20\d{2}[-/.年]\d{1,2}|批次",
            remainder,
        ):
            return None
        return [label], remainder

    def column_number(label: str) -> int:
        number = 0
        for character in label:
            number = number * 26 + (ord(character) - ord("A") + 1)
        return number

    top_tokens = [column_ruler_tokens(value) for value in top]
    for column_index, tokens in enumerate(top_tokens):
        if len(tokens) != 1:
            continue
        token = tokens[0]
        if not (
            2 <= len(token) <= 3
            and all(
                ord(right) == ord(left) + 1
                for left, right in zip(token, token[1:])
            )
        ):
            continue
        neighbour_numbers = [
            column_number(candidate[0])
            for candidate in top_tokens[column_index + 1 :]
            if len(candidate) == 1
        ]
        previous_numbers = [
            column_number(candidate[-1])
            for candidate in top_tokens[:column_index]
            if candidate
        ]
        trailing_sequence_supported = bool(
            previous_numbers
            and 1 <= column_number(token[0]) - previous_numbers[-1] <= 2
        )
        fused_corner_sequence = bool(
            column_index == 0
            and token.startswith("A")
            and len(token) == len(top) - 1
            and sum(bool(candidate) for candidate in top_tokens) == 1
        )
        if (
            neighbour_numbers
            and neighbour_numbers[0] == column_number(token[-1]) + 1
        ) or trailing_sequence_supported or fused_corner_sequence:
            top_tokens[column_index] = list(token)
    embedded_titles: list[tuple[int, str]] = []
    for column_index, value in enumerate(top):
        if top_tokens[column_index] or not value:
            continue
        embedded = embedded_ruler_title(value)
        if embedded is None:
            continue
        top_tokens[column_index] = embedded[0]
        embedded_titles.append((column_index, embedded[1]))
    nonempty_token_cells = [
        (column_index, tokens)
        for column_index, tokens in enumerate(top_tokens)
        if tokens
    ]
    column_labels = [
        token
        for _, tokens in nonempty_token_cells
        for token in tokens
    ]
    column_numbers = [column_number(label) for label in column_labels]
    sequential_columns = bool(
        column_numbers
        and all(
            right == left + 1
            for left, right in zip(column_numbers, column_numbers[1:])
        )
    )
    one_missing_column = bool(
        column_numbers
        and column_numbers[0] == 1
        and all(
            1 <= right - left <= 2
            for left, right in zip(column_numbers, column_numbers[1:])
        )
        and sum(
            right - left - 1
            for left, right in zip(column_numbers, column_numbers[1:])
        )
        <= 1
    )
    positioned_columns = []
    for column_index, tokens in nonempty_token_cells:
        positioned_columns.extend(
            (column_index + token_offset, column_number(token))
            for token_offset, token in enumerate(tokens)
        )
    position_offset = (
        positioned_columns[0][1] - positioned_columns[0][0]
        if positioned_columns
        else 0
    )
    position_consistent = bool(
        positioned_columns
        and all(
            number - column_index == position_offset
            for column_index, number in positioned_columns
        )
    )
    only_ruler_text_or_blank = all(
        not value
        or bool(tokens)
        or value in {"0"}
        for value, tokens in zip(top, top_tokens)
    )
    fused_ruler_title = bool(len(embedded_titles) == 1 and one_missing_column)
    has_column_ruler = (
        len(column_labels) >= 3
        and only_ruler_text_or_blank
        and not fused_ruler_title
        and (sequential_columns or position_consistent or one_missing_column)
    )
    fused_corner_ruler = bool(
        has_column_ruler
        and top_tokens[0]
        and top_tokens[0][0] == "A"
        and len(top_tokens[0]) >= 2
    )
    row_start = ruler_row_index + 1 if has_column_ruler else 0
    row_labels = [str(row[0]).strip() for row in grid[row_start:]]
    checked_labels = row_labels[: min(8, len(row_labels))]
    numeric_ruler_cells = sum(
        bool(re.fullmatch(r"\d+(?:\s+\d+)*", value))
        for value in checked_labels
    )
    numeric_positions = [
        (index, int(value))
        for index, value in enumerate(checked_labels)
        if re.fullmatch(r"[0-9]+", value)
    ]
    row_number_offsets = {
        number - index for index, number in numeric_positions
    }
    has_row_ruler = bool(
        len(row_labels) >= 3
        and checked_labels
        and numeric_ruler_cells >= max(3, int(math.ceil(len(checked_labels) * 0.60)))
        and (
            not has_column_ruler
            or not top[0]
            or top[0] == "0"
            or fused_corner_ruler
        )
        and (
            has_column_ruler
            or (
                row_number_offsets == {1}
            )
        )
    )
    empty_row_ruler_gutter = bool(
        has_column_ruler
        and not top[0]
        and positioned_columns
        and positioned_columns[0] == (1, 1)
        and sum(
            bool(str(row[0]).strip())
            for row in grid[row_start : min(len(grid), row_start + 12)]
        )
        <= 1
    )
    if not has_column_ruler and not has_row_ruler:
        return grid, confidence_grid
    if not has_column_ruler and has_row_ruler:
        first_content = [str(value).strip() for value in grid[0][1:] if str(value).strip()]
        second_content = [str(value).strip() for value in grid[1][1:] if str(value).strip()]
        header_hints = (
            "序号", "编号", "名称", "项目", "日期", "时间", "单位",
            "标准", "示值", "修正", "误差", "温度", "湿度", "有效期",
            "信息", "测量", "记录", "判定", "追溯", "人员", "校准员",
            "复核员", "件数", "重量", "状态", "类型", "分类",
            "学号", "姓名", "班级", "课程", "任课教师", "教师", "星期",
        )
        first_header_hints = sum(
            any(hint in value for hint in header_hints)
            for value in first_content
        )
        second_header_hints = sum(
            any(hint in value for hint in header_hints)
            for value in second_content
        )
        direct_dense_header = bool(
            len(first_content) >= 4
            and first_header_hints >= max(2, int(math.ceil(len(first_content) * 0.25)))
            and len(second_content) >= max(2, len(first_content) // 2)
        )
        sparse_group_header = bool(
            2 <= len(first_content) <= max(6, (len(grid[0]) - 1) // 2)
            and first_header_hints >= 2
            and len(second_content) >= max(4, len(grid[0]) - 3)
            and second_header_hints >= 3
        )
        joined_first_content = " ".join(first_content)
        title_like_header = bool(
            len(first_content) <= 3
            and len(second_content) >= 2
            and re.search(r"20\d{2}[-/.年]\d{1,2}|批次", joined_first_content)
        )
        legacy_title_header = (
            len(first_content) <= 1 and len(second_content) >= 2
        ) or title_like_header
        if (
            not (
                legacy_title_header
                or direct_dense_header
                or sparse_group_header
                or fused_ruler_title
            )
        ):
            return grid, confidence_grid

    column_start = 1 if has_row_ruler or empty_row_ruler_gutter else 0
    trimmed_grid = [row[column_start:] for row in grid[row_start:]]
    trimmed_confidence = (
        [row[column_start:] for row in confidence_grid[row_start:]]
        if confidence_grid is not None
        else None
    )
    if fused_ruler_title and row_start == 0 and column_start == 1 and trimmed_grid:
        source_column, title = embedded_titles[0]
        source_confidence = (
            float(confidence_grid[0][source_column])
            if confidence_grid is not None
            else 0.77
        )
        trimmed_grid[0] = ["" for _ in trimmed_grid[0]]
        trimmed_grid[0][0] = title
        if trimmed_confidence is not None:
            trimmed_confidence[0] = [0.0 for _ in trimmed_confidence[0]]
            trimmed_confidence[0][0] = min(source_confidence, 0.77)
    return trimmed_grid, trimmed_confidence


def _spreadsheet_ruler_expected_columns(grid: list[list[str]]) -> int:
    """Read the A..H count from a spatial grid without trusting its cell count."""
    if len(grid) < 4 or not grid[0]:
        return 0
    labels: list[str] = []
    for value in grid[0]:
        normalized = " ".join(str(value).upper().split())
        if not normalized:
            continue
        if re.sub(r"[A-Z\s]+", "", normalized):
            return 0
        labels.extend(re.findall(r"[A-Z]{1,3}", normalized))
    if len(labels) < 3:
        return 0

    def column_number(label: str) -> int:
        number = 0
        for character in label:
            number = number * 26 + ord(character) - ord("A") + 1
        return number

    numbers = [column_number(label) for label in labels]
    if (
        numbers[0] != 1
        or any(
            not 1 <= right - left <= 2
            for left, right in zip(numbers, numbers[1:])
        )
        or sum(
            right - left - 1
            for left, right in zip(numbers, numbers[1:])
        )
        > 1
    ):
        return 0
    return numbers[-1]


def _row_center_boundaries(row_centers: list[float], image_height: int) -> list[int]:
    """Convert detector row centres to non-overlapping cell boundaries."""
    centers = [float(value) for value in row_centers]
    if len(centers) < 2 or image_height < 2:
        return []
    if any(right <= left for left, right in zip(centers, centers[1:])):
        return []
    boundaries = [
        max(0, int(round(centers[0] - (centers[1] - centers[0]) * 0.5)))
    ]
    boundaries.extend(
        int(round((left + right) * 0.5))
        for left, right in zip(centers, centers[1:])
    )
    boundaries.append(
        min(
            image_height - 1,
            int(round(centers[-1] + (centers[-1] - centers[-2]) * 0.5)),
        )
    )
    if min(np.diff(boundaries), default=0) < 4:
        return []
    return boundaries


def _spreadsheet_columns_from_spatial_ruler(
    image_shape: tuple[int, int],
    spatial_grid: list[list[str]],
    spatial_geometry: dict[str, Any],
    *,
    expected_columns: int,
) -> list[int]:
    """Recover one missed photo column from positioned A..Z ruler OCR boxes."""
    if not 3 <= expected_columns <= 32 or not spatial_grid or not spatial_grid[0]:
        return []
    row_count = len(spatial_grid)
    raw_columns = max((len(row) for row in spatial_grid), default=0)
    stripped, _ = _strip_spreadsheet_ui_headers(
        [list(row) for row in spatial_grid],
        None,
    )
    if (
        not stripped
        or not stripped[0]
        or len(stripped) != row_count - 1
        or len(stripped[0]) != raw_columns - 1
    ):
        return []
    grouped_rows = list(spatial_geometry.get("grouped_rows", []))
    if not grouped_rows:
        return []

    def column_number(label: str) -> int:
        number = 0
        for character in label:
            number = number * 26 + ord(character) - ord("A") + 1
        return number

    positioned: dict[int, float] = {}
    scores: list[float] = []
    for entry in grouped_rows[0]:
        label = str(entry.get("text", "")).strip().upper()
        if not re.fullmatch(r"[A-Z]{1,2}", label):
            continue
        number = column_number(label)
        if not 1 <= number <= expected_columns or number in positioned:
            return []
        positioned[number] = float(entry.get("center_x", 0.0))
        scores.append(float(entry.get("score", 0.0)))
    missing = [
        number for number in range(1, expected_columns + 1) if number not in positioned
    ]
    if (
        len(positioned) < expected_columns - 1
        or len(missing) > 1
        or 1 not in positioned
        or expected_columns not in positioned
        or not scores
        or sum(scores) / len(scores) < 0.90
    ):
        return []
    if missing:
        number = missing[0]
        if number - 1 not in positioned or number + 1 not in positioned:
            return []
        positioned[number] = (
            positioned[number - 1] + positioned[number + 1]
        ) * 0.5
    centers = [positioned[number] for number in range(1, expected_columns + 1)]
    gaps = [right - left for left, right in zip(centers, centers[1:])]
    typical_gap = float(median(gaps)) if gaps else 0.0
    if (
        typical_gap <= 0.0
        or any(gap < typical_gap * 0.50 for gap in gaps)
        or any(gap > typical_gap * 1.70 for gap in gaps)
    ):
        return []
    spatial_boundaries = _spatial_geometry_cell_boundaries(
        spatial_geometry,
        image_shape,
        row_count,
        raw_columns,
    )
    if spatial_boundaries is None or len(spatial_boundaries[0]) != raw_columns + 1:
        return []
    left = int(spatial_boundaries[0][1])
    right = int(spatial_boundaries[0][-1])
    image_width = int(image_shape[1])
    if right >= image_width * 0.95:
        right = image_width - 1
    if not left < centers[0] or not centers[-1] < right:
        return []
    columns = [left]
    columns.extend(
        int(round((first + second) * 0.5))
        for first, second in zip(centers, centers[1:])
    )
    columns.append(right)
    if min(
        (right - left for left, right in zip(columns, columns[1:])),
        default=0,
    ) < 8:
        return []
    return columns


def _rebuild_spreadsheet_grid_from_ruler(
    image: np.ndarray,
    spatial_grid: list[list[str]],
    spatial_geometry: dict[str, Any] | None,
    boxes: Any,
    texts: Any,
    scores: Any,
    ruler_image: np.ndarray | None = None,
) -> tuple[list[list[str]], list[list[float]], dict[str, Any]] | None:
    """Repair a missing screenshot column using independently visible rulers."""
    expected_columns = _spreadsheet_ruler_expected_columns(spatial_grid)
    if not expected_columns or not spatial_geometry:
        return None
    current_columns = max((len(row) for row in spatial_grid), default=0)
    if current_columns > expected_columns:
        return None
    row_centers = [float(value) for value in spatial_geometry.get("row_centers", [])]
    if len(row_centers) != len(spatial_grid) or len(row_centers) < 4:
        return None
    geometry_image = image
    if ruler_image is not None and ruler_image.size:
        source_height, source_width = ruler_image.shape[:2]
        target_height, target_width = image.shape[:2]
        if (
            abs(source_width / max(1, target_width) - 1.0) <= 0.03
            and abs(source_height / max(1, target_height) - 1.0) <= 0.03
        ):
            geometry_image = ruler_image
    source_height, source_width = geometry_image.shape[:2]
    target_height, target_width = image.shape[:2]
    band_bottom = int(round(row_centers[1] * 1.5 * source_height / target_height))
    source_columns = pipeline.extract_spreadsheet_ruler_columns(
        geometry_image,
        expected_columns,
        band_bottom,
    )
    columns_from_spatial_ruler = False
    if not source_columns:
        source_columns = _spreadsheet_columns_from_spatial_ruler(
            image.shape[:2],
            spatial_grid,
            spatial_geometry,
            expected_columns=expected_columns,
        )
        if source_columns:
            geometry_image = image
            columns_from_spatial_ruler = True
    columns = [
        min(target_width - 1, int(round(column * target_width / source_width)))
        for column in source_columns
    ]
    if columns_from_spatial_ruler:
        source_height, source_width = target_height, target_width
        columns = list(source_columns)
    if columns:
        columns[-1] = target_width - 1
    rows = _row_center_boundaries(row_centers, image.shape[0])
    if len(columns) != expected_columns + 1 or len(rows) != len(spatial_grid) + 1:
        return None
    rebuilt_grid, rebuilt_confidence = pipeline.assign_ocr_to_grid(
        columns,
        rows,
        boxes,
        texts,
        scores,
        preserve_geometry=True,
    )
    if (
        len(rebuilt_grid) != len(spatial_grid)
        or any(len(row) != expected_columns for row in rebuilt_grid)
    ):
        return None
    preview, _ = _strip_spreadsheet_ui_headers(rebuilt_grid, None)
    if (
        len(preview) != len(rebuilt_grid) - 1
        or max((len(row) for row in preview), default=0) != expected_columns
        or not (
            _spatial_has_credible_header(preview, [])
            or _spatial_has_implicit_title_multilevel_header(preview)
        )
        or _grid_has_fused_physical_columns(preview)
        or _grid_has_concatenated_physical_rows(preview)
        or _grid_has_misaligned_anchor_rows(preview)
    ):
        return None
    geometry = _ruled_grid_recovery_geometry(columns, rows)
    geometry["first_structured_row"] = 1
    return rebuilt_grid, rebuilt_confidence, geometry


def _select_strong_header_group_boundaries(
    header_positions: list[int],
    boundary_support: dict[int, float],
    column_count: int,
) -> list[int] | None:
    if (
        not header_positions
        or column_count < 2
        or header_positions != sorted(set(header_positions))
        or not all(0 <= position < column_count for position in header_positions)
    ):
        return None
    required = len(header_positions) - 1
    candidates = sorted(
        boundary
        for boundary, support in boundary_support.items()
        if 0 < boundary < column_count and float(support) >= 0.55
    )
    if len(candidates) < required:
        return None
    scored: list[tuple[float, list[int]]] = []
    for interior in itertools.combinations(candidates, required):
        boundaries = [0, *interior, column_count]
        if all(
            sum(start <= source < end for source in header_positions) == 1
            for start, end in zip(boundaries, boundaries[1:])
        ):
            scored.append(
                (
                    sum(float(boundary_support[boundary]) for boundary in interior),
                    boundaries,
                )
            )
    if not scored:
        return None
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    if len(scored) > 1 and scored[0][0] - scored[1][0] < 0.10:
        return None
    return scored[0][1]


def _recover_slanted_spreadsheet_grid_from_rulers(
    image: np.ndarray,
    boxes: Any,
    texts: Any,
    scores: Any,
    *,
    expected_rows: int = 0,
    expected_columns: int = 0,
    ocr_engine: Any | None = None,
) -> tuple[
    list[list[str]],
    list[list[float]],
    list[dict[str, Any]],
    dict[str, Any],
] | None:
    """Recover a photographed Excel grid from complete A..Z and 1..N rulers."""
    if image.size == 0 or boxes is None or texts is None:
        return None
    height, width = image.shape[:2]
    if height < 240 or width < 480:
        return None
    box_values = list(boxes)
    text_values = [str(value).strip() for value in texts]
    score_values = [float(value) for value in ([] if scores is None else scores)]
    if len(box_values) != len(text_values):
        return None

    entries: list[dict[str, Any]] = []
    for index, (box, text) in enumerate(zip(box_values, text_values)):
        points = np.asarray(box, dtype=float).reshape(-1, 2)
        entries.append(
            {
                "index": index,
                "text": text,
                "score": score_values[index] if index < len(score_values) else 0.0,
                "left": float(points[:, 0].min()),
                "right": float(points[:, 0].max()),
                "top": float(points[:, 1].min()),
                "bottom": float(points[:, 1].max()),
                "center_x": float(points[:, 0].mean()),
                "center_y": float(points[:, 1].mean()),
            }
        )

    numeric_candidates = sorted(
        (
            entry
            for entry in entries
            if entry["center_x"] <= width * 0.08
            and re.fullmatch(r"\d+", entry["text"])
        ),
        key=lambda entry: (entry["center_y"], entry["center_x"]),
    )
    candidate_sequences = []
    for first_number in (1, 2):
        sequence = []
        expected_number = first_number
        for entry in numeric_candidates:
            if int(entry["text"]) == expected_number:
                sequence.append(entry)
                expected_number += 1
        candidate_sequences.append(sequence)
    row_rulers = max(candidate_sequences, key=len, default=[])
    if (
        row_rulers
        and int(row_rulers[0]["text"]) == 2
        and len(row_rulers) >= 11
        and int(row_rulers[-1]["text"]) == len(row_rulers) + 1
    ):
        first_step = float(row_rulers[1]["center_y"]) - float(
            row_rulers[0]["center_y"]
        )
        inferred = dict(row_rulers[0])
        inferred["text"] = "1"
        inferred["center_y"] = float(row_rulers[0]["center_y"]) - first_step
        inferred["top"] = float(row_rulers[0]["top"]) - first_step
        row_rulers.insert(0, inferred)
    if not 12 <= len(row_rulers) <= 128:
        return None
    if expected_rows and len(row_rulers) != expected_rows:
        return None
    ruler_x = [float(entry["center_x"]) for entry in row_rulers]
    ruler_y = [float(entry["center_y"]) for entry in row_rulers]
    row_ruler_line = np.polyfit(ruler_y, ruler_x, 1)
    row_ruler_residuals = np.abs(
        np.asarray(ruler_x, dtype=float)
        - np.polyval(row_ruler_line, np.asarray(ruler_y, dtype=float))
    )
    if (
        abs(float(row_ruler_line[0])) > 0.15
        or float(np.percentile(row_ruler_residuals, 95)) > 4.0
        or float(np.mean([entry["score"] for entry in row_rulers])) < 0.95
    ):
        return None
    row_steps = np.diff(ruler_y)
    typical_row_step = float(np.median(row_steps)) if row_steps.size else 0.0
    if (
        typical_row_step < 8.0
        or float(
            np.mean(
                np.abs(row_steps - typical_row_step)
                <= max(4.0, typical_row_step * 0.30)
            )
        )
        < 0.90
    ):
        return None

    first_row_y = ruler_y[0]
    letter_confusions = {"8": "B", "1": "I", "一": "I"}
    column_rulers: list[dict[str, Any]] = []
    for entry in entries:
        normalized = letter_confusions.get(entry["text"].upper(), entry["text"].upper())
        if (
            entry["center_y"] < first_row_y - max(6.0, typical_row_step * 0.15)
            and re.fullmatch(r"[A-Z]", normalized)
            and entry["score"] >= 0.75
        ):
            candidate = dict(entry)
            candidate["letter"] = normalized
            column_rulers.append(candidate)
    column_rulers.sort(key=lambda entry: entry["center_x"])
    if (
        len(column_rulers) < 6
        and len(column_rulers) >= 3
        and [entry["letter"] for entry in column_rulers]
        == [chr(ord("A") + index) for index in range(len(column_rulers))]
    ):
        gray_for_lines = (
            cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            if image.ndim == 3
            else image
        )
        edges = cv2.Canny(gray_for_lines, 30, 100)
        line_segments = cv2.HoughLinesP(
            edges,
            1,
            np.pi / 1800.0,
            threshold=max(30, int(round(height * 0.025))),
            minLineLength=max(180, int(round(height * 0.25))),
            maxLineGap=max(20, int(round(height * 0.025))),
        )
        middle_y = float(np.median(ruler_y))
        projected_x: list[float] = []
        if line_segments is not None:
            for x1, y1, x2, y2 in line_segments.reshape(-1, 4):
                delta_y = float(y2 - y1)
                delta_x = float(x2 - x1)
                if (
                    abs(delta_y) < height * 0.25
                    or abs(delta_x) > abs(delta_y) * 0.15
                ):
                    continue
                top_y, bottom_y = sorted((float(y1), float(y2)))
                if (
                    top_y > ruler_y[0] + typical_row_step * 5.0
                    or bottom_y < ruler_y[-1] - typical_row_step * 5.0
                ):
                    continue
                projected_x.append(
                    float(x1) + delta_x * (middle_y - float(y1)) / delta_y
                )
        projected_x.sort()
        line_groups: list[list[float]] = []
        cluster_gap = max(6.0, width * 0.004)
        for value in projected_x:
            if not line_groups or value - line_groups[-1][-1] > cluster_gap:
                line_groups.append([])
            line_groups[-1].append(value)
        long_line_centers = [
            float(np.median(group))
            for group in line_groups
            if group
            and width * 0.02 <= float(np.median(group)) <= width * 0.98
        ]
        ruler_center_x = float(np.median(ruler_x))
        if (
            8 <= len(long_line_centers) <= 34
            and long_line_centers[0] < ruler_center_x < long_line_centers[1]
        ):
            content_boundaries = long_line_centers[1:]
            boundary_gaps = np.diff(content_boundaries)
            content_count = len(content_boundaries) - 1
            if (
                6 <= content_count <= 26
                and boundary_gaps.size
                and float(boundary_gaps.min()) >= 8.0
                and float(boundary_gaps.max())
                <= float(np.median(boundary_gaps)) * 3.0
                and all(
                    content_boundaries[index]
                    < float(entry["center_x"])
                    < content_boundaries[index + 1]
                    for index, entry in enumerate(column_rulers)
                )
            ):
                ruler_y_line = np.polyfit(
                    [float(entry["center_x"]) for entry in column_rulers],
                    [float(entry["center_y"]) for entry in column_rulers],
                    1,
                )
                minimum_score = min(
                    float(entry["score"]) for entry in column_rulers
                )
                observed_letter_count = len(column_rulers)
                column_rulers = [
                    {
                        "letter": chr(ord("A") + index),
                        "text": chr(ord("A") + index),
                        "center_x": (
                            content_boundaries[index]
                            + content_boundaries[index + 1]
                        )
                        * 0.5,
                        "center_y": float(
                            np.polyval(
                                ruler_y_line,
                                (
                                    content_boundaries[index]
                                    + content_boundaries[index + 1]
                                )
                                * 0.5,
                            )
                        ),
                        "score": minimum_score,
                    }
                    for index in range(content_count)
                ]
                _write_runtime_trace(
                    "route",
                    name="slanted_ruler_columns_synthesized",
                    columns=content_count,
                    long_line_boundaries=len(long_line_centers),
                    observed_letters=observed_letter_count,
                )
    if (
        len(column_rulers) >= 3
        and expected_columns == len(column_rulers) + 1
        and expected_columns <= 26
        and [entry["letter"] for entry in column_rulers]
        == [chr(ord("A") + index) for index in range(len(column_rulers))]
    ):
        previous = column_rulers[-2]
        last = column_rulers[-1]
        inferred = dict(last)
        inferred["letter"] = chr(ord("A") + len(column_rulers))
        inferred["text"] = inferred["letter"]
        inferred["center_x"] = float(last["center_x"]) + (
            float(last["center_x"]) - float(previous["center_x"])
        )
        inferred["center_y"] = float(last["center_y"]) + (
            float(last["center_y"]) - float(previous["center_y"])
        )
        column_rulers.append(inferred)
    if not 6 <= len(column_rulers) <= 26:
        _write_runtime_trace(
            "route",
            name="slanted_ruler_recovery_rejected",
            reason="insufficient_column_rulers",
            columns=len(column_rulers),
        )
        return None
    if expected_columns and len(column_rulers) != expected_columns:
        return None
    expected_letters = [chr(ord("A") + index) for index in range(len(column_rulers))]
    if [entry["letter"] for entry in column_rulers] != expected_letters:
        return None
    letter_x = np.asarray(
        [float(entry["center_x"]) for entry in column_rulers], dtype=float
    )
    letter_y = np.asarray(
        [float(entry["center_y"]) for entry in column_rulers], dtype=float
    )
    ruler_line = np.polyfit(letter_x, letter_y, 1)
    if float(np.max(np.abs(letter_y - np.polyval(ruler_line, letter_x)))) > 6.0:
        _write_runtime_trace(
            "route",
            name="slanted_ruler_recovery_rejected",
            reason="column_ruler_baseline_residual",
        )
        return None

    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    vertical_gradient = np.abs(
        cv2.Sobel(gray.astype(np.float32), cv2.CV_32F, 1, 0, ksize=3)
    )
    horizontal_gradient = np.abs(
        cv2.Sobel(gray.astype(np.float32), cv2.CV_32F, 0, 1, ksize=3)
    )

    def strongest_line(
        gradient: np.ndarray,
        fixed_coordinates: np.ndarray,
        predicted_origin: float,
        search_radius: float,
        slope_values: np.ndarray,
        origin_reference: float,
        *,
        vertical: bool,
    ) -> tuple[float, float, float] | None:
        lower = int(round(predicted_origin - search_radius))
        upper = int(round(predicted_origin + search_radius))
        best: tuple[float, float, float, float] | None = None
        for slope in slope_values:
            for origin in range(lower, upper + 1, 2 if vertical else 1):
                moving = np.rint(
                    origin + float(slope) * (fixed_coordinates - origin_reference)
                ).astype(int)
                limit = width if vertical else height
                valid = (moving >= 2) & (moving < limit - 2)
                if int(np.count_nonzero(valid)) < fixed_coordinates.size * 0.80:
                    continue
                fixed = fixed_coordinates[valid]
                moving = moving[valid]
                if vertical:
                    values = np.maximum.reduce(
                        [gradient[fixed, moving + offset] for offset in (-2, -1, 0, 1, 2)]
                    )
                else:
                    values = np.maximum.reduce(
                        [gradient[moving + offset, fixed] for offset in (-2, -1, 0, 1, 2)]
                    )
                robust = float(np.percentile(values, 40))
                candidate = (robust, float(np.median(values)), float(origin), float(slope))
                if best is None or candidate > best:
                    best = candidate
        if best is None or best[0] < 12.0:
            return None
        _, _, origin, slope = best
        return slope, origin - slope * origin_reference, best[0]

    vertical_samples = np.arange(
        max(2, int(round(first_row_y))),
        min(height - 2, int(round(ruler_y[-1] + typical_row_step * 0.7))),
        3,
    )
    if vertical_samples.size < 40:
        return None
    vertical_lines: list[tuple[float, float]] = []
    vertical_scores: list[float] = []
    letter_centers = [float(entry["center_x"]) for entry in column_rulers]
    first_gap = letter_centers[1] - letter_centers[0]
    last_gap = letter_centers[-1] - letter_centers[-2]
    for boundary_index in range(len(letter_centers) + 1):
        if boundary_index == 0:
            predicted = letter_centers[0] - first_gap * 0.5
            lower_limit = max(ruler_x) + max(4.0, width * 0.003)
            upper_limit = letter_centers[0] - 8.0
            predicted = min(upper_limit, max(lower_limit, predicted))
            radius = max(4.0, min(predicted - lower_limit, upper_limit - predicted))
        elif boundary_index == len(letter_centers):
            predicted = letter_centers[-1] + last_gap * 0.5
            radius = max(8.0, last_gap * 0.28)
        else:
            gap = letter_centers[boundary_index] - letter_centers[boundary_index - 1]
            predicted = (
                letter_centers[boundary_index - 1]
                + letter_centers[boundary_index]
            ) * 0.5
            radius = max(8.0, gap * 0.28)
        line = strongest_line(
            vertical_gradient,
            vertical_samples,
            predicted,
            radius,
            np.arange(-0.15, 0.151, 0.003),
            first_row_y,
            vertical=True,
        )
        if line is None:
            _write_runtime_trace(
                "route",
                name="slanted_ruler_recovery_rejected",
                reason="vertical_boundary_not_found",
                boundary=boundary_index,
                columns=len(letter_centers),
            )
            return None
        vertical_lines.append((line[0], line[1]))
        vertical_scores.append(line[2])

    middle_y = float(np.median(vertical_samples))
    middle_columns = [slope * middle_y + intercept for slope, intercept in vertical_lines]
    if min(np.diff(middle_columns), default=0.0) < 8.0:
        return None
    for index, entry in enumerate(column_rulers):
        y = float(entry["center_y"])
        x = float(entry["center_x"])
        left = vertical_lines[index][0] * y + vertical_lines[index][1]
        right = vertical_lines[index + 1][0] * y + vertical_lines[index + 1][1]
        if not left < x < right:
            _write_runtime_trace(
                "route",
                name="slanted_ruler_recovery_rejected",
                reason="column_label_outside_fitted_cell",
                column=index,
            )
            return None

    left_sample = int(round(middle_columns[0])) + 5
    right_sample = int(round(middle_columns[-1])) - 5
    horizontal_samples = np.arange(
        max(2, left_sample), min(width - 2, right_sample), 4
    )
    if horizontal_samples.size < 80:
        return None
    horizontal_lines: list[tuple[float, float]] = []
    horizontal_scores: list[float] = []
    for boundary_index in range(len(row_rulers) + 1):
        if boundary_index == 0:
            predicted = ruler_y[0] - row_steps[0] * 0.5
            gap = row_steps[0]
            reference_x = ruler_x[0]
        elif boundary_index == len(row_rulers):
            predicted = ruler_y[-1] + row_steps[-1] * 0.5
            gap = row_steps[-1]
            reference_x = ruler_x[-1]
        else:
            predicted = (ruler_y[boundary_index - 1] + ruler_y[boundary_index]) * 0.5
            gap = row_steps[boundary_index - 1]
            reference_x = (ruler_x[boundary_index - 1] + ruler_x[boundary_index]) * 0.5
        line = strongest_line(
            horizontal_gradient,
            horizontal_samples,
            predicted,
            max(6.0, float(gap) * 0.28),
            np.arange(-0.06, 0.061, 0.002),
            reference_x,
            vertical=False,
        )
        if line is None:
            _write_runtime_trace(
                "route",
                name="slanted_ruler_recovery_rejected",
                reason="horizontal_boundary_not_found",
                boundary=boundary_index,
                rows=len(row_rulers),
            )
            return None
        horizontal_lines.append((line[0], line[1]))
        horizontal_scores.append(line[2])

    middle_x = float(np.median(horizontal_samples))
    middle_rows = [slope * middle_x + intercept for slope, intercept in horizontal_lines]
    if min(np.diff(middle_rows), default=0.0) < 6.0:
        return None
    for index, entry in enumerate(row_rulers):
        x = float(entry["center_x"])
        y = float(entry["center_y"])
        top = horizontal_lines[index][0] * x + horizontal_lines[index][1]
        bottom = horizontal_lines[index + 1][0] * x + horizontal_lines[index + 1][1]
        if not top < y < bottom:
            _write_runtime_trace(
                "route",
                name="slanted_ruler_recovery_rejected",
                reason="row_label_outside_fitted_cell",
                row=index,
            )
            return None

    row_count = len(row_rulers)
    column_count = len(column_rulers)
    cell_entries: list[list[list[tuple[float, float, str, float]]]] = [
        [[] for _ in range(column_count)] for _ in range(row_count)
    ]
    stacked_candidates: list[tuple[dict[str, Any], int, int, int, float]] = []
    for entry in entries:
        x = float(entry["center_x"])
        y = float(entry["center_y"])
        row_boundaries = [slope * x + intercept for slope, intercept in horizontal_lines]
        column_boundaries = [slope * y + intercept for slope, intercept in vertical_lines]
        row_index = int(np.searchsorted(row_boundaries, y, side="right") - 1)
        column_index = int(np.searchsorted(column_boundaries, x, side="right") - 1)
        if 0 <= row_index < row_count and 0 <= column_index < column_count:
            if entry["text"]:
                crossed = [
                    (boundary_index, boundary)
                    for boundary_index, boundary in enumerate(
                        row_boundaries[1:-1], start=1
                    )
                    if float(entry["top"]) < boundary < float(entry["bottom"])
                    and 0.18
                    <= (boundary - float(entry["top"]))
                    / max(1.0, float(entry["bottom"]) - float(entry["top"]))
                    <= 0.82
                ]
                if len(crossed) == 1:
                    boundary_index, boundary = crossed[0]
                    upper_row = boundary_index - 1
                    if (
                        0 <= upper_row < row_count - 1
                        and column_index >= 0
                    ):
                        stacked_candidates.append(
                            (
                                entry,
                                upper_row,
                                upper_row + 1,
                                column_index,
                                float(boundary),
                            )
                        )
                cell_entries[row_index][column_index].append(
                    (
                        float(entry["top"]),
                        float(entry["left"]),
                        str(entry["text"]),
                        float(entry["score"]),
                    )
                )

    grid = [["" for _ in range(column_count)] for _ in range(row_count)]
    confidence = [[-1.0 for _ in range(column_count)] for _ in range(row_count)]
    for row_index, row in enumerate(cell_entries):
        for column_index, values in enumerate(row):
            values.sort(key=lambda item: (item[0], item[1]))
            if not values:
                continue
            grid[row_index][column_index] = " ".join(item[2] for item in values)
            confidence[row_index][column_index] = min(
                0.77,
                min(item[3] for item in values),
            )
    stacked_recognizer = (
        getattr(ocr_engine, "fast_text_rec", None)
        if ocr_engine is not None
        else None
    )
    if callable(stacked_recognizer) and stacked_candidates:
        from rapidocr.ch_ppocr_rec.typings import TextRecInput

        split_crops: list[np.ndarray] = []
        retained_candidates: list[
            tuple[dict[str, Any], int, int, int, float]
        ] = []
        for candidate in stacked_candidates:
            entry, upper_row, lower_row, column, boundary = candidate
            left = max(0, int(math.floor(float(entry["left"]))) - 2)
            right = min(width, int(math.ceil(float(entry["right"]))) + 3)
            top = max(0, int(math.floor(float(entry["top"]))) - 2)
            bottom = min(height, int(math.ceil(float(entry["bottom"]))) + 3)
            split = int(round(boundary))
            upper = image[top:split, left:right]
            lower = image[split:bottom, left:right]
            upper_tight = _tight_text_crop(upper) if upper.size else upper
            lower_tight = _tight_text_crop(lower) if lower.size else lower
            if upper_tight.size == 0 or lower_tight.size == 0:
                continue
            retained_candidates.append(candidate)
            split_crops.extend([upper_tight, lower_tight])
        if split_crops:
            split_output = stacked_recognizer(TextRecInput(img=split_crops))
            _release_recognition_images(split_output)
            split_texts = [str(value).strip() for value in split_output.txts]
            split_scores = [float(value) for value in split_output.scores]
            if len(split_texts) == len(split_crops) and len(split_scores) == len(
                split_crops
            ):
                for index, candidate in enumerate(retained_candidates):
                    _, upper_row, lower_row, column, _ = candidate
                    upper_text, lower_text = split_texts[index * 2 : index * 2 + 2]
                    upper_score, lower_score = split_scores[
                        index * 2 : index * 2 + 2
                    ]
                    if (
                        upper_text
                        and lower_text
                        and min(upper_score, lower_score) >= 0.78
                        and not str(grid[lower_row][column]).strip()
                    ):
                        grid[upper_row][column] = upper_text
                        grid[lower_row][column] = lower_text
                        confidence[upper_row][column] = min(upper_score, 0.77)
                        confidence[lower_row][column] = min(lower_score, 0.77)
    if (
        _grid_has_fused_physical_columns(grid)
        or _grid_has_concatenated_physical_rows(grid)
        or _grid_has_misaligned_anchor_rows(grid)
    ):
        return None

    spans: list[dict[str, Any]] = []
    first_row_positions = [
        column for column, value in enumerate(grid[0]) if str(value).strip()
    ]
    group_boundaries: list[int] = []
    for header_row in range(min(3, row_count - 1)):
        header_positions = [
            column
            for column, value in enumerate(grid[header_row])
            if str(value).strip()
        ]
        if not header_positions or len(header_positions) >= column_count:
            continue
        boundary_support: dict[int, float] = {}
        for boundary_index in range(1, column_count):
            samples = []
            for fraction in np.linspace(0.15, 0.85, 16):
                x = middle_columns[boundary_index]
                top = (
                    horizontal_lines[header_row][0] * x
                    + horizontal_lines[header_row][1]
                )
                bottom = (
                    horizontal_lines[header_row + 1][0] * x
                    + horizontal_lines[header_row + 1][1]
                )
                y = top + (bottom - top) * float(fraction)
                boundary_x = (
                    vertical_lines[boundary_index][0] * y
                    + vertical_lines[boundary_index][1]
                )
                ix = int(round(boundary_x))
                iy = int(round(y))
                if 2 <= ix < width - 2 and 2 <= iy < height - 2:
                    samples.append(
                        float(vertical_gradient[iy, ix - 2 : ix + 3].max())
                    )
            boundary_support[boundary_index] = (
                float(np.mean(np.asarray(samples) > 50.0)) if samples else 0.0
            )
        selected_boundaries = _select_strong_header_group_boundaries(
            header_positions,
            boundary_support,
            column_count,
        )
        if selected_boundaries is None:
            continue
        if header_row == 0:
            group_boundaries = selected_boundaries
        for source, start, end in zip(
            header_positions,
            selected_boundaries,
            selected_boundaries[1:],
        ):
            if end - start < 2:
                continue
            value = grid[header_row][source]
            score = confidence[header_row][source]
            grid[header_row][source] = ""
            confidence[header_row][source] = -1.0
            grid[header_row][start] = value
            confidence[header_row][start] = score
            spans.append(
                {
                    "row": header_row,
                    "column": start,
                    "row_span": 1,
                    "column_span": end - start,
                    "role": "group_header",
                }
            )
    return grid, confidence, spans, {
        "ruler_rows": row_count,
        "content_columns": column_count,
        "vertical_gradient_floor": round(min(vertical_scores), 3),
        "horizontal_gradient_floor": round(min(horizontal_scores), 3),
        "slanted_dual_ruler_recovery": True,
        "header_positions": first_row_positions,
        "header_group_boundaries": group_boundaries,
    }


def _spreadsheet_ruler_row_count_with_one_bracketed_gap(
    spatial_grid: list[list[str]],
) -> int | None:
    """Validate ordered row rulers while tolerating one visibly bracketed miss."""
    tokens_by_row: dict[int, list[int]] = {}
    ruler_numbers: list[int] = []
    for row_index, row in enumerate(spatial_grid):
        value = str(row[0] if row else "").strip()
        if not value:
            continue
        if not re.fullmatch(r"\d+(?:\s+\d+)*", value):
            return None
        tokens = sorted(int(token) for token in value.split())
        if (
            not tokens
            or len(tokens) != len(set(tokens))
            or tokens != list(range(tokens[0], tokens[-1] + 1))
        ):
            return None
        tokens_by_row[row_index] = tokens
        ruler_numbers.extend(tokens)
    if len(ruler_numbers) < 12 or ruler_numbers != sorted(set(ruler_numbers)):
        return None
    expected_rows = max(ruler_numbers)
    if not 12 <= expected_rows <= 128:
        return None
    missing = sorted(set(range(1, expected_rows + 1)) - set(ruler_numbers))
    if len(missing) > 1 or len(ruler_numbers) != expected_rows - len(missing):
        return None
    if missing:
        missing_value = missing[0]
        bracketed_positions = [
            row_index
            for row_index in range(1, len(spatial_grid) - 1)
            if not str(spatial_grid[row_index][0]).strip()
            and tokens_by_row.get(row_index - 1, [0])[-1] == missing_value - 1
            and tokens_by_row.get(row_index + 1, [expected_rows + 1])[0]
            == missing_value + 1
        ]
        if len(bracketed_positions) != 1:
            return None
    return expected_rows


def _select_adjacent_monotonic_row_track(
    previous: np.ndarray,
    observed: np.ndarray,
    *,
    tolerance: float = 7.0,
) -> np.ndarray | None:
    """Select one ordered line per prior boundary while skipping local outliers."""
    if previous.size < 4 or observed.size < previous.size:
        return None
    previous = np.asarray(previous, dtype=float)
    observed = np.asarray(observed, dtype=float)
    row_count = int(previous.size)
    observed_count = int(observed.size)
    infinity = float("inf")
    costs = np.full((row_count + 1, observed_count + 1), infinity, dtype=float)
    taken = np.zeros((row_count + 1, observed_count + 1), dtype=np.uint8)
    costs[0, :] = 0.0
    for row_index in range(1, row_count + 1):
        for observed_index in range(1, observed_count + 1):
            skip_cost = costs[row_index, observed_index - 1]
            distance = abs(
                float(observed[observed_index - 1])
                - float(previous[row_index - 1])
            )
            match_cost = (
                costs[row_index - 1, observed_index - 1] + distance
                if distance <= tolerance
                else infinity
            )
            if match_cost <= skip_cost:
                costs[row_index, observed_index] = match_cost
                taken[row_index, observed_index] = 1
            else:
                costs[row_index, observed_index] = skip_cost
    if not np.isfinite(costs[row_count, observed_count]):
        return None
    selected: list[int] = []
    row_index = row_count
    observed_index = observed_count
    while row_index:
        if observed_index <= 0:
            return None
        if taken[row_index, observed_index]:
            selected.append(observed_index - 1)
            row_index -= 1
            observed_index -= 1
        else:
            observed_index -= 1
    selected.reverse()
    result = observed[np.asarray(selected, dtype=int)]
    if result.size != previous.size or float(np.max(np.abs(result - previous))) > tolerance:
        return None
    return result


def _group_header_boundary_has_edge_evidence(
    gradient: np.ndarray,
    boundary: int,
) -> bool:
    if gradient.size == 0 or gradient.shape[0] < 10:
        return False
    band = gradient[:, max(0, boundary - 2) : boundary + 3]
    if band.size == 0:
        return False
    margin_rows = np.r_[0:5, gradient.shape[0] - 5 : gradient.shape[0]]
    margin_band = band[margin_rows]
    margin_support = float(np.mean(margin_band > 50.0))
    full_support = float(np.mean(band > 50.0))
    return bool(
        margin_support >= 0.55
        or (margin_support >= 0.35 and full_support >= 0.50)
    )


def _recover_perspective_spreadsheet_from_rulers(
    image: np.ndarray,
    spatial_grid: list[list[str]],
    spatial_geometry: dict[str, Any] | None,
    boxes: Any,
    texts: Any,
    scores: Any,
    ocr_engine: Any | None = None,
) -> tuple[
    list[list[str]],
    list[list[float]],
    list[dict[str, Any]],
    dict[str, Any],
] | None:
    """Rebuild a slanted sheet from its visible row ruler and physical rules."""
    slanted_recovery = _recover_slanted_spreadsheet_grid_from_rulers(
        image,
        boxes,
        texts,
        scores,
        expected_rows=0,
        expected_columns=0,
        ocr_engine=ocr_engine,
    )
    if slanted_recovery is not None:
        return slanted_recovery
    if not spatial_geometry or len(spatial_grid) < 10 or not spatial_grid[0]:
        return None
    raw_columns = max((len(row) for row in spatial_grid), default=0)
    content_column_count = raw_columns - 1
    if not 6 <= content_column_count <= 32:
        return None

    expected_rows = _spreadsheet_ruler_row_count_with_one_bracketed_gap(
        spatial_grid
    )
    if expected_rows is None:
        return None

    data_like = re.compile(
        r"^(?:[+\-]?\d+(?:\.\d+)?(?:e[+\-]?\d+)?%?|\d{4}[-/.]\d{1,2}[-/.]\d{1,2})$",
        re.IGNORECASE,
    )
    detail_values: list[str] | None = None
    for candidate_row in spatial_grid[1 : min(len(spatial_grid), 4)]:
        candidate = [
            str(value).strip() for value in candidate_row[1:raw_columns]
        ]
        if (
            len(candidate) == content_column_count
            and sum(bool(value) for value in candidate) >= content_column_count - 1
            and sum(
                bool(_segment_concatenated_header_labels(value))
                or value in _COMMON_HEADER_LABELS
                or (bool(value) and not data_like.fullmatch(value))
                for value in candidate
            )
            >= max(3, int(math.ceil(content_column_count * 0.70)))
        ):
            detail_values = candidate
            break
    if detail_values is None:
        return None

    spatial_boundaries = _spatial_geometry_cell_boundaries(
        spatial_geometry,
        image.shape[:2],
        len(spatial_grid),
        raw_columns,
    )
    if spatial_boundaries is None:
        return None
    global_columns = spatial_boundaries[0]
    content_columns = global_columns[1:]
    if len(content_columns) != content_column_count + 1:
        return None

    horizontal, vertical, _ = pipeline._grid_maps(image)

    def horizontal_centers(left: int, right: int) -> list[int]:
        inset = max(3, int(round((right - left) * 0.08)))
        left += inset
        right -= inset
        if right - left < 16:
            return []
        projection = np.count_nonzero(horizontal[:, left:right], axis=1)
        indices = np.flatnonzero(
            projection >= max(3, int(round((right - left) * 0.30)))
        )
        groups = np.split(indices, np.where(np.diff(indices) > 1)[0] + 1)
        return [int(round(float(group.mean()))) for group in groups if group.size]

    reference_rows = horizontal_centers(content_columns[0], content_columns[1])
    if len(reference_rows) == expected_rows + 2 and content_column_count <= 26:
        ruler_values = [
            str(value).strip()
            for value in spatial_grid[0][1 : content_column_count + 1]
        ]
        ruler_support = sum(
            _spreadsheet_ruler_label_matches(value, chr(ord("A") + index))
            for index, value in enumerate(ruler_values)
        )
        body_gaps = np.diff(reference_rows[1:]).astype(float)
        typical_body_gap = float(np.median(body_gaps)) if body_gaps.size else 0.0
        if (
            ruler_support >= content_column_count - 1
            and reference_rows[0] <= image.shape[0] * 0.02
            and reference_rows[1] <= image.shape[0] * 0.05
            and typical_body_gap >= 8.0
            and reference_rows[1] - reference_rows[0]
            <= typical_body_gap * 0.85
        ):
            reference_rows = reference_rows[1:]
    if len(reference_rows) != expected_rows + 1:
        return None
    height = image.shape[0]
    row_gaps = np.diff(reference_rows).astype(float)
    typical_row_gap = float(np.median(row_gaps)) if row_gaps.size else 0.0
    if not (
        reference_rows[0] <= height * 0.04
        and reference_rows[-1] >= height * 0.965
        and typical_row_gap >= 8.0
        and float(
            np.mean(
                np.abs(row_gaps - typical_row_gap)
                <= max(4.0, typical_row_gap * 0.30)
            )
        )
        >= 0.85
    ):
        return None

    reference_track = np.asarray(reference_rows, dtype=float)
    previous_track = reference_track
    row_mappings: list[tuple[float, np.ndarray]] = []
    for left, right in zip(content_columns, content_columns[1:]):
        observed = np.asarray(horizontal_centers(left, right), dtype=float)
        selected_track = _select_adjacent_monotonic_row_track(
            previous_track,
            observed,
        )
        if selected_track is None:
            continue
        row_mappings.append(
            ((float(left) + float(right)) * 0.5, selected_track)
        )
        previous_track = selected_track
    if len(row_mappings) < max(4, int(math.ceil(content_column_count * 0.70))):
        return None
    row_mappings.sort(key=lambda item: item[0])
    mapping_x = np.asarray([item[0] for item in row_mappings], dtype=float)
    mapping_rows = np.asarray([item[1] for item in row_mappings], dtype=float)

    def rows_at_x(center_x: float) -> np.ndarray:
        return np.asarray(
            [
                np.interp(center_x, mapping_x, mapping_rows[:, boundary_index])
                for boundary_index in range(expected_rows + 1)
            ],
            dtype=float,
        )

    detected_column_rows: list[tuple[float, list[int]]] = []
    expected_vertical_boundaries = raw_columns + 1
    for top, bottom in zip(reference_rows, reference_rows[1:]):
        projection = np.count_nonzero(vertical[top:bottom, :], axis=0)
        indices = np.flatnonzero(
            projection >= max(2, int(round((bottom - top) * 0.35)))
        )
        groups = np.split(indices, np.where(np.diff(indices) > 1)[0] + 1)
        centers = [int(round(float(group.mean()))) for group in groups if group.size]
        if len(centers) == expected_vertical_boundaries:
            detected_column_rows.append(((top + bottom) * 0.5, centers))
    if len(detected_column_rows) < max(
        8, int(math.ceil((expected_rows - 5) * 0.70))
    ):
        return None

    column_models: list[np.ndarray] = []
    detected_y = np.asarray([item[0] for item in detected_column_rows], dtype=float)
    for boundary_index in range(expected_vertical_boundaries):
        detected_x = np.asarray(
            [item[1][boundary_index] for item in detected_column_rows], dtype=float
        )
        coefficients = np.polyfit(detected_y, detected_x, 1)
        residuals = np.abs(detected_x - np.polyval(coefficients, detected_y))
        if float(np.percentile(residuals, 95)) > 3.0:
            return None
        column_models.append(coefficients)

    entries: list[list[list[tuple[float, float, str, float]]]] = [
        [[] for _ in range(content_column_count)] for _ in range(expected_rows)
    ]
    score_values = list([] if scores is None else scores)
    box_values = [] if boxes is None else boxes
    text_values = [] if texts is None else texts
    for index, (box, text) in enumerate(zip(box_values, text_values)):
        points = np.asarray(box, dtype=float).reshape(-1, 2)
        center_x = float(points[:, 0].mean())
        center_y = float(points[:, 1].mean())
        local_rows = rows_at_x(center_x)
        row_index = int(np.searchsorted(local_rows, center_y, side="right") - 1)
        local_columns = [
            float(np.polyval(coefficients, center_y))
            for coefficients in column_models
        ][1:]
        column_index = int(
            np.searchsorted(local_columns, center_x, side="right") - 1
        )
        if not (
            0 <= row_index < expected_rows
            and 0 <= column_index < content_column_count
        ):
            continue
        value = str(text).strip()
        if not value:
            continue
        score = float(score_values[index]) if index < len(score_values) else 0.0
        entries[row_index][column_index].append(
            (
                float(points[:, 0].min()),
                float(points[:, 1].min()),
                value,
                score,
            )
        )

    grid = [["" for _ in range(content_column_count)] for _ in range(expected_rows)]
    confidence = [[0.0 for _ in range(content_column_count)] for _ in range(expected_rows)]
    for row_index, row in enumerate(entries):
        for column_index, cell_entries in enumerate(row):
            cell_entries.sort(key=lambda item: (item[1], item[0]))
            grid[row_index][column_index] = " ".join(
                item[2] for item in cell_entries
            )
            confidence[row_index][column_index] = min(
                (item[3] for item in cell_entries), default=0.0
            )

    verified_cell_count = 0
    if ocr_engine is not None and callable(getattr(ocr_engine, "text_rec", None)):
        from rapidocr.ch_ppocr_rec.typings import TextRecInput

        unit_columns = {
            column
            for column, value in enumerate(detail_values)
            if "单位" in str(value)
        }
        numeric_columns = {
            column
            for column, value in enumerate(detail_values)
            if any(
                hint in str(value)
                for hint in (
                    "数量", "金额", "价格", "目标值", "实测值", "偏差",
                    "下限", "上限", "峰值", "合计", "总计",
                )
            )
        }
        targets: list[tuple[int, int]] = []
        views: list[np.ndarray] = []
        for row_index in range(1, expected_rows):
            reference_center = (
                reference_rows[row_index] + reference_rows[row_index + 1]
            ) * 0.5
            reference_columns = [
                float(np.polyval(coefficients, reference_center))
                for coefficients in column_models
            ][1:]
            for column_index in range(content_column_count):
                current_value = str(grid[row_index][column_index]).strip()
                current_score = float(confidence[row_index][column_index])
                trailing_sign_number = bool(
                    column_index in numeric_columns
                    and re.fullmatch(r"\d+(?:\.\d+)?[+\-]", current_value)
                )
                if current_value and current_score >= 0.90 and not trailing_sign_number:
                    continue
                center_x = (
                    reference_columns[column_index]
                    + reference_columns[column_index + 1]
                ) * 0.5
                local_rows = rows_at_x(center_x)
                top = int(round(float(local_rows[row_index])))
                bottom = int(round(float(local_rows[row_index + 1])))
                center_y = (top + bottom) * 0.5
                local_columns = [
                    int(round(float(np.polyval(coefficients, center_y))))
                    for coefficients in column_models
                ][1:]
                left = local_columns[column_index]
                right = local_columns[column_index + 1]
                pad_x = max(2, min(5, (right - left) // 20))
                pad_y = max(2, min(4, (bottom - top) // 12))
                crop = image[
                    top + pad_y : bottom - pad_y,
                    left + pad_x : right - pad_x,
                ]
                if crop.size == 0:
                    continue
                if not current_value:
                    if (
                        column_index in unit_columns
                        and sum(
                            _has_visible_celsius_degree_ring(view)
                            for view in _unit_cell_morphology_views(
                                image,
                                left,
                                right,
                                top,
                                bottom,
                            )
                        )
                        >= 2
                    ):
                        grid[row_index][column_index] = "℃"
                        confidence[row_index][column_index] = 0.77
                        verified_cell_count += 1
                    continue
                tight = _tight_text_crop(crop)
                if tight.size == 0:
                    continue
                gray_view = (
                    cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY)
                    if tight.ndim == 3
                    else tight
                )
                ordinary = cv2.resize(
                    tight,
                    None,
                    fx=3.2,
                    fy=3.2,
                    interpolation=cv2.INTER_LANCZOS4,
                )
                grayscale = cv2.resize(
                    gray_view,
                    None,
                    fx=3.2,
                    fy=3.2,
                    interpolation=cv2.INTER_LANCZOS4,
                )
                if ordinary.ndim == 2:
                    ordinary = cv2.cvtColor(ordinary, cv2.COLOR_GRAY2BGR)
                grayscale = cv2.cvtColor(grayscale, cv2.COLOR_GRAY2BGR)
                targets.append((row_index, column_index))
                views.extend((ordinary, grayscale))
        if views:
            with contextlib.redirect_stdout(sys.stderr):
                verification = ocr_engine.text_rec(TextRecInput(img=views))
            _release_recognition_images(verification)
            for index, (row_index, column_index) in enumerate(targets):
                candidates = [
                    (
                        str(verification.txts[index * 2 + view]).strip(),
                        float(verification.scores[index * 2 + view]),
                    )
                    for view in range(2)
                ]
                if (
                    candidates[0][0]
                    and _comparable_text(candidates[0][0])
                    == _comparable_text(candidates[1][0])
                    and min(candidates[0][1], candidates[1][1]) >= 0.95
                ):
                    grid[row_index][column_index] = candidates[0][0]
                    confidence[row_index][column_index] = min(
                        candidates[0][1], candidates[1][1]
                    )
                    verified_cell_count += 1

    top_center = (reference_rows[0] + reference_rows[1]) * 0.5
    top_columns = [
        int(round(float(np.polyval(coefficients, top_center))))
        for coefficients in column_models
    ][1:]
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) if image.ndim == 3 else image
    header_top = reference_rows[0] + 2
    header_bottom = reference_rows[1] - 2
    if header_bottom - header_top < 10:
        return None
    gradient = np.abs(
        cv2.Sobel(
            gray[header_top:header_bottom].astype(np.float32),
            cv2.CV_32F,
            1,
            0,
            ksize=3,
        )
    )
    group_boundaries = [0]
    for boundary_index, boundary in enumerate(top_columns[1:-1], start=1):
        if _group_header_boundary_has_edge_evidence(gradient, boundary):
            group_boundaries.append(boundary_index)
    group_boundaries.append(content_column_count)
    header_positions = [
        column for column, value in enumerate(grid[0]) if str(value).strip()
    ]
    if len(header_positions) != len(group_boundaries) - 1:
        return None
    for source, start, end in zip(
        header_positions,
        group_boundaries,
        group_boundaries[1:],
    ):
        if not start <= source < end or end - start < 2:
            return None
    spans = []
    for source, start, end in zip(
        header_positions,
        group_boundaries,
        group_boundaries[1:],
    ):
        value = grid[0][source]
        score = confidence[0][source]
        grid[0][source] = ""
        confidence[0][source] = 0.0
        grid[0][start] = value
        confidence[0][start] = score
        spans.append(
            {
                "row": 0,
                "column": start,
                "row_span": 1,
                "column_span": end - start,
                "role": "group_header",
            }
        )

    for row_index, confidence_row in enumerate(confidence):
        for column_index, score in enumerate(confidence_row):
            confidence_row[column_index] = (
                min(float(score), 0.77)
                if str(grid[row_index][column_index]).strip()
                else -1.0
            )
    return grid, confidence, spans, {
        "ruler_rows": expected_rows,
        "content_columns": content_column_count,
        "confirmed_row_mappings": len(row_mappings),
        "confirmed_column_rows": len(detected_column_rows),
        "group_boundaries": group_boundaries,
        "verified_low_confidence_cells": verified_cell_count,
    }


def _realign_split_spatial_rows_by_column_rank(
    grid: list[list[str]],
    grouped_rows: list[list[dict[str, Any]]],
    anchors: list[float],
    spans: list[dict[str, Any]],
) -> tuple[
    list[list[str]],
    list[list[float]],
    list[list[dict[str, Any]]],
    list[float],
] | None:
    """Repair one extra wrinkle-split row when every column has equal rank."""
    column_count = len(anchors)
    expected_rows = len(grid) - 1
    if spans or column_count < 3 or expected_rows < 3:
        return None
    ranked_columns: list[list[dict[str, Any]]] = [[] for _ in anchors]
    for entry in (entry for row in grouped_rows for entry in row):
        column = min(
            range(column_count),
            key=lambda index: abs(float(entry["center_x"]) - anchors[index]),
        )
        ranked_columns[column].append(entry)
    for column in ranked_columns:
        column.sort(key=lambda entry: float(entry["center_y"]))
    if any(len(column) != expected_rows for column in ranked_columns):
        return None

    repaired_grid: list[list[str]] = []
    repaired_confidence: list[list[float]] = []
    repaired_groups: list[list[dict[str, Any]]] = []
    repaired_centers: list[float] = []
    for row_index in range(expected_rows):
        entries = [column[row_index] for column in ranked_columns]
        values: list[str] = []
        scores: list[float] = []
        for entry in entries:
            text = str(entry["text"]).strip()
            score = float(entry["score"])
            minimum_score = 0.60 if _is_trusted_short_unit(text) else 0.78
            values.append(text if text and score >= minimum_score else "")
            scores.append(score if text and score >= minimum_score else -1.0)
        repaired_grid.append(values)
        repaired_confidence.append(scores)
        repaired_groups.append(entries)
        repaired_centers.append(float(np.median([entry["center_y"] for entry in entries])))
    return (
        repaired_grid,
        repaired_confidence,
        repaired_groups,
        repaired_centers,
    )


def _borderless_spatial_grid(
    boxes,
    texts,
    scores=None,
    return_geometry: bool = False,
):
    if boxes is None or texts is None or len(texts) == 0:
        empty_result = ([], [], [], False)
        return (*empty_result, {}) if return_geometry else empty_result

    score_values = list(scores) if scores is not None else [1.0] * len(texts)
    entries: list[dict[str, Any]] = []
    heights: list[float] = []
    for index, (box, text) in enumerate(zip(boxes, texts)):
        value = str(text).strip()
        if not value:
            continue
        points = np.asarray(box, dtype=float).reshape(-1, 2)
        left = float(points[:, 0].min())
        right = float(points[:, 0].max())
        top = float(points[:, 1].min())
        bottom = float(points[:, 1].max())
        height = max(1.0, bottom - top)
        entries.append(
            {
                "left": left,
                "right": right,
                "top": top,
                "bottom": bottom,
                "center_x": (left + right) * 0.5,
                "center_y": (top + bottom) * 0.5,
                "height": height,
                "text": value,
                "score": float(score_values[index]) if index < len(score_values) else 1.0,
            }
        )
        heights.append(height)
    if not entries:
        empty_result = ([], [], [], False)
        return (*empty_result, {}) if return_geometry else empty_result

    # A page detector occasionally gives the header and first data row boxes
    # close centres after perspective correction.  Centre distance alone then
    # puts both physical rows into one group and later joins e.g. ``编号 1``.
    # Keep the coarse threshold for speed, but require a meaningful vertical
    # overlap with the existing row band before treating text as one row.
    # Splitting a strongly skewed row is preferable to silently merging two
    # different records into one editable/exported cell.
    median_height = float(np.median(heights))
    row_threshold = max(8.0, median_height * 0.65)
    minimum_row_overlap = 0.45
    grouped_rows: list[list[dict[str, Any]]] = []
    row_centers: list[float] = []
    for entry in sorted(entries, key=lambda item: (item["center_y"], item["center_x"])):
        candidates = []
        for index, center in enumerate(row_centers):
            if abs(entry["center_y"] - center) > row_threshold:
                continue
            row_top = min(item["top"] for item in grouped_rows[index])
            row_bottom = max(item["bottom"] for item in grouped_rows[index])
            overlap = max(0.0, min(entry["bottom"], row_bottom) - max(entry["top"], row_top))
            reference_height = max(1.0, min(entry["height"], row_bottom - row_top))
            if overlap / reference_height >= minimum_row_overlap:
                candidates.append((abs(entry["center_y"] - center), index))
        if candidates:
            _, target = min(candidates)
            previous_count = len(grouped_rows[target])
            row_centers[target] = (
                row_centers[target] * previous_count + entry["center_y"]
            ) / (previous_count + 1)
        else:
            target = len(grouped_rows)
            grouped_rows.append([])
            row_centers.append(entry["center_y"])
        grouped_rows[target].append(entry)
    grouped_rows = [sorted(row, key=lambda item: item["center_x"]) for row in grouped_rows]

    # Text detection can split one English word at a contrast seam and place
    # the suffix in the next inferred column. Join only when the left fragment
    # is not a word, the concatenation is a dictionary word, and both boxes are
    # physically adjacent on the same row.
    english_words = _english_words()
    if english_words:
        repaired_rows = []
        for row in grouped_rows:
            repaired = []
            index = 0
            while index < len(row):
                current = dict(row[index])
                if index + 1 < len(row):
                    following = row[index + 1]
                    left_match = re.search(r"([A-Za-z]{2,})$", current["text"])
                    right_match = re.match(r"([A-Za-z]{1,})(.*)$", following["text"])
                    gap = float(following["left"] - current["right"])
                    if left_match and right_match:
                        left_word = left_match.group(1).casefold()
                        joined_word = (left_match.group(1) + right_match.group(1)).casefold()
                        if (
                            left_word not in english_words
                            and joined_word in english_words
                            and -median_height * 0.15 <= gap
                            <= max(12.0, median_height * 0.75)
                        ):
                            current["right"] = max(current["right"], following["right"])
                            current["top"] = min(current["top"], following["top"])
                            current["bottom"] = max(current["bottom"], following["bottom"])
                            current["center_x"] = (current["left"] + current["right"]) * 0.5
                            current["center_y"] = (current["top"] + current["bottom"]) * 0.5
                            current["height"] = max(1.0, current["bottom"] - current["top"])
                            current["text"] = current["text"] + following["text"]
                            current["score"] = min(current["score"], following["score"])
                            index += 1
                repaired.append(current)
                index += 1
            repaired_rows.append(repaired)
        grouped_rows = repaired_rows

    # A local paper ridge can move one cell vertically without moving the
    # neighbouring columns.  Centre-only grouping then creates a mostly full
    # row plus a one-cell phantom row.  Merge only complementary fragments:
    # they must be close, one side must be sparse, and they must not contain
    # competing boxes at the same horizontal anchor.  Consecutive real rows
    # contain overlapping anchors and therefore remain separate.
    typical_columns = max((len(row) for row in grouped_rows), default=1)
    merged_rows: list[list[dict[str, Any]]] = []
    merged_centers: list[float] = []
    row_index = 0
    while row_index < len(grouped_rows):
        current = grouped_rows[row_index]
        current_center = row_centers[row_index]
        if row_index + 1 < len(grouped_rows):
            following = grouped_rows[row_index + 1]
            following_center = row_centers[row_index + 1]
            sparse_fragment = min(len(current), len(following)) <= max(
                2, int(math.ceil(typical_columns * 0.35))
            )
            horizontal_conflict = any(
                abs(left["center_x"] - right["center_x"]) <= median_height * 1.8
                for left in current
                for right in following
            )
            if (
                sparse_fragment
                and not horizontal_conflict
                and abs(following_center - current_center) <= median_height * 1.15
            ):
                combined = sorted(current + following, key=lambda item: item["center_x"])
                merged_rows.append(combined)
                merged_centers.append(
                    (
                        current_center * len(current)
                        + following_center * len(following)
                    )
                    / len(combined)
                )
                row_index += 2
                continue
        merged_rows.append(current)
        merged_centers.append(current_center)
        row_index += 1
    grouped_rows = merged_rows
    row_centers = merged_centers

    if (
        len(grouped_rows) >= 5
        and len(grouped_rows[0]) == 1
        and len(grouped_rows[1]) >= 3
        and re.match(
            r"^(?:[一二三四五六七八九十]{1,3}|\d{1,2})[、.．]",
            grouped_rows[0][0]["text"],
        )
        and grouped_rows[0][0]["right"] - grouped_rows[0][0]["left"]
        < (
            max(entry["right"] for row in grouped_rows[1:5] for entry in row)
            - min(entry["left"] for row in grouped_rows[1:5] for entry in row)
        ) * 0.30
    ):
        grouped_rows = grouped_rows[1:]
        row_centers = row_centers[1:]

    if (
        len(grouped_rows) >= 5
        and len(grouped_rows[0]) == 1
        and 1 <= len(grouped_rows[1]) <= 2
        and len(grouped_rows[2]) >= 3
        and (
            sum(len(row) >= 3 for row in grouped_rows[2:5]) >= 2
            or (
                len(row_centers) >= 5
                and row_centers[2] - row_centers[1]
                >= float(np.median(np.diff(row_centers[2:]))) * 1.35
            )
        )
        and all(
            re.search(
                r"(?:填表人|记录单位|制表人|记录人|执行时间|填表日期|制表日期)\s*[:：]",
                entry["text"],
            )
            for entry in grouped_rows[1]
        )
    ):
        grouped_rows = grouped_rows[2:]
        row_centers = row_centers[2:]
    if (
        len(grouped_rows) >= 5
        and len(grouped_rows[0]) == 1
        and len(grouped_rows[1]) >= 3
        and row_centers[1] - row_centers[0]
        >= float(np.median(np.diff(row_centers[1:]))) * 1.45
    ):
        grouped_rows = grouped_rows[1:]
        row_centers = row_centers[1:]
    if len(grouped_rows) >= 4 and len(grouped_rows[-1]) <= 2 and len(grouped_rows[-2]) >= 3:
        footer = "".join(str(entry["text"]).replace(" ", "") for entry in grouped_rows[-1])
        earlier_gaps = np.diff(row_centers[:-1]).astype(float)
        typical_gap = float(np.median(earlier_gaps)) if earlier_gaps.size else 0.0
        if (
            re.fullmatch(r"\d{4}年\d{1,2}月\d{1,2}日", footer)
            and typical_gap > 0
            and row_centers[-1] - row_centers[-2] >= typical_gap * 1.20
        ):
            grouped_rows.pop()
            row_centers.pop()

    for note_row in range(5, len(grouped_rows)):
        column_count_before_note = len(grouped_rows[note_row - 1])
        previous = grouped_rows[note_row - 5:note_row]
        previous_gaps = np.diff(row_centers[note_row - 5:note_row])
        if (
            column_count_before_note >= 3
            and all(len(row) == column_count_before_note for row in previous)
            and all(len(row) <= 2 for row in grouped_rows[note_row:])
            and any(
                re.match(r"^(?:注|备注)\s*[:：]", str(entry["text"]))
                for entry in grouped_rows[note_row]
            )
            and previous_gaps.size
            and row_centers[note_row] - row_centers[note_row - 1]
            >= float(np.median(previous_gaps)) * 1.20
        ):
            grouped_rows = grouped_rows[:note_row]
            row_centers = row_centers[:note_row]
            break

    row_counts = [len(row) for row in grouped_rows if len(row) > 1]
    if not row_counts:
        text_result = (
            [[entry["text"]] for row in grouped_rows for entry in row],
            [],
            [],
            False,
        )
        return (*text_result, {}) if return_geometry else text_result
    frequencies = {count: row_counts.count(count) for count in set(row_counts) if count <= 32}
    if not frequencies:
        empty_result = ([], [], [], False)
        return (*empty_result, {}) if return_geometry else empty_result
    column_count = max(frequencies, key=lambda count: (frequencies[count], count))
    first_structured_row = next(
        (index for index, row in enumerate(grouped_rows) if len(row) > 1),
        0,
    )
    header_band_counts = {
        len(grouped_rows[index])
        for index in range(
            first_structured_row,
            min(len(grouped_rows), first_structured_row + 2),
        )
    }
    modal_frequency = frequencies[column_count]
    supported_header_counts = [
        count
        for count, frequency in frequencies.items()
        if count > column_count
        and count in header_band_counts
        and frequency >= 2
        and frequency >= math.ceil(modal_frequency * 0.5)
    ]
    if supported_header_counts:
        # Intentional blanks make N-1 boxes more frequent than N on sparse
        # tables. A complete header plus repeated complete body rows is
        # stronger structural evidence than that raw mode.
        column_count = max(supported_header_counts)
    if column_count < 12:
        wider_rows = [
            row for row in grouped_rows[first_structured_row + 1:]
            if len(row) == column_count + 1
        ]
        header = grouped_rows[first_structured_row]
        if len(wider_rows) >= 2 and len(header) >= column_count:
            wider_anchors = [
                float(np.median([row[column]["center_x"] for row in wider_rows]))
                for column in range(column_count + 1)
            ]
            wider_gaps = np.diff(wider_anchors)
            typical_wider_gap = float(np.median(wider_gaps))
            header_anchors = {
                min(range(len(wider_anchors)),
                    key=lambda column: abs(entry["center_x"] - wider_anchors[column]))
                for entry in header
                if min(abs(entry["center_x"] - anchor) for anchor in wider_anchors)
                <= typical_wider_gap * 0.25
            }
            if (
                typical_wider_gap >= 20
                and float(wider_gaps.min()) >= typical_wider_gap * 0.55
                and float(wider_gaps.max()) <= typical_wider_gap * 1.80
                and len(header_anchors) >= column_count
                and all(
                    all(
                        min(abs(entry["center_x"] - anchor) for anchor in wider_anchors)
                        <= typical_wider_gap * 0.25
                        for entry in row
                    )
                    for row in grouped_rows[first_structured_row:]
                )
            ):
                column_count += 1
    header_entries = grouped_rows[first_structured_row]
    if column_count < len(header_entries) <= min(12, column_count + 2):
        header_centers = [entry["center_x"] for entry in header_entries]
        gaps = np.diff(header_centers).astype(float)
        typical_gap = float(np.median(gaps)) if gaps.size else 0.0
        matching_body_rows = sum(
            len(row) >= column_count - 1
            and all(
                min(abs(entry["center_x"] - anchor) for anchor in header_centers)
                <= typical_gap * 0.25
                for entry in row
            )
            for row in grouped_rows[first_structured_row + 1:]
        )
        if (
            typical_gap >= 15.0
            and float(gaps.min()) >= typical_gap * 0.55
            and float(gaps.max()) <= typical_gap * 1.80
            and matching_body_rows >= max(4, math.ceil((len(grouped_rows) - first_structured_row - 1) * 0.60))
        ):
            column_count = len(header_entries)
    reference_rows = [row for row in grouped_rows if len(row) == column_count]
    anchors = [
        float(np.median([row[column_index]["center_x"] for row in reference_rows]))
        for column_index in range(column_count)
    ]

    if first_structured_row >= 2 and len(grouped_rows) - first_structured_row >= 5:
        body_centers = row_centers[first_structured_row + 1:]
        body_gaps = np.diff(body_centers)
        typical_body_gap = float(np.median(body_gaps)) if body_gaps.size else 0.0
        prefix_gaps = np.diff(row_centers[:first_structured_row + 1])
        if (
            typical_body_gap >= 12
            and prefix_gaps.size
            and float(prefix_gaps.max()) >= typical_body_gap * 1.40
            and all(len(row) <= 2 for row in grouped_rows[:first_structured_row])
            and sum(
                len(row) >= column_count - 1
                for row in grouped_rows[first_structured_row + 1:]
            ) >= 4
        ):
            grouped_rows = grouped_rows[first_structured_row:]
            row_centers = row_centers[first_structured_row:]
            first_structured_row = 0

    grid: list[list[str]] = []
    confidence_grid: list[list[float]] = []
    spans: list[dict[str, Any]] = []
    dense_row_count = 0
    minimum_dense_cells = max(2, (column_count * 3 + 4) // 5)

    for row_index, row in enumerate(grouped_rows):
        values = [""] * column_count
        confidences = [0.0] * column_count
        if row_index < first_structured_row and len(row) == 1:
            entry = row[0]
            if entry["score"] >= 0.78:
                values[0] = entry["text"]
                confidences[0] = entry["score"]
            else:
                values[0] = ""
                confidences[0] = -1.0
            spans.append(
                {
                    "row": row_index,
                    "column": 0,
                    "row_span": 1,
                    "column_span": column_count,
                    "role": "title",
                }
            )
            for column_index in range(1, column_count):
                confidences[column_index] = 0.0
            grid.append(values)
            confidence_grid.append(confidences)
            continue

        def assign(column_index: int, text: str, score: float) -> None:
            minimum_score = 0.60 if _is_trusted_short_unit(text) else 0.78
            if score < minimum_score:
                confidences[column_index] = -1.0
                return
            if values[column_index]:
                values[column_index] = f"{values[column_index]} {text}"
                confidences[column_index] = (
                    -1.0
                    if confidences[column_index] < 0
                    else min(confidences[column_index], score)
                )
            else:
                values[column_index] = text
                confidences[column_index] = score

        if row_index > first_structured_row and column_count >= 4:
            typical_gap = float(np.median(np.diff(anchors)))
            tail_start = 0
            while tail_start < min(len(row), column_count):
                entry = row[tail_start]
                if (
                    abs(entry["center_x"] - anchors[tail_start]) > typical_gap * 0.30
                    or entry["right"] - entry["left"] > typical_gap * 1.65
                ):
                    break
                tail_start += 1
            if (
                3 <= tail_start < len(row)
                and row[tail_start]["left"]
                <= row[tail_start - 1]["left"] + typical_gap * 0.20
            ):
                tail_start -= 1
            tail = row[tail_start:]
            if (
                2 <= tail_start <= column_count - 2
                and 1 <= len(tail) <= 2
                and len(row) <= column_count - 2
                and tail[0]["left"] >= (
                    anchors[tail_start - 1] + anchors[tail_start]
                ) * 0.5 - typical_gap * 0.20
                and max(entry["right"] for entry in tail)
                >= anchors[-1] - typical_gap * 0.50
                and sum(len(entry["text"]) for entry in tail) >= 6
            ):
                for column_index, entry in enumerate(row[:tail_start]):
                    assign(column_index, entry["text"], entry["score"])
                merged_text = "\n".join(
                    entry["text"] for entry in sorted(tail, key=lambda item: item["top"])
                )
                assign(tail_start, merged_text, min(entry["score"] for entry in tail))
                spans.append({
                    "row": row_index,
                    "column": tail_start,
                    "row_span": 1,
                    "column_span": column_count - tail_start,
                })
                grid.append(values)
                confidence_grid.append(confidences)
                continue

        for entry in row:
            margin = entry["height"] * 0.25
            covered = [
                index
                for index, anchor in enumerate(anchors)
                if entry["left"] - margin <= anchor <= entry["right"] + margin
            ]
            parts = entry["text"].split()
            if row_index < first_structured_row + 3:
                header_parts = _segment_concatenated_header_labels(entry["text"])
                if len(header_parts) == len(covered):
                    parts = header_parts
            if len(covered) > 1 and len(parts) == len(covered):
                for column_index, part in zip(covered, parts):
                    assign(column_index, part, entry["score"])
            else:
                column_index = min(
                    range(column_count),
                    key=lambda index: abs(entry["center_x"] - anchors[index]),
                )
                assign(column_index, entry["text"], entry["score"])

        nonempty_count = sum(bool(value) for value in values)
        if nonempty_count >= minimum_dense_cells:
            dense_row_count += 1
        grid.append(values)
        confidence_grid.append(confidences)

    realigned = _realign_split_spatial_rows_by_column_rank(
        grid,
        grouped_rows,
        anchors,
        spans,
    )
    if realigned is not None:
        grid, confidence_grid, grouped_rows, row_centers = realigned
        dense_row_count = sum(
            sum(bool(value) for value in row) >= minimum_dense_cells
            for row in grid
        )

    strong_layout = column_count >= 2 and dense_row_count >= 2
    if return_geometry:
        geometry = {
            "anchors": anchors,
            "row_centers": row_centers,
            "grouped_rows": grouped_rows,
            "first_structured_row": first_structured_row,
        }
        return grid, confidence_grid, spans, strong_layout, geometry
    return grid, confidence_grid, spans, strong_layout


def _merge_unruled_stacked_spatial_header(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
) -> bool:
    if (
        image.size == 0
        or spans
        or len(grid) < 4
        or not grid[0]
        or any(len(row) != len(grid[0]) for row in grid + confidence_grid)
    ):
        return False
    centers = [float(value) for value in geometry.get("row_centers", [])]
    grouped = geometry.get("grouped_rows", [])
    if len(centers) != len(grid) or len(grouped) != len(grid):
        return False
    gaps = np.diff(centers)
    if (
        gaps.size < 3
        or gaps[0] >= gaps[1] * 0.75
        or gaps[1] < float(np.median(gaps[2:])) * 1.35
        or any(sum(bool(str(value).strip()) for value in grid[row]) < len(grid[0]) - 1 for row in (0, 1))
    ):
        return False
    horizontal, _, _ = pipeline._grid_maps(image)
    left = int(image.shape[1] * 0.03)
    right = int(image.shape[1] * 0.97)

    def line_support(first: float, second: float) -> float:
        center = int(round((first + second) * 0.5))
        values = []
        for row in range(max(0, center - 5), min(image.shape[0], center + 6)):
            values.append(
                np.count_nonzero(horizontal[row, left:right]) / float(max(1, right - left))
            )
        return max(values, default=0.0)

    if line_support(centers[0], centers[1]) >= 0.10:
        return False
    if line_support(centers[1], centers[2]) < 0.45:
        return False
    for column in range(len(grid[0])):
        top = str(grid[0][column]).strip()
        bottom = str(grid[1][column]).strip()
        separator = "" if bottom.startswith(("(", "[", "{", "/")) else " "
        grid[0][column] = (top + separator + bottom).strip()
        confidence_grid[0][column] = min(
            float(confidence_grid[0][column]),
            float(confidence_grid[1][column]),
        )
    del grid[1]
    del confidence_grid[1]
    centers[0] = (centers[0] + centers[1]) * 0.5
    del centers[1]
    del grouped[1]
    geometry["row_centers"] = centers
    geometry["grouped_rows"] = grouped
    geometry["stacked_header_merged"] = True
    return True


def _grid_has_text_supported_outer_rows(
    image: np.ndarray,
    grid: tuple[list[int], list[int], np.ndarray],
    growth: int,
    *,
    leading_only: bool = False,
) -> bool:
    """Reject geometric expansion that adds blank camera margin as table rows."""
    columns, rows, _ = grid
    if not 1 <= int(growth) <= 6 or len(columns) < 3:
        return False
    horizontal, vertical, _ = pipeline._grid_maps(image)

    def interval_has_text(index: int) -> bool:
        return pipeline._leading_interval_has_text_components(
            image,
            int(rows[index]),
            int(rows[index + 1]),
            horizontal,
            vertical,
        )

    leading = all(interval_has_text(index) for index in range(int(growth)))
    if leading_only:
        return leading
    trailing_start = len(rows) - 1 - int(growth)
    trailing = all(
        interval_has_text(index)
        for index in range(trailing_start, len(rows) - 1)
    )
    return bool(leading and trailing)


def _aligned_borderless_spans_certificate(
    image: np.ndarray,
    grid: list[list[str]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
) -> dict[str, Any] | None:
    """Certify a regular text lattice, including safe merges, when rules are absent."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    anchors = [float(value) for value in geometry.get("anchors", [])]
    centers = [float(value) for value in geometry.get("row_centers", [])]
    grouped = geometry.get("grouped_rows", [])
    if (
        not 3 <= row_count <= 60
        or not 2 <= column_count <= 12
        or len(spans) > max(4, row_count // 2)
        or len(anchors) != column_count
        or len(centers) != row_count
        or len(grouped) != row_count
        or any(len(row) != column_count for row in grid)
    ):
        return None
    column_gaps = np.diff(anchors)
    row_gaps = np.diff(centers)
    column_gap = float(np.median(column_gaps))
    stacked_header = bool(geometry.get("stacked_header_merged", False))
    regular_row_gaps = row_gaps[1:] if stacked_header and row_gaps.size > 1 else row_gaps
    row_gap = float(np.median(regular_row_gaps))
    if (
        column_gap < 18 or row_gap < 8
        or min(column_gaps) < column_gap * 0.50
        or max(column_gaps) > column_gap * 2.0
        or min(regular_row_gaps) < row_gap * 0.45
        or max(regular_row_gaps) > row_gap * 2.1
        or (
            stacked_header
            and not 1.2 <= float(row_gaps[0]) / row_gap <= 3.2
        )
    ):
        return None
    merged_rows = {int(span.get("row", -1)) for span in spans}
    complete_rows = [
        row for index, row in enumerate(grouped)
        if index not in merged_rows and len(row) == column_count
        and all(
            abs(entry["center_x"] - anchors[column]) <= column_gap * 0.35
            for column, entry in enumerate(row)
        )
    ]
    minimum_complete_rows = (
        max(3, row_count - len(spans) - 1)
        if spans
        else max(3, int(math.ceil(row_count * 0.35)))
    )
    if len(complete_rows) < minimum_complete_rows:
        return None
    if not spans:
        for row_values, entries in zip(grid, grouped):
            assigned = {
                min(
                    range(column_count),
                    key=lambda column: abs(entry["center_x"] - anchors[column]),
                )
                for entry in entries
                if min(abs(entry["center_x"] - anchor) for anchor in anchors)
                <= column_gap * 0.35
            }
            expected = {
                column
                for column, value in enumerate(row_values)
                if str(value).strip()
            }
            if assigned != expected or len(assigned) != len(entries):
                return None
    for span in spans:
        row = int(span.get("row", -1))
        column = int(span.get("column", -1))
        if (
            not 1 <= row < row_count
            or not 2 <= column <= column_count - 2
            or span.get("row_span") != 1
            or span.get("column_span") != column_count - column
            or len(grouped[row]) not in (column + 1, column + 2)
            or len(grid[row][column].strip()) < 6
            or not all(
                abs(grouped[row][index]["center_x"] - anchors[index])
                <= column_gap * 0.35
                for index in range(column)
            )
            or max(entry["right"] for entry in grouped[row][column:])
            < anchors[-1] - column_gap * 0.50
            or re.sub(r"\s+", "", grid[row][column])
            != re.sub(
                r"\s+", "",
                "".join(entry["text"] for entry in grouped[row][column:]),
            )
        ):
            return None

    def boundaries(values: list[float], limit: int) -> list[int]:
        return [
            max(0, int(round(values[0] - (values[1] - values[0]) * 0.5))),
            *(int(round((left + right) * 0.5))
              for left, right in zip(values, values[1:])),
            min(limit, int(round(values[-1] + (values[-1] - values[-2]) * 0.5))),
        ]

    columns = boundaries(anchors, image.shape[1])
    rows = boundaries(centers, image.shape[0])
    if (
        any(right <= left for left, right in zip(columns, columns[1:]))
        or any(bottom <= top for top, bottom in zip(rows, rows[1:]))
    ):
        return None
    certificate = _new_structure_certificate(
        image, columns, rows, "borderless_aligned_text_boxes"
    )
    certificate["spans"] = copy.deepcopy(spans)
    certificate["ui_headers_processed"] = True
    return certificate


def _confirm_aligned_borderless_span_text(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> list[float]:
    """Require two additional model families to read every long merged line."""
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    crops = []
    targets = []
    for span in spans:
        row, column = int(span["row"]), int(span["column"])
        for entry in geometry["grouped_rows"][row][column:]:
            top = max(0, int(entry["top"]) - 3)
            bottom = min(image.shape[0], int(entry["bottom"]) + 4)
            left = max(0, int(entry["left"]) - 4)
            right = min(image.shape[1], int(entry["right"]) + 5)
            crop = image[top:bottom, left:right]
            if crop.size == 0:
                confidence_grid[row][column] = min(confidence_grid[row][column], 0.77)
                continue
            crops.append(crop)
            targets.append((
                row, column, str(entry["text"]).strip(), float(entry["score"])
            ))
    if not crops:
        return []

    scores = []
    output = ocr_engine.text_rec(TextRecInput(img=crops))
    _release_recognition_images(output)
    medium_readings = list(zip(output.txts, output.scores))
    scores.extend(float(score) for _, score in medium_readings)
    if len(medium_readings) != len(targets):
        for row, column, _, _ in targets:
            confidence_grid[row][column] = min(confidence_grid[row][column], 0.77)
        return scores
    additional = [
        index for index, (_, _, expected, page_score) in enumerate(targets)
        if not (
            str(medium_readings[index][0]).strip() == expected
            and float(medium_readings[index][1]) >= 0.995
            and page_score >= 0.999
        )
    ]
    v5_readings = {}
    if additional:
        _write_runtime_trace("model_construct", family="v5-server-independent")
        v5_recognizer = _build_independent_v5_text_recognizer(model_directory())
        output = v5_recognizer(TextRecInput(img=[crops[index] for index in additional]))
        _release_recognition_images(output)
        current = list(zip(output.txts, output.scores))
        scores.extend(float(score) for _, score in current)
        if len(current) == len(additional):
            v5_readings = dict(zip(additional, current))
    for index, (row, column, expected, _) in enumerate(targets):
        if (
            str(medium_readings[index][0]).strip() != expected
            or float(medium_readings[index][1]) < 0.95
            or (
                index in additional
                and (
                    index not in v5_readings
                    or str(v5_readings[index][0]).strip() != expected
                    or float(v5_readings[index][1]) < 0.90
                )
            )
        ):
            confidence_grid[row][column] = min(confidence_grid[row][column], 0.77)
        else:
            confidence_grid[row][column] = max(confidence_grid[row][column], 0.86)
    return scores


def _confirm_perspective_photo_risk_cells(
    source: np.ndarray,
    rectified: np.ndarray,
    rectification: dict[str, Any],
    certificate: dict[str, Any],
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    small_recognizer: Any,
    medium_recognizer: Any,
    single_source_numeric_cells: set[tuple[int, int]] | None = None,
) -> list[float]:
    """Re-read a few uncertain ruled cells from untouched camera pixels."""
    if (
        certificate.get("source") not in {
            "photographic_ruled_grid", "photographic_dense_ruled_cell_grid"
        }
        or list(certificate.get("source_shape", [])) != list(rectified.shape[:2])
    ):
        return []
    corners = np.asarray(rectification.get("corners", []), dtype=np.float32)
    columns = certificate.get("column_boundaries", [])
    rows = certificate.get("row_boundaries", [])
    if (
        corners.shape != (4, 2)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
    ):
        return []
    targets = [
        (row, column)
        for row, values in enumerate(grid)
        for column, value in enumerate(values)
        if str(value).strip() and float(confidence_grid[row][column]) < 0.78
    ]
    if not 1 <= len(targets) <= 16:
        return []
    height, width = rectified.shape[:2]
    to_source = cv2.getPerspectiveTransform(
        np.float32([
            [0, 0], [width - 1, 0],
            [width - 1, height - 1], [0, height - 1],
        ]),
        corners,
    )
    crops = []
    active = []
    for row, column in targets:
        left, right = columns[column : column + 2]
        top, bottom = rows[row : row + 2]
        polygon = np.float32([[[
            left + 1, top + 1,
        ], [right - 1, top + 1], [right - 1, bottom - 1], [left + 1, bottom - 1]]])
        transformed = cv2.perspectiveTransform(polygon, to_source)[0]
        x0, y0 = np.floor(transformed.min(axis=0)).astype(int)
        x1, y1 = np.ceil(transformed.max(axis=0)).astype(int)
        if column == 0:
            x0 -= 16
        crop = source[
            max(0, y0 - 2) : min(source.shape[0], y1 + 2),
            max(0, x0) : min(source.shape[1], x1 + 4),
        ]
        if crop.size:
            active.append((row, column))
            crops.append(crop)
    if not crops:
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    output = small_recognizer(TextRecInput(img=crops))
    _release_recognition_images(output)
    small_readings = list(zip(output.txts, output.scores))
    if len(small_readings) != len(active):
        return []
    scores = [float(score) for _, score in small_readings]
    single_source_numeric_cells = single_source_numeric_cells or set()
    medium_positions = [
        index for index, cell in enumerate(active)
        if cell not in single_source_numeric_cells
    ]
    medium_by_position: dict[int, tuple[str, float]] = {}
    if medium_positions:
        output = medium_recognizer(TextRecInput(img=[crops[index] for index in medium_positions]))
        _release_recognition_images(output)
        medium_readings = list(zip(output.txts, output.scores))
        if len(medium_readings) != len(medium_positions):
            return scores
        for position, reading in zip(medium_positions, medium_readings):
            medium_by_position[position] = reading
            scores.append(float(reading[1]))

    if not small_readings:
        return scores

    def uppercase_glyph_height(row: int, column: int) -> int:
        left, right = columns[column : column + 2]
        top, bottom = rows[row : row + 2]
        crop = rectified[top + 4 : bottom - 4, left + 4 : right - 4]
        if crop.size == 0 or crop.shape[0] < 8 or crop.shape[1] < 8:
            return 0
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        background = float(np.median(gray))
        _, _, stats, _ = cv2.connectedComponentsWithStats(
            np.uint8(gray < background - 28), 8
        )
        glyphs = [
            (int(area), int(glyph_height))
            for x, y, glyph_width, glyph_height, area in stats[1:]
            if area >= 3
            and x > 1 and x + glyph_width < gray.shape[1] - 1
            and y > 0 and y + glyph_height <= gray.shape[0]
            and glyph_width < gray.shape[1] * 0.70
        ]
        return max(glyphs)[1] if glyphs else 0

    corrections = []
    leading_omission_risks = _dense_leading_glyph_omission_risks(grid)
    for index, (row, column) in enumerate(active):
        small_text, small_score = small_readings[index]
        current = str(grid[row][column]).strip()
        if (row, column) in single_source_numeric_cells:
            if (
                re.fullmatch(r"\d{1,3}", current)
                and str(small_text).strip() == current
                and float(small_score) >= 0.90
            ):
                confidence_grid[row][column] = 0.86
            continue
        medium_text, medium_score = medium_by_position[index]
        selected = str(medium_text).strip()
        if (
            (row, column) in leading_omission_risks
            and str(small_text).strip() == selected
            and len(selected) == len(current) + 1
            and selected.endswith(current)
            and float(small_score) >= 0.90
            and float(medium_score) >= 0.90
            and sum(str(values[column]).strip() == selected for values in grid) >= 2
        ):
            grid[row][column] = selected
            confidence_grid[row][column] = 0.86
            continue
        if (
            _is_horizontal_mark_confusable(current)
            and _is_horizontal_mark_confusable(small_text)
            and _is_horizontal_mark_confusable(medium_text)
            and float(small_score) >= 0.55
            and float(medium_score) >= 0.70
            and _recover_horizontal_mark(crops[index], allow_shorter=True)
        ):
            coded_peers = sum(
                bool(re.fullmatch(
                    r"[A-Z](?:[、，,][A-Z])*",
                    str(grid[other][column]).strip(),
                ))
                for other in range(1, len(grid)) if other != row
            )
            if current in {"一", "-", "—", "–", "−"} and coded_peers >= 3:
                grid[row][column] = "—"
            confidence_grid[row][column] = 0.86
            continue
        if (
            re.fullmatch(r"\d{1,3}", current)
            and re.fullmatch(r"\d{1,3}", selected)
            and str(small_text).strip() == selected
            and min(float(small_score), float(medium_score)) >= 0.85
        ):
            grid[row][column] = selected
            confidence_grid[row][column] = 0.86
            continue
        if (
            re.fullmatch(r"[A-Z]{1,2}\d{1,3}-\d{3,6}", selected)
            and str(small_text).strip() == selected
            and float(small_score) >= 0.90
            and float(medium_score) >= 0.85
        ):
            grid[row][column] = selected
            confidence_grid[row][column] = 0.86
            continue
        if (
            current == "I"
            and str(small_text).strip() == "1"
            and selected == "I"
            and float(medium_score) >= 0.80
            and min(crops[index].shape[:2]) >= 20
        ):
            isolated = [
                _tight_cell_ink_crop(crops[index][pad:-pad, pad:-pad])
                for pad in (2, 6)
            ]
            if all(view.size for view in isolated):
                proof = []
                for recognizer in (small_recognizer, medium_recognizer):
                    output = recognizer(TextRecInput(img=isolated))
                    _release_recognition_images(output)
                    proof.append(list(zip(output.txts, output.scores)))
                if (
                    all(len(family) == 2 for family in proof)
                    and all(
                        str(proof[1][view][0]).strip() == "I"
                        and float(proof[1][view][1]) >= 0.75
                        for view in range(2)
                    )
                    and any(
                        str(proof[0][view][0]).strip() == "I"
                        and float(proof[0][view][1]) >= 0.85
                        for view in range(2)
                    )
                    and all(
                        str(proof[0][view][0]).strip() in {"I", "1", "l"}
                        and float(proof[0][view][1]) >= 0.70
                        for view in range(2)
                    )
                ):
                    confidence_grid[row][column] = 0.86
                    continue
        if (
            re.fullmatch(r"[A-Za-z]", current)
            and str(small_text).strip().casefold() == current.casefold()
            and selected.casefold() == current.casefold()
            and min(float(small_score), float(medium_score)) >= 0.50
            and max(float(small_score), float(medium_score)) >= 0.70
        ):
            peers = [
                uppercase_glyph_height(other, column)
                for other in range(1, len(grid))
                if other != row
                and re.fullmatch(r"[A-Z]", str(grid[other][column]).strip())
                and float(confidence_grid[other][column]) >= 0.85
            ]
            peers = [height for height in peers if height >= 7]
            target_height = uppercase_glyph_height(row, column)
            if (
                len(peers) >= 3
                and target_height >= 7
                and 0.85 <= target_height / float(np.median(peers)) <= 1.20
            ):
                grid[row][column] = current.upper()
                confidence_grid[row][column] = 0.86
                continue
        tight_case_peers = sum(
            bool(re.fullmatch(r"[A-Z]", str(values[column]).strip()))
            and float(confidence_grid[other][column]) >= 0.85
            for other, values in enumerate(grid)
            if other != row
        )
        if (
            re.fullmatch(r"[a-z]", current)
            and str(small_text).strip().casefold() == current.casefold()
            and selected.casefold() == current.casefold()
            and float(small_score) >= 0.55
            and float(medium_score) >= 0.60
            and tight_case_peers >= 3
        ):
            grid[row][column] = current.upper()
            confidence_grid[row][column] = 0.86
            continue
        if (
            str(small_text).strip() != selected
            or not re.fullmatch(r"[A-Za-z]{1,3}[、，,./][A-Za-z]{1,3}", selected)
            or float(small_score) < 0.80
            or float(medium_score) < 0.85
            or (
                selected != current
                and (
                    _text_edit_distance(selected, current) > 2
                    or (
                        _text_edit_distance(selected, current) == 2
                        and min(float(small_score), float(medium_score)) < 0.90
                    )
                )
            )
        ):
            continue
        if selected == current:
            confidence_grid[row][column] = 0.86
        else:
            corrections.append((index, row, column, selected))
    if corrections:
        _write_runtime_trace("model_construct", family="v5-server-independent")
        v5_recognizer = _build_independent_v5_text_recognizer(model_directory())
        output = v5_recognizer(TextRecInput(img=[crops[index] for index, _, _, _ in corrections]))
        _release_recognition_images(output)
        v5_readings = list(zip(output.txts, output.scores))
        scores.extend(float(score) for _, score in v5_readings)
        if len(v5_readings) == len(corrections):
            for (_, row, column, selected), (text, score) in zip(
                corrections, v5_readings
            ):
                score_floor = (
                    0.50
                    if re.fullmatch(r"[A-Z]{1,2}\d{1,3}-\d{3,6}", selected)
                    else 0.75
                )
                if str(text).strip() == selected and float(score) >= score_floor:
                    grid[row][column] = selected
                    confidence_grid[row][column] = 0.86
    return scores


def _split_stacked_spatial_entries(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any] | None,
) -> None:
    """Split one detector box that visibly spans consecutive physical rows."""
    if not geometry or len(grid) < 2 or not grid[0]:
        return
    anchors = [float(value) for value in geometry.get("anchors", [])]
    row_centers = [float(value) for value in geometry.get("row_centers", [])]
    grouped_rows = list(geometry.get("grouped_rows", []))
    if (
        len(anchors) != len(grid[0])
        or len(row_centers) != len(grid)
        or len(grouped_rows) != len(grid)
    ):
        return
    boundaries = [
        (left + right) * 0.5 for left, right in zip(row_centers, row_centers[1:])
    ]
    row_gaps = [right - left for left, right in zip(row_centers, row_centers[1:])]
    for source_row, entries in enumerate(grouped_rows):
        for entry in entries:
            text = str(entry.get("text", "")).strip()
            stacked_ordinal = bool(re.fullmatch(r"\d{4}", text))
            if not stacked_ordinal and not re.fullmatch(r"[\u3400-\u9fff]{2,8}", text):
                continue
            top = float(entry.get("top", 0.0))
            bottom = float(entry.get("bottom", 0.0))
            height = max(0.0, bottom - top)
            crossed = [
                index
                for index, boundary in enumerate(boundaries, start=1)
                if top < boundary < bottom
                and 0.12 <= (boundary - top) / max(1.0, height) <= 0.88
            ]
            if not crossed:
                continue
            first_row = crossed[0] - 1
            last_row = crossed[-1]
            covered_rows = list(range(first_row, last_row + 1))
            if (
                crossed != list(range(crossed[0], crossed[-1] + 1))
                or len(text) % len(covered_rows)
                or first_row < 0
                or last_row >= len(grid)
            ):
                continue
            relevant_gaps = row_gaps[first_row:last_row]
            if not relevant_gaps or height < min(relevant_gaps) * (len(covered_rows) - 0.75):
                continue
            column = min(
                range(len(anchors)),
                key=lambda index: abs(float(entry.get("center_x", 0.0)) - anchors[index]),
            )
            if str(grid[source_row][column]).strip() != text:
                continue
            if any(
                row != source_row and str(grid[row][column]).strip()
                for row in covered_rows
            ):
                continue
            part_length = len(text) // len(covered_rows)
            parts = [
                text[offset : offset + part_length]
                for offset in range(0, len(text), part_length)
            ]
            if stacked_ordinal and not (
                len(parts) == 2
                and part_length == 2
                and first_row > 0
                and last_row + 1 < len(grid)
                and str(grid[first_row - 1][column]).isdigit()
                and str(grid[last_row + 1][column]).isdigit()
                and int(grid[first_row - 1][column]) + 1 == int(parts[0])
                and int(parts[1]) + 1 == int(grid[last_row + 1][column])
            ):
                continue
            grid[source_row][column] = ""
            confidence_grid[source_row][column] = 0.0
            score = float(entry.get("score", 0.0))
            for row, part in zip(covered_rows, parts):
                grid[row][column] = part
                confidence_grid[row][column] = score


def _spatial_cell_crop(
    image: np.ndarray,
    geometry: dict[str, Any],
    row: int,
    column: int,
) -> np.ndarray:
    anchors = geometry.get("anchors", [])
    centers = geometry.get("row_centers", [])
    if (
        len(anchors) < 2 or len(centers) < 2
        or not 0 <= column < len(anchors) or not 0 <= row < len(centers)
    ):
        return image[0:0, 0:0]

    def bounds(values: list[float], index: int, limit: int) -> tuple[int, int]:
        before = values[index] - values[index - 1] if index else values[1] - values[0]
        after = values[index + 1] - values[index] if index + 1 < len(values) else values[-1] - values[-2]
        return (
            max(0, int(round(values[index] - before * 0.5)) + 3),
            min(limit, int(round(values[index] + after * 0.5)) - 3),
        )

    left, right = bounds(anchors, column, image.shape[1])
    top, bottom = bounds(centers, row, image.shape[0])
    return image[top:bottom, left:right]


def _striped_borderless_certificate(
    image: np.ndarray,
    grid: list[list[str]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
    *,
    minimum_dense_row_ratio: float = 0.80,
) -> dict[str, Any] | None:
    minimum_certified_rows = 6
    title_span = [{
        "row": 0,
        "column": 0,
        "row_span": 1,
        "column_span": len(grid[0]) if grid and grid[0] else 0,
        "role": "title",
    }]
    has_title_span = spans == title_span
    if (
        (spans and not has_title_span)
        or len(grid) < minimum_certified_rows or not 3 <= len(grid[0]) <= 12
        or any(len(row) != len(grid[0]) for row in grid)
    ):
        return None
    anchors = [float(value) for value in geometry.get("anchors", [])]
    centers = [float(value) for value in geometry.get("row_centers", [])]
    if len(anchors) != len(grid[0]) or len(centers) != len(grid):
        return None
    gaps = np.diff(centers).astype(float)
    typical = float(np.median(gaps[1:])) if gaps.size > 1 else 0.0
    if (
        typical < 12.0
        or float(gaps.min()) < typical * 0.70
        or float(gaps.max()) > typical * 1.30
        or centers[0] < image.shape[0] * 0.02
        or centers[-1] > image.shape[0] * 0.95
        or (
            sum(bool(value) for value in grid[0]) != 1
            if has_title_span
            else sum(bool(value) for value in grid[0]) < len(grid[0]) - 1
        )
        or sum(
            sum(bool(value) for value in row) >= len(grid[0]) - 1
            for row in grid[1:]
        ) < (len(grid) - 1) * minimum_dense_row_ratio
    ):
        return None
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    stripe_channels = (
        gray,
        cv2.cvtColor(image, cv2.COLOR_BGR2LAB)[:, :, 2],
    )
    parity = np.asarray([(-1.0) ** index for index in range(len(centers) - 1)])
    positions = np.arange(len(parity), dtype=float)
    supported_x = []
    for left_anchor, right_anchor in zip(anchors, anchors[1:]):
        x = int(round((left_anchor + right_anchor) * 0.5))
        if not 12 <= x < gray.shape[1] - 12:
            continue
        for channel in stripe_channels:
            brightness = np.asarray([
                float(np.mean(channel[max(0, int(round(y)) - 4):int(round(y)) + 5,
                                      x - 12:x + 13]))
                for y in centers[1:]
            ])
            if not np.isfinite(brightness).all():
                continue
            residual = brightness - np.polyval(np.polyfit(positions, brightness, 1), positions)
            variation = float(np.std(residual))
            if variation < 0.4:
                continue
            correlation = float(np.mean(residual * parity) / variation)
            if abs(correlation) >= 0.90 and abs(float(np.mean(residual * parity))) >= 0.4:
                supported_x.append(x)
                break
    if len(supported_x) < 2 or supported_x[-1] - supported_x[0] < gray.shape[1] * 0.10:
        return None

    def boundaries(values: list[float], limit: int) -> list[int]:
        middle = [(first + second) * 0.5 for first, second in zip(values, values[1:])]
        return [
            max(0, int(round(values[0] - (middle[0] - values[0])))),
            *[int(round(value)) for value in middle],
            min(limit - 1, int(round(values[-1] + (values[-1] - middle[-1])))),
        ]

    columns = boundaries(anchors, image.shape[1])
    rows = boundaries(centers, image.shape[0])
    if min(np.diff(columns)) <= 0 or min(np.diff(rows)) <= 0:
        return None
    edges = cv2.Canny(gray, 40, 100)
    table_width = max(1, columns[-1] - columns[0])
    lines = cv2.HoughLinesP(
        edges, 1, np.pi / 720,
        threshold=max(60, table_width // 15),
        minLineLength=max(120, int(table_width * 0.35)),
        maxLineGap=max(20, int(table_width * 0.08)),
    )
    if lines is None:
        return None
    center_x = (anchors[0] + anchors[-1]) * 0.5
    border_lines = []
    for x1, y1, x2, y2 in lines.reshape(-1, 4):
        if abs(int(x2) - int(x1)) < table_width * 0.45:
            continue
        # 2026-10-30（lead 复查，高）：`cv2.HoughLinesP` 返回的端点方向是**任意**的。
        # 旧写法 `slope = (y2-y1)/max(1.0, x2-x1)` 在 x1>x2 时分母恒为 1.0，
        # 一条 800px 长、3px 落差的水平线会算出 |slope|=3.0 而被 `<=0.14` 丢弃
        # （约一半横线如此），随后的投影也错位 ⇒ `border_lines` 只剩"左→右且完全水平"
        # 的段 ⇒ 下面的上下边界校验大概率失败 ⇒ 整条 striped-borderless 证书路线
        # **静默降级**（证书恒 None）。先把端点按 x 归一化方向再算斜率。
        if x2 < x1:
            x1, y1, x2, y2 = x2, y2, x1, y1
        slope = (float(y2) - float(y1)) / max(1.0, float(x2) - float(x1))
        if abs(slope) <= 0.14:
            border_lines.append(float(y1) + slope * (center_x - float(x1)))
    tolerance = max(10.0, typical * 0.30)
    if any(
        not any(abs(line_y - boundary) <= tolerance for line_y in border_lines)
        for boundary in (rows[0], rows[-1])
    ):
        return None
    certificate = _new_structure_certificate(
        image, columns, rows, "photographic_striped_borderless_grid"
    )
    certificate["ui_headers_processed"] = True
    certificate["spans"] = spans
    certificate["stripe_support_x"] = supported_x
    return certificate


def _striped_medium_two_view_support(
    mobile: tuple[str, float],
    small: tuple[str, float],
    tight_medium: tuple[str, float],
    second_medium: tuple[str, float],
) -> bool:
    tight_text = _comparable_text(tight_medium[0])
    second_text = _comparable_text(second_medium[0])
    if (
        not tight_text
        or tight_text != second_text
        or len(tight_text) < 3
        or tight_medium[1] < 0.84
        or second_medium[1] < 0.93
    ):
        return False
    return any(
        score >= 0.50
        and _text_edit_distance(_comparable_text(text), tight_text) <= 1
        for text, score in (mobile, small)
    )


def _striped_body_three_family_support(
    mobile: tuple[str, float],
    small: tuple[str, float],
    medium: tuple[str, float],
) -> bool:
    keys = tuple(_comparable_text(value) for value, _ in (mobile, small, medium))
    scores = tuple(float(score) for _, score in (mobile, small, medium))
    return bool(
        keys[0]
        and keys[0] == keys[1] == keys[2]
        and min(scores) >= 0.60
        and scores[2] >= 0.80
        and max(scores) >= 0.80
    )


def _striped_conflict_needs_cjk_multiview(
    conflict: tuple[Any, ...],
    server_reading: tuple[str, float],
) -> bool:
    return any(
        re.fullmatch(r"[\u3400-\u9fff]{1,4}", _comparable_text(value))
        for value in (conflict[1], conflict[3], conflict[5], server_reading[0])
    )


def _striped_title_multiview_selection(
    small_views: tuple[tuple[str, float], ...],
    medium_views: tuple[tuple[str, float], ...],
) -> str | None:
    if len(small_views) < 2 or len(medium_views) < 2:
        return None
    small_keys = [_comparable_text(value) for value, _ in small_views]
    medium_keys = [_comparable_text(value) for value, _ in medium_views]
    candidate = medium_keys[0]
    if (
        not candidate
        or len(candidate) < 4
        or len(set(small_keys)) != 1
        or len(set(medium_keys)) != 1
        or small_keys[0] != candidate
        or min(float(score) for _, score in small_views) < 0.93
        or min(float(score) for _, score in medium_views) < 0.95
    ):
        return None
    return str(medium_views[0][0]).strip()


def _verify_regular_numeric_spatial_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> list[float]:
    """Recheck short missing numbers and uncertain row labels in a regular text lattice."""
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    if (
        not 5 <= len(grid) <= 80
        or not 3 <= len(grid[0]) <= 8
        or len(geometry.get("row_centers", [])) != len(grid)
        or len(geometry.get("anchors", [])) != len(grid[0])
    ):
        return []
    gaps = np.diff(geometry["row_centers"])
    typical = float(np.median(gaps))
    if typical < 12 or float(gaps.min()) < typical * 0.80 or float(gaps.max()) > typical * 1.20:
        return []
    numeric_columns = {
        column for column in range(1, len(grid[0]))
        if sum(bool(re.fullmatch(r"\d+", str(row[column]).strip())) for row in grid[1:])
        >= (len(grid) - 1) * 0.60
    }
    if len(numeric_columns) < 2:
        return []

    def read(recognizer: Any, crop: np.ndarray) -> tuple[str, float] | None:
        output = recognizer(TextRecInput(img=[crop.copy()]))
        readings = list(zip(output.txts, output.scores))
        _release_recognition_images(output)
        return (str(readings[0][0]).strip(), float(readings[0][1])) if len(readings) == 1 else None

    scores = []
    missing = [
        (row, column) for row in range(1, len(grid)) for column in numeric_columns
        if not str(grid[row][column]).strip()
        and sum(bool(str(value).strip()) for value in grid[row]) >= len(grid[0]) - 1
    ]
    if len(missing) <= 8:
        for row, column in missing:
            raw = _spatial_cell_crop(image, geometry, row, column)
            tight = _tight_cell_ink_crop(raw)
            if raw.size == 0 or tight.size == 0 or tight.shape[1] >= raw.shape[1] * 0.80:
                continue
            first = read(ocr_engine.fast_text_rec, raw)
            second = read(ocr_engine.fast_text_rec, tight)
            third = read(ocr_engine.text_rec, tight)
            if first is None or second is None or third is None:
                continue
            scores.extend((first[1], second[1], third[1]))
            if (
                first[0] == second[0] == third[0]
                and re.fullmatch(r"\d{1,4}", first[0])
                and first[1] >= 0.95
                and min(second[1], third[1]) >= 0.99
            ):
                grid[row][column] = first[0]
                confidence_grid[row][column] = 0.86

    uncertain_labels = [
        row for row in range(1, len(grid))
        if re.fullmatch(r"[\u3400-\u9fff]{2,8}", str(grid[row][0]))
        and 0.0 < confidence_grid[row][0] < 0.95
    ]
    if 0 < len(uncertain_labels) <= 8:
        independent = _build_independent_v5_text_recognizer(model_directory())
        for row in uncertain_labels:
            raw = _spatial_cell_crop(image, geometry, row, 0)
            if raw.size == 0:
                continue
            bright = cv2.convertScaleAbs(raw, alpha=1.5, beta=10)
            medium = read(ocr_engine.text_rec, raw)
            medium_bright = read(ocr_engine.text_rec, bright)
            v5 = read(independent, raw)
            if medium is None or medium_bright is None or v5 is None:
                continue
            scores.extend((medium[1], medium_bright[1], v5[1]))
            current = _comparable_text(grid[row][0])
            proposed = _comparable_text(medium[0])
            if (
                proposed == _comparable_text(medium_bright[0]) == _comparable_text(v5[0])
                and re.fullmatch(r"[\u3400-\u9fff]{2,8}", proposed)
                and len(proposed) == len(current)
                and _text_edit_distance(current, proposed) == 1
                and medium[1] >= 0.90 and medium_bright[1] >= 0.95 and v5[1] >= 0.90
            ):
                grid[row][0] = medium[0]
                confidence_grid[row][0] = 0.86
        del independent
    return scores


def _regular_numeric_borderless_certificate(
    image: np.ndarray,
    grid: list[list[str]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
) -> dict[str, Any] | None:
    if spans or len(grid) < 5 or not 3 <= len(grid[0]) <= 8:
        return None
    column_count = len(grid[0])
    blank_count = sum(not str(value).strip() for row in grid for value in row)
    sparse = blank_count > 0
    anchors = [float(value) for value in geometry.get("anchors", [])]
    centers = [float(value) for value in geometry.get("row_centers", [])]
    grouped = geometry.get("grouped_rows", [])
    header_verified = bool(geometry.get("header_cells_verified"))
    if sparse and not header_verified and grouped and len(anchors) == column_count:
        populated = {column for column, value in enumerate(grid[0]) if str(value).strip()}
        matched = {
            column
            for entry in grouped[0]
            for column in [min(
                range(column_count),
                key=lambda index: abs(float(entry["center_x"]) - anchors[index]),
            )]
            if float(entry.get("score", 0.0)) >= 0.98
            and _comparable_text(entry.get("text", ""))
            == _comparable_text(grid[0][column])
        }
        header_verified = bool(
            len(populated) >= column_count - 1
            and len(grouped[0]) == len(populated) == len(matched)
        )
    if (
        len(anchors) != column_count
        or len(centers) != len(grid)
        or len(grouped) != len(grid)
        or any(len(row) != column_count for row in grid)
        or (
            sparse and (
                not header_verified
                or blank_count > len(grid) * column_count * 0.40
                or sum(len(row) >= column_count - 1 for row in grouped[1:])
                < max(3, (len(grid) - 1) * 0.60)
            )
        )
        or (
            not sparse and (
                any(len(row) != column_count for row in grouped)
                or any(not all(str(value).strip() for value in row) for row in grid)
            )
        )
    ):
        return None
    row_gaps = np.diff(centers)
    column_gaps = np.diff(anchors)
    typical_row = float(np.median(row_gaps))
    typical_column = float(np.median(column_gaps))
    if (
        typical_row < 12 or typical_column < 20
        or float(row_gaps.min()) < typical_row * 0.80
        or float(row_gaps.max()) > typical_row * 1.20
        or float(column_gaps.min()) < typical_column * (0.40 if sparse else 0.55)
        or float(column_gaps[1:].max()) > typical_column * 1.60
        or float(column_gaps[0]) > typical_column * (2.5 if sparse else 1.60)
    ):
        return None
    low_score_count = 0
    for row in grouped:
        for column, entry in enumerate(row):
            score = float(entry.get("score", 0.0))
            low_score_count += score < 0.90
            nearest = min(
                range(column_count),
                key=lambda index: abs(float(entry.get("center_x", -1)) - anchors[index]),
            )
            aligned = bool(
                abs(float(entry.get("center_x", -1)) - anchors[nearest])
                <= typical_column * (0.30 if sparse else 0.18)
                or (
                    sparse and nearest == 0
                    and float(entry.get("left", -1)) < anchors[0] + typical_column * 0.20
                    and float(entry.get("right", 1e9)) < anchors[1] - typical_column * 0.10
                )
            )
            if score < 0.85 or not aligned:
                return None
    if low_score_count > max(1, len(grid) * column_count // 50):
        return None
    numeric_columns = [
        column for column in range(column_count)
        if sum(
            bool(re.fullmatch(r"[+-]?\d+(?:[.,]\d+)?", str(row[column]).strip()))
            for row in grid[1:]
        ) >= (len(grid) - 1) * (0.65 if sparse else 0.80)
    ]
    if len(numeric_columns) < 2:
        return None

    def boundaries(values: list[float], limit: int) -> list[int]:
        middle = [(left + right) * 0.5 for left, right in zip(values, values[1:])]
        return [
            max(0, int(round(values[0] - (middle[0] - values[0])))),
            *[int(round(value)) for value in middle],
            min(limit - 1, int(round(values[-1] + values[-1] - middle[-1]))),
        ]

    columns = boundaries(anchors, image.shape[1])
    rows = boundaries(centers, image.shape[0])
    if min(np.diff(columns)) <= 0 or min(np.diff(rows)) <= 0:
        return None
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    for row in range(len(grid)):
        for column in range(column_count):
            crop = gray[
                rows[row] + 2:rows[row + 1] - 2,
                columns[column] + 2:columns[column + 1] - 2,
            ]
            if crop.size == 0:
                return None
            if sparse:
                cutoff = min(185, int(np.median(crop)) - 15)
                _, _, components, _ = cv2.connectedComponentsWithStats(
                    np.uint8(crop < cutoff), 8
                )
                glyphs = [
                    (x, y, width, height)
                    for x, y, width, height, area in components[1:]
                    if area >= 8 and height >= 8 and width >= 2
                ]
                if str(grid[row][column]).strip() and not glyphs:
                    return None
                if not str(grid[row][column]).strip():
                    for x, y, width, height in glyphs:
                        if height >= crop.shape[0] * 0.85 or width >= crop.shape[1] * 0.75:
                            continue
                        glyph_left = columns[column] + 2 + x
                        glyph_right = glyph_left + width
                        glyph_top = rows[row] + 2 + y
                        glyph_bottom = glyph_top + height
                        if not any(
                            abs(owner - column) == 1
                            and str(grid[row][owner]).strip()
                            and float(entry["left"]) - 4 <= glyph_left
                            and glyph_right <= float(entry["right"]) + 4
                            and float(entry["top"]) - 4 <= glyph_top
                            and glyph_bottom <= float(entry["bottom"]) + 4
                            and min(
                                abs(glyph_left - columns[column]),
                                abs(columns[column + 1] - glyph_right),
                            ) <= (columns[column + 1] - columns[column]) * 0.18
                            for entry in grouped[row]
                            for owner in [min(
                                range(column_count),
                                key=lambda index: abs(entry["center_x"] - anchors[index]),
                            )]
                        ):
                            return None
            else:
                cutoff = min(170, int(np.median(crop)) - 20)
                if np.count_nonzero(crop < cutoff) < 8:
                    return None
    certificate = _new_structure_certificate(
        image, columns, rows, "photographic_regular_numeric_text_lattice"
    )
    certificate["ui_headers_processed"] = True
    certificate["numeric_columns"] = numeric_columns
    certificate["visibly_empty_cells_checked"] = sparse
    return certificate


def _recognize_certified_numeric_text_lattice(
    request: dict[str, Any],
    image_path: Path,
    rectified: np.ndarray,
    rectified_path: Path,
    source_quality: dict[str, Any],
    rectified_quality: dict[str, Any],
    rectification: dict[str, Any],
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
    ocr_engine: Any,
    budget: _RecognitionBudget,
) -> dict[str, Any] | None:
    """Finish a visibly checked numeric lattice after independent text-box OCR."""
    certificate = _regular_numeric_borderless_certificate(
        rectified, grid, spans, geometry
    )
    if certificate is None or not _structure_certificate_matches(
        certificate, grid, spans
    ):
        return None
    anchors = [float(value) for value in geometry["anchors"]]
    targets = []
    crops = []
    for row, entries in enumerate(geometry["grouped_rows"]):
        occupied = set()
        for entry in entries:
            column = min(
                range(len(anchors)),
                key=lambda index: abs(entry["center_x"] - anchors[index]),
            )
            if column in occupied or str(grid[row][column]).strip() != str(entry["text"]).strip():
                return None
            occupied.add(column)
            top = max(0, int(entry["top"]) - 3)
            bottom = min(rectified.shape[0], int(entry["bottom"]) + 4)
            left = max(0, int(entry["left"]) - 4)
            right = min(rectified.shape[1], int(entry["right"]) + 5)
            crop = rectified[top:bottom, left:right]
            if crop.size == 0:
                return None
            crops.append(crop)
            targets.append((row, column, str(entry["text"]).strip()))
    if not crops:
        return None
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    output = ocr_engine.text_rec(TextRecInput(img=crops))
    _release_recognition_images(output)
    readings = list(zip(output.txts, output.scores))
    if len(readings) != len(targets) or any(
        str(text).strip() != expected or float(score) < 0.98
        for (_, _, expected), (text, score) in zip(targets, readings)
    ):
        return None
    for row, column, _ in targets:
        confidence_grid[row][column] = max(float(confidence_grid[row][column]), 0.86)
    for row, values in enumerate(grid):
        for column, value in enumerate(values):
            if not str(value).strip():
                confidence_grid[row][column] = 0.0
    _write_image(rectified_path, rectified)
    _normalize_ocr_unit_symbols(grid)
    rectification["regular_numeric_borderless_verified"] = True
    result = pipeline.build_result(
        grid,
        confidence=float(np.mean([score for _, score in readings])),
        confidences=confidence_grid,
        engine="PP-OCRv6 Small + Medium certified numeric text lattice",
        rectified_image=str(rectified_path),
        spans=[],
    )
    result.update({
        "source_image": str(image_path),
        "image_quality": {
            "source": source_quality,
            "rectified": rectified_quality,
            "issues": rectified_quality.get("issues", []),
            "issue_labels": rectified_quality.get("issue_labels", []),
            "needs_recapture": bool(rectified_quality.get("needs_recapture", False)),
        },
        "rectification": rectification,
        "document_mode": "borderless_columns",
        "structure_verified": True,
        "structure_certificate": certificate,
        "withheld_numeric_segments": [],
        "recognition_state": "verified",
        "publication_blocked": False,
        "publication_block_reasons": [],
        "structure_review_required": False,
        "structure_warnings": [],
        "processing_notices": [],
        "memory_mode": _ACTIVE_RECOGNITION_MEMORY_MODE,
        "degraded": bool(budget.limited or budget.reached()),
        "deadline_seconds": budget.seconds,
        "elapsed_seconds": round(budget.elapsed(), 3),
        "review_cell_count": 0,
        "review_ratio": 0.0,
    })
    _write_runtime_trace(
        "route", name="certified_numeric_text_lattice_fast",
        rows=len(grid), columns=len(grid[0]), checked_boxes=len(targets),
    )
    return result


def _restore_regular_decimal_punctuation(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> list[float]:
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    grouped = geometry.get("grouped_rows", [])
    if len(grouped) != len(grid):
        return []
    targets = []
    crops = []
    for column in range(len(grid[0])):
        dotted = sum(
            bool(re.fullmatch(r"\d+\.\d{2}", str(row[column])))
            for row in grid[1:]
        )
        if dotted < max(3, (len(grid) - 1) * 0.70):
            continue
        for row in range(1, len(grid)):
            current = str(grid[row][column])
            if not re.fullmatch(r"\d+,\d{2}", current):
                continue
            entry = grouped[row][column]
            expected = current.replace(",", ".")
            if (
                str(entry.get("text", "")) != expected
                or float(entry.get("score", 0.0)) < 0.95
            ):
                continue
            crop = image[
                max(0, int(entry["top"]) - 5):min(image.shape[0], int(entry["bottom"]) + 5),
                max(0, int(entry["left"]) - 5):min(image.shape[1], int(entry["right"]) + 5),
            ]
            if crop.size:
                targets.append((row, column, expected))
                crops.append(crop)
    if not targets:
        return []
    small = ocr_engine.fast_text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    medium = ocr_engine.text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    readings = list(zip(small.txts, small.scores, medium.txts, medium.scores))
    _release_recognition_images(small)
    _release_recognition_images(medium)
    if len(readings) != len(targets):
        return []
    scores = []
    for (row, column, expected), (first, first_score, second, second_score) in zip(
        targets, readings
    ):
        scores.extend((float(first_score), float(second_score)))
        if (
            str(first).strip() == str(second).strip() == expected
            and min(float(first_score), float(second_score)) >= 0.94
        ):
            grid[row][column] = expected
            confidence_grid[row][column] = 0.86
    return scores


def _recover_sparse_borderless_header_by_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> tuple[bool, list[float]]:
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    if not grid or not 3 <= len(grid[0]) <= 8 or len(grid) < 5:
        return False, []
    columns = len(grid[0])
    if (
        len(geometry.get("anchors", [])) != columns
        or len(geometry.get("row_centers", [])) != len(grid)
        or sum(bool(str(value).strip()) for value in grid[0]) >= columns - 1
        or sum(
            sum(bool(str(value).strip()) for value in row) >= columns - 1
            for row in grid[1:]
        ) < 3
    ):
        return False, []
    crops = [
        _tight_cell_ink_crop(_spatial_cell_crop(image, geometry, 0, column))
        for column in range(columns)
    ]
    if any(crop.size == 0 for crop in crops):
        return False, []
    active = []
    for column, crop in enumerate(crops):
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        cutoff = min(185, int(np.median(gray)) - 15)
        _, _, components, _ = cv2.connectedComponentsWithStats(
            np.uint8(gray < cutoff), 8
        )
        if any(
            area >= 8 and height >= 8 and width >= 2
            for _, _, width, height, area in components[1:]
        ):
            active.append(column)
    if len(active) < columns - 1:
        return False, []
    active_crops = [crops[column].copy() for column in active]
    small = ocr_engine.fast_text_rec(TextRecInput(img=active_crops))
    medium = ocr_engine.text_rec(TextRecInput(img=[crop.copy() for crop in active_crops]))
    readings = list(zip(small.txts, small.scores, medium.txts, medium.scores))
    _release_recognition_images(small)
    _release_recognition_images(medium)
    if len(readings) != len(active):
        return False, []
    by_column = dict(zip(active, readings))
    resolved = [""] * columns
    scores = []
    for column in active:
        first, first_score, second, second_score = by_column[column]
        scores.extend((float(first_score), float(second_score)))
        first_text = str(first).strip()
        second_text = str(second).strip()
        if (
            _comparable_text(first_text) == _comparable_text(second_text)
            and min(float(first_score), float(second_score)) >= 0.95
        ):
            resolved[column] = second_text
        else:
            return False, scores
    if (
        sum(bool(value) for value in resolved) < columns - 1
        or _comparable_text("".join(resolved))
        != _comparable_text("".join(str(value) for value in grid[0]))
    ):
        return False, scores
    grid[0][:] = resolved
    confidence_grid[0][:] = [0.86 if value else 0.0 for value in resolved]
    spans[:] = [
        span for span in spans
        if not (
            span.get("row") == 0
            and (
                not (
                    0 <= int(span.get("column", 0)) < columns
                    and resolved[int(span.get("column", 0))]
                )
                or sum(
                    bool(resolved[column])
                    for column in range(
                        int(span.get("column", 0)),
                        min(columns, int(span.get("column", 0)) + int(span.get("column_span", 1))),
                    )
                ) > 1
            )
        )
    ]
    geometry["first_structured_row"] = 0
    geometry["header_cells_verified"] = True
    return True, scores


def _tight_cell_ink_crop(crop: np.ndarray) -> np.ndarray:
    if crop.size == 0:
        return crop
    gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY) if crop.ndim == 3 else crop
    cutoff = min(140, int(np.median(gray)) - 25)
    _, _, components, _ = cv2.connectedComponentsWithStats(
        np.uint8(gray < cutoff), 8
    )
    glyphs = [
        (int(x), int(y), int(x + width), int(y + height))
        for x, y, width, height, area in components[1:]
        if area >= 8
        and height >= max(8, gray.shape[0] * 0.18)
        and width < gray.shape[1] * 0.75
        and not (
            height >= gray.shape[0] * 0.85
            and (
                width <= max(2, gray.shape[0] * 0.08)
                or x <= 1
                or x + width >= gray.shape[1] - 1
            )
        )
    ]
    if not glyphs:
        return crop
    glyph_top = min(y for _, y, _, _ in glyphs)
    glyph_bottom = max(y for _, _, _, y in glyphs)
    short_strokes = [
        (int(x), int(y), int(x + width), int(y + height))
        for x, y, width, height, area in components[1:]
        if area >= 5
        and width >= 2
        and height >= 2
        and width < gray.shape[1] * 0.75
        and glyph_top - 3 <= y + height * 0.5 <= glyph_bottom + 3
    ]
    glyphs.extend(short_strokes)
    left = max(0, min(x for x, _, _, _ in glyphs) - 5)
    top = max(0, min(y for _, y, _, _ in glyphs) - 5)
    right = min(crop.shape[1], max(x for _, _, x, _ in glyphs) + 5)
    bottom = min(crop.shape[0], max(y for _, _, _, y in glyphs) + 5)
    return crop[top:bottom, left:right]


def _recover_sparse_striped_cells_from_source(
    source: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    certificate: dict[str, Any],
    source_scale: float,
    ocr_engine: Any,
) -> list[float]:
    if not 0 < source_scale <= 1.0:
        return []
    columns = certificate.get("column_boundaries", [])
    rows = certificate.get("row_boundaries", [])
    if len(columns) != len(grid[0]) + 1 or len(rows) != len(grid) + 1:
        return []
    body = grid[1:]
    densities = [
        sum(bool(str(row[column]).strip()) for row in body) / len(body)
        for column in range(len(grid[0]))
    ]
    if max(densities) < 0.70 or min(densities) >= 0.35:
        return []
    targets = [
        (row, column) for row in range(1, len(grid))
        for column, density in enumerate(densities)
        if density < 0.35 and not str(grid[row][column]).strip()
    ]
    if not targets or len(targets) > 96:
        return []

    crops = []
    for row, column in targets:
        crop = source[
            max(0, int((rows[row] + 3) / source_scale)):
                min(source.shape[0], int((rows[row + 1] - 3) / source_scale)),
            max(0, int((columns[column] + 3) / source_scale)):
                min(source.shape[1], int((columns[column + 1] - 3) / source_scale)),
        ]
        if crop.size == 0:
            return []
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        cutoff = min(140, int(np.median(gray)) - 25)
        _, _, components, _ = cv2.connectedComponentsWithStats(
            np.uint8(gray < cutoff), 8
        )
        glyphs = [
            (int(x), int(x + width))
            for x, _, width, height, area in components[1:]
            if area >= 8 and height >= max(8, gray.shape[0] * 0.20)
        ]
        if not glyphs:
            crops.append(None)
            continue
        left = max(0, min(x for x, _ in glyphs) - 4)
        right = min(crop.shape[1], max(x for _, x in glyphs) + 8)
        crops.append(crop[:, left:right].copy())

    active = [(target, crop) for target, crop in zip(targets, crops) if crop is not None]
    if not active:
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    evidence = []
    for recognizer in (ocr_engine.fast_text_rec, ocr_engine.text_rec):
        output = recognizer(TextRecInput(img=[crop.copy() for _, crop in active]))
        evidence.append(list(zip(output.txts, output.scores)))
        _release_recognition_images(output)
    if any(len(readings) != len(active) for readings in evidence):
        return []
    scores = []
    for index, ((row, column), _) in enumerate(active):
        readings = [family[index] for family in evidence]
        scores.extend(float(score) for _, score in readings)
        if (
            _comparable_text(readings[0][0])
            and _comparable_text(readings[0][0]) == _comparable_text(readings[1][0])
            and min(float(score) for _, score in readings) >= 0.90
        ):
            grid[row][column] = str(readings[1][0]).strip()
            confidence_grid[row][column] = 0.90
    return scores


def _reread_borderless_header_outliers(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any],
    ocr_engine: Any,
    source: np.ndarray | None = None,
    source_scale: float = 1.0,
) -> list[float]:
    if len(grid) < 4 or len(grid[0]) < 3:
        return []
    header = int(geometry.get("first_structured_row", 0))
    if not 0 <= header < len(grid):
        return []
    values = [str(value).strip() for value in grid[header]]
    if sum(len(value) >= 2 for value in values) < len(values) - 1:
        return []
    targets = [
        column for column, value in enumerate(values)
        if (len(value) == 1 and float(confidence_grid[header][column]) > 0)
        or not value
    ]
    if not targets or len(targets) > 2:
        return []
    crop_image = image
    crop_geometry = geometry
    if source is not None and 0 < source_scale < 1.0:
        crop_image = source
        crop_geometry = {
            **geometry,
            "anchors": [float(value) / source_scale for value in geometry.get("anchors", [])],
            "row_centers": [float(value) / source_scale for value in geometry.get("row_centers", [])],
        }
    crops = [
        _tight_cell_ink_crop(_spatial_cell_crop(crop_image, crop_geometry, header, column))
        for column in targets
    ]
    if any(crop.size == 0 for crop in crops):
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    evidence = []
    for recognizer in (ocr_engine.text_rec, ocr_engine.server_text_rec):
        output = recognizer(TextRecInput(img=[crop.copy() for crop in crops]))
        evidence.append(list(zip(output.txts, output.scores)))
        _release_recognition_images(output)
    if any(len(family) != len(targets) for family in evidence):
        return []
    scores = []
    for index, column in enumerate(targets):
        readings = [family[index] for family in evidence]
        scores.extend(float(score) for _, score in readings)
        if (
            min(float(score) for _, score in readings) >= 0.95
            and len(_comparable_text(readings[0][0])) >= 2
            and _comparable_text(readings[0][0]) == _comparable_text(readings[1][0])
        ):
            grid[header][column] = str(readings[0][0]).strip()
            confidence_grid[header][column] = 0.86
    return scores


def _verify_short_borderless_peer_prefix(
    image: np.ndarray, grid: list[list[str]], confidence: list[list[float]],
    geometry: dict[str, Any], ocr_engine: Any,
) -> tuple[list[float], set[tuple[int, int]]]:
    if len(grid) < 5 or len(grid[0]) < 3:
        return [], set()
    anchors = geometry.get("anchors", [])
    centers = geometry.get("row_centers", [])
    if len(anchors) != len(grid[0]) or len(centers) != len(grid):
        return [], set()
    from rapidocr.ch_ppocr_rec.typings import TextRecInput
    scores = []
    confirmed = set()
    for row in range(1, len(grid)):
        current = str(grid[row][0]).strip()
        if (not re.fullmatch(r"[\u3400-\u9fff]{2,4}", current)
                or confidence[row][0] < .85):
            continue
        peers = Counter(
            text[-len(current):] for index, values in enumerate(grid)
            if index != row
            for text in [str(values[0]).strip()]
            if len(text) > len(current) and text.endswith(current[1:])
        )
        if not peers:
            continue
        proposed, support = peers.most_common(1)[0]
        if (support < 2 or proposed == current
                or proposed[1:] != current[1:]):
            continue
        left = max(0, int(round(anchors[0] - (anchors[1] - anchors[0]) * .5)) + 3)
        right = min(image.shape[1], int(round(
            anchors[0] + (anchors[1] - anchors[0]) * .5)) - 3)
        top = max(0, int(round(centers[row] -
                                (centers[row] - centers[row - 1]) * .5)) + 3)
        after = centers[row + 1] - centers[row] if row + 1 < len(grid) else centers[row] - centers[row - 1]
        bottom = min(image.shape[0], int(round(centers[row] + after * .5)) - 3)
        crop = image[max(0, top - 5):min(image.shape[0], bottom + 5),
                     left:min(image.shape[1], right + max(40, min(60, int((right - left) * .33))))]
        if crop.size == 0:
            continue
        tight = _tight_cell_ink_crop(crop)
        readings = []
        for recognizer in (ocr_engine.fast_text_rec, ocr_engine.text_rec):
            output = recognizer(TextRecInput(img=[tight.copy()]))
            readings.append((str(output.txts[0]).strip(), float(output.scores[0]))
                            if len(output.txts) == 1 else ("", 0.0))
            _release_recognition_images(output)
        scores.extend(score for _, score in readings)
        if (readings[0][0] == readings[1][0] == proposed
                and readings[0][1] >= .85 and readings[1][1] >= .95):
            grid[row][0] = proposed
            confidence[row][0] = .90
            confirmed.add((row, 0))
    return scores, confirmed


def _recover_collapsed_borderless_header(
    source: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    spans: list[dict[str, Any]],
    geometry: dict[str, Any],
    source_scale: float,
    ocr_engine: Any,
) -> bool:
    if not 0 < source_scale < 1.0 or len(grid) < 10 or len(grid[0]) < 4:
        return False
    columns = len(grid[0])
    header = "".join(str(value).strip() for value in grid[0])
    labels = (
        "名称", "型号", "日期", "数量", "单价", "金额", "项目", "工时",
        "车牌", "班级", "姓名", "时间", "状态", "规格", "批次",
    )
    if (
        sum(bool(str(value).strip()) for value in grid[0]) >= columns - 1
        or "记录表" in header
        or sum(label in header for label in labels) < 2
        or sum(bool(re.search(r"\d", str(value))) for value in grid[1]) < 2
        or sum(sum(bool(value) for value in row) >= columns - 1 for row in grid[1:])
        < (len(grid) - 1) * 0.80
    ):
        return False
    anchors = geometry.get("anchors", [])
    centers = geometry.get("row_centers", [])
    if len(anchors) != columns or len(centers) != len(grid):
        return False
    source_geometry = {
        **geometry,
        "anchors": [float(value) / source_scale for value in anchors],
        "row_centers": [float(value) / source_scale for value in centers],
    }
    crops = [
        _tight_cell_ink_crop(_spatial_cell_crop(source, source_geometry, 0, column))
        for column in range(columns)
    ]
    if any(crop.size == 0 for crop in crops):
        return False
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    evidence = []
    for recognizer in (ocr_engine.text_rec, ocr_engine.server_text_rec):
        output = recognizer(TextRecInput(img=[crop.copy() for crop in crops]))
        evidence.append(list(zip(output.txts, output.scores)))
        _release_recognition_images(output)
    if any(len(readings) != columns for readings in evidence):
        return False
    resolved = []
    for column in range(columns):
        first, second = (readings[column] for readings in evidence)
        if (
            len(_comparable_text(first[0])) < 2
            or _comparable_text(first[0]) != _comparable_text(second[0])
            or min(float(first[1]), float(second[1])) < 0.90
        ):
            return False
        resolved.append(str(first[0]).strip())
    grid[0][:] = resolved
    confidence_grid[0][:] = [0.86] * columns
    spans[:] = [span for span in spans if not (span.get("row") == 0 and span.get("role") == "title")]
    geometry["first_structured_row"] = 0
    return True


def _recover_joined_borderless_sequence(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> list[float]:
    if len(grid) < 8 or not grid[0]:
        return []
    candidates = []
    for column in range(len(grid[0])):
        numeric_count = sum(
            str(grid[row][column]).isdigit() for row in range(1, len(grid))
        )
        if numeric_count < 8:
            continue
        for row in range(2, len(grid) - 2):
            previous = str(grid[row - 1][column]).strip()
            merged = str(grid[row + 1][column]).strip()
            following = str(grid[row + 2][column]).strip()
            if (
                str(grid[row][column]).strip()
                or not (previous.isdigit() and merged.isdigit() and following.isdigit())
            ):
                continue
            first = str(int(previous) + 1)
            second = str(int(following) - 1)
            if int(second) == int(first) + 1 and merged == first + second:
                candidates.append((row, column, first, second))
    if not candidates or len(candidates) > 4:
        return []
    crops = [
        _spatial_cell_crop(image, geometry, row + offset, column)
        for row, column, _, _ in candidates for offset in (0, 1)
    ]
    if any(crop.size == 0 for crop in crops):
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    evidence = []
    for recognizer in (ocr_engine.fast_text_rec, ocr_engine.text_rec):
        output = recognizer(TextRecInput(img=[crop.copy() for crop in crops]))
        evidence.append(list(zip(output.txts, output.scores)))
        _release_recognition_images(output)
    if any(len(family) != len(crops) for family in evidence):
        return []
    scores = []
    for index, (row, column, first, second) in enumerate(candidates):
        readings = [
            (str(family[index * 2 + offset][0]).strip(), float(family[index * 2 + offset][1]))
            for family in evidence for offset in (0, 1)
        ]
        scores.extend(score for _, score in readings)
        if (
            readings[0][0] == readings[2][0] == first
            and readings[1][0] == readings[3][0] == second
            and readings[0][1] >= 0.85
            and readings[2][1] >= 0.50
            and readings[1][1] >= 0.85
            and readings[3][1] >= 0.80
        ):
            grid[row][column] = first
            grid[row + 1][column] = second
            confidence_grid[row][column] = 0.77
            confidence_grid[row + 1][column] = 0.77
    return scores


def _recover_missing_spatial_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any] | None,
    ocr_engine: Any,
    max_candidates: int | None = 12,
    require_cross_model: bool = False,
    excluded_cells: set[tuple[int, int]] | None = None,
    skip_unsharp_suggestions: bool = False,
    reuse_combined_blank_evidence: bool = False,
) -> tuple[list[list[str]], list[list[float]], list[float]]:
    """Recover detector-missed cells only when two crop variants agree.

    Page-level detection can omit a whole short status/unit cell under shadow.
    The established row/column anchors still identify that cell.  Recovery is
    deliberately bounded and consensus-only: no text is inferred from peers.
    """
    if not geometry or len(grid) < 3 or not grid[0]:
        return grid, confidence_grid, []

    anchors = [float(value) for value in geometry.get("anchors", [])]
    row_centers = [float(value) for value in geometry.get("row_centers", [])]
    column_boundaries = [
        float(value) for value in geometry.get("column_boundaries", [])
    ]
    row_boundaries = [
        float(value) for value in geometry.get("row_boundaries", [])
    ]
    cell_bounds = geometry.get("cell_bounds", {})
    if not isinstance(cell_bounds, dict):
        cell_bounds = {}
    grouped_rows = list(geometry.get("grouped_rows", []))
    first_structured_row = int(geometry.get("first_structured_row", 0))
    row_count = len(grid)
    column_count = len(grid[0])
    if (
        len(anchors) != column_count
        or len(row_centers) != row_count
        or len(grouped_rows) != row_count
    ):
        return grid, confidence_grid, []

    body_rows = list(range(first_structured_row, row_count))
    if len(body_rows) < 3:
        return grid, confidence_grid, []
    review_scores = (
        _mark_low_confidence_fixed_cell_reviews(
            image,
            grid,
            confidence_grid,
            geometry,
            ocr_engine,
        )
        if require_cross_model
        else []
    )
    column_density = [
        sum(bool(str(grid[row][column]).strip()) for row in body_rows) / len(body_rows)
        for column in range(column_count)
    ]
    row_density = [
        sum(bool(str(value).strip()) for value in grid[row]) / column_count
        for row in range(row_count)
    ]
    trusted_ruled_geometry = bool(grouped_rows) and all(
        not grouped_row for grouped_row in grouped_rows
    )
    sparse_borderless_columns_supported = bool(
        require_cross_model
        and not trusted_ruled_geometry
        and column_count <= 12
        and len(grouped_rows[first_structured_row]) >= column_count - 1
        and sum(bool(value) for value in grid[first_structured_row]) >= column_count - 1
        and sum(density >= 0.70 for density in column_density) >= 1
    )
    exact_ruled_boundary_shape = bool(
        trusted_ruled_geometry
        and len(column_boundaries) == column_count + 1
        and len(row_boundaries) == row_count + 1
    )

    header_search_end = min(row_count, first_structured_row + 3)
    semantic_sparse_columns = {
        column
        for column in range(column_count)
        if any(
            any(label in str(grid[row][column]) for label in ("备注", "说明", "状态"))
            for row in range(first_structured_row, header_search_end)
        )
    }

    candidates: list[tuple[float, int, int]] = []
    for row in body_rows:
        minimum_row_density = (
            0.0
            if exact_ruled_boundary_shape and require_cross_model
            else 0.20
            if sparse_borderless_columns_supported
            else 0.25
            if trusted_ruled_geometry and row < min(row_count, first_structured_row + 2)
            else 0.45
            if require_cross_model
            else 0.55
        )
        if row_density[row] < minimum_row_density:
            continue
        for column in range(column_count):
            if excluded_cells and (row, column) in excluded_cells:
                continue
            minimum_column_density = (
                0.0
                if (exact_ruled_boundary_shape and require_cross_model)
                or sparse_borderless_columns_supported
                else 0.20
                if column in semantic_sparse_columns
                else 0.50
                if trusted_ruled_geometry
                else 0.45
                if require_cross_model
                else 0.68
            )
            if (
                str(grid[row][column]).strip()
                or column_density[column] < minimum_column_density
            ):
                continue
            score = column_density[column] * 2.0 + row_density[row]
            candidates.append((score, row, column))
    candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
    if not candidates:
        return grid, confidence_grid, review_scores

    unit_columns = {
        column
        for column in range(column_count)
        if any(
            "单位" in str(grid[row][column])
            for row in range(first_structured_row, header_search_end)
        )
    }
    quantity_columns = {
        column
        for column in range(column_count)
        if any(
            any(label in str(grid[row][column]) for label in ("数量", "个数"))
            for row in range(first_structured_row, header_search_end)
        )
    }

    height, width = image.shape[:2]
    has_exact_cell_bounds = bool(
        len(column_boundaries) == column_count + 1
        and len(row_boundaries) == row_count + 1
        and all(
            right > left
            for left, right in zip(column_boundaries, column_boundaries[1:])
        )
        and all(
            bottom > top
            for top, bottom in zip(row_boundaries, row_boundaries[1:])
        )
    )

    def midpoint_bounds(values: list[float], index: int, limit: int) -> tuple[int, int]:
        if len(values) == 1:
            return 0, limit
        left_gap = values[1] - values[0] if index == 0 else values[index] - values[index - 1]
        right_gap = values[-1] - values[-2] if index == len(values) - 1 else values[index + 1] - values[index]
        start = int(round(values[index] - left_gap * 0.5))
        end = int(round(values[index] + right_gap * 0.5))
        return max(0, start), min(limit, end)

    prepared_candidates: list[
        tuple[
            bool,
            float,
            int,
            int,
            int,
            int,
            int,
            int,
            str,
        ]
    ] = []
    for score, row, column in candidates:
        exact_cell_bounds = cell_bounds.get((row, column))
        if exact_cell_bounds is not None and len(exact_cell_bounds) == 4:
            left = max(0, int(round(exact_cell_bounds[0])))
            right = min(width, int(round(exact_cell_bounds[1])))
            top = max(0, int(round(exact_cell_bounds[2])))
            bottom = min(height, int(round(exact_cell_bounds[3])))
        elif has_exact_cell_bounds:
            left = max(0, int(round(column_boundaries[column])))
            right = min(width, int(round(column_boundaries[column + 1])))
            top = max(0, int(round(row_boundaries[row])))
            bottom = min(height, int(round(row_boundaries[row + 1])))
        else:
            left, right = midpoint_bounds(anchors, column, width)
            top, bottom = midpoint_bounds(row_centers, row, height)
        if exact_cell_bounds is not None:
            # SLANet already returns the physical cell quadrilateral. Keep only
            # a one-pixel line inset; the wider generic inset can clip the
            # leading digit or CJK glyph in a tightly aligned camera frame.
            pad_x = max(1, min(2, (right - left) // 30))
            pad_y = 1
        else:
            pad_x = max(1, min(4, (right - left) // 15))
            pad_y = max(1, min(3, (bottom - top) // 12))
        crop = image[top + pad_y : bottom - pad_y, left + pad_x : right - pad_x]
        if crop.size == 0:
            continue
        visible_mark = _recover_horizontal_mark(
            crop,
            allow_shorter=column in semantic_sparse_columns,
        )
        if not visible_mark and column in semantic_sparse_columns:
            visible_mark = _recover_speckled_semantic_horizontal_mark(crop)
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY) if crop.ndim == 3 else crop
        if float(np.mean(gray < 230)) < 0.003 and not visible_mark:
            continue
        tight = _tight_text_crop(crop)
        if tight.size == 0:
            continue
        prepared_candidates.append(
            (
                bool(visible_mark),
                score,
                row,
                column,
                left,
                right,
                top,
                bottom,
                visible_mark,
            )
        )

    # A short dash is both small and frequently missed by page-level OCR.  It
    # must not lose the bounded recovery budget merely because later blank
    # cells have the same density score.  Visual-mark detection is cheap, so
    # inspect every plausible blank first and reserve the OCR slots for marks.
    prepared_candidates.sort(
        key=lambda item: (-int(item[0]), -item[1], item[2], item[3])
    )
    if max_candidates is not None:
        for candidate in prepared_candidates[max_candidates:]:
            row = int(candidate[2])
            column = int(candidate[3])
            if not str(grid[row][column]).strip():
                confidence_grid[row][column] = -2.0
        prepared_candidates = prepared_candidates[:max_candidates]

    locations: list[tuple[int, int]] = []
    raw_cell_crops: list[np.ndarray] = []
    original_crops: list[np.ndarray] = []
    enhanced_crops: list[np.ndarray] = []
    unsharp_sources: list[np.ndarray] = []
    visible_marks: dict[tuple[int, int], str] = {}
    for (
        _,
        _,
        row,
        column,
        left,
        right,
        top,
        bottom,
        visible_mark,
    ) in prepared_candidates:
        if (row, column) in cell_bounds:
            pad_x = max(1, min(2, (right - left) // 30))
            pad_y = 1
        else:
            pad_x = max(1, min(4, (right - left) // 15))
            pad_y = max(1, min(3, (bottom - top) // 12))
        raw_cell_crop = image[
            top + pad_y : bottom - pad_y,
            left + pad_x : right - pad_x,
        ]
        tight = _tight_text_crop(raw_cell_crop)
        if tight.size == 0:
            continue
        unsharp_source = (
            cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY)
            if tight.ndim == 3
            else tight
        )
        clahe = cv2.createCLAHE(
            clipLimit=2.0, tileGridSize=(4, 4)
        ).apply(unsharp_source)
        original_crop = cv2.resize(
            tight,
            None,
            fx=3.2,
            fy=3.2,
            interpolation=cv2.INTER_LANCZOS4,
        )
        if original_crop.ndim == 2:
            original_crop = cv2.cvtColor(
                original_crop, cv2.COLOR_GRAY2BGR
            )
        gray_scaled = cv2.resize(
            clahe,
            None,
            fx=3.2,
            fy=3.2,
            interpolation=cv2.INTER_LANCZOS4,
        )
        sharp = cv2.addWeighted(
            gray_scaled,
            1.8,
            cv2.GaussianBlur(gray_scaled, (0, 0), 1.2),
            -0.8,
            0,
        )
        enhanced_crop = cv2.cvtColor(sharp, cv2.COLOR_GRAY2BGR)
        locations.append((row, column))
        raw_cell_crops.append(raw_cell_crop)
        original_crops.append(original_crop)
        enhanced_crops.append(enhanced_crop)
        unsharp_sources.append(unsharp_source)
        if visible_mark:
            visible_marks[(row, column)] = visible_mark

    visible_mark_columns: dict[int, int] = {}
    for _, column in visible_marks:
        visible_mark_columns[column] = visible_mark_columns.get(column, 0) + 1

    if not locations:
        return grid, confidence_grid, review_scores

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    candidate_count = len(locations)
    # Capture the exact Small original/enhanced batches while Small is still
    # resident; the later blank selector reuses them after Medium recovery.
    precomputed_small_blank_results: dict[
        tuple[str, int], tuple[str, float]
    ] = {}
    if require_cross_model:
        small_recognizer = getattr(ocr_engine, "fast_text_rec", None)
        if callable(small_recognizer):
            for view_name, view_crops in (
                ("original", raw_cell_crops),
                ("enhanced", enhanced_crops),
            ):
                output = small_recognizer(TextRecInput(img=view_crops))
                _release_recognition_images(output)
                output_texts = list(output.txts)
                output_scores = [float(score) for score in output.scores]
                if (
                    len(output_texts) != candidate_count
                    or len(output_scores) != candidate_count
                ):
                    precomputed_small_blank_results = {}
                    break
                for index, text, score in zip(
                    range(candidate_count),
                    output_texts,
                    output_scores,
                ):
                    precomputed_small_blank_results[(view_name, index)] = (
                        str(text),
                        score,
                    )
                if not precomputed_small_blank_results:
                    break
    precomputed_small_blank_valid = bool(
        len(precomputed_small_blank_results) == candidate_count * 2
    )
    combined = ocr_engine.text_rec(
        TextRecInput(img=original_crops + enhanced_crops)
    )
    _release_recognition_images(combined)
    first_texts = list(combined.txts[:candidate_count])
    second_texts = list(combined.txts[candidate_count:])
    first_scores = [float(score) for score in combined.scores[:candidate_count]]
    second_scores = [float(score) for score in combined.scores[candidate_count:]]
    if not (
        len(first_texts)
        == len(second_texts)
        == len(first_scores)
        == len(second_scores)
        == candidate_count
    ):
        return grid, confidence_grid, first_scores + second_scores
    all_scores = review_scores + first_scores + second_scores
    server_first_texts = [""] * candidate_count
    server_second_texts = [""] * candidate_count
    server_first_scores = [0.0] * candidate_count
    server_second_scores = [0.0] * candidate_count
    server_batch_valid = False
    server_text_rec = getattr(ocr_engine, "server_text_rec", None)
    if require_cross_model and callable(server_text_rec):
        server_output = server_text_rec(
            TextRecInput(img=original_crops + enhanced_crops)
        )
        _release_recognition_images(server_output)
        server_first_texts = [str(text) for text in server_output.txts[:candidate_count]]
        server_second_texts = [str(text) for text in server_output.txts[candidate_count:]]
        server_first_scores = [float(score) for score in server_output.scores[:candidate_count]]
        server_second_scores = [float(score) for score in server_output.scores[candidate_count:]]
        if not (
            len(server_first_texts)
            == len(server_second_texts)
            == len(server_first_scores)
            == len(server_second_scores)
            == candidate_count
        ):
            server_first_texts = [""] * candidate_count
            server_second_texts = [""] * candidate_count
            server_first_scores = [0.0] * candidate_count
            server_second_scores = [0.0] * candidate_count
        else:
            server_batch_valid = True
        all_scores.extend(server_first_scores)
        all_scores.extend(server_second_scores)
    for index, (location, text_a, score_a, text_b, score_b) in enumerate(zip(
        locations,
        first_texts,
        first_scores,
        second_texts,
        second_scores,
    )):
        row, column = location
        comparable_a = _comparable_text(text_a)
        comparable_b = _comparable_text(text_b)
        canonical_unit_a = _canonical_unit_text(text_a) if column in unit_columns else ""
        canonical_unit_b = _canonical_unit_text(text_b) if column in unit_columns else ""
        server_candidates = (
            (server_first_texts[index], server_first_scores[index]),
            (server_second_texts[index], server_second_scores[index]),
        )
        cross_model_candidates = server_candidates
        server_comparable_scores = [
            score
            for text, score in cross_model_candidates
            if _comparable_text(text) == comparable_a and score >= 0.78
        ]
        strong_server_variant_agreement = [
            score
            for text, score in server_candidates
            if _comparable_text(text) == comparable_a and score >= 0.90
        ]
        repeated_cross_family_text_agreement = bool(
            comparable_a
            and comparable_a == comparable_b
            and len(comparable_a) >= 2
            and not re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable_a)
            and min(score_a, score_b) >= 0.70
            and sum(
                _comparable_text(text) == comparable_a and score >= 0.60
                for text, score in server_candidates
            ) == 2
        )
        server_unit_scores = [
            score
            for text, score in cross_model_candidates
            if _canonical_unit_text(text) == canonical_unit_a and score >= 0.48
        ] if canonical_unit_a else []
        known_header_label = ""
        if row < header_search_end:
            for label in _COMMON_HEADER_LABELS:
                comparable_label = _comparable_text(label)
                exact_server_model_scores = [
                    score
                    for text, score in server_candidates
                    if _comparable_text(text) == comparable_label and score >= 0.78
                ]
                exact_server_scores = [
                    score
                    for text, score in cross_model_candidates
                    if _comparable_text(text) == comparable_label and score >= 0.48
                ]
                near_medium_scores = [
                    score
                    for text, score in ((text_a, score_a), (text_b, score_b))
                    if (
                        score >= 0.74
                        and len(_comparable_text(text)) == len(comparable_label)
                        and _text_edit_distance(_comparable_text(text), comparable_label) <= 1
                    )
                    or (
                        score >= 0.90
                        and len(_comparable_text(text)) == len(comparable_label) - 1
                        and comparable_label.endswith(_comparable_text(text))
                    )
                ]
                status_body_values = {
                    "正常", "异常", "复核", "待机", "在用", "启用", "停用",
                    "告警", "合格", "不合格", "完成", "已完成", "进行中",
                    "等待", "暂停", "维修中", "校准中", "待检", "在检",
                }
                populated_below = [
                    str(grid[body_row][column]).strip()
                    for body_row in range(row + 1, row_count)
                    if str(grid[body_row][column]).strip()
                ]
                status_body_support = bool(
                    label == "状态"
                    and len(populated_below) >= 3
                    and sum(value in status_body_values for value in populated_below)
                    >= max(3, int(math.ceil(len(populated_below) * 0.75)))
                )
                if (
                    (
                        len(comparable_label) >= 3
                        and exact_server_scores
                        and len(near_medium_scores) == 2
                    )
                    or (
                        len(comparable_label) == 2
                        and (
                            (
                                comparable_a == comparable_label
                                and comparable_b == comparable_label
                                and min(score_a, score_b) >= 0.78
                                and exact_server_scores
                            )
                            or (
                                len(exact_server_scores) >= 2
                                and len(near_medium_scores) == 2
                            )
                            or (
                                len(exact_server_model_scores) == 2
                                and status_body_support
                            )
                        )
                    )
                ):
                    known_header_label = label
                    break
        if not require_cross_model and known_header_label:
            grid[row][column] = known_header_label
            confidence_grid[row][column] = 0.88
        elif (
            not require_cross_model
            and
            canonical_unit_a
            and canonical_unit_a == canonical_unit_b
            and min(score_a, score_b) >= 0.48
        ):
            # Canonical spelling is only the consensus key.  Preserve the
            # glyph that is actually visible in the source (for example ℃
            # rather than rewriting it to °C).
            representative_unit = max(
                ((str(text_a).strip(), score_a), (str(text_b).strip(), score_b)),
                key=lambda item: (
                    item[1],
                    item[0] == canonical_unit_a,
                ),
            )[0]
            grid[row][column] = representative_unit
            confidence_grid[row][column] = min(
                [score_a, score_b] + server_unit_scores
            )
        elif not require_cross_model and location in visible_marks and (
            all(_is_horizontal_mark_confusable(value) for value in (text_a, text_b))
            or (
                column in semantic_sparse_columns
                and visible_mark_columns.get(column, 0) >= 2
            )
        ):
            grid[row][column] = "—"
            confidence_grid[row][column] = 0.86
        elif (
            not require_cross_model
            and comparable_a
            and comparable_a == comparable_b
            and (
                min(score_a, score_b) >= 0.78
                or (
                    require_cross_model
                    and min(score_a, score_b) >= 0.74
                    and len(strong_server_variant_agreement) == 2
                )
                or (require_cross_model and repeated_cross_family_text_agreement)
            )
            and (
                not require_cross_model
                or server_comparable_scores
                or repeated_cross_family_text_agreement
                or (
                    len(comparable_a) >= 4
                    and not re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable_a)
                    and min(score_a, score_b) >= 0.94
                    and not any(
                        score >= 0.80
                        and _comparable_text(text)
                        and _text_edit_distance(_comparable_text(text), comparable_a) > 1
                        for text, score in cross_model_candidates
                    )
                )
                or (
                    len(comparable_a) >= 4
                    and not re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable_a)
                    and min(score_a, score_b) >= 0.90
                    and any(
                        score >= 0.65
                        and abs(len(_comparable_text(text)) - len(comparable_a)) <= 1
                        and _text_edit_distance(_comparable_text(text), comparable_a) <= 2
                        for text, score in cross_model_candidates
                    )
                )
            )
        ):
            grid[row][column] = str(text_a).strip()
            confidence_grid[row][column] = (
                max(0.86, min(score_a, score_b))
                if min(score_a, score_b) < 0.78
                and (
                    len(strong_server_variant_agreement) == 2
                    or repeated_cross_family_text_agreement
                )
                else min([score_a, score_b] + server_comparable_scores)
            )
        elif confidence_grid[row][column] < 0:
            confidence_grid[row][column] = -1.0

    # A full cell sometimes preserves a short glyph that the tight crop loses.
    # Surface it only as a review suggestion: the original and enhanced views
    # must each have independent two-family agreement.  Existing values and
    # precision-sensitive numeric strings are never changed by this recovery.
    suggestion_indices = [
        index
        for index, (row, column) in enumerate(locations)
        if require_cross_model and not str(grid[row][column]).strip()
    ]
    suggestion_recognizers = (
        (
            ("mobile", getattr(ocr_engine, "fast_text_rec", None)),
            ("medium", getattr(ocr_engine, "text_rec", None)),
            ("v5-server", server_text_rec),
        )
        if suggestion_indices
        else ()
    )
    strict_blank_suggestion_available = bool(
        suggestion_indices
        and all(callable(recognizer) for _, recognizer in suggestion_recognizers)
    )
    if suggestion_indices and strict_blank_suggestion_available:
        suggestion_candidates: dict[int, list[tuple[str, str, str, float]]] = {
            index: [] for index in suggestion_indices
        }
        if precomputed_small_blank_valid:
            for index in suggestion_indices:
                for view_name in ("original", "enhanced"):
                    text, score = precomputed_small_blank_results[(view_name, index)]
                    suggestion_candidates[index].append(
                        (view_name, "mobile", text, score)
                    )
                    all_scores.append(score)
        reusable_original_families: set[str] = set()
        reusable_enhanced_families: set[str] = set()
        if reuse_combined_blank_evidence:
            reusable_original_families.add("medium")
            reusable_enhanced_families.add("medium")
            if server_batch_valid:
                reusable_original_families.add("v5-server")
                reusable_enhanced_families.add("v5-server")
            for index in suggestion_indices:
                suggestion_candidates[index].extend(
                    [
                        (
                            "original",
                            "medium",
                            str(first_texts[index]),
                            float(first_scores[index]),
                        ),
                        (
                            "enhanced",
                            "medium",
                            str(second_texts[index]),
                            float(second_scores[index]),
                        ),
                    ]
                )
                if server_batch_valid:
                    suggestion_candidates[index].append(
                        (
                            "original",
                            "v5-server",
                            str(server_first_texts[index]),
                            float(server_first_scores[index]),
                        )
                    )
        elif server_batch_valid:
            reusable_enhanced_families.add("v5-server")
        for index in suggestion_indices:
            # V5 Server uses an internal batch size of one, so its enhanced
            # crop evidence is exactly reusable. Medium must be re-run in its
            # historical batch context because neighbour widths affect input
            # normalization.
            suggestion_candidates[index].extend(
                (
                    "enhanced",
                    family_name,
                    str(texts[index]),
                    float(scores_by_family[index]),
                )
                for family_name, texts, scores_by_family in (
                    ("v5-server", server_second_texts, server_second_scores),
                )
                if family_name in reusable_enhanced_families
            )
        suggestion_images = (
            (
                "original",
                raw_cell_crops,
                tuple(
                    (family_name, recognizer)
                    for family_name, recognizer in suggestion_recognizers
                    if family_name not in reusable_original_families
                    and not (
                        precomputed_small_blank_valid
                        and family_name == "mobile"
                    )
                ),
            ),
            (
                "enhanced",
                enhanced_crops,
                tuple(
                    (family_name, recognizer)
                    for family_name, recognizer in suggestion_recognizers
                    if family_name not in reusable_enhanced_families
                    and not (
                        precomputed_small_blank_valid
                        and family_name == "mobile"
                    )
                ),
            ),
        )
        recognition_results: dict[
            tuple[str, str], list[tuple[int, str, float]]
        ] = {}
        for family_name, recognizer in suggestion_recognizers:
            for view_name, view_crops, view_recognizers in suggestion_images:
                if family_name not in {
                    candidate_family for candidate_family, _ in view_recognizers
                }:
                    continue
                call_group_size = (
                    _RECOGNITION_CALL_GROUP_SIZE
                    if family_name == "v5-server"
                    else _SERVER_RECOGNITION_BATCH_SIZE
                )
                for batch_start in range(
                    0, len(suggestion_indices), call_group_size
                ):
                    batch_indices = suggestion_indices[
                        batch_start:batch_start + call_group_size
                    ]
                    output = recognizer(
                        TextRecInput(img=[view_crops[index] for index in batch_indices])
                    )
                    _release_recognition_images(output)
                    output_texts = list(output.txts)
                    output_scores = [float(score) for score in output.scores]
                    all_scores.extend(output_scores)
                    if (
                        len(output_texts) != len(batch_indices)
                        or len(output_scores) != len(batch_indices)
                    ):
                        continue
                    for index, text, score in zip(
                        batch_indices, output_texts, output_scores
                    ):
                        recognition_results.setdefault(
                            (view_name, family_name), []
                        ).append(
                            (index, str(text), score)
                        )
        # Inference is grouped by model family to avoid Small/Medium rebuild
        # cycles. Replay evidence in the historical view-major order so every
        # selector sees the exact same candidate ordering as before.
        for view_name, _, view_recognizers in suggestion_images:
            for family_name, _ in view_recognizers:
                for index, text, score in recognition_results.get(
                    (view_name, family_name), []
                ):
                    suggestion_candidates[index].append(
                        (view_name, family_name, text, score)
                    )
        strict_suggestions = {
            index: _select_cross_view_blank_suggestion(
                suggestion_candidates.get(index, [])
            )
            for index in suggestion_indices
        }
        unsharp_indices = [
            index
            for index in suggestion_indices
            if not skip_unsharp_suggestions and strict_suggestions[index] is None
        ]
        unsharp_results: dict[str, list[tuple[int, str, float]]] = {}
        unsharp_recognizers = tuple(
            (family_name, recognizer)
            for family_name, recognizer in reversed(suggestion_recognizers[:2])
            if not (
                precomputed_small_blank_valid
                and family_name == "mobile"
            )
        )
        for family_name, recognizer in unsharp_recognizers:
            family_results: list[tuple[int, str, float]] = []
            for batch_start in range(
                0, len(unsharp_indices), _MEDIUM_RECOGNITION_BATCH_SIZE
            ):
                batch_indices = unsharp_indices[
                    batch_start:batch_start + _MEDIUM_RECOGNITION_BATCH_SIZE
                ]
                if not batch_indices:
                    continue
                batch_crops = []
                for index in batch_indices:
                    source = unsharp_sources[index]
                    unsharp = cv2.addWeighted(
                        source,
                        1.9,
                        cv2.GaussianBlur(source, (0, 0), 1.2),
                        -0.9,
                        0,
                    )
                    unsharp = cv2.resize(
                        unsharp,
                        None,
                        fx=3.2,
                        fy=3.2,
                        interpolation=cv2.INTER_LANCZOS4,
                    )
                    batch_crops.append(cv2.cvtColor(unsharp, cv2.COLOR_GRAY2BGR))
                output = recognizer(
                    TextRecInput(img=batch_crops)
                )
                _release_recognition_images(output)
                output_texts = list(output.txts)
                output_scores = [float(score) for score in output.scores]
                if (
                    len(output_texts) != len(batch_indices)
                    or len(output_scores) != len(batch_indices)
                ):
                    continue
                for index, text, score in zip(
                    batch_indices, output_texts, output_scores
                ):
                    family_results.append((index, str(text), score))
                del output, batch_crops
            unsharp_results[family_name] = family_results
        # Small的原图/增强图证据已在释放前缓存，不再为第三个视图重载。
        # 未命中缓存时Small最后运行；候选仍按历史顺序回放。
        for family_name, _ in suggestion_recognizers[:2]:
            for index, text, score in unsharp_results.get(family_name, []):
                suggestion_candidates[index].append(
                    ("unsharp", family_name, text, score)
                )
                all_scores.append(score)
        for index in suggestion_indices:
            suggestion = strict_suggestions[index]
            if suggestion is None:
                suggestion = _select_server_guarded_unsharp_suggestion(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None:
                suggestion = _select_stable_local_review_suggestion(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None:
                suggestion = _select_single_cjk_review_from_view_candidates(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None:
                suggestion = _select_identifier_review_from_view_candidates(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None and locations[index][1] in unit_columns:
                suggestion = _select_visible_celsius_review_suggestion(
                    raw_cell_crops[index],
                    suggestion_candidates.get(index, []),
                )
            if suggestion is None and locations[index][1] in quantity_columns:
                suggestion = _select_quantity_multidigit_review_suggestion(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None and locations[index][1] in quantity_columns:
                suggestion = _select_quantity_single_digit_review_suggestion(
                    suggestion_candidates.get(index, [])
                )
            if suggestion is None:
                # Every suggestion index belongs to a bounded physical cell
                # whose inset crop already passed the visible-ink gate.  If
                # the independent-model selectors cannot safely surface its
                # text, keep the cell empty and mark it as a hard publishing
                # blocker.  Guessing would corrupt the table; treating it as
                # a legitimate blank would silently lose human-visible data.
                row, column = locations[index]
                confidence_grid[row][column] = -2.0
                continue
            row, column = locations[index]
            grid[row][column], confidence_grid[row][column] = suggestion
    elif suggestion_indices and require_cross_model:
        for index in suggestion_indices:
            row, column = locations[index]
            confidence_grid[row][column] = -2.0
    return grid, confidence_grid, all_scores


def _select_cross_view_blank_suggestion(
    candidates: list[tuple[str, str, str, float]],
) -> tuple[str, float] | None:
    """Return a review-only blank-cell suggestion from two independent views."""
    score_floors = {
        "mobile": 0.78,
        "medium": 0.78,
        "v5-server": 0.80,
    }
    per_view: dict[str, dict[str, dict[str, tuple[str, float]]]] = {
        "original": {},
        "enhanced": {},
    }
    precision_sensitive_keys: set[str] = set()
    simple_integer_keys: set[str] = set()
    single_cjk_keys: set[str] = set()
    for view, family, text, score in candidates:
        if view not in per_view or family not in score_floors:
            continue
        cleaned = str(text).strip()
        comparable = _comparable_text(cleaned)
        precision_sensitive = bool(
            re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
        )
        if (
            not comparable
            or float(score) < score_floors[family]
        ):
            continue
        if precision_sensitive:
            precision_sensitive_keys.add(comparable)
            if re.fullmatch(r"\d{1,9}", comparable):
                simple_integer_keys.add(comparable)
        elif len(comparable) < 2:
            if re.fullmatch(r"[\u3400-\u9fff]", comparable):
                single_cjk_keys.add(comparable)
            else:
                continue
        family_votes = per_view[view].setdefault(comparable, {})
        previous = family_votes.get(family)
        if previous is None or float(score) > previous[1]:
            family_votes[family] = (cleaned, float(score))

    supported_by_view: dict[str, set[str]] = {}
    for view, groups in per_view.items():
        supported_by_view[view] = {
            comparable
            for comparable, family_votes in groups.items()
            if len(family_votes)
            >= (
                2
                if comparable in simple_integer_keys
                else 3
                if comparable in precision_sensitive_keys
                else 2
            )
        }
    if (
        len(supported_by_view["original"]) != 1
        or len(supported_by_view["enhanced"]) != 1
        or supported_by_view["original"] != supported_by_view["enhanced"]
    ):
        return None
    comparable = next(iter(supported_by_view["original"]))
    original_votes = per_view["original"][comparable]
    enhanced_votes = per_view["enhanced"][comparable]
    combined_families = set(original_votes) | set(enhanced_votes)
    if comparable in simple_integer_keys:
        if min(len(original_votes), len(enhanced_votes)) < 3:
            return None
    elif comparable in precision_sensitive_keys:
        if len(original_votes) < 3 or len(enhanced_votes) < 3:
            return None
    elif comparable in single_cjk_keys:
        if (
            len(combined_families) < 3
            or not ({"mobile", "medium"} & combined_families)
            or "v5-server" not in combined_families
        ):
            return None
    elif (
        len(combined_families) < 3
        or not ({"mobile", "medium"} & combined_families)
        or "v5-server" not in combined_families
    ):
        return None
    selected_text, _ = max(
        list(original_votes.values()) + list(enhanced_votes.values()),
        key=lambda item: item[1],
    )
    # 0.77 is intentionally below the verified threshold.  The UI keeps the
    # suggestion yellow until a user checks or edits the cell.
    return selected_text, 0.77


def _select_server_guarded_unsharp_suggestion(
    candidates: list[tuple[str, str, str, float]],
) -> tuple[str, float] | None:
    """Offer review-only text when V5 and a local unsharp view agree."""
    score_floors = {
        "mobile": 0.78,
        "medium": 0.78,
        "v5-server": 0.80,
    }
    votes: dict[tuple[str, str], tuple[str, str, float]] = {}
    for view, family, text, score in candidates:
        if family not in score_floors or float(score) < score_floors[family]:
            continue
        cleaned = str(text).strip()
        comparable = _comparable_text(cleaned)
        if (
            (len(comparable) < 2 and not re.fullmatch(r"[\u3400-\u9fff]", comparable))
            or re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
        ):
            continue
        key = (view, family)
        previous = votes.get(key)
        if previous is None or float(score) > previous[2]:
            votes[key] = (comparable, cleaned, float(score))

    original_v5 = votes.get(("original", "v5-server"))
    if original_v5 is None:
        return None
    selected_key = original_v5[0]
    local_unsharp = [
        vote
        for family in ("mobile", "medium")
        if (vote := votes.get(("unsharp", family))) is not None
        and vote[0] == selected_key
    ]
    if not local_unsharp:
        return None

    support_by_key: dict[str, set[str]] = {}
    for (_, family), (comparable, _, _) in votes.items():
        support_by_key.setdefault(comparable, set()).add(family)
    if any(
        comparable != selected_key and len(families) >= 2
        for comparable, families in support_by_key.items()
    ):
        return None

    selected_text, _ = max(
        [(original_v5[1], original_v5[2])]
        + [(vote[1], vote[2]) for vote in local_unsharp],
        key=lambda item: item[1],
    )
    return selected_text, 0.77


def _select_stable_local_review_suggestion(
    candidates: list[tuple[str, str, str, float]],
) -> tuple[str, float] | None:
    """Offer review-only text that remains stable across image views.

    This is weaker than independent model consensus, so it never produces a
    verified value.  It only surfaces a non-numeric medium-model reading after
    two image treatments agree and no competing answer has two-family support.
    """
    score_floors = {
        "mobile": 0.78,
        "medium": 0.78,
        "v5-server": 0.80,
    }
    medium_by_key: dict[str, dict[str, tuple[str, float]]] = {}
    support_by_view: dict[str, dict[str, set[str]]] = {}
    for view, family, text, score in candidates:
        if view not in {"original", "enhanced", "unsharp"}:
            continue
        cleaned = str(text).strip()
        comparable = _comparable_text(cleaned)
        if (
            len(comparable) < 2
            or re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
        ):
            continue
        if family == "medium" and float(score) >= 0.74:
            previous = medium_by_key.setdefault(comparable, {}).get(view)
            if previous is None or float(score) > previous[1]:
                medium_by_key[comparable][view] = (cleaned, float(score))
        if family in score_floors and float(score) >= score_floors[family]:
            support_by_view.setdefault(view, {}).setdefault(comparable, set()).add(
                family
            )

    stable = [
        (comparable, per_view)
        for comparable, per_view in medium_by_key.items()
        if len(per_view) >= 2
        and max(score for _, score in per_view.values()) >= 0.82
    ]
    if len(stable) != 1:
        return None
    selected_key, selected_views = stable[0]
    if any(
        comparable != selected_key and len(families) >= 2
        for groups in support_by_view.values()
        for comparable, families in groups.items()
    ):
        return None
    selected_text, _ = max(selected_views.values(), key=lambda item: item[1])
    return selected_text, 0.77


def _cross_view_text_has_two_family_support(
    current_text: str,
    candidates: list[tuple[str, str, str, float]],
) -> bool:
    """Confirm an existing value without changing it or using row semantics."""
    score_floors = {
        "mobile": 0.78,
        "medium": 0.78,
        "v5-server": 0.80,
    }
    current_key = _comparable_text(current_text)
    if not current_key:
        return False
    support: dict[str, set[str]] = {"original": set(), "enhanced": set()}
    for view, family, text, score in candidates:
        if (
            view in support
            and family in score_floors
            and float(score) >= score_floors[family]
            and _comparable_text(text) == current_key
        ):
            support[view].add(family)
    return all(len(families) >= 2 for families in support.values())


def _mark_low_confidence_fixed_cell_reviews(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    geometry: dict[str, Any],
    ocr_engine: Any,
) -> list[float]:
    """Yellow low-confidence fixed-cell text that models cannot reconfirm."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    anchors = [float(value) for value in geometry.get("anchors", [])]
    row_centers = [float(value) for value in geometry.get("row_centers", [])]
    column_boundaries = [
        float(value) for value in geometry.get("column_boundaries", [])
    ]
    row_boundaries = [
        float(value) for value in geometry.get("row_boundaries", [])
    ]
    if (
        row_count < 3
        or column_count < 2
        or len(anchors) != column_count
        or len(row_centers) != row_count
    ):
        return []

    height, width = image.shape[:2]
    has_exact_bounds = bool(
        len(column_boundaries) == column_count + 1
        and len(row_boundaries) == row_count + 1
        and all(
            right > left
            for left, right in zip(column_boundaries, column_boundaries[1:])
        )
        and all(
            bottom > top
            for top, bottom in zip(row_boundaries, row_boundaries[1:])
        )
    )

    def midpoint_bounds(
        values: list[float], index: int, limit: int
    ) -> tuple[int, int]:
        if len(values) == 1:
            return 0, limit
        left_gap = (
            values[1] - values[0]
            if index == 0
            else values[index] - values[index - 1]
        )
        right_gap = (
            values[-1] - values[-2]
            if index == len(values) - 1
            else values[index + 1] - values[index]
        )
        start = int(round(values[index] - left_gap * 0.5))
        end = int(round(values[index] + right_gap * 0.5))
        return max(0, start), min(limit, end)

    first_structured_row = int(geometry.get("first_structured_row", 0))
    locations: list[tuple[int, int]] = []
    original_crops: list[np.ndarray] = []
    enhanced_crops: list[np.ndarray] = []
    for row in range(first_structured_row, row_count):
        for column in range(column_count):
            current_text = str(grid[row][column]).strip()
            current_key = _comparable_text(current_text)
            current_confidence = float(confidence_grid[row][column])
            if (
                re.fullmatch(r"[\u3400-\u9fff]{2,4}", current_key) is None
                or not 0.78 <= current_confidence < 0.90
            ):
                continue
            if has_exact_bounds:
                left = max(0, int(round(column_boundaries[column])))
                right = min(width, int(round(column_boundaries[column + 1])))
                top = max(0, int(round(row_boundaries[row])))
                bottom = min(height, int(round(row_boundaries[row + 1])))
            else:
                left, right = midpoint_bounds(anchors, column, width)
                top, bottom = midpoint_bounds(row_centers, row, height)
            pad_x = max(1, min(4, (right - left) // 15))
            pad_y = max(1, min(3, (bottom - top) // 12))
            crop = image[
                top + pad_y : bottom - pad_y,
                left + pad_x : right - pad_x,
            ]
            if crop.size == 0:
                continue
            tight = _tight_text_crop(crop)
            if tight.size == 0:
                continue
            gray = (
                cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY)
                if tight.ndim == 3
                else tight
            )
            clahe = cv2.createCLAHE(
                clipLimit=2.0,
                tileGridSize=(4, 4),
            ).apply(gray)
            scaled = cv2.resize(
                clahe,
                None,
                fx=3.2,
                fy=3.2,
                interpolation=cv2.INTER_LANCZOS4,
            )
            sharp = cv2.addWeighted(
                scaled,
                1.8,
                cv2.GaussianBlur(scaled, (0, 0), 1.2),
                -0.8,
                0,
            )
            locations.append((row, column))
            original_crops.append(crop)
            enhanced_crops.append(cv2.cvtColor(sharp, cv2.COLOR_GRAY2BGR))

    if not locations:
        return []

    recognizers = (
        ("mobile", getattr(ocr_engine, "fast_text_rec", None)),
        ("medium", getattr(ocr_engine, "text_rec", None)),
        ("v5-server", getattr(ocr_engine, "server_text_rec", None)),
    )
    if not all(callable(recognizer) for _, recognizer in recognizers):
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    candidates: dict[int, list[tuple[str, str, str, float]]] = {
        index: [] for index in range(len(locations))
    }
    all_scores: list[float] = []
    for family_name, recognizer in recognizers:
        call_group_size = (
            _RECOGNITION_CALL_GROUP_SIZE
            if family_name == "v5-server"
            else _RECOGNITION_CALL_GROUP_SIZE * _SERVER_RECOGNITION_BATCH_SIZE
        )
        for view_name, view_crops in (
            ("original", original_crops),
            ("enhanced", enhanced_crops),
        ):
            for batch_start in range(
                0, len(locations), call_group_size
            ):
                batch_indices = list(
                    range(
                        batch_start,
                        min(
                            len(locations),
                            batch_start + call_group_size,
                        ),
                    )
                )
                output = recognizer(
                    TextRecInput(img=[view_crops[index] for index in batch_indices])
                )
                _release_recognition_images(output)
                output_texts = list(output.txts)
                output_scores = [float(score) for score in output.scores]
                all_scores.extend(output_scores)
                if (
                    len(output_texts) != len(batch_indices)
                    or len(output_scores) != len(batch_indices)
                ):
                    continue
                for index, text, score in zip(
                    batch_indices, output_texts, output_scores
                ):
                    candidates[index].append(
                        (view_name, family_name, str(text), score)
                    )

    for index, (row, column) in enumerate(locations):
        if not _cross_view_text_has_two_family_support(
            str(grid[row][column]),
            candidates.get(index, []),
        ):
            confidence_grid[row][column] = 0.77
    return all_scores


def _select_cross_model_motion_consensus(
    candidates: list[tuple[str, str, float]],
) -> tuple[str, float] | None:
    """Accept one deblurred cell only when independent model families agree."""
    groups: dict[str, dict[str, tuple[str, float]]] = {}
    for model_name, text, score in candidates:
        comparable = _comparable_text(text)
        if not comparable:
            continue
        single_cjk = bool(re.fullmatch(r"[\u3400-\u9fff]", comparable))
        if len(comparable) < 2 and not single_cjk:
            continue
        numeric_or_punctuated = bool(
            re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
        )
        score_floor = 0.90 if single_cjk else 0.84 if numeric_or_punctuated else 0.78
        if score < score_floor:
            continue
        per_model = groups.setdefault(comparable, {})
        previous = per_model.get(model_name)
        if previous is None or score > previous[1]:
            per_model[model_name] = (str(text).strip(), float(score))

    supported = [
        (comparable, per_model)
        for comparable, per_model in groups.items()
        if len(per_model)
        >= (
            3
            if len(comparable) == 1
            or re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
            else 2
        )
        and "medium" in per_model
        and "v5-server" in per_model
    ]
    if len(supported) != 1:
        return None
    selected_comparable, selected_models = supported[0]
    if any(
        comparable != selected_comparable and len(per_model) >= 2
        for comparable, per_model in groups.items()
    ):
        return None
    selected_text, _ = max(
        selected_models.values(),
        key=lambda item: item[1],
    )
    confidence = max(
        0.86,
        min(score for _, score in selected_models.values()),
    )
    return selected_text, confidence


def _refine_motion_blurred_ruled_lines(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    source_crops: list[np.ndarray],
    locations: list[tuple[int, int, int, int]],
    ocr_engine: Any,
) -> list[float]:
    """Correct bounded motion-blur omissions without changing cell geometry."""
    initially_blank = {
        (row, column)
        for row, values in enumerate(grid)
        for column, value in enumerate(values)
        if not str(value).strip()
    }
    pending_cells = sum(
        not str(value).strip()
        or (
            row < len(confidence_grid)
            and column < len(confidence_grid[row])
            and confidence_grid[row][column] < 0
        )
        for row, values in enumerate(grid)
        for column, value in enumerate(values)
    )
    review_cells = sum(
        row < len(confidence_grid)
        and column < len(confidence_grid[row])
        and confidence_grid[row][column] < 0
        for row, values in enumerate(grid)
        for column, _ in enumerate(values)
    )
    near_text_variant = False
    column_count = max((len(row) for row in grid), default=0)
    for column in range(column_count):
        values = {
            _comparable_text(row[column])
            for row in grid
            if column < len(row) and _comparable_text(row[column])
        }
        for left_index, left in enumerate(values):
            for right in list(values)[left_index + 1 :]:
                if max(len(left), len(right)) < 2 or re.search(r"\d", left + right):
                    continue
                shorter, longer = sorted((left, right), key=len)
                if (
                    longer.startswith(shorter)
                    and len(longer) - len(shorter) <= 2
                ) or (
                    len(left) == len(right)
                    and _text_edit_distance(left, right) == 1
                ):
                    near_text_variant = True
                    break
            if near_text_variant:
                break
        if near_text_variant:
            break
    if pending_cells < 2 and review_cells == 0 and not near_text_variant:
        return []

    recognizers = (
        ("mobile", getattr(ocr_engine, "fast_text_rec", None)),
        ("medium", getattr(ocr_engine, "text_rec", None)),
        ("v5-server", getattr(ocr_engine, "server_text_rec", None)),
    )
    if not all(callable(recognizer) for _, recognizer in recognizers):
        return []

    line_indices = [
        index
        for index, (row, column, line_index, line_count) in enumerate(locations)
        if line_count == 1
        and line_index == 0
        and (row, column) in initially_blank
        and row < len(grid)
        and column < len(grid[row])
        and not (
            str(grid[row][column]).strip()
            and _is_horizontal_mark_confusable(grid[row][column])
        )
    ]
    if not line_indices:
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    all_scores: list[float] = []
    batch_size = max(1, _MEDIUM_RECOGNITION_BATCH_SIZE)
    candidates: dict[int, list[tuple[str, str, float]]] = {
        index: [] for index in line_indices
    }
    # _HybridOcrEngine keeps only one recognition family resident.  Running
    # all Small batches before switching to Medium avoids reconstructing both
    # model families for every four-cell batch.  Views are rebuilt per family
    # to keep peak memory bounded; their deterministic preprocessing and batch
    # membership remain unchanged.
    for model_name, recognizer in recognizers:
        for batch_start in range(0, len(line_indices), batch_size):
            candidate_indices = line_indices[batch_start : batch_start + batch_size]
            batch_views: list[np.ndarray] = []
            batch_indices: list[int] = []
            for index in candidate_indices:
                crop = source_crops[index]
                if crop.size == 0:
                    continue
                gray = (
                    cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
                    if crop.ndim == 3
                    else crop
                )
                restored = _wiener_motion_deblur_view(gray, 7, 45.0)
                restored = cv2.resize(
                    restored,
                    None,
                    fx=3.2,
                    fy=3.2,
                    interpolation=cv2.INTER_LANCZOS4,
                )
                batch_views.append(cv2.cvtColor(restored, cv2.COLOR_GRAY2BGR))
                batch_indices.append(index)
            if not batch_indices:
                continue
            output = recognizer(
                TextRecInput(img=batch_views)
            )
            _release_recognition_images(output)
            texts = list(output.txts)
            scores = [float(score) for score in output.scores]
            all_scores.extend(scores)
            if len(texts) != len(batch_indices) or len(scores) != len(batch_indices):
                continue
            for index, text, score in zip(batch_indices, texts, scores):
                candidates[index].append((model_name, str(text), float(score)))

    for index in line_indices:
        agreement = _select_cross_model_motion_consensus(candidates[index])
        if agreement is None:
            continue
        selected_text, _ = agreement
        row, column, _, _ = locations[index]
        current_text = str(grid[row][column]).strip()
        current_key = _comparable_text(current_text)
        selected_key = _comparable_text(selected_text)
        if not selected_key:
            continue
        if not current_key and (row, column) in initially_blank:
            grid[row][column] = selected_text
            confidence_grid[row][column] = 0.77
    return all_scores


def _refine_motion_blurred_ruled_grid(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    *,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> list[float]:
    """Build exact physical-cell crops after missing-cell recovery, then refine text."""
    row_count = min(len(grid), max(0, len(rows) - 1))
    column_count = max(0, len(columns) - 1)
    excluded = excluded_cells or set()
    source_crops: list[np.ndarray] = []
    locations: list[tuple[int, int, int, int]] = []
    for row, (top, bottom) in enumerate(zip(rows[:row_count], rows[1 : row_count + 1])):
        for column, (left, right) in enumerate(zip(columns, columns[1:])):
            if column >= column_count or column >= len(grid[row]):
                continue
            if (row, column) in excluded:
                continue
            pad_x = (
                2
                if column in (0, column_count - 1)
                else max(2, min(5, (right - left) // 16))
            )
            pad_y = max(2, min(4, (bottom - top) // 12))
            crop = image[
                top + pad_y : bottom - pad_y,
                left + pad_x : right - pad_x,
            ]
            if crop.size == 0:
                continue
            if not str(grid[row][column]).strip():
                visible_mark = _recover_horizontal_mark(crop, allow_shorter=True)
                if not _physical_cell_has_visible_text_ink(crop) and not visible_mark:
                    # A confirmed clean physical blank has no recognition
                    # evidence to add. Do not spend four model families on it;
                    # ink-bearing blanks still follow the original consensus.
                    continue
                # Preserve faint edge strokes in an initially blank physical
                # cell.  The downstream motion selector still requires
                # independent model-family agreement and only writes a yellow
                # review suggestion; existing text is never changed here.
                source_crops.append(crop)
                locations.append((row, column, 0, 1))
                continue
            line_crops = _split_text_line_crops(_tight_text_crop(crop))
            for line_index, line_crop in enumerate(line_crops):
                source_crops.append(line_crop)
                locations.append((row, column, line_index, len(line_crops)))
    return _refine_motion_blurred_ruled_lines(
        grid,
        confidence_grid,
        source_crops,
        locations,
        ocr_engine,
    )


def _motion_cell_consensus_key(value: Any) -> str:
    """Normalize glyph presentation while preserving meaningful word spacing."""
    normalized = unicodedata.normalize("NFKC", str(value)).translate(
        _DASH_TRANSLATION
    )
    return re.sub(r"\s+", " ", normalized.strip()).casefold()


def _page_grid_needs_motion_cell_consensus(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
) -> bool:
    """Detect a dense ruled page whose raw OCR is systemically uncertain."""
    if len(grid) < 4 or not grid[0] or len(confidence_grid) != len(grid):
        return False
    column_count = len(grid[0])
    if column_count < 2 or any(len(row) != column_count for row in grid):
        return False
    if any(len(row) != column_count for row in confidence_grid):
        return False
    cell_count = len(grid) * column_count
    if not 20 <= cell_count <= 320:
        return False
    populated = sum(bool(str(value).strip()) for row in grid for value in row)
    if populated < max(12, int(math.ceil(cell_count * 0.55))):
        return False
    evidence_scores = [
        float(confidence_grid[row][column])
        for row in range(len(grid))
        for column in range(column_count)
        if str(grid[row][column]).strip()
        or float(confidence_grid[row][column]) != 0.0
    ]
    # assign_ocr_to_grid represents a detector-missed, evidence-free physical
    # blank as ("", 0.0). Counting those legitimate blanks as uncertain makes
    # an otherwise clear, partially filled table look systemically blurred.
    # Ink-bearing blanks are handled by the bounded physical-cell recovery
    # gates; this page-level decision therefore measures only observed evidence.
    occupied = [
        [
            bool(str(grid[row][column]).strip())
            or float(confidence_grid[row][column]) != 0.0
            for column in range(column_count)
        ]
        for row in range(len(grid))
    ]
    row_population = [sum(row) for row in occupied]
    column_population = [
        sum(occupied[row][column] for row in range(len(grid)))
        for column in range(column_count)
    ]
    structural_misses = 0
    for row in range(len(grid)):
        for column in range(column_count):
            if occupied[row][column]:
                continue
            dense_leading_row = bool(
                row < 2 and row_population[row] >= max(2, column_count - 2)
            )
            expected_body_cell = bool(
                row_population[row] >= int(math.ceil(column_count * 0.40))
                and column_population[column] >= int(math.ceil(len(grid) * 0.75))
            )
            if dense_leading_row or expected_body_cell:
                structural_misses += 1
    uncertain = sum(score < 0.80 for score in evidence_scores) + structural_misses
    evidence_count = len(evidence_scores) + structural_misses
    return uncertain >= max(6, int(math.ceil(evidence_count * 0.28)))


def _multilevel_header_rows_for_review(grid: list[list[str]]) -> set[int]:
    """Return leading header rows whose blank anchors remain structurally ambiguous."""
    if len(grid) < 4 or not grid[0]:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = next(
        (
            row
            for row in range(1, min(5, len(grid)))
            if re.fullmatch(r"\d{1,4}", str(grid[row][0]).strip())
            and sum(bool(str(value).strip()) for value in grid[row])
            >= max(3, int(math.ceil(column_count * 0.65)))
        ),
        -1,
    )
    if body_start < 2:
        return set()
    header_rows = list(range(body_start))
    has_sparse_group_row = any(
        1 < sum(bool(str(value).strip()) for value in grid[row]) < column_count
        for row in header_rows
    )
    has_dense_label_row = any(
        sum(bool(_header_semantic_labels(value)) for value in grid[row])
        >= max(2, int(math.ceil(column_count * 0.20)))
        for row in header_rows
    )
    dense_terminal_header = bool(
        sum(bool(str(value).strip()) for value in grid[body_start - 1])
        >= int(math.ceil(column_count * 0.75))
        and any(
            label in str(value)
            for value in grid[body_start - 1]
            for label in ("序号", "编号")
        )
        and sum(
            bool(re.fullmatch(r"\d{1,4}", str(grid[row][0]).strip()))
            for row in range(body_start, min(len(grid), body_start + 6))
        )
        >= min(4, len(grid) - body_start)
    )
    return (
        set(header_rows)
        if has_sparse_group_row and (has_dense_label_row or dense_terminal_header)
        else set()
    )


def _certified_selective_header_risks(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
) -> set[tuple[int, int]]:
    """Keep full multilevel headers, but only suspicious cells in a simple header."""
    if not grid or not grid[0]:
        return set()
    header_rows = _multilevel_header_rows_for_review(grid)
    header_rows.update({
        int(span.get("row", -1))
        for span in _strict_multilevel_title_span(grid, confidence_grid)
        if 0 <= int(span.get("row", -1)) < min(3, len(grid))
    })
    if not header_rows:
        return _suspicious_leading_ruled_cells(grid, confidence_grid)
    for row in range(min(3, len(grid))):
        populated = [value for value in grid[row] if str(value).strip()]
        semantic_labels = sum(
            bool(_header_semantic_labels(value)) for value in populated
        )
        if semantic_labels >= max(2, int(math.ceil(len(populated) * 0.40))):
            header_rows.add(row)
    if header_rows and max(header_rows) - min(header_rows) >= 2:
        header_rows.update(range(min(header_rows), max(header_rows) + 1))
    return {
        (row, column)
        for row in header_rows
        for column in range(len(grid[row]))
    }


def _dense_four_digit_value_risks(grid: list[list[str]]) -> set[tuple[int, int]]:
    """Keep dense four-digit measurements visible until independently confirmed."""
    if len(grid) < 6 or not grid[0]:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = max(_multilevel_header_rows_for_review(grid) or {0}) + 1
    selected: set[tuple[int, int]] = set()
    for column in range(column_count):
        locations = [
            (row, column)
            for row in range(body_start, len(grid))
            if re.fullmatch(r"\d{4}", str(grid[row][column]).strip())
        ]
        if len(locations) >= 4:
            selected.update(locations)
    return selected


def _dense_quantity_magnitude_outlier_risks(
    grid: list[list[str]],
) -> set[tuple[int, int]]:
    """Select visible four-digit quantity values with an isolated lost magnitude."""
    if len(grid) < 8 or not grid[0]:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = max(_multilevel_header_rows_for_review(grid) or {0}) + 1
    quantity_columns = {
        column
        for column in range(column_count)
        if any(
            "数量" in str(grid[row][column])
            # Camera screenshots may still carry up to two spreadsheet ruler
            # rows here; the visible table header then starts at row 2 or 3.
            for row in range(min(5, len(grid)))
        )
    }
    selected: set[tuple[int, int]] = set()
    for column in quantity_columns:
        values = [
            (row, int(str(grid[row][column]).strip()))
            for row in range(body_start, len(grid))
            if re.fullmatch(r"\d{4}", str(grid[row][column]).strip())
        ]
        if len(values) < 6:
            continue
        normal_magnitude = sum(value >= 1000 for _, value in values)
        if normal_magnitude < int(math.ceil(len(values) * 0.80)):
            continue
        selected.update((row, column) for row, value in values if value < 1000)
    return selected


def _dense_digit_shape_confusion_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 64,
) -> set[tuple[int, int]]:
    """Select bounded 3-4 digit values dominated by camera-confusable glyphs."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = max(_multilevel_header_rows_for_review(grid) or {0}) + 1
    selected = {
        (row, column)
        for row in range(body_start, len(grid))
        for column, value in enumerate(grid[row])
        for text in [str(value).strip()]
        if re.fullmatch(r"\d{3,4}", text)
        and sum(character in "01689" for character in text) >= 3
    }
    return selected if len(selected) <= maximum_cells else set()


def _dense_numeric_length_review_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 32,
) -> set[tuple[int, int]]:
    """Select a bounded 3/5-digit outlier in a column dominated by four digits."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = max(_multilevel_header_rows_for_review(grid) or {0}) + 1
    selected: set[tuple[int, int]] = set()
    for column in range(column_count):
        numeric_values = [
            (row, str(grid[row][column]).strip())
            for row in range(body_start, len(grid))
            if re.fullmatch(r"\d{3,5}", str(grid[row][column]).strip())
        ]
        if len(numeric_values) < 6:
            continue
        four_digit_count = sum(len(text) == 4 for _, text in numeric_values)
        if four_digit_count < int(math.ceil(len(numeric_values) * 0.70)):
            continue
        selected.update(
            (row, column)
            for row, text in numeric_values
            if len(text) in {3, 5}
        )
    return selected if len(selected) <= maximum_cells else set()


def _recover_original_resolution_risk_cells(
    image_path: Path,
    processing_scale: float,
    rectification: dict[str, Any],
    rectified_shape: tuple[int, int],
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    ocr_engine: Any,
) -> tuple[list[float], set[tuple[int, int]]]:
    """Re-read bounded numeric/text outliers from the original camera pixels."""
    if (
        processing_scale <= 0.0
        or not grid
        or not grid[0]
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or not callable(getattr(ocr_engine, "text_rec", None))
        or not callable(getattr(ocr_engine, "server_text_rec", None))
    ):
        return [], set()
    risk_modes = {
        (row, column): "numeric_insertion"
        for row, column in _dense_numeric_length_review_risks(grid)
        if len(str(grid[row][column]).strip()) == 5
    }
    short_text_risks = {
        (row, column)
        for row, column in _dense_repeated_text_residual_risks(grid)
        if len(_comparable_text(grid[row][column])) == 1
    }
    if len(short_text_risks) <= 4:
        risk_modes.update(
            {location: "short_text" for location in short_text_risks}
        )
    for header_row in range(min(4, len(grid) - 1)):
        for column, header in enumerate(grid[header_row]):
            if re.sub(r"\s+", "", str(header)) not in {"序号", "No.", "No"}:
                continue
            body = list(range(header_row + 1, len(grid)))
            matching = sum(
                str(grid[row][column]).strip() == str(offset + 1)
                for offset, row in enumerate(body)
            )
            if matching < max(6, len(body) - 2):
                continue
            for offset, row in enumerate(body):
                current = str(grid[row][column]).strip()
                expected = str(offset + 1)
                if current.isdigit() and current != expected:
                    risk_modes[(row, column)] = f"ordinal:{expected}"
    if processing_scale >= 0.999:
        risk_modes = {}
        unit_risks = _short_unit_visual_confusion_risks(grid)
        if len(unit_risks) <= 12:
            risk_modes.update({location: "unit" for location in unit_risks})
    if not risk_modes:
        return [], set()
    corners = np.asarray(rectification.get("corners", []), dtype=np.float32)
    if corners.shape != (4, 2):
        return [], set()
    rectified_height, rectified_width = rectified_shape
    if rectified_height < 2 or rectified_width < 2:
        return [], set()
    source = _read_image(image_path)
    source_height, source_width = source.shape[:2]
    rectified_corners = np.asarray(
        [
            [0.0, 0.0],
            [rectified_width - 1.0, 0.0],
            [rectified_width - 1.0, rectified_height - 1.0],
            [0.0, rectified_height - 1.0],
        ],
        dtype=np.float32,
    )
    to_resized_source = cv2.getPerspectiveTransform(
        rectified_corners,
        corners,
    )
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    all_scores: list[float] = []
    recovered: set[tuple[int, int]] = set()
    for row, column in sorted(risk_modes):
        rectified_cell = np.asarray(
            [[
                [columns[column], rows[row]],
                [columns[column + 1], rows[row]],
                [columns[column + 1], rows[row + 1]],
                [columns[column], rows[row + 1]],
            ]],
            dtype=np.float32,
        )
        source_cell = cv2.perspectiveTransform(
            rectified_cell,
            to_resized_source,
        )[0] / float(processing_scale)
        if (
            float(np.min(source_cell[:, 0])) < -1.0
            or float(np.min(source_cell[:, 1])) < -1.0
            or float(np.max(source_cell[:, 0])) > source_width
            or float(np.max(source_cell[:, 1])) > source_height
        ):
            continue
        target_width = max(
            8,
            int(round(max(
                np.linalg.norm(source_cell[1] - source_cell[0]),
                np.linalg.norm(source_cell[2] - source_cell[3]),
            ))),
        )
        target_height = max(
            8,
            int(round(max(
                np.linalg.norm(source_cell[3] - source_cell[0]),
                np.linalg.norm(source_cell[2] - source_cell[1]),
            ))),
        )
        target = np.asarray(
            [
                [0.0, 0.0],
                [target_width - 1.0, 0.0],
                [target_width - 1.0, target_height - 1.0],
                [0.0, target_height - 1.0],
            ],
            dtype=np.float32,
        )
        crop = cv2.warpPerspective(
            source,
            cv2.getPerspectiveTransform(source_cell.astype(np.float32), target),
            (target_width, target_height),
            flags=cv2.INTER_CUBIC,
            borderValue=(255, 255, 255),
        )
        tight = _tight_text_crop(crop)
        if tight.size == 0:
            continue
        views = [
            crop if crop.ndim == 3 else cv2.cvtColor(crop, cv2.COLOR_GRAY2BGR)
        ]
        candidates: list[tuple[str, float]] = []
        for recognizer in (ocr_engine.text_rec, ocr_engine.server_text_rec):
            output = recognizer(TextRecInput(img=views))
            _release_recognition_images(output)
            if len(output.txts) != len(views) or len(output.scores) != len(views):
                candidates = []
                break
            scores = [float(score) for score in output.scores]
            all_scores.extend(scores)
            candidates.extend(
                (str(text).strip(), score)
                for text, score in zip(output.txts, scores)
            )
        mode = risk_modes[(row, column)]
        score_floor = 0.85 if mode == "unit" else 0.95
        keys = {
            _comparable_text(text)
            for text, score in candidates
            if score >= score_floor
        }
        if (
            len(candidates) != len(views) * 2
            or len(keys) != 1
            or "" in keys
            or any(score < score_floor for _, score in candidates)
        ):
            continue
        selected = candidates[0][0]
        if mode == "numeric_insertion":
            accepted = bool(re.fullmatch(r"\d{4}", selected))
        elif mode.startswith("ordinal:"):
            accepted = selected == mode.split(":", 1)[1]
        elif mode == "unit":
            accepted = selected in {"A", "V"}
        else:
            accepted = bool(re.fullmatch(r"[\u3400-\u9fff]{2,4}", selected))
        if not accepted:
            continue
        grid[row][column] = selected
        confidence_grid[row][column] = 0.77
        recovered.add((row, column))
    del source
    return all_scores, recovered


def _recover_source_leading_glyphs(
    image_path: Path,
    processing_scale: float,
    rectification: dict[str, Any],
    rectified_shape: tuple[int, int],
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    ocr_engine: Any,
) -> tuple[list[float], set[tuple[int, int]]]:
    identifier_risks = _dense_identifier_prefix_risks(grid)
    risks = _dense_leading_glyph_omission_risks(grid) | identifier_risks
    if not risks or not grid or len(risks) > 12:
        return [], set()
    for row, column in risks:
        confidence_grid[row][column] = min(float(confidence_grid[row][column]), 0.77)
    if len(columns) != len(grid[0]) + 1 or len(rows) != len(grid) + 1:
        return [], set()
    corners = np.asarray(rectification.get("corners", []), dtype=np.float32)
    if corners.shape != (4, 2) or processing_scale <= 0:
        return [], set()
    height, width = rectified_shape
    frame = np.asarray(
        [[0, 0], [width - 1, 0], [width - 1, height - 1], [0, height - 1]],
        dtype=np.float32,
    )
    to_source = cv2.getPerspectiveTransform(frame, corners)
    source = _read_image(image_path)
    source_height, source_width = source.shape[:2]
    locations = []
    views = []
    for row, column in sorted(risks):
        cell = np.asarray([[
            [columns[column], rows[row]],
            [columns[column + 1], rows[row]],
            [columns[column + 1], rows[row + 1]],
            [columns[column], rows[row + 1]],
        ]], dtype=np.float32)
        source_cell = cv2.perspectiveTransform(cell, to_source)[0] / processing_scale
        expanded_views = []
        for ratio in (0.05, 0.10):
            quad = source_cell.copy()
            quad[0] -= (quad[1] - quad[0]) * ratio
            quad[3] -= (quad[2] - quad[3]) * ratio
            if (
                np.min(quad[:, 0]) < 0 or np.min(quad[:, 1]) < 0
                or np.max(quad[:, 0]) >= source_width
                or np.max(quad[:, 1]) >= source_height
            ):
                break
            target_width = int(round(max(
                np.linalg.norm(quad[1] - quad[0]), np.linalg.norm(quad[2] - quad[3])
            )))
            target_height = int(round(max(
                np.linalg.norm(quad[3] - quad[0]), np.linalg.norm(quad[2] - quad[1])
            )))
            if target_width < 8 or target_height < 8:
                break
            target = np.asarray(
                [[0, 0], [target_width - 1, 0],
                 [target_width - 1, target_height - 1], [0, target_height - 1]],
                dtype=np.float32,
            )
            expanded_views.append(cv2.warpPerspective(
                source, cv2.getPerspectiveTransform(quad, target),
                (target_width, target_height), flags=cv2.INTER_CUBIC,
                borderValue=(255, 255, 255),
            ))
        if len(expanded_views) == 2:
            locations.append((row, column))
            views.extend(expanded_views)
    del source
    if not locations:
        return [], set()

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    results = []
    scores = []
    for recognizer in (ocr_engine.fast_text_rec, ocr_engine.text_rec):
        output = recognizer(TextRecInput(img=[view.copy() for view in views]))
        results.append([str(value).strip() for value in output.txts])
        scores.append([float(value) for value in output.scores])
        _release_recognition_images(output)
    if any(len(values) != len(views) for values in results + scores):
        return [], set()

    recovered = set()
    for index, (row, column) in enumerate(locations):
        evidence = [
            (results[family][index * 2 + view], scores[family][index * 2 + view])
            for family in range(2) for view in range(2)
        ]
        keys = {_comparable_text(text) for text, _ in evidence}
        if len(keys) != 1 or "" in keys or min(score for _, score in evidence) < 0.85:
            continue
        selected = evidence[2][0]
        current = str(grid[row][column]).strip()
        if (row, column) in identifier_risks:
            accepted = bool(
                (
                    re.fullmatch(r"[A-Z]{1,2}\d{1,3}-\d{3,6}", selected)
                    and (selected[1:] == current or selected[1:] == current[1:])
                )
                or (
                    re.fullmatch(r"[A-Z]\d{2}", selected)
                    and re.fullmatch(r"[0-9<]\d{2}", current)
                    and selected[1:] == current[1:]
                )
            )
        else:
            peers = sum(str(values[column]).strip() == selected for values in grid)
            accepted = len(selected) == len(current) + 1 and selected.endswith(current) and peers >= 2
        if accepted:
            grid[row][column] = selected
            confidence_grid[row][column] = 0.86 if min(score for _, score in evidence) >= 0.95 else 0.77
            recovered.add((row, column))
    return [score for family in scores for score in family], recovered


def _repeated_digit_shape_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 24,
) -> set[tuple[int, int]]:
    """Select bounded 3-4 digit values containing one repeated camera glyph."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    body_start = max(_multilevel_header_rows_for_review(grid) or {0}) + 1
    selected = {
        (row, column)
        for row in range(body_start, len(grid))
        for column, value in enumerate(grid[row])
        for text in [str(value).strip()]
        if re.fullmatch(r"\d{3,4}", text)
        and max(text.count(digit) for digit in set(text)) >= 3
    }
    return selected if len(selected) <= maximum_cells else set()


def _invalid_quantity_glyph_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 8,
) -> set[tuple[int, int]]:
    """Select currency-like OCR glyphs only inside an explicit quantity column."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    quantity_headers = {
        column: row
        for row in range(min(5, len(grid)))
        for column, value in enumerate(grid[row])
        if "数量" in str(value)
    }
    selected = {
        (row, column)
        for column, header_row in quantity_headers.items()
        for row in range(header_row + 1, len(grid))
        if re.fullmatch(r"[£$¥￥]\d{2,4}", str(grid[row][column]).strip())
    }
    return selected if len(selected) <= maximum_cells else set()


def _short_unit_visual_confusion_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 24,
) -> set[tuple[int, int]]:
    """Select bounded unit glyphs whose camera shapes need isolated re-reading."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    unit_headers = {
        column: row
        for row in range(min(5, len(grid)))
        for column, value in enumerate(grid[row])
        if "单位" in str(value)
    }
    selected = {
        (row, column)
        for column, header_row in unit_headers.items()
        for row in range(header_row + 1, len(grid))
        if str(grid[row][column]).strip() in {"A", "V", "C", "c", "v", "m/s"}
    }
    return selected if len(selected) <= maximum_cells else set()


def _person_name_glyph_confusion_risks(
    grid: list[list[str]],
    *,
    maximum_cells: int = 8,
) -> set[tuple[int, int]]:
    """Select bounded 吴/昊 camera ambiguities only in an explicit person column."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    person_headers = {
        column: row
        for row in range(min(5, len(grid)))
        for column, value in enumerate(grid[row])
        if any(label in str(value) for label in ("负责人", "姓名", "人员"))
    }
    selected = {
        (row, column)
        for column, header_row in person_headers.items()
        for row in range(header_row + 1, len(grid))
        for text in [str(grid[row][column]).strip()]
        if re.fullmatch(r"[\u4e00-\u9fff]{2,3}", text)
        and any(character in text for character in "吴昊")
    }
    return selected if len(selected) <= maximum_cells else set()


def _recover_clipped_short_unit_multiview(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
) -> list[float]:
    """Recover one visibly clipped unit prefix from strict Medium multiview evidence."""
    if (
        not grid
        or not grid[0]
        or len(confidence_grid) != len(grid)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or any(len(row) != len(grid[0]) for row in grid + confidence_grid)
    ):
        return []
    unit_headers = {
        column: row
        for row in range(min(5, len(grid)))
        for column, value in enumerate(grid[row])
        if "单位" in str(value)
    }
    candidates = [
        (row, column)
        for column, header_row in unit_headers.items()
        for row in range(header_row + 1, len(grid))
        if str(grid[row][column]).strip() == "m/s"
    ]
    medium = getattr(ocr_engine, "text_rec", None)
    alternate = getattr(ocr_engine, "server_text_rec", None)
    if not candidates or not callable(medium) or not callable(alternate):
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    image_height, image_width = image.shape[:2]
    scores: list[float] = []
    for row, column in candidates:
        left = max(0, int(columns[column]))
        right = min(image_width, int(columns[column + 1]))
        top = max(0, int(rows[row]))
        bottom = min(image_height, int(rows[row + 1]))
        pad_x = max(1, min(4, (right - left) // 15))
        pad_y = max(1, min(3, (bottom - top) // 12))
        crop = image[top + pad_y : bottom - pad_y, left + pad_x : right - pad_x]
        tight = _tight_text_crop(crop)
        if tight.size == 0:
            continue
        gray = cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY) if tight.ndim == 3 else tight
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(4, 4)).apply(gray)
        unsharp = cv2.addWeighted(
            clahe,
            1.9,
            cv2.GaussianBlur(clahe, (0, 0), 1.2),
            -0.9,
            0,
        )
        raw_views = (crop, tight, clahe, unsharp)
        views = []
        for view in raw_views:
            scaled = cv2.resize(
                view,
                None,
                fx=3.2,
                fy=3.2,
                interpolation=cv2.INTER_LANCZOS4,
            )
            if scaled.ndim == 2:
                scaled = cv2.cvtColor(scaled, cv2.COLOR_GRAY2BGR)
            views.append(scaled)
        outputs: list[tuple[list[str], list[float]]] = []
        for recognizer in (medium, alternate):
            output = recognizer(TextRecInput(img=views))
            _release_recognition_images(output)
            texts = [str(value).strip() for value in output.txts]
            model_scores = [float(value) for value in output.scores]
            scores.extend(model_scores)
            if len(texts) != 4 or len(model_scores) != 4:
                outputs = []
                break
            outputs.append((texts, model_scores))
        if len(outputs) != 2:
            continue
        medium_texts, medium_scores = outputs[0]
        alternate_texts, alternate_scores = outputs[1]
        candidate = medium_texts[2]
        current = str(grid[row][column]).strip()
        if (
            candidate
            and candidate == medium_texts[3]
            and min(medium_scores[2], medium_scores[3]) >= 0.98
            and len(candidate) == len(current) + 1
            and candidate[1:] == current
            and re.fullmatch(r"[A-Za-zµμ]+/[A-Za-z]+", candidate)
            and any(
                text == candidate and score >= 0.90
                for text, score in zip(alternate_texts, alternate_scores)
            )
        ):
            grid[row][column] = candidate
            confidence_grid[row][column] = 0.77
    return scores


def _recover_explicit_summary_footer_row(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    candidate_columns: list[int],
    candidate_rows: list[int],
    page_text_evidence: list[tuple[str, float, float, float]],
    image: np.ndarray | None = None,
) -> bool:
    """Append one physically bounded summary row proved by page text."""
    if (
        not grid
        or not grid[0]
        or len(confidence_grid) != len(grid)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or len(candidate_columns) != len(columns)
        or len(candidate_rows) != len(rows) + 1
    ):
        return False
    column_gap = (
        float(median(right - left for left, right in zip(columns, columns[1:])))
        if len(columns) > 1
        else 0.0
    )
    row_gap = (
        float(median(bottom - top for top, bottom in zip(rows, rows[1:])))
        if len(rows) > 1
        else 0.0
    )
    column_tolerance = max(3.0, column_gap * 0.08)
    row_tolerance = max(3.0, row_gap * 0.12)
    if any(
        abs(float(expected) - float(observed)) > column_tolerance
        for expected, observed in zip(columns, candidate_columns)
    ) or any(
        abs(float(expected) - float(observed)) > row_tolerance
        for expected, observed in zip(rows, candidate_rows[:-1])
    ):
        return False
    footer_top, footer_bottom = candidate_rows[-2], candidate_rows[-1]
    entries = sorted(
        [
            (str(text).strip(), float(center_x), float(score))
            for text, center_x, center_y, score in page_text_evidence
            if str(text).strip()
            and float(score) >= 0.85
            and float(columns[0]) <= float(center_x) <= float(columns[-1])
            and float(footer_top) <= float(center_y) <= float(footer_bottom)
        ],
        key=lambda item: item[1],
    )
    joined = re.sub(r"\s+", "", "".join(text for text, _, _ in entries))
    if not re.search(r"(?:合计|总计|小计|共\d+(?:条|项|行|笔))", joined):
        return False
    footer = ["" for _ in grid[0]]
    footer_confidence = [0.0 for _ in grid[0]]
    for text, center_x, score in entries:
        column = next(
            (
                index
                for index, (left, right) in enumerate(zip(columns, columns[1:]))
                if float(left) <= center_x <= float(right)
            ),
            None,
        )
        if column is None:
            continue
        normalized = "".join(unicodedata.normalize("NFKC", text).split())
        if image is not None and normalized in {"-", "_", "—", "–", "−"}:
            left = max(0, int(round(columns[column])))
            right = min(image.shape[1], int(round(columns[column + 1])))
            top = max(0, int(round(footer_top)))
            bottom = min(image.shape[0], int(round(footer_bottom)))
            pad_x = max(2, min(5, (right - left) // 14))
            pad_y = max(2, min(4, (bottom - top) // 10))
            crop = image[top + pad_y : bottom - pad_y, left + pad_x : right - pad_x]
            if not _recover_horizontal_mark(crop, allow_shorter=True):
                continue
        footer[column] = f"{footer[column]} {text}".strip()
        footer_confidence[column] = min(
            0.77,
            score,
        )
    if not 1 <= sum(bool(value) for value in footer) <= max(3, len(footer) // 3):
        return False
    grid.append(footer)
    confidence_grid.append(footer_confidence)
    rows[:] = [int(value) for value in candidate_rows]
    return True


def _recover_repeated_digits_multimodel(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    *,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> tuple[list[float], set[tuple[int, int]]]:
    """Recover repeated digits only after staged Small/Medium view agreement."""
    if (
        not grid
        or not grid[0]
        or len(confidence_grid) != len(grid)
        or len(columns) != len(grid[0]) + 1
        or len(rows) != len(grid) + 1
        or any(len(row) != len(grid[0]) for row in grid + confidence_grid)
    ):
        return [], set()
    locations = sorted(
        _repeated_digit_shape_risks(grid) - (excluded_cells or set())
    )
    recognizers = [
        getattr(ocr_engine, name, None)
        for name in ("fast_text_rec", "text_rec")
    ]
    if not locations or not all(callable(recognizer) for recognizer in recognizers):
        return [], set()

    views: list[np.ndarray] = []
    valid_locations: list[tuple[int, int]] = []
    for row, column in locations:
        cell_views = _unit_cell_morphology_views(
            image,
            int(columns[column]),
            int(columns[column + 1]),
            int(rows[row]),
            int(rows[row + 1]),
        )
        if not cell_views:
            continue
        tight = _tight_text_crop(cell_views[-1])
        if tight.size == 0:
            continue
        gray = cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY) if tight.ndim == 3 else tight
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(4, 4)).apply(gray)
        unsharp = cv2.addWeighted(
            clahe,
            1.9,
            cv2.GaussianBlur(clahe, (0, 0), 1.2),
            -0.9,
            0,
        )
        for view in (tight, clahe, unsharp):
            scaled = cv2.resize(
                view,
                None,
                fx=3.2,
                fy=3.2,
                interpolation=cv2.INTER_LANCZOS4,
            )
            if scaled.ndim == 2:
                scaled = cv2.cvtColor(scaled, cv2.COLOR_GRAY2BGR)
            views.append(scaled)
        valid_locations.append((row, column))
    if not valid_locations:
        return [], set()

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    all_scores: list[float] = []
    small_output = recognizers[0](TextRecInput(img=views))
    _release_recognition_images(small_output)
    small_texts = [str(value).strip() for value in small_output.txts]
    small_scores = [float(value) for value in small_output.scores]
    all_scores.extend(small_scores)
    if len(small_texts) != len(views) or len(small_scores) != len(views):
        return all_scores, set()

    medium_indices: list[int] = []
    medium_views: list[np.ndarray] = []
    for index, (row, column) in enumerate(valid_locations):
        start = index * 3
        candidate_texts = set(small_texts[start : start + 3])
        current = str(grid[row][column]).strip()
        if (
            len(candidate_texts) != 1
            or any(score < 0.80 for score in small_scores[start : start + 3])
        ):
            continue
        selected = next(iter(candidate_texts))
        if (
            selected == current
            or not re.fullmatch(r"\d{3,4}", selected)
            or len(selected) != len(current)
        ):
            continue
        medium_indices.append(index)
        medium_views.extend(views[start : start + 3])
    if not medium_indices:
        return all_scores, set()

    medium_output = recognizers[1](TextRecInput(img=medium_views))
    _release_recognition_images(medium_output)
    medium_texts = [str(value).strip() for value in medium_output.txts]
    medium_scores = [float(value) for value in medium_output.scores]
    all_scores.extend(medium_scores)
    if (
        len(medium_texts) != len(medium_views)
        or len(medium_scores) != len(medium_views)
    ):
        return all_scores, set()

    recovered: set[tuple[int, int]] = set()
    for medium_index, location_index in enumerate(medium_indices):
        row, column = valid_locations[location_index]
        small_start = location_index * 3
        medium_start = medium_index * 3
        candidates = list(
            zip(
                small_texts[small_start : small_start + 3],
                small_scores[small_start : small_start + 3],
            )
        ) + list(
            zip(
                medium_texts[medium_start : medium_start + 3],
                medium_scores[medium_start : medium_start + 3],
            )
        )
        candidate_texts = {text for text, score in candidates if score >= 0.80}
        current = str(grid[row][column]).strip()
        if (
            len(candidate_texts) != 1
            or any(score < 0.80 for _, score in candidates)
        ):
            continue
        selected = next(iter(candidate_texts))
        if (
            selected == current
            or not re.fullmatch(r"\d{3,4}", selected)
            or len(selected) != len(current)
        ):
            continue
        grid[row][column] = selected
        confidence_grid[row][column] = 0.77
        recovered.add((row, column))
    return all_scores, recovered


def _standard_physical_consensus_locations(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    locked_cells: set[tuple[int, int]],
    *,
    preserve_recognition_batches: bool = True,
    certified_selective_review: bool = False,
) -> set[tuple[int, int]]:
    """Select risk cells from a clear ruled page for bounded Medium review."""
    if not grid or not grid[0] or len(confidence_grid) != len(grid):
        return set()
    column_count = len(grid[0])
    if (
        any(len(row) != column_count for row in grid + confidence_grid)
        or len(columns) != column_count + 1
        or len(rows) != len(grid) + 1
    ):
        return set()
    selected = _dense_screen_page_risk_locations(
        image,
        grid,
        confidence_grid,
        columns,
        rows,
        locked_cells=locked_cells,
        include_identifier_columns=not certified_selective_review,
    )
    selected.update(_numeric_unit_row_context_risks(grid))
    selected.update(_percentage_decimal_pattern_risks(grid))
    selected.update(_ipv4_sequence_truncation_risks(grid))
    selected.update(_dense_repeated_text_residual_risks(grid))
    selected.update(_dense_leading_glyph_omission_risks(grid))
    selected.update(_dense_numeric_length_review_risks(grid))
    selected.update(_dense_leading_zero_measurement_risks(grid))
    repeated_token_risks, _ = _dense_repeated_token_residual_risks(grid)
    selected.update(repeated_token_risks)
    angle_columns = {
        column
        for row in range(min(3, len(grid)))
        for column, value in enumerate(grid[row])
        if any(keyword in str(value) for keyword in ("方位角", "角度"))
    }
    selected.update(
        (row, column)
        for column in angle_columns
        for row in range(1, len(grid))
        if column < len(grid[row])
        and str(grid[row][column]).strip()
        and not re.fullmatch(
            r"[+\-]?\d{1,3}(?:\.\d+)?[°º]",
            str(grid[row][column]).strip(),
        )
    )
    structured_punctuation_risks: set[tuple[int, int]] = set()
    for row, values in enumerate(grid):
        for column, value in enumerate(values):
            text = str(value).strip()
            if not re.search(r"\d", text) or not re.search(r"[/：:；;_]", text):
                continue
            valid_time = re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", text)
            score = float(confidence_grid[row][column])
            if valid_time is not None and score >= 0.95:
                continue
            structured_punctuation_risks.add((row, column))
    selected.update(structured_punctuation_risks)
    if certified_selective_review:
        selected.update(
            _certified_selective_header_risks(grid, confidence_grid)
        )
    else:
        selected.update(
            (row, column)
            for row in range(min(2, len(grid)))
            for column in range(column_count)
            if str(grid[row][column]).strip()
        )
    selected.difference_update(locked_cells)
    unlocked_order = [
        (row, column)
        for row in range(len(grid))
        for column in range(column_count)
        if (row, column) not in locked_cells
    ]
    # Small ruled tables are inexpensive to re-read and are sensitive to
    # recognition batch composition.  Preserve the established full-table
    # Medium pass for them; selective review is reserved for larger grids.
    if len(unlocked_order) <= 64:
        return set(unlocked_order)
    if not preserve_recognition_batches:
        return selected
    expanded: set[tuple[int, int]] = set()
    for offset in range(0, len(unlocked_order), 4):
        batch_group = unlocked_order[offset : offset + 4]
        if selected.intersection(batch_group):
            expanded.update(batch_group)
    selected = expanded
    unlocked = set(unlocked_order)
    if selected and len(selected) >= int(math.ceil(len(unlocked) * 0.80)):
        return unlocked
    return selected


def _repeated_semantic_column_target(
    grid: list[list[str]],
    row: int,
    column: int,
    candidates: list[tuple[str, str, float]],
) -> str:
    """Use repeated column context plus two Medium views as a review suggestion."""
    if not grid or not 0 <= row < len(grid) or not 0 <= column < len(grid[row]):
        return ""
    header_labels = {
        label
        for header_row in range(min(3, len(grid)))
        if column < len(grid[header_row])
        for label in _header_semantic_labels(grid[header_row][column])
    }
    if not header_labels.intersection({"备注", "说明", "状态", "当前状态", "结果"}):
        return ""
    family_candidates = {
        family: (_motion_cell_consensus_key(text), float(score))
        for family, text, score in candidates
        if str(text).strip()
    }
    medium = family_candidates.get("medium")
    alternate = family_candidates.get("medium-alternate")
    if (
        medium is None
        or alternate is None
        or medium[1] < 0.45
        or alternate[1] < 0.45
    ):
        return ""
    current_key = _motion_cell_consensus_key(grid[row][column])
    repeated: dict[str, tuple[str, int]] = {}
    for other_row, values in enumerate(grid):
        if other_row == row or column >= len(values):
            continue
        text = str(values[column]).strip()
        key = _motion_cell_consensus_key(text)
        if len(key) >= 3:
            representative, count = repeated.get(key, (text, 0))
            repeated[key] = (representative, count + 1)
    matches = [
        representative
        for key, (representative, count) in repeated.items()
        if count >= 2
        and (not current_key or _text_edit_distance(current_key, key) <= 1)
        and _text_edit_distance(medium[0], key) <= 1
        and _text_edit_distance(alternate[0], key) <= 1
    ]
    return matches[0] if len(matches) == 1 else ""


def _complete_unique_common_header_prefix(value: Any) -> str:
    """Complete one missing trailing glyph only when the header is unique."""
    text = str(value).strip()
    key = _motion_cell_consensus_key(text)
    if len(key) < 2:
        return text
    matches = [
        label
        for label in _COMMON_HEADER_LABELS
        if len(_motion_cell_consensus_key(label)) == len(key) + 1
        and _motion_cell_consensus_key(label).startswith(key)
    ]
    return matches[0] if len(matches) == 1 else text


def _bounded_large_photo_low_confidence_cells(
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    locked_cells: set[tuple[int, int]],
    *,
    maximum_cells: int = 32,
) -> set[tuple[int, int]]:
    if (
        not grid
        or len(confidence_grid) != len(grid)
        or any(len(values) != len(scores) for values, scores in zip(grid, confidence_grid))
    ):
        return set()
    selected = {
        (row, column)
        for row, values in enumerate(grid)
        for column, value in enumerate(values)
        if str(value).strip()
        and (row, column) not in locked_cells
        and 0.0 <= float(confidence_grid[row][column]) < 0.80
    }
    return selected if 0 < len(selected) <= maximum_cells else set()


def _bounded_visible_blank_body_cells(
    grid: list[list[str]],
    locked_cells: set[tuple[int, int]],
    *,
    maximum_cells: int = 16,
) -> set[tuple[int, int]]:
    """Select dense body blanks for strict per-cell OCR, never for inference."""
    if not grid or not grid[0] or maximum_cells <= 0:
        return set()
    column_count = len(grid[0])
    if any(len(row) != column_count for row in grid):
        return set()
    header_rows = _multilevel_header_rows_for_review(grid)
    body_start = max(header_rows) + 1 if header_rows else 1
    if body_start >= len(grid):
        return set()
    body_rows = list(range(body_start, len(grid)))
    column_density = [
        sum(bool(str(grid[row][column]).strip()) for row in body_rows)
        / len(body_rows)
        for column in range(column_count)
    ]
    candidates: list[tuple[float, int, int]] = []
    for row in body_rows:
        row_density = (
            sum(bool(str(value).strip()) for value in grid[row]) / column_count
        )
        if row_density < 0.50:
            continue
        for column in range(column_count):
            if (
                (row, column) in locked_cells
                or str(grid[row][column]).strip()
                or column_density[column] < 0.50
            ):
                continue
            candidates.append(
                (column_density[column] * 2.0 + row_density, row, column)
            )
    candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
    return {
        (row, column)
        for _, row, column in candidates[:maximum_cells]
    }


def _non_unit_visible_blank_cells(
    grid: list[list[str]],
    visible_blank_cells: set[tuple[int, int]],
) -> set[tuple[int, int]]:
    """Leave blank unit cells to the stricter glyph-specific recovery paths."""
    unit_columns = {
        column
        for row in range(min(5, len(grid)))
        for column, value in enumerate(grid[row])
        if "单位" in str(value)
    }
    return {
        (row, column)
        for row, column in visible_blank_cells
        if column not in unit_columns
    }


def _verify_motion_blurred_ruled_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    *,
    view_mode: str = "motion",
    first_row: int = 0,
    selected_cells: set[tuple[int, int]] | None = None,
    row_columns: list[list[int]] | None = None,
    cell_span_widths: dict[tuple[int, int], int] | None = None,
    isolated_recognition: bool = False,
    isolated_group_size: int = 1,
    strict_blank_cross_model: bool = False,
    verified_cells_out: set[tuple[int, int]] | None = None,
    skip_raw_blank_retries: bool = False,
) -> list[float]:
    """Use Small page evidence and bounded Medium cell views to verify risks."""
    row_count = len(grid)
    column_count = len(grid[0]) if grid else 0
    if (
        row_count != len(rows) - 1
        or column_count != len(columns) - 1
        or len(confidence_grid) != row_count
        or any(len(row) != column_count for row in confidence_grid)
    ):
        return []
    medium_recognizer = getattr(ocr_engine, "text_rec", None)
    alternate_medium_recognizer = getattr(ocr_engine, "server_text_rec", None)
    if not callable(medium_recognizer):
        return []

    if view_mode not in {"motion", "motion_horizontal", "standard"}:
        raise ValueError(f"unsupported physical-cell view mode: {view_mode}")

    locations: list[tuple[int, int]] = []
    views: list[np.ndarray] = []
    raw_views: list[np.ndarray] = []
    for row, (top, bottom) in enumerate(zip(rows, rows[1:])):
        if row < first_row:
            continue
        local_columns = (
            row_columns[row]
            if row_columns is not None
            and row < len(row_columns)
            and len(row_columns[row]) == column_count + 1
            else columns
        )
        for column, (left, right) in enumerate(zip(local_columns, local_columns[1:])):
            if selected_cells is not None and (row, column) not in selected_cells:
                continue
            span_width = int((cell_span_widths or {}).get((row, column), 1))
            if span_width > 1:
                right = local_columns[min(column_count, column + span_width)]
            pad_x = 1 if view_mode == "standard" else (
                2
                if column in (0, column_count - 1)
                else max(2, min(5, (right - left) // 16))
            )
            pad_y = max(2, min(4, (bottom - top) // 12))
            crop = image[top + pad_y : bottom - pad_y, left + pad_x : right - pad_x]
            if crop.size == 0:
                continue
            tight = _tight_text_crop(crop)
            if tight.size == 0:
                continue
            raw_view = tight
            if raw_view.ndim == 2:
                raw_view = cv2.cvtColor(raw_view, cv2.COLOR_GRAY2BGR)
            if view_mode in {"motion", "motion_horizontal"}:
                gray = (
                    cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY)
                    if tight.ndim == 3
                    else tight
                )
                restored = _wiener_motion_deblur_view(
                    gray,
                    7,
                    0.0 if view_mode == "motion_horizontal" else 45.0,
                )
            else:
                restored = tight
            restored = cv2.resize(
                restored,
                None,
                fx=3.2,
                fy=3.2,
                interpolation=cv2.INTER_LANCZOS4,
            )
            if restored.ndim == 2:
                restored = cv2.cvtColor(restored, cv2.COLOR_GRAY2BGR)
            views.append(restored)
            raw_views.append(raw_view)
            locations.append((row, column))
    if not locations:
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    candidates: list[list[tuple[str, str, float]]] = [[] for _ in locations]
    all_scores: list[float] = []
    def semantic_headers() -> list[set[str]]:
        result: list[set[str]] = []
        for column in range(column_count):
            labels: set[str] = set()
            for header_row in range(min(3, row_count)):
                if column < len(grid[header_row]):
                    labels.update(_header_semantic_labels(grid[header_row][column]))
                    header_text = str(grid[header_row][column]).strip()
                    if "类别" in header_text or "分类" in header_text:
                        labels.add("类别")
                    if "单位" in header_text:
                        labels.add("单位")
                    if "信号名称" in header_text:
                        labels.add("信号名称")
            result.append(labels)
        return result

    semantic_headers_by_column = semantic_headers()

    def add_recognition_batch(
        family: str,
        recognizer: Any,
        indices: list[int],
    ) -> bool:
        if not indices:
            return True
        extreme_aspect_indices = [
            index
            for index in indices
            if views[index].shape[1]
            / max(1.0, float(views[index].shape[0]))
            >= 20.0
        ]
        extreme_aspect_locations = [
            [
                int(locations[index][0]),
                int(locations[index][1]),
                round(
                    views[index].shape[1]
                    / max(1.0, float(views[index].shape[0])),
                    3,
                ),
                int((cell_span_widths or {}).get(locations[index], 1)),
            ]
            for index in extreme_aspect_indices
        ]
        if extreme_aspect_locations:
            _write_runtime_trace(
                "route",
                name="extreme_aspect_cell_batch",
                family=family,
                locations=extreme_aspect_locations,
            )
        if isolated_recognition:
            group_size = max(1, int(isolated_group_size))
            recognition_groups = [
                indices[start : start + group_size]
                for start in range(0, len(indices), group_size)
            ]
        else:
            extreme_index_set = set(extreme_aspect_indices)
            ordinary_indices = [
                index for index in indices if index not in extreme_index_set
            ]
            recognition_groups = (
                [ordinary_indices, extreme_aspect_indices]
                if (
                    0 < len(extreme_aspect_indices) <= 8
                    and len(ordinary_indices) >= 8
                )
                else [indices]
            )
        for group in recognition_groups:
            output = recognizer(TextRecInput(img=[views[index] for index in group]))
            _release_recognition_images(output)
            texts = [str(text).strip() for text in output.txts]
            scores = [float(score) for score in output.scores]
            all_scores.extend(scores)
            if len(texts) != len(group) or len(scores) != len(group):
                return False
            for index, text, score in zip(group, texts, scores):
                candidates[index].append((family, text, score))
        return True

    def supported_group(index: int) -> list[tuple[str, str, float]] | None:
        groups: dict[str, list[tuple[str, str, float]]] = {}
        _, column = locations[index]
        column_semantics = semantic_headers_by_column[column]
        for family, text, score in candidates[index]:
            comparable = _motion_cell_consensus_key(text)
            # Signal-name cells often contain several OCR fragments. Two Medium
            # preprocessing views preserve their left-to-right order but may differ only in
            # presentation spaces; page OCR can instead concatenate the same
            # fragments in detector order. Ignore spaces only for consensus in
            # this explicitly labelled column so the two cell recognizers can
            # repair ordering without weakening spacing rules elsewhere.
            group_key = (
                re.sub(r"\s+", "", comparable)
                if "信号名称" in column_semantics
                else comparable
            )
            numeric_or_punctuated = bool(
                re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", comparable)
            )
            trusted_unit = bool(
                "单位" in column_semantics and _canonical_unit_text(text)
            )
            trusted_category_code = bool(
                "类别" in column_semantics
                and re.fullmatch(r"[\u4e00-\u9fff]+\d+", comparable)
            )
            if trusted_unit:
                score_floor = 0.60
            elif trusted_category_code:
                score_floor = 0.78
            else:
                score_floor = (
                    0.84
                    if numeric_or_punctuated
                    else 0.90
                    if len(comparable) == 1
                    else 0.78
                )
            if group_key and score >= score_floor:
                groups.setdefault(group_key, []).append((family, text, score))
        supported = [
            values
            for values in groups.values()
            # These are evidence views, not necessarily independent models.
            if len({family for family, _, _ in values}) >= 2
        ]
        if strict_blank_cross_model and index in initially_blank_indices:
            supported = [
                values
                for values in supported
                if {family for family, _, _ in values}
                >= {"small-cell", "medium", "medium-alternate"}
                and min(score for _, _, score in values) >= 0.98
            ]
        if len(supported) != 1:
            return None
        return supported[0]

    def apply_supported_group(
        index: int,
        values: list[tuple[str, str, float]],
    ) -> None:
        row, column = locations[index]
        slash_code_review = False
        semantic_code_column = bool(
            semantic_headers_by_column[column].intersection({"备注", "说明", "结果"})
        )
        code_candidates = [
            (family, str(text).strip(), float(score))
            for family, text, score in candidates[index]
            if re.fullmatch(r"N/?A", str(text).strip(), flags=re.IGNORECASE)
        ]
        normalized_codes = {
            re.sub(r"/", "", text).casefold()
            for _, text, _ in code_candidates
        }
        visible_slash = next(
            (
                text
                for family, text, score in code_candidates
                if family == "medium"
                and "/" in text
                and score >= 0.90
            ),
            "",
        )
        if (
            semantic_code_column
            and visible_slash
            and normalized_codes == {"na"}
            and len({family for family, _, _ in code_candidates}) >= 3
        ):
            selected = visible_slash
            slash_code_review = True
        elif "单位" in semantic_headers_by_column[column]:
            visible_spellings: dict[str, list[tuple[str, float]]] = {}
            for _, text, score in values:
                visible_spellings.setdefault(str(text).strip(), []).append((text, score))
            selected = max(
                visible_spellings.values(),
                key=lambda spellings: (
                    len(spellings),
                    max(score for _, score in spellings),
                ),
            )[0][0]
        else:
            selected = next(
                (text for family, text, _ in values if family == "medium"),
                max(values, key=lambda item: item[2])[1],
            )
        # Several OCR evidence views may agree on a short, legitimate header
        # (for example ``项目``).  Do not extend their result from a dictionary
        # prefix: that previously changed visible text into ``项目组``.
        current = str(grid[row][column]).strip()
        current_key = _motion_cell_consensus_key(current)
        selected_key = _motion_cell_consensus_key(selected)
        # Page OCR is better at retaining visible underscores in signal names,
        # while the per-cell models sometimes render the same separators as
        # spaces. Preserve the page spelling when character order is identical;
        # the cell consensus is still allowed to replace a reordered page value.
        if (
            "信号名称" in semantic_headers_by_column[column]
            and "_" in current
            and "_" not in selected
            and re.sub(r"[\s_]+", "", current_key)
            == re.sub(r"[\s_]+", "", selected_key)
        ):
            return
        if (
            view_mode == "standard"
            and row < min(3, row_count)
            and current in {"基础信息", "测量与判定"}
            and len(selected_key) < len(current_key)
            and selected_key
            and selected_key in current_key
        ):
            return
        left_neighbor_key = (
            _motion_cell_consensus_key(grid[row][column - 1])
            if column > 0
            else ""
        )
        right_neighbor_key = (
            _motion_cell_consensus_key(grid[row][column + 1])
            if column + 1 < column_count
            else ""
        )
        upper_neighbor_key = (
            _motion_cell_consensus_key(grid[row - 1][column])
            if row > 0
            else ""
        )
        lower_neighbor_key = (
            _motion_cell_consensus_key(grid[row + 1][column])
            if row + 1 < row_count
            else ""
        )

        def includes_neighbor_fragment(base: str, expanded: str) -> bool:
            if not base or len(expanded) <= len(base):
                return False
            if expanded.startswith(base):
                suffix = expanded[len(base) :]
                return bool(
                    suffix
                    and any(
                        neighbor.startswith(suffix)
                        for neighbor in (right_neighbor_key, lower_neighbor_key)
                    )
                )
            if expanded.endswith(base):
                prefix = expanded[: -len(base)]
                return bool(
                    prefix
                    and any(
                        neighbor.endswith(prefix)
                        for neighbor in (left_neighbor_key, upper_neighbor_key)
                    )
                )
            return False

        selected_is_neighbor_spill = includes_neighbor_fragment(
            current_key,
            selected_key,
        )
        current_has_neighbor_spill = includes_neighbor_fragment(
            selected_key,
            current_key,
        )
        column_headers = {
            str(grid[header_row][column]).strip()
            for header_row in range(min(3, row_count))
        }
        selected_is_likely_neighbor_spill = bool(
            selected_is_neighbor_spill
            or (
                len(selected_key) > len(current_key)
                and current_key in selected_key
                and column_headers.intersection({"优先级", "状态", "当前状态"})
            )
        )
        if (
            view_mode == "standard"
            and current
            and float(confidence_grid[row][column]) >= 0.90
            and selected_key != current_key
            and (
                (
                    len(selected_key) < len(current_key)
                    and selected_key in current_key
                    and not current_has_neighbor_spill
                )
                or selected_is_likely_neighbor_spill
            )
        ):
            return
        grid[row][column] = selected
        model_families = {
            "small" if family.startswith("small") else "medium"
            for family, _, _ in values
        }
        view_count = len({family for family, _, _ in values})
        consensus_confidence = (
            0.77
            if (
                slash_code_review
                or index in initially_blank_indices
                or len(model_families) < 2
            )
            else 0.90
            if view_count >= 3
            else 0.86
        )
        confidence_grid[row][column] = (
            max(float(confidence_grid[row][column]), consensus_confidence)
            if current_key == selected_key
            else consensus_confidence
        )
        if verified_cells_out is not None:
            verified_cells_out.add((row, column))

    all_indices = list(range(len(locations)))
    initially_blank_indices = {
        index
        for index, (row, column) in enumerate(locations)
        if not str(grid[row][column]).strip()
    }
    # V6 Small has already run once over the full page. Reuse that bounded
    # evidence instead of invoking its recognizer again for each physical cell.
    for index, (row, column) in enumerate(locations):
        current = str(grid[row][column]).strip()
        current_score = float(confidence_grid[row][column])
        if current and current_score > 0.0:
            candidates[index].append(("small-page", current, current_score))

    if strict_blank_cross_model and initially_blank_indices:
        small_recognizer = getattr(ocr_engine, "fast_text_rec", None)
        if callable(small_recognizer):
            if not add_recognition_batch(
                "small-cell",
                small_recognizer,
                sorted(initially_blank_indices),
            ):
                return all_scores

    # V6 Medium performs one complete, ordered physical-cell pass. Its alternate
    # preprocessing view sees only cells that Small+Medium did not confirm.
    if not add_recognition_batch("medium", medium_recognizer, all_indices):
        return all_scores
    unresolved = []
    for index, (row, column) in enumerate(locations):
        if str(grid[row][column]).strip() and _is_horizontal_mark_confusable(
            grid[row][column]
        ):
            continue
        values = supported_group(index)
        if values is None:
            unresolved.append(index)
        else:
            apply_supported_group(index, values)

    # Medium may have recovered a missing semantic header in the same pass.
    # Refresh before the alternate Medium view judges unresolved body cells so 类别1 is evaluated as a
    # category code rather than generic numeric text.
    semantic_headers_by_column = semantic_headers()
    if unresolved and callable(alternate_medium_recognizer):
        deferred_leading_extreme = {
            index
            for index in unresolved
            if locations[index][0] < min(2, row_count)
            and views[index].shape[1]
            / max(1.0, float(views[index].shape[0]))
            >= 20.0
        }
        alternate_indices = [
            index for index in unresolved if index not in deferred_leading_extreme
        ]
        if not add_recognition_batch(
            "medium-alternate", alternate_medium_recognizer, alternate_indices
        ):
            return all_scores
        still_unresolved = list(deferred_leading_extreme)
        for index in alternate_indices:
            values = supported_group(index)
            if values is None:
                still_unresolved.append(index)
            else:
                apply_supported_group(index, values)
                row, _ = locations[index]
                if row < min(3, row_count):
                    semantic_headers_by_column = semantic_headers()
        unresolved = still_unresolved

    leading_line_indices = [
        index
        for index in range(len(locations))
        if "信号名称" in semantic_headers_by_column[locations[index][1]]
        and re.match(
            r"[1Iil][A-Za-z]{2,}",
            re.sub(
                r"[\s_]+",
                "",
                str(grid[locations[index][0]][locations[index][1]]).strip(),
            ),
        )
    ]
    small_recognizer = getattr(ocr_engine, "fast_text_rec", None)
    if leading_line_indices and callable(small_recognizer):
        small_view_outputs = []
        for source_views in (views, raw_views):
            output = small_recognizer(
                TextRecInput(img=[source_views[index] for index in leading_line_indices])
            )
            _release_recognition_images(output)
            texts = [str(text).strip() for text in output.txts]
            scores = [float(score) for score in output.scores]
            all_scores.extend(scores)
            if (
                len(texts) != len(leading_line_indices)
                or len(scores) != len(leading_line_indices)
            ):
                small_view_outputs = []
                break
            small_view_outputs.append(list(zip(texts, scores)))
        corrected_leading_lines: set[int] = set()
        if len(small_view_outputs) == 2:
            line_like = {"1", "I", "i", "l"}
            for offset, index in enumerate(leading_line_indices):
                first_text, first_score = small_view_outputs[0][offset]
                second_text, second_score = small_view_outputs[1][offset]
                first_key = re.sub(
                    r"[\s_]+", "", _motion_cell_consensus_key(first_text)
                )
                second_key = re.sub(
                    r"[\s_]+", "", _motion_cell_consensus_key(second_text)
                )
                row, column = locations[index]
                current = str(grid[row][column]).strip()
                current_key = re.sub(
                    r"[\s_]+", "", _motion_cell_consensus_key(current)
                )
                if (
                    first_key
                    and first_key == second_key
                    and min(first_score, second_score) >= 0.94
                    and len(first_key) == len(current_key)
                    and first_key[1:].casefold() == current_key[1:].casefold()
                    and first_key[0] in line_like
                    and current_key[0] in line_like
                    and first_key[0] != current_key[0]
                ):
                    grid[row][column] = first_text
                    confidence_grid[row][column] = 0.77
                    corrected_leading_lines.add(index)
                    if verified_cells_out is not None:
                        verified_cells_out.add((row, column))
        unresolved = [
            index for index in unresolved if index not in corrected_leading_lines
        ]

    decimal_comma_indices = [
        index
        for index in range(len(locations))
        if "信号名称" in semantic_headers_by_column[locations[index][1]]
        and re.search(
            r"\d,\d",
            str(grid[locations[index][0]][locations[index][1]]),
        )
    ]
    if decimal_comma_indices and callable(small_recognizer):
        small_output = small_recognizer(
            TextRecInput(img=[raw_views[index] for index in decimal_comma_indices])
        )
        medium_output = medium_recognizer(
            TextRecInput(img=[raw_views[index] for index in decimal_comma_indices])
        )
        _release_recognition_images(small_output)
        _release_recognition_images(medium_output)
        small_texts = [str(text).strip() for text in small_output.txts]
        medium_texts = [str(text).strip() for text in medium_output.txts]
        small_scores = [float(score) for score in small_output.scores]
        medium_scores = [float(score) for score in medium_output.scores]
        all_scores.extend(small_scores)
        all_scores.extend(medium_scores)
        corrected_decimal_commas: set[int] = set()
        if (
            len(small_texts) == len(decimal_comma_indices)
            and len(medium_texts) == len(decimal_comma_indices)
            and len(small_scores) == len(decimal_comma_indices)
            and len(medium_scores) == len(decimal_comma_indices)
        ):
            for offset, index in enumerate(decimal_comma_indices):
                small_key = re.sub(
                    r"[\s_]+", "", _motion_cell_consensus_key(small_texts[offset])
                )
                medium_key = re.sub(
                    r"[\s_]+", "", _motion_cell_consensus_key(medium_texts[offset])
                )
                if (
                    small_key
                    and small_key == medium_key
                    and min(small_scores[offset], medium_scores[offset]) >= 0.90
                    and "," not in small_key
                    and re.search(r"\d\.\d", small_key)
                ):
                    row, column = locations[index]
                    grid[row][column] = medium_texts[offset]
                    confidence_grid[row][column] = 0.77
                    corrected_decimal_commas.add(index)
                    if verified_cells_out is not None:
                        verified_cells_out.add((row, column))
        unresolved = [
            index for index in unresolved if index not in corrected_decimal_commas
        ]

    # A dense recognizer batch can normalize one narrow four-digit quantity to
    # the width of its neighbours (for example, 9000 -> 0006).  Re-read only
    # the independently selected magnitude outliers as single physical cells.
    # These are two preprocessing views of the same Medium model, so even exact
    # agreement remains a yellow review value rather than a clean correction.
    quantity_outlier_indices = {
        index
        for index, location in enumerate(locations)
        if location in _dense_quantity_magnitude_outlier_risks(grid)
    }
    percentage_outlier_indices = {
        index
        for index, location in enumerate(locations)
        if location in _percentage_decimal_pattern_risks(grid)
    }
    isolated_format_indices = sorted(
        quantity_outlier_indices | percentage_outlier_indices
    )
    corrected_format_outliers: set[int] = set()
    if isolated_format_indices and callable(alternate_medium_recognizer):
        for index in isolated_format_indices:
            isolated_candidates: list[tuple[str, float]] = []
            for recognizer in (medium_recognizer, alternate_medium_recognizer):
                output = recognizer(TextRecInput(img=[views[index]]))
                _release_recognition_images(output)
                if len(output.txts) != 1 or len(output.scores) != 1:
                    isolated_candidates = []
                    break
                text = str(output.txts[0]).strip()
                score = float(output.scores[0])
                all_scores.append(score)
                isolated_candidates.append((text, score))
            selected_text = (
                isolated_candidates[0][0]
                if len(isolated_candidates) == 2
                else ""
            )
            valid_format = bool(
                re.fullmatch(r"\d{4}", selected_text)
                if index in quantity_outlier_indices
                else re.fullmatch(r"[+\-]?\d+(?:\.\d+)?%", selected_text)
            )
            if (
                len(isolated_candidates) != 2
                or isolated_candidates[0][0] != isolated_candidates[1][0]
                or not valid_format
                or min(score for _, score in isolated_candidates) < 0.95
            ):
                continue
            row, column = locations[index]
            grid[row][column] = selected_text
            confidence_grid[row][column] = 0.77
            corrected_format_outliers.add(index)
        unresolved = [
            index for index in unresolved if index not in corrected_format_outliers
        ]

    # Upscaling normally helps tiny crops, but it can also turn a clear glyph
    # into a different stroke (for example 类别1 -> 类刷1).  For an originally
    # blank physical cell only, retry the untouched tight crop when the scaled
    # views disagree. Two Medium preprocessing views must return exactly the
    # same text; because they are one model, this remains a yellow suggestion.
    # The same pass may have just recovered a missing header such as ``类别`` or
    # ``单位``. Refresh the column semantics before judging initially blank body
    # cells; otherwise correct values like ``类别1`` are rejected as generic
    # numeric text by a stale pre-recognition cache.
    semantic_headers_by_column = semantic_headers()
    raw_retry_indices = (
        []
        if skip_raw_blank_retries
        else [
            index
            for index in unresolved
            if index in initially_blank_indices
            and (
                strict_blank_cross_model
                or locations[index][0] < min(3, row_count)
                or semantic_headers_by_column[locations[index][1]].intersection(
                    {"单位", "类别"}
                )
            )
        ][:24]
    )
    if raw_retry_indices and callable(alternate_medium_recognizer):
        recovered_from_raw: set[int] = set()
        primary_candidates: dict[int, tuple[str, float]] = {}
        verification_component = getattr(
            ocr_engine, "_verification_recognizer", None
        )
        recognition_shape = getattr(
            verification_component, "rec_image_shape", None
        )
        base_width_ratio = None
        if recognition_shape is not None and len(recognition_shape) >= 3:
            recognition_height = float(recognition_shape[1])
            recognition_width = float(recognition_shape[2])
            if recognition_height > 0.0 and recognition_width > 0.0:
                base_width_ratio = recognition_width / recognition_height

        batchable_primary_indices = []
        isolated_primary_indices = []
        for index in raw_retry_indices:
            raw_height, raw_width = raw_views[index].shape[:2]
            if raw_height < 6 or raw_width < 6:
                continue
            # 低于模型基础宽高比时，单图和同类批次都使用同一固定输入宽度；
            # 只合并这部分裁格，超宽裁格仍逐格识别，避免改变归一化证据。
            if (
                base_width_ratio is not None
                and raw_height > 0
                and raw_width / float(raw_height) <= base_width_ratio
            ):
                batchable_primary_indices.append(index)
            else:
                isolated_primary_indices.append(index)

        if len(batchable_primary_indices) >= 2:
            output = medium_recognizer(
                TextRecInput(
                    img=[raw_views[index] for index in batchable_primary_indices]
                )
            )
            _release_recognition_images(output)
            if (
                len(output.txts) == len(batchable_primary_indices)
                and len(output.scores) == len(batchable_primary_indices)
            ):
                for index, text, score in zip(
                    batchable_primary_indices, output.txts, output.scores
                ):
                    value = (str(text).strip(), float(score))
                    primary_candidates[index] = value
                    all_scores.append(value[1])
            else:
                isolated_primary_indices.extend(batchable_primary_indices)
        else:
            isolated_primary_indices.extend(batchable_primary_indices)

        for index in isolated_primary_indices:
            output = medium_recognizer(TextRecInput(img=[raw_views[index]]))
            _release_recognition_images(output)
            if len(output.txts) != 1 or len(output.scores) != 1:
                continue
            value = (str(output.txts[0]).strip(), float(output.scores[0]))
            primary_candidates[index] = value
            all_scores.append(value[1])

        for index in raw_retry_indices:
            primary_candidate = primary_candidates.get(index)
            if primary_candidate is None:
                continue
            row, column = locations[index]
            current_column_semantics = semantic_headers()[column]
            text, score = primary_candidate
            key = _motion_cell_consensus_key(text)
            numeric_or_punctuated = bool(
                re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", key)
            )
            primary_can_be_accepted = bool(
                score >= 0.80
                and (
                    (
                        "单位" in current_column_semantics
                        and _canonical_unit_text(text)
                    )
                    or (len(key) >= 2 and not numeric_or_punctuated)
                    or (
                        "类别" in current_column_semantics
                        and re.fullmatch(r"[\u4e00-\u9fff]+\d+", key)
                    )
                )
            )
            if not primary_can_be_accepted:
                # 主视图已不满足任一接受分支的必要条件，第二视图不可能
                # 改变结论；保留未确认状态并停止这次无效推理。
                continue
            output = alternate_medium_recognizer(
                TextRecInput(img=[raw_views[index]])
            )
            _release_recognition_images(output)
            if len(output.txts) != 1 or len(output.scores) != 1:
                continue
            alternate_candidate = (
                str(output.txts[0]).strip(),
                float(output.scores[0]),
            )
            all_scores.append(alternate_candidate[1])
            raw_candidates = {
                "medium": primary_candidate,
                "medium-alternate": alternate_candidate,
            }
            medium_text, medium_score = raw_candidates["medium"]
            alternate_text, alternate_score = raw_candidates["medium-alternate"]
            key = _motion_cell_consensus_key(medium_text)
            if not key or key != _motion_cell_consensus_key(alternate_text):
                continue
            unit_value = _canonical_unit_text(medium_text)
            numeric_or_punctuated = bool(
                re.search(r"[0-9%+\-\u2212\u2013\u2014./:]", key)
            )
            accepted = bool(
                (
                    "单位" in current_column_semantics
                    and unit_value
                    and medium_score >= 0.80
                    and alternate_score >= 0.60
                )
                or (
                    len(key) >= 2
                    and not numeric_or_punctuated
                    and medium_score >= 0.80
                    and alternate_score >= 0.72
                )
                or (
                    "类别" in current_column_semantics
                    and re.fullmatch(r"[\u4e00-\u9fff]+\d+", key)
                    and medium_score >= 0.80
                    and alternate_score >= 0.72
                )
            )
            if not accepted:
                continue
            grid[row][column] = medium_text
            confidence_grid[row][column] = 0.77
            if row < min(3, row_count):
                semantic_headers_by_column = semantic_headers()
            recovered_from_raw.add(index)
        unresolved = [
            index for index in unresolved if index not in recovered_from_raw
        ]

    repeated_token_risks, repeated_token_counts = (
        _dense_repeated_token_residual_risks(grid)
    )
    repeated_token_indices = {
        index
        for index, location in enumerate(locations)
        if location in repeated_token_risks
    }
    if repeated_token_indices and callable(alternate_medium_recognizer):
        corrected_indices: set[int] = set()
        for index in sorted(repeated_token_indices):
            row, column = locations[index]
            left, right = columns[column], columns[column + 1]
            top, bottom = rows[row], rows[row + 1]
            inner_pad_x = max(2, min(4, (right - left) // 20))
            inner_pad_y = max(2, min(4, (bottom - top) // 12))
            inner_crop = image[
                top + inner_pad_y : bottom - inner_pad_y,
                left + inner_pad_x : right - inner_pad_x,
            ]
            inner_raw_view = _tight_text_crop(inner_crop)
            if inner_raw_view.size == 0:
                continue
            raw_candidates: dict[str, tuple[str, float]] = {}
            for family, recognizer in (
                ("medium", medium_recognizer),
                ("medium-alternate", alternate_medium_recognizer),
            ):
                output = recognizer(TextRecInput(img=[inner_raw_view]))
                _release_recognition_images(output)
                if len(output.txts) != 1 or len(output.scores) != 1:
                    raw_candidates = {}
                    break
                score = float(output.scores[0])
                raw_candidates[family] = (str(output.txts[0]).strip(), score)
                all_scores.append(score)
            if len(raw_candidates) != 2:
                continue
            medium_text, medium_score = raw_candidates["medium"]
            alternate_text, alternate_score = raw_candidates["medium-alternate"]
            correction = _select_repeated_token_raw_consensus(
                grid[row][column],
                medium_text,
                medium_score,
                alternate_text,
                alternate_score,
                repeated_token_counts,
            )
            if correction is None:
                continue
            grid[row][column] = correction
            confidence_grid[row][column] = 0.86
            corrected_indices.add(index)
        unresolved = [
            index for index in unresolved if index not in corrected_indices
        ]

    # An unresolved alternate-view disagreement is evidence, not permission to
    # publish the Small/Medium majority. Keep visible text for review, but make the strict
    # publication gate block it; a detector-missed blank stays explicitly empty.
    for index in unresolved:
        row, column = locations[index]
        confidence_grid[row][column] = (
            min(float(confidence_grid[row][column]), 0.77)
            if str(grid[row][column]).strip()
            else -1.0
        )

    semantic_indices = (
        range(len(locations)) if view_mode == "motion" else unresolved
    )
    for index in semantic_indices:
        row, column = locations[index]
        target = _repeated_semantic_column_target(
            grid,
            row,
            column,
            candidates[index],
        )
        if target:
            grid[row][column] = target
            confidence_grid[row][column] = 0.77

    # When one blurred category cell remains uncertain, medium OCR may still
    # read the same vocabulary already visible twice in that column. Require a
    # near-match to the current crop before using that table-internal support.
    column_counts: list[dict[str, int]] = []
    for column in range(column_count):
        counts: dict[str, int] = {}
        for row in range(row_count):
            comparable = _motion_cell_consensus_key(grid[row][column])
            if comparable:
                counts[comparable] = counts.get(comparable, 0) + 1
        column_counts.append(counts)
    vocabulary_indices = (
        range(len(locations)) if view_mode == "standard" else unresolved
    )
    for index in vocabulary_indices:
        row, column = locations[index]
        current = str(grid[row][column]).strip()
        high_confidence_current = bool(
            current and float(confidence_grid[row][column]) >= 0.78
        )
        if high_confidence_current and view_mode != "standard":
            continue
        medium = next(
            candidate for candidate in candidates[index] if candidate[0] == "medium"
        )
        medium_key = _motion_cell_consensus_key(medium[1])
        current_key = _motion_cell_consensus_key(current)
        if (
            medium[2] < (0.88 if high_confidence_current else 0.80)
            or len(medium_key) < 2
            or column_counts[column].get(medium_key, 0) < 2
            or (
                high_confidence_current
                and (
                    current_key == medium_key
                    or _text_edit_distance(current_key, medium_key) != 1
                )
            )
            or (
                current_key
                and _text_edit_distance(current_key, medium_key)
                > max(1, int(round(len(medium_key) * 0.25)))
            )
        ):
            continue
        grid[row][column] = medium[1]
        confidence_grid[row][column] = (
            0.77 if current and view_mode == "standard" else 0.86
        )
    return all_scores


def _recover_shadowed_responsible_column(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
) -> list[float]:
    """Re-read one shadowed responsible-person column with bounded light views."""
    header_row = -1
    column = -1
    for row in range(min(3, len(grid) - 1)):
        for candidate_column, value in enumerate(grid[row]):
            if str(value).strip() == "负责人":
                header_row = row
                column = candidate_column
                break
        if column >= 0:
            break
    if (
        column < 0
        or len(grid) - header_row - 1 < 8
        or len(rows) != len(grid) + 1
        or len(columns) != len(grid[0]) + 1
    ):
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    locations: list[tuple[int, int]] = []
    views: list[np.ndarray] = []
    for row in range(header_row + 1, len(grid)):
        crop = image[
            rows[row] + 2 : rows[row + 1] - 2,
            columns[column] + 2 : columns[column + 1] - 2,
        ]
        tight = _tight_text_crop(crop) if crop.size else crop
        if tight.size == 0:
            continue
        gray = cv2.cvtColor(tight, cv2.COLOR_BGR2GRAY) if tight.ndim == 3 else tight
        local_views = (
            tight,
            cv2.divide(gray, cv2.GaussianBlur(gray, (0, 0), 9), scale=235),
            cv2.createCLAHE(clipLimit=2.5, tileGridSize=(4, 4)).apply(gray),
        )
        for view in local_views:
            resized = cv2.resize(
                view, None, fx=3.2, fy=3.2, interpolation=cv2.INTER_LANCZOS4
            )
            if resized.ndim == 2:
                resized = cv2.cvtColor(resized, cv2.COLOR_GRAY2BGR)
            views.append(resized)
            locations.append((row, column))
    if not views:
        return []

    candidates: dict[tuple[int, int], list[tuple[str, str, float]]] = {}
    scores: list[float] = []

    def add_family(
        family: str,
        recognizer: Any,
        selected_indices: list[int],
    ) -> None:
        if not callable(recognizer) or not selected_indices:
            return
        selected_views = [views[index] for index in selected_indices]
        selected_locations = [locations[index] for index in selected_indices]
        output = recognizer(TextRecInput(img=selected_views))
        _release_recognition_images(output)
        output_scores = [float(score) for score in output.scores]
        scores.extend(output_scores)
        if (
            len(output.txts) != len(selected_views)
            or len(output_scores) != len(selected_views)
        ):
            return
        for location, text, score in zip(
            selected_locations, output.txts, output_scores
        ):
            value = str(text).strip()
            if value:
                candidates.setdefault(location, []).append(
                    (family, value, float(score))
                )

    def apply_supported(location: tuple[int, int]) -> bool:
        values = candidates.get(location, [])
        grouped: dict[str, list[tuple[str, str, float]]] = {}
        for family, text, score in values:
            key = _motion_cell_consensus_key(text)
            if score >= 0.45 and re.fullmatch(r"[\u3400-\u9fff]{2,4}", key):
                grouped.setdefault(key, []).append((family, text, score))
        supported = [
            group
            for group in grouped.values()
            if len({family for family, _, _ in group}) >= 2
        ]
        if len(supported) != 1:
            return False
        row, target_column = location
        selected = next(
            (text for family, text, _ in supported[0] if family == "medium"),
            max(supported[0], key=lambda item: item[2])[1],
        )
        if _motion_cell_consensus_key(grid[row][target_column]) != _motion_cell_consensus_key(selected):
            grid[row][target_column] = selected
            confidence_grid[row][target_column] = 0.77
        return True

    all_indices = list(range(len(views)))
    add_family("medium", getattr(ocr_engine, "text_rec", None), all_indices)
    add_family("v5-server", getattr(ocr_engine, "server_text_rec", None), all_indices)

    unique_locations = list(dict.fromkeys(locations))
    for location in unique_locations:
        apply_supported(location)

    _repair_periodic_responsible_labels(grid, confidence_grid, candidates)
    return scores


def _ruled_grid_recovery_geometry(
    columns: list[int],
    rows: list[int],
) -> dict[str, Any]:
    """Describe ruled cells with the geometry expected by blank recovery."""
    anchors = [
        (float(left) + float(right)) * 0.5
        for left, right in zip(columns, columns[1:])
    ]
    row_centers = [
        (float(top) + float(bottom)) * 0.5
        for top, bottom in zip(rows, rows[1:])
    ]
    return {
        "anchors": anchors,
        "row_centers": row_centers,
        "column_boundaries": [float(value) for value in columns],
        "row_boundaries": [float(value) for value in rows],
        "grouped_rows": [[] for _ in row_centers],
        "first_structured_row": 0,
    }


def _locked_merged_blank_locations(
    image: np.ndarray,
    columns: list[int],
    rows: list[int],
    grid: list[list[str]],
) -> set[tuple[int, int]]:
    """Return subordinate title cells that blank recovery must not refill."""
    if len(grid) < 2 or not grid[0] or len(columns) != len(grid[0]) + 1:
        return set()
    if len(rows) != len(grid) + 1:
        return set()

    _, vertical, _ = pipeline._grid_maps(image)
    image_height, image_width = vertical.shape[:2]

    def divider_support(row_index: int) -> list[float]:
        top, bottom = rows[row_index], rows[row_index + 1]
        inset = max(2, int(round((bottom - top) * 0.16)))
        band_top = max(0, min(image_height, top + inset))
        band_bottom = max(band_top + 1, min(image_height, bottom - inset))
        support: list[float] = []
        for position in columns[1:-1]:
            left = max(0, min(image_width, position - 3))
            right = max(left + 1, min(image_width, position + 4))
            band = vertical[band_top:band_bottom, left:right]
            support.append(
                float(np.mean(np.any(band > 0, axis=1))) if band.size else 0.0
            )
        return support

    locked: set[tuple[int, int]] = set()
    candidate_rows = [0]
    first_row_values = [str(value).strip() for value in grid[0] if str(value).strip()]
    if first_row_values and (
        sum(bool(re.fullmatch(r"[A-Z]{1,3}|\d+", value)) for value in first_row_values)
        / len(first_row_values)
        >= 0.60
    ):
        candidate_rows.append(1)

    column_count = len(grid[0])
    for row_index in candidate_rows:
        if row_index >= len(grid) - 1:
            continue
        populated = [
            column
            for column, value in enumerate(grid[row_index])
            if str(value).strip()
        ]
        if len(populated) != 1:
            continue
        following_populations = [
            sum(bool(str(value).strip()) for value in grid[index])
            for index in range(row_index + 1, min(len(grid), row_index + 3))
        ]
        if not following_populations or not (
            following_populations[0] >= 2
            or (
                following_populations[0] >= 1
                and len(following_populations) >= 2
                and following_populations[1] >= column_count - 1
            )
        ):
            continue
        title_support = divider_support(row_index)
        if not title_support or any(value >= 0.18 for value in title_support):
            continue
        structured_row = next(
            (
                index
                for index in range(row_index + 1, min(len(grid), row_index + 3))
                if sum(bool(str(value).strip()) for value in grid[index])
                >= min(column_count, max(3, column_count - 1))
            ),
            None,
        )
        if structured_row is None:
            continue
        structured_support = divider_support(structured_row)
        if (
            not structured_support
            or np.mean([value >= 0.35 for value in structured_support]) < 0.70
        ):
            continue
        locked.update(
            (row_index, column)
            for column in range(column_count)
            if column != populated[0]
        )

    # Sparse stacked headers may contain several independent merged groups on
    # the same row.  Lock each physically open span only when the following
    # dense header row restores the missing dividers, proving that the gaps are
    # deliberate merges rather than weak global line detection.
    for row_index in range(len(grid)):
        if sum(bool(str(value).strip()) for value in grid[row_index]) > max(
            3, column_count // 2
        ):
            continue
        nearby_rows = sorted(
            (
                index
                for index in range(max(0, row_index - 2), min(len(grid), row_index + 3))
                if index != row_index
                and sum(bool(str(value).strip()) for value in grid[index])
                >= min(column_count, max(3, column_count - 1))
            ),
            key=lambda index: abs(index - row_index),
        )
        structured_row = nearby_rows[0] if nearby_rows else None
        if structured_row is None:
            continue
        current_support = divider_support(row_index)
        structured_support = divider_support(structured_row)
        missing_boundaries = [
            index
            for index, (current, detailed) in enumerate(
                zip(current_support, structured_support),
                start=1,
            )
            if current < 0.18 and detailed >= 0.35
        ]
        runs: list[list[int]] = []
        for boundary in missing_boundaries:
            if not runs or boundary != runs[-1][-1] + 1:
                runs.append([])
            runs[-1].append(boundary)
        for run in runs:
            start_column = run[0] - 1
            end_column = run[-1]
            populated = [
                column
                for column in range(start_column, end_column + 1)
                if str(grid[row_index][column]).strip()
            ]
            if len(populated) != 1:
                continue
            locked.update(
                (row_index, column)
                for column in range(start_column, end_column + 1)
                if column != populated[0]
            )
    return locked


def _ruled_semantic_header_kind(value: Any) -> str:
    header = _comparable_text(value).casefold()
    header_has_frequency_unit = bool(re.search(r"[kmgt]?hz", header))
    header_has_sample_unit = bool(re.search(r"[kmgt]?(?:s|sa)/s", header))
    if "采样率" in header:
        return "sample_rate_header_unit" if header_has_sample_unit else "sample_rate"
    if "功率" in header:
        return "power"
    if "带宽" in header:
        return "bandwidth_header_unit" if header_has_frequency_unit else "bandwidth"
    if "频率" in header:
        return "frequency_header_unit" if header_has_frequency_unit else "frequency"
    if "数量" in header or "数目" in header or "个数" in header:
        return "quantity"
    if "日期" in header:
        return "date"
    return ""


def _ruled_semantic_value_is_valid(kind: str, value: Any) -> bool:
    normalized = unicodedata.normalize("NFKC", str(value)).translate(
        _DASH_TRANSLATION
    )
    normalized = re.sub(r"\s+", "", normalized).casefold()
    number = r"[+\-]?\d+(?:\.\d+)?"
    if kind == "sample_rate":
        return bool(
            re.fullmatch(
                number + r"(?:%|[kmgt]?hz|[kmgt]?s/s|[kmgt]?sa/s)",
                normalized,
            )
        )
    if kind == "sample_rate_header_unit":
        return bool(
            re.fullmatch(number + r"(?:[kmgt]?s/s|[kmgt]?sa/s)?", normalized)
        )
    if kind == "power":
        return bool(re.fullmatch(number + r"(?:dbm)?", normalized))
    if kind in {"frequency", "bandwidth"}:
        return bool(re.fullmatch(number + r"(?:[kmgt]?hz)", normalized))
    if kind in {"frequency_header_unit", "bandwidth_header_unit"}:
        return bool(re.fullmatch(number + r"(?:[kmgt]?hz)?", normalized))
    if kind == "quantity":
        return bool(re.fullmatch(number + r"(?:个|台|套|件)?", normalized))
    if kind == "date":
        match = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", normalized)
        if match is None:
            return False
        year, month, day = (int(part) for part in match.groups())
        if not 1900 <= year <= 2199 or not 1 <= month <= 12:
            return False
        month_days = [
            31,
            29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28,
            31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
        ]
        return 1 <= day <= month_days[month - 1]
    return True


def _suspicious_ruled_semantic_locations(
    grid: list[list[str]],
) -> list[tuple[int, int, str, str]]:
    if len(grid) < 2 or not grid[0]:
        return []
    header_limit = min(3, len(grid) - 1)
    header_index = -1
    kinds: list[str] = []
    for row_index in range(header_limit):
        candidate_kinds = [
            _ruled_semantic_header_kind(value) for value in grid[row_index]
        ]
        if sum(bool(kind) for kind in candidate_kinds) > sum(bool(kind) for kind in kinds):
            header_index = row_index
            kinds = candidate_kinds
    if header_index < 0 or not any(kinds):
        return []

    sample_column = next(
        (index for index, kind in enumerate(kinds) if kind.startswith("sample_rate")),
        -1,
    )
    power_column = next(
        (index for index, kind in enumerate(kinds) if kind == "power"),
        -1,
    )
    quantity_columns = [
        index for index, kind in enumerate(kinds) if kind == "quantity"
    ]
    locations: dict[tuple[int, int], tuple[str, str]] = {}
    for row_index in range(header_index + 1, len(grid)):
        row = grid[row_index]
        for column, kind in enumerate(kinds):
            if not kind or column >= len(row):
                continue
            value = str(row[column]).strip()
            if value and not _ruled_semantic_value_is_valid(kind, value):
                locations[(row_index, column)] = (kind, "invalid_format")
        invalid_quantity_columns = [
            column
            for column in quantity_columns
            if column < len(row)
            and str(row[column]).strip()
            and not _ruled_semantic_value_is_valid("quantity", row[column])
        ]
        for column in invalid_quantity_columns:
            for neighbour in quantity_columns:
                if abs(neighbour - column) == 1 and neighbour < len(row):
                    locations.setdefault(
                        (row_index, neighbour),
                        ("quantity", "boundary_pair"),
                    )
        if (
            0 <= sample_column < len(row)
            and 0 <= power_column < len(row)
            and not _ruled_semantic_value_is_valid(
                kinds[sample_column], row[sample_column]
            )
        ):
            # A page OCR box commonly spans the power/sample boundary and puts
            # both values in the power cell. Re-read the pair as two bounded
            # physical cells even when the fused number looks syntactically
            # valid by itself (for example -10.008).
            locations[(row_index, sample_column)] = (
                "sample_rate", "boundary_pair"
            )
            locations[(row_index, power_column)] = ("power", "boundary_pair")

    # A fused neighbouring fragment can still look like a syntactically valid
    # power value (for example -20 becoming 520 or -30 becoming 2530).  Learn
    # only the signed/magnitude pattern of this physical column and use it as a
    # re-recognition trigger; never manufacture the missing sign from peers.
    for column, kind in enumerate(kinds):
        if kind != "power":
            continue
        numeric_values: list[tuple[int, str, float]] = []
        for row_index in range(header_index + 1, len(grid)):
            if column >= len(grid[row_index]):
                continue
            normalized = re.sub(
                r"\s+",
                "",
                unicodedata.normalize("NFKC", str(grid[row_index][column])).translate(
                    _DASH_TRANSLATION
                ),
            ).casefold()
            match = re.fullmatch(r"([+\-]?)(\d+(?:\.\d+)?)(?:dbm)?", normalized)
            if match is not None:
                numeric_values.append(
                    (row_index, match.group(1), abs(float(match.group(2))))
                )
        ordinary_magnitudes = [
            magnitude for _, _, magnitude in numeric_values if magnitude <= 100.0
        ]
        typical_magnitude = (
            float(np.median(ordinary_magnitudes)) if ordinary_magnitudes else 0.0
        )
        signed = [item for item in numeric_values if item[1] in {"+", "-"}]
        negative_magnitudes = [
            magnitude for _, sign, magnitude in numeric_values if sign == "-"
        ]
        for row_index, sign, magnitude in numeric_values:
            if typical_magnitude > 0 and magnitude > max(100.0, typical_magnitude * 5.0):
                locations[(row_index, column)] = (
                    "power", "power_magnitude_outlier"
                )
                continue
            matching_negative = any(
                abs(candidate - magnitude) <= max(0.05, magnitude * 0.01)
                for candidate in negative_magnitudes
            )
            if (
                not sign
                and len(signed) >= 3
                and len(signed) / max(1.0, float(len(numeric_values))) >= 0.45
                and matching_negative
            ):
                locations[(row_index, column)] = (
                    "power", "power_missing_sign"
                )

    # Learn the dominant decimal precision only as a re-recognition trigger.
    # Never insert a decimal point from neighboring rows: the bounded physical
    # crop must still be confirmed by independent model families below.
    numeric_pattern = re.compile(
        r"[+\-]?\d+(?:\.(\d+))?"
        r"(?:[kmgt]?(?:hz|s/s|sa/s)|dbm|个|台|套|件)?"
    )
    for column, kind in enumerate(kinds):
        if not kind:
            continue
        numeric_rows: list[tuple[int, int]] = []
        precision_counts: dict[int, int] = {}
        for row_index in range(header_index + 1, len(grid)):
            if column >= len(grid[row_index]):
                continue
            normalized = re.sub(
                r"\s+",
                "",
                unicodedata.normalize(
                    "NFKC", str(grid[row_index][column])
                ).translate(_DASH_TRANSLATION),
            ).casefold()
            match = numeric_pattern.fullmatch(normalized)
            if match is None:
                continue
            precision = len(match.group(1) or "")
            numeric_rows.append((row_index, precision))
            precision_counts[precision] = precision_counts.get(precision, 0) + 1
        decimal_precisions = {
            precision: count
            for precision, count in precision_counts.items()
            if precision > 0
        }
        if not decimal_precisions:
            continue
        _, dominant_count = max(
            decimal_precisions.items(),
            key=lambda item: (item[1], item[0]),
        )
        if (
            dominant_count < 4
            or dominant_count / max(1.0, float(len(numeric_rows))) < 0.60
        ):
            continue
        for row_index, precision in numeric_rows:
            if precision == 0:
                locations.setdefault(
                    (row_index, column),
                    (kind, "decimal_precision_mismatch"),
                )
    return [
        (row, column, kind, reason)
        for (row, column), (kind, reason) in sorted(locations.items())
    ]


def _repair_suspicious_ruled_semantic_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    preverified_cells: set[tuple[int, int]] | None = None,
) -> list[float]:
    locations = _suspicious_ruled_semantic_locations(grid)
    retained_locations = []
    for row, column, kind, reason in locations:
        if (
            reason == "power_missing_sign"
            and (
                (row, column) in (preverified_cells or set())
                or (
                    row < len(confidence_grid)
                    and column < len(confidence_grid[row])
                    and float(confidence_grid[row][column]) <= 0.77
                )
            )
        ):
            # The main physical-cell consensus already retained this visible
            # unsigned value for review. Re-running three recognizers cannot
            # prove a missing sign and finishes at the same yellow cell.
            confidence_grid[row][column] = min(
                float(confidence_grid[row][column]), 0.77
            )
            continue
        retained_locations.append((row, column, kind, reason))
    locations = retained_locations
    legacy_recognizers = (
        ("mobile", getattr(ocr_engine, "fast_text_rec", None), 0.80),
        ("medium", getattr(ocr_engine, "text_rec", None), 0.85),
        ("v5-server", getattr(ocr_engine, "server_text_rec", None), 0.80),
    )
    decimal_recognizers = (
        ("medium", getattr(ocr_engine, "text_rec", None), 0.85),
        ("v5-server", getattr(ocr_engine, "server_text_rec", None), 0.80),
    )
    if not locations:
        return []

    height, width = image.shape[:2]
    crops: list[np.ndarray] = []
    retained_locations: list[tuple[int, int, str, str]] = []
    for row, column, kind, reason in locations:
        if row + 1 >= len(rows) or column + 1 >= len(columns):
            continue
        left, right = columns[column], columns[column + 1]
        top, bottom = rows[row], rows[row + 1]
        pad_x = max(2, min(5, (right - left) // 16))
        pad_y = max(2, min(4, (bottom - top) // 12))
        crop = image[
            max(0, top + pad_y) : min(height, bottom - pad_y),
            max(0, left + pad_x) : min(width, right - pad_x),
        ]
        if crop.size:
            crops.append(crop)
            retained_locations.append((row, column, kind, reason))
    if not crops:
        return []

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    candidates: list[list[tuple[str, str, float]]] = [
        [] for _ in retained_locations
    ]
    all_scores: list[float] = []
    recognition_groups = (
        (
            [
                index
                for index, location in enumerate(retained_locations)
                if location[3] != "decimal_precision_mismatch"
            ],
            legacy_recognizers,
        ),
        (
            [
                index
                for index, location in enumerate(retained_locations)
                if location[3] == "decimal_precision_mismatch"
            ],
            decimal_recognizers,
        ),
    )
    for group_indices, recognizers in recognition_groups:
        if not group_indices:
            continue
        if not all(callable(item[1]) for item in recognizers):
            return all_scores
        group_crops = [crops[index] for index in group_indices]
        for family, recognizer, floor in recognizers:
            output = recognizer(TextRecInput(img=group_crops))
            _release_recognition_images(output)
            texts = [str(text).strip() for text in output.txts]
            scores = [float(score) for score in output.scores]
            all_scores.extend(scores)
            if len(texts) != len(group_indices) or len(scores) != len(group_indices):
                continue
            for index, text, score in zip(group_indices, texts, scores):
                if text and score >= floor:
                    candidates[index].append((family, text, score))

    for index, (row, column, kind, reason) in enumerate(retained_locations):
        grouped: dict[str, list[tuple[str, str, float]]] = {}
        for family, text, score in candidates[index]:
            key = re.sub(
                r"\s+",
                "",
                unicodedata.normalize("NFKC", text).translate(_DASH_TRANSLATION),
            ).casefold()
            if key:
                grouped.setdefault(key, []).append((family, text, score))
        supported = []
        for values in grouped.values():
            families = {family for family, _, _ in values}
            independent_sign_vote = reason in {
                "power_missing_sign",
                "power_magnitude_outlier",
            }
            if len(families) < 2 or (not independent_sign_vote and "medium" not in families):
                continue
            if (
                reason == "decimal_precision_mismatch"
                and "v5-server" not in families
            ):
                continue
            supported.append(values)
        if len(supported) != 1:
            if reason == "power_magnitude_outlier":
                grid[row][column] = ""
                confidence_grid[row][column] = -1.0
            else:
                confidence_grid[row][column] = min(
                    float(confidence_grid[row][column]), 0.77
                )
            continue
        values = supported[0]
        selected = next(
            (text for family, text, _ in values if family == "medium"),
            max(values, key=lambda item: item[2])[1],
        )
        selected_key = _motion_cell_consensus_key(selected)
        if reason == "power_missing_sign" and not re.fullmatch(
            r"[+\-]\d+(?:\.\d+)?(?:dbm)?", selected_key
        ):
            # A mixed power column can legitimately contain unsigned positive
            # values alongside negative values.  Peer rows cannot prove that a
            # sign is missing, so preserve the observed text and require review.
            confidence_grid[row][column] = min(
                float(confidence_grid[row][column]), 0.77
            )
            continue
        if reason == "power_magnitude_outlier":
            selected_match = re.fullmatch(
                r"[+\-]?(\d+(?:\.\d+)?)(?:dbm)?", selected_key
            )
            if selected_match is None or abs(float(selected_match.group(1))) > 100.0:
                grid[row][column] = ""
                confidence_grid[row][column] = -1.0
                continue
        if (
            reason == "decimal_precision_mismatch"
            and "." not in _motion_cell_consensus_key(selected)
        ):
            server_saw_decimal = any(
                family == "v5-server"
                and "." in _motion_cell_consensus_key(text)
                for family, text, _ in candidates[index]
            )
            if server_saw_decimal:
                confidence_grid[row][column] = min(
                    float(confidence_grid[row][column]), 0.77
                )
                continue
        if not _ruled_semantic_value_is_valid(kind, selected):
            confidence_grid[row][column] = min(
                float(confidence_grid[row][column]), 0.77
            )
            continue
        grid[row][column] = selected
        confidence_grid[row][column] = (
            0.90 if len({family for family, _, _ in values}) >= 3 else 0.86
        )
    return all_scores


def _repair_repeated_semantic_singletons(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    row_columns: list[list[int]] | None = None,
) -> list[float]:
    """Re-read one-off status tokens only when they are near a repeated value."""
    if (
        not grid
        or len(rows) != len(grid) + 1
        or len(columns) != len(grid[0]) + 1
    ):
        return []
    medium_recognizer = getattr(ocr_engine, "text_rec", None)
    alternate_recognizer = getattr(ocr_engine, "server_text_rec", None)
    if not callable(medium_recognizer) or not callable(alternate_recognizer):
        return []

    semantic_columns = {
        column
        for header_row in range(min(3, len(grid)))
        for column, value in enumerate(grid[header_row])
        if set(_header_semantic_labels(value)).intersection(
            {"状态", "当前状态", "审核状态", "结果", "判定"}
        )
    }
    inferred_categorical_columns: set[int] = set()
    column_count = len(grid[0])
    for column in range(column_count):
        categorical_counts: dict[str, int] = {}
        categorical_values = 0
        for row in range(1, len(grid)):
            if column >= len(grid[row]):
                continue
            key = _motion_cell_consensus_key(grid[row][column])
            if (
                not 2 <= len(key) <= 12
                or re.search(r"\d|[:：/%+\-]", key)
                or not re.search(r"[A-Za-z\u3400-\u9fff]", key)
            ):
                continue
            categorical_values += 1
            categorical_counts[key] = categorical_counts.get(key, 0) + 1
        if (
            categorical_values >= 6
            and max(categorical_counts.values(), default=0) >= 3
        ):
            inferred_categorical_columns.add(column)
    candidate_columns = semantic_columns | inferred_categorical_columns
    candidates: list[tuple[int, int, str]] = []
    for column in candidate_columns:
        counts: dict[str, tuple[str, int]] = {}
        for row in range(1, len(grid)):
            if column >= len(grid[row]):
                continue
            text = str(grid[row][column]).strip()
            key = _motion_cell_consensus_key(text)
            if key:
                representative, count = counts.get(key, (text, 0))
                counts[key] = (representative, count + 1)
        repeated = {
            key: (representative, count)
            for key, (representative, count) in counts.items()
            if count >= 2
        }
        for row in range(1, len(grid)):
            if column >= len(grid[row]):
                continue
            current = str(grid[row][column]).strip()
            current_key = _motion_cell_consensus_key(current)
            current_count = counts.get(current_key, ("", 0))[1]
            if not current_key or not 1 <= current_count <= 4:
                continue
            inferred_column = column in inferred_categorical_columns
            if inferred_column and (
                not 1 <= len(current_key) <= 12
                or (
                    re.search(r"\d|[:：/%+\-]", current_key)
                    and re.fullmatch(r"\d", current_key) is None
                )
            ):
                continue
            nearby = [
                representative
                for key, (representative, count) in repeated.items()
                if key != current_key
                and (
                    (
                        inferred_column
                        and (
                            key.startswith(current_key)
                            or key.endswith(current_key)
                        )
                        and 1 <= len(key) - len(current_key) <= 4
                        and count >= 2
                    )
                    or (
                        (
                            not inferred_column
                            or len(current_key) >= 2
                            or re.fullmatch(r"\d", current_key) is not None
                        )
                        and
                        abs(len(key) - len(current_key)) <= 1
                        and _text_edit_distance(current_key, key)
                        <= (3 if inferred_column and len(key) != len(current_key) else 2)
                        and count
                        >= (
                            max(3, current_count * 2)
                            if inferred_column
                            else max(2, current_count)
                        )
                    )
                )
            ]
            if nearby:
                candidates.append((row, column, nearby))
    if not candidates:
        return []
    candidates.sort(
        key=lambda item: (
            not any(
                _motion_cell_consensus_key(value).startswith(
                    _motion_cell_consensus_key(grid[item[0]][item[1]])
                )
                or _motion_cell_consensus_key(value).endswith(
                    _motion_cell_consensus_key(grid[item[0]][item[1]])
                )
                for value in item[2]
            ),
            item[0],
            item[1],
        )
    )

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    from colored_table import _tight_crop
    all_scores: list[float] = []
    height, width = image.shape[:2]
    for row, column, repeated_values in candidates[:8]:
        top, bottom = rows[row], rows[row + 1]
        active_columns = row_columns[row] if row_columns is not None else columns
        left, right = active_columns[column], active_columns[column + 1]
        crop = image[
            max(0, top + 2) : min(height, bottom - 2),
            max(0, left + 1) : min(width, right - 1),
        ]
        tight = _tight_crop(crop) if crop.size else crop
        if tight.size == 0:
            continue
        view = cv2.resize(
            tight,
            None,
            fx=3.2,
            fy=3.2,
            interpolation=cv2.INTER_LANCZOS4,
        )
        recognized: list[tuple[str, float]] = []
        for recognizer in (medium_recognizer, alternate_recognizer):
            output = recognizer(TextRecInput(img=[view]))
            _release_recognition_images(output)
            if len(output.txts) != 1 or len(output.scores) != 1:
                recognized = []
                break
            recognized.append((str(output.txts[0]).strip(), float(output.scores[0])))
            all_scores.append(float(output.scores[0]))
        if len(recognized) != 2 or min(score for _, score in recognized) < 0.80:
            continue
        first_key = _motion_cell_consensus_key(recognized[0][0])
        alternate_key = re.sub(
            r"^[☑☐□✓√]+",
            "",
            _motion_cell_consensus_key(recognized[1][0]),
        )
        if (
            first_key
            and recognized[0][1] >= 0.98
            and first_key == alternate_key
            and first_key in {
                _motion_cell_consensus_key(value) for value in repeated_values
            }
        ):
            grid[row][column] = recognized[0][0]
            confidence_grid[row][column] = 0.77
            independent = getattr(ocr_engine, "fast_text_rec", None)
            if callable(independent):
                confirmation = independent(TextRecInput(img=[view.copy()]))
                if (
                    len(confirmation.txts) == len(confirmation.scores) == 1
                    and _motion_cell_consensus_key(confirmation.txts[0]) == first_key
                    and float(confirmation.scores[0]) >= 0.95
                ):
                    confidence_grid[row][column] = 0.86
                _release_recognition_images(confirmation)
    return all_scores


def _repair_repeated_short_category_truncations(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
    row_columns: list[list[int]] | None = None,
) -> tuple[list[float], set[tuple[int, int]]]:
    """Re-read repeated short categories that may share a missing prefix or suffix."""
    if (
        not grid
        or len(rows) != len(grid) + 1
        or len(columns) != len(grid[0]) + 1
    ):
        return [], set()
    medium = getattr(ocr_engine, "text_rec", None)
    alternate = getattr(ocr_engine, "server_text_rec", None)
    fast = getattr(ocr_engine, "fast_text_rec", None)
    if not callable(medium) or not callable(alternate):
        return [], set()

    targets: list[tuple[int, int, str]] = []
    for column in range(len(grid[0])):
        values = [str(row[column]).strip() for row in grid]
        counts = Counter(value for value in values if value)
        for row, current in enumerate(values):
            key = _motion_cell_consensus_key(current)
            if (
                1 <= counts[current] <= 4
                and 1 <= len(key) <= 2
                and re.search(r"[A-Za-z\u3400-\u9fff]", key)
                and not re.search(r"\d|[:：/%+\-]", key)
                and key[-1] in {"楼", "器", "线", "仓"}
            ):
                targets.append((row, column, current))
    if not targets or len(targets) > 64:
        return [], set()

    from colored_table import _tight_crop
    crops: list[np.ndarray] = []
    valid_targets: list[tuple[int, int, str]] = []
    for row, column, current in targets:
        active_columns = row_columns[row] if row_columns is not None else columns
        cell_height = int(rows[row + 1]) - int(rows[row])
        cell_width = int(active_columns[column + 1]) - int(active_columns[column])
        pad = 10 if min(cell_height, cell_width) >= 28 else 6 if min(
            cell_height, cell_width
        ) >= 20 else 2
        crop = image[
            int(rows[row]) + pad:int(rows[row + 1]) - pad,
            int(active_columns[column]) + pad:int(active_columns[column + 1]) - pad,
        ]
        tight = _tight_crop(crop) if crop.size else crop
        if tight.size == 0:
            continue
        crops.append(cv2.resize(
            tight, None, fx=3.2, fy=3.2, interpolation=cv2.INTER_LANCZOS4
        ))
        valid_targets.append((row, column, current))
    if not valid_targets:
        return [], set()

    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    scores: list[float] = []
    repaired: set[tuple[int, int]] = set()
    independent_values = None
    if callable(fast):
        screening = fast(TextRecInput(img=[crop.copy() for crop in crops]))
        screening_values = list(zip(screening.txts, screening.scores))
        scores.extend(float(score) for _, score in screening_values)
        _release_recognition_images(screening)
        selected_indices = [
            index
            for index, ((_, _, current), value) in enumerate(
                zip(valid_targets, screening_values)
            )
            for current_key in [_motion_cell_consensus_key(current)]
            for candidate_key in [_motion_cell_consensus_key(value[0])]
            if (
                float(value[1]) >= 0.85
                and 1 <= len(candidate_key) - len(current_key) <= 4
                and (
                    candidate_key.startswith(current_key)
                    or candidate_key.endswith(current_key)
                )
            )
        ]
        if not selected_indices:
            return scores, repaired
        crops = [crops[index] for index in selected_indices]
        valid_targets = [valid_targets[index] for index in selected_indices]
        independent_values = [screening_values[index] for index in selected_indices]

    primary = medium(TextRecInput(img=[crop.copy() for crop in crops]))
    secondary = alternate(TextRecInput(img=[crop.copy() for crop in crops]))
    primary_values = list(zip(primary.txts, primary.scores))
    secondary_values = list(zip(secondary.txts, secondary.scores))
    scores.extend(
        float(score)
        for _, score in primary_values + secondary_values
    )
    if (
        len(primary_values) == len(valid_targets)
        and len(secondary_values) == len(valid_targets)
    ):
        for index, ((row, column, current), first, second) in enumerate(zip(
            valid_targets, primary_values, secondary_values
        )):
            current_key = _motion_cell_consensus_key(current)
            first_text = str(first[0]).strip()
            candidate_key = _motion_cell_consensus_key(first_text)
            if (
                candidate_key == _motion_cell_consensus_key(second[0])
                and 1 <= len(candidate_key) - len(current_key) <= 4
                and (
                    candidate_key.startswith(current_key)
                    or candidate_key.endswith(current_key)
                )
                and float(first[1]) >= 0.90
                and float(second[1]) >= 0.80
            ):
                grid[row][column] = first_text
                confidence_grid[row][column] = (
                    0.86 if independent_values is not None
                    and _motion_cell_consensus_key(independent_values[index][0]) == candidate_key
                    and float(independent_values[index][1]) >= 0.90
                    else 0.77
                )
                repaired.add((row, column))
    _release_recognition_images(primary)
    _release_recognition_images(secondary)
    return scores, repaired


def _recover_multiline_ruled_header_blanks(
    image: np.ndarray, grid: list[list[str]], confidence_grid: list[list[float]],
    columns: list[int], rows: list[int], ocr_engine: Any,
    excluded: set[tuple[int, int]],
) -> list[float]:
    """只用两套模型逐行确认被全格 OCR 漏掉的可见多行表头。"""
    if (not grid or len(columns) != len(grid[0]) + 1
            or len(rows) != len(grid) + 1):
        return []
    targets = []
    crops = []
    for row in range(min(3, len(grid))):
        if sum(bool(value.strip()) for value in grid[row]) < len(grid[row]) * .60:
            continue
        for column, value in enumerate(grid[row]):
            if (value or confidence_grid[row][column] >= 0
                    or (row, column) in excluded):
                continue
            crop = image[rows[row] + 3:rows[row + 1] - 3,
                         columns[column] + 3:columns[column + 1] - 3]
            if crop.size == 0 or not _physical_cell_has_visible_text_ink(crop):
                continue
            lines = _split_low_resolution_ruled_cell_lines(crop)
            if not 2 <= len(lines) <= 4:
                continue
            if any(min(line.shape[:2]) < 12 for line in lines):
                continue
            targets.append((row, column, len(crops), len(crops) + len(lines)))
            crops.extend(_tight_text_crop(line) for line in lines)
    if not 1 <= len(targets) <= 3:
        return []
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    small = ocr_engine.fast_text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    medium = ocr_engine.text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    first = list(zip(small.txts, small.scores))
    second = list(zip(medium.txts, medium.scores))
    _release_recognition_images(small)
    _release_recognition_images(medium)
    if len(first) != len(second) or len(first) != len(crops):
        return []
    for row, column, start, end in targets:
        if all(str(a).strip() == str(b).strip()
               and str(a).strip() and min(float(sa), float(sb)) >= .95
               for (a, sa), (b, sb) in zip(first[start:end], second[start:end])):
            grid[row][column] = "\n".join(str(text).strip() for text, _ in first[start:end])
            confidence_grid[row][column] = .86
    return [float(score) for _, score in first + second]


def _reanchor_concatenated_physical_headers(
    image: np.ndarray, grid: list[list[str]], confidence_grid: list[list[float]],
    columns: list[int], rows: list[int], spans: list[dict[str, Any]],
    ocr_engine: Any,
) -> set[tuple[int, int]]:
    """按独立格像素拆开被整页 OCR 拼进首格的相邻表头。"""
    if (not grid or len(columns) != len(grid[0]) + 1
            or len(rows) != len(grid) + 1):
        return set()
    covered = {
        (r, c)
        for span in spans
        for r in range(span["row"], span["row"] + span["row_span"])
        for c in range(span["column"], span["column"] + span["column_span"])
        if (r, c) != (span["row"], span["column"])
    }
    candidates = []
    for row in range(min(3, len(grid))):
        for source, value in enumerate(grid[row]):
            if len(value.strip()) < 4 or (row, source) in covered:
                continue
            for target in range(source + 2, len(grid[row])):
                if any(
                    span["row"] == row and span["column"] == source
                    and span["row"] <= row < span["row"] + span["row_span"]
                    and span["column"] <= target < span["column"] + span["column_span"]
                    for span in spans
                ):
                    continue
                crop = image[rows[row] + 3:rows[row + 1] - 3,
                             columns[target] + 3:columns[target + 1] - 3]
                if crop.size == 0 or not _physical_cell_has_visible_text_ink(crop):
                    continue
                original = str(grid[row][target]).strip()
                if original and (len(original) < 8 or not value.strip().endswith(original)):
                    continue
                candidates.append((row, source, target))
    if not 1 <= len(candidates) <= 3:
        return set()
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    changed = set()
    for row, source, target in candidates:
        crops = [
            _tight_text_crop(image[rows[row] + 3:rows[row + 1] - 3,
                                   columns[column] + 3:columns[column + 1] - 3])
            for column in (source, target)
        ]
        if any(crop.size == 0 for crop in crops):
            continue
        small = ocr_engine.fast_text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
        medium = ocr_engine.text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
        first = list(zip(small.txts, small.scores))
        second = list(zip(medium.txts, medium.scores))
        _release_recognition_images(small)
        _release_recognition_images(medium)
        if len(first) != 2 or len(second) != 2:
            continue
        words = [str(text).strip() for text, _ in first]
        if not all(words[index] == str(second[index][0]).strip()
                   and words[index] and min(float(first[index][1]), float(second[index][1])) >= .95
                   for index in range(2)):
            continue
        if ("".join(str(grid[row][source]).split())
                != "".join((words[0] + words[1]).split())):
            continue
        if grid[row][target] and grid[row][target].strip() != words[1]:
            continue
        grid[row][source], grid[row][target] = words
        confidence_grid[row][source] = confidence_grid[row][target] = .86
        changed.update({(row, source), (row, target)})
    return changed


def _audit_reanchored_physical_grid(
    image: np.ndarray, grid: list[list[str]], confidence_grid: list[list[float]],
    columns: list[int], rows: list[int], ocr_engine: Any,
) -> list[dict[str, Any]] | None:
    """用真实格线、空格像素和两套逐行模型复核被整页布局质疑的表。"""
    if (not grid or len(columns) != len(grid[0]) + 1
            or len(rows) != len(grid) + 1):
        return None
    from colored_table import physical_spans
    physical = physical_spans(image, rows, columns)
    if physical is None or _spans_hide_non_anchor_text(grid, physical):
        return None
    covered = {
        (r, c)
        for span in physical
        for r in range(span["row"], span["row"] + span["row_span"])
        for c in range(span["column"], span["column"] + span["column_span"])
        if (r, c) != (span["row"], span["column"])
    }
    locations = []
    crops = []
    for row, values in enumerate(grid):
        for column, value in enumerate(values):
            if (row, column) in covered:
                continue
            crop = image[rows[row] + 3:rows[row + 1] - 3,
                         columns[column] + 3:columns[column + 1] - 3]
            if crop.size == 0:
                return None
            if not value:
                if _physical_cell_has_visible_text_ink(crop):
                    return None
                continue
            parts = str(value).split("\n")
            lines = _split_low_resolution_ruled_cell_lines(crop) if len(parts) > 1 else [crop]
            if len(lines) != len(parts):
                return None
            for part, line in zip(parts, lines):
                locations.append((row, column, part))
                crops.append(_tight_text_crop(line))
    if not 1 <= len(crops) <= 256 or any(crop.size == 0 for crop in crops):
        return None
    from rapidocr.ch_ppocr_rec.typings import TextRecInput

    small = ocr_engine.fast_text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    medium = ocr_engine.text_rec(TextRecInput(img=[crop.copy() for crop in crops]))
    first = list(zip(small.txts, small.scores))
    second = list(zip(medium.txts, medium.scores))
    _release_recognition_images(small)
    _release_recognition_images(medium)
    if len(first) != len(locations) or len(second) != len(locations):
        return None
    for (_, _, expected), (a, sa), (b, sb) in zip(locations, first, second):
        expected = re.sub(r"(\d{4}-\d{2}-\d{2})(\d{2}:\d{2}:\d{2})",
                          r"\1 \2", expected)
        normalized = [re.sub(r"(\d{4}-\d{2}-\d{2})(\d{2}:\d{2}:\d{2})",
                             r"\1 \2", str(text)) for text in (a, b)]
        if (min(float(sa), float(sb)) < .95
                or any(_comparable_text(expected) != _comparable_text(text)
                       for text in normalized)):
            return None
    for row, values in enumerate(grid):
        for column, value in enumerate(values):
            confidence_grid[row][column] = .86 if value else 0.0
    return physical


def _recover_missing_ruled_cells(
    image: np.ndarray,
    grid: list[list[str]],
    confidence_grid: list[list[float]],
    columns: list[int],
    rows: list[int],
    ocr_engine: Any,
) -> tuple[list[list[str]], list[list[float]], list[float]]:
    """Re-read visible blanks inside trusted ruled geometry with two models."""
    if not grid or not grid[0]:
        return grid, confidence_grid, []
    stripped_preview, _ = _strip_spreadsheet_ui_headers(grid, None)
    geometry = _ruled_grid_recovery_geometry(columns, rows)
    if len(stripped_preview) < len(grid):
        # Exclude the spreadsheet column-letter ruler from recovery.  Missing
        # ruler letters are application chrome, not document content.
        geometry["first_structured_row"] = 1
    locked_merged_cells = _locked_merged_blank_locations(
        image,
        columns,
        rows,
        grid,
    )
    grid, confidence_grid, recovery_scores = _recover_missing_spatial_cells(
        image,
        grid,
        confidence_grid,
        geometry,
        ocr_engine,
        max_candidates=None,
        require_cross_model=True,
        excluded_cells=locked_merged_cells,
    )
    recovery_scores.extend(_recover_multiline_ruled_header_blanks(
        image, grid, confidence_grid, columns, rows, ocr_engine,
        locked_merged_cells,
    ))
    _recover_visible_marks_in_grid(
        image,
        grid,
        confidence_grid,
        columns,
        rows,
    )
    recovery_scores.extend(
        _restore_ruled_numeric_signs(
            image,
            grid,
            confidence_grid,
            columns,
            rows,
            ocr_engine,
        )
    )
    recovery_scores.extend(
        _repair_suspicious_ruled_semantic_cells(
            image,
            grid,
            confidence_grid,
            columns,
            rows,
            ocr_engine,
        )
    )
    return grid, confidence_grid, recovery_scores


def _spatial_fallback(boxes, texts) -> list[list[str]]:
    grid, _, _, _ = _borderless_spatial_grid(boxes, texts)
    return grid


