        _repair_single_letter_column_case(grid, confidence_grid)
        _repair_short_code_column_consistency(grid, confidence_grid)
        _harmonize_duplicate_row_text_case(grid, confidence_grid)
        _repair_camel_case_visual_confusions(grid, confidence_grid)
